# ── Store Commands ───────────────────────────────────────────

def _get_store_manager():
    from data_pipeline.store.store_manager import StoreManager
    sm = StoreManager()
    # Auto-load from .env if no stores configured
    stores = sm.list_stores()
    if not stores:
        url = os.environ.get("SHOPAI_SHOPIFY_URL", "")
        key = os.environ.get("SHOPAI_SHOPIFY_KEY", "")
        if url and key:
            store_id = url.replace(".myshopify.com", "").replace("https://", "")
            sm.add_store(store_id, url, key, name="Default Store")
    return sm


def _cmd_store_add(args) -> None:
    sm = _get_store_manager()
    result = sm.add_store(
        args.store_id, args.shop_url,
        api_key=args.api_key,
        client_id=args.client_id,
        client_secret=args.client_secret,
        name=args.name, niche=args.niche, store_type=args.store_type,
    )
    print(f"✓ Store added: {args.store_id}")
    print(f"  URL: {args.shop_url}")
    print(f"  Auth: {'OAuth (auto-refresh)' if args.client_id else 'Legacy token' if args.api_key else 'No credentials'}")
    print(f"  Type: {args.store_type}")
    if args.niche:
        print(f"  Niche: {args.niche}")
    # Drill-down hint: just-added store needs auth verification
    # + first sync before per-store commands work. Skip when
    # credentials weren't supplied (caller knows they're not
    # done yet).
    if args.api_key or args.client_id:
        print()
        print(
            f"  Next: `shopai store connect {args.store_id}` "
            "(verify auth)."
        )


def _cmd_transfer(args) -> None:
    """Dispatcher for ``shopai transfer <verb>``."""
    verb = getattr(args, "transfer_action", None)
    if verb == "scan":
        _cmd_transfer_scan(args)
        return
    if verb == "suggest":
        _cmd_transfer_suggest(args)
        return
    if verb == "apply":
        _cmd_transfer_apply(args)
        return
    if verb == "sources":
        _cmd_transfer_sources(args)
        return
    if verb == "history":
        _cmd_transfer_history(args)
        return
    if verb == "outcomes":
        _cmd_transfer_outcomes(args)
        return
    if verb == "credit":
        _cmd_transfer_credit(args)
        return
    print(
        "Usage: shopai transfer "
        "{suggest|apply|sources|history|outcomes|credit}"
    )


def _cmd_transfer_scan(args) -> None:
    """Wave 71: empire-wide transfer scanner.

    Walks every (source, target) store pair, identifies
    transferable winners, ranks across the fleet. For 20-store
    empires, replaces 380 manual `transfer suggest` calls.
    """
    from engines._transfer_scanner import scan_empire_transfers

    as_json = bool(getattr(args, "json", False))
    top_k = max(1, int(getattr(args, "top", 20) or 20))
    min_pos = max(
        1, int(getattr(args, "min_positive", 2) or 2),
    )
    same_niche = bool(getattr(args, "same_niche", False))

    report = scan_empire_transfers(
        top_k=top_k,
        min_positive_outcomes=min_pos,
        same_niche_only=same_niche,
    )

    if as_json:
        print(json.dumps({
            "pairs_scanned": report.pairs_scanned,
            "total_candidates": report.total_candidates,
            "top_pair": list(report.top_pair) if report.top_pair else None,
            "same_niche_only": same_niche,
            "candidates": [
                {
                    "from_store": c.from_store,
                    "to_store": c.to_store,
                    "engine": c.engine,
                    "action_type": c.action_type,
                    "capability": c.capability,
                    "positive_outcomes": c.positive_outcomes,
                    "total_revenue": c.total_revenue,
                    "score": c.score,
                    "from_niche": c.from_niche,
                    "to_niche": c.to_niche,
                    "niche_compat": c.niche_compat,
                }
                for c in report.candidates
            ],
        }, indent=2, default=str))
        return

    suffix = " (same-niche only)" if same_niche else ""
    print(
        f"Transfer scan -- {report.pairs_scanned} pair(s) "
        f"checked, {report.total_candidates} "
        f"candidate(s){suffix}"
    )
    print()
    if not report.candidates:
        hint = (
            "  (no same-niche transfers found; try without "
            "--same-niche or lower --min-positive)"
            if same_niche else
            "  (no transferable winners found; try lowering "
            "--min-positive)"
        )
        print(hint)
        return
    # Wave 82: niche-compat marker column.
    print(
        f"  {'from':<14} {'to':<14} {'engine':<24} "
        f"{'pos':>4} {'$':>8}  score  niche"
    )
    compat_marker = {
        "match": "[==]",
        "cross": "[!=]",
        "unknown": "[? ]",
    }
    for c in report.candidates:
        nm = compat_marker.get(c.niche_compat, "[? ]")
        print(
            f"  {c.from_store[:14]:<14} {c.to_store[:14]:<14} "
            f"{c.engine[:24]:<24} "
            f"{c.positive_outcomes:>4} "
            f"${c.total_revenue:>6,.0f}  "
            f"{c.score:>6.1f}  {nm}"
        )
    print()
    if not same_niche:
        # Only suggest the filter when it's still off.
        cross_count = sum(
            1 for c in report.candidates
            if c.niche_compat == "cross"
        )
        if cross_count:
            print(
                f"  {cross_count} of {report.total_candidates} "
                "are cross-niche -- run with `--same-niche` to "
                "restrict to high-confidence transfers."
            )
    print(
        "  Apply a single candidate: "
        "`shopai transfer apply --from X --to Y "
        "--engine Z --action-type ...`"
    )


def _cmd_transfer_suggest(args) -> None:
    """Cross-store transfer recommender.

    For each (engine, action_type) tuple that succeeded on the
    ``--from`` store and was NOT tried on the ``--to`` store,
    surface it as a transfer candidate. Ranked by success count
    + measured revenue.

    Empire-AGI payoff command: "Store A had revenue lift from
    loyalty mints; suggest minting equivalents on Store B."
    """
    as_json = bool(getattr(args, "json", False))
    from_store = args.from_store
    to_store = args.to_store
    engine_filter = getattr(args, "engine", "") or None
    k = max(1, int(getattr(args, "k", 5) or 5))

    if from_store == to_store:
        msg = "--from and --to must be different stores"
        if as_json:
            print(json.dumps(
                {"status": "error", "error": msg},
                indent=2, default=str,
            ))
        else:
            print(f"Error: {msg}")
        sys.exit(1)
        return

    try:
        from core.approval.queue import (
            ApprovalStatus, get_approval_queue,
        )
    except Exception as exc:  # noqa: BLE001
        msg = f"approval queue unavailable: {exc}"
        if as_json:
            print(json.dumps(
                {"status": "error", "error": msg},
                indent=2, default=str,
            ))
        else:
            print(msg)
        sys.exit(1)
        return

    queue = get_approval_queue()

    # ── Step 1: pull EXECUTED actions on the source store ───
    try:
        source_executed = queue.list_by_status(
            ApprovalStatus.EXECUTED,
            engine=engine_filter,
            store_id=from_store,
            limit=2000,
        )
    except TypeError:
        # Pre-#239 queue without store_id kwarg — bail with a
        # clear error rather than silently crossing stores.
        msg = (
            "approval queue does not support per-store filter "
            "(needs PR #239 or later)"
        )
        if as_json:
            print(json.dumps(
                {"status": "error", "error": msg},
                indent=2, default=str,
            ))
        else:
            print(f"Error: {msg}")
        sys.exit(1)
        return

    # ── Step 2: aggregate by (engine, action_type, capability) ─
    success_groups: dict[tuple, dict] = {}
    for a in source_executed:
        key = (a.engine, a.action_type, a.capability)
        bucket = success_groups.setdefault(key, {
            "engine": a.engine,
            "action_type": a.action_type,
            "capability": a.capability,
            "success_count": 0,
            "positive_outcomes": 0,
            "negative_outcomes": 0,
            "total_revenue": 0.0,
            "sample_params": a.params,
        })
        bucket["success_count"] += 1
        # Pull outcomes for revenue + polarity rollup.
        try:
            outcomes = queue.get_outcomes(a.id) or []
        except Exception as exc:  # noqa: BLE001
            logger.debug("transfer-suggest outcomes raised: %s", exc)
            outcomes = []
        for o in outcomes:
            polarity = o.get("polarity", "neutral")
            if polarity == "positive":
                bucket["positive_outcomes"] += 1
            elif polarity == "negative":
                bucket["negative_outcomes"] += 1
            metrics = o.get("metrics") or {}
            rev = metrics.get("revenue")
            if rev is not None:
                try:
                    bucket["total_revenue"] += float(rev)
                except (TypeError, ValueError) as exc:
                    logger.debug(
                        "transfer-suggest revenue parse: %s", exc,
                    )

    # ── Step 3: filter out anything already tried on target ─
    # Pull every status on the target store and build the
    # already-tried set of (engine, action_type) pairs.
    already_tried: set[tuple] = set()
    for status in (
        ApprovalStatus.EXECUTED, ApprovalStatus.FAILED,
        ApprovalStatus.PENDING, ApprovalStatus.APPROVED,
        ApprovalStatus.REJECTED,
    ):
        try:
            target_actions = queue.list_by_status(
                status, engine=engine_filter,
                store_id=to_store, limit=2000,
            )
        except Exception as exc:  # noqa: BLE001
            logger.debug(
                "transfer-suggest target list_by_status raised: %s",
                exc,
            )
            continue
        for a in target_actions:
            already_tried.add((a.engine, a.action_type))

    # Filter + rank.
    candidates = [
        v for k_tuple, v in success_groups.items()
        if (v["engine"], v["action_type"]) not in already_tried
    ]
    candidates.sort(
        key=lambda v: (
            -(v["positive_outcomes"]),
            -v["total_revenue"],
            -v["success_count"],
        ),
    )
    suggestions = candidates[:k]

    # ── JSON envelope ─────────────────────────────────────
    if as_json:
        print(json.dumps({
            "from_store": from_store,
            "to_store": to_store,
            "engine_filter": engine_filter,
            "k": k,
            "source_executed_count": len(source_executed),
            "source_unique_actions": len(success_groups),
            "already_tried_count": len(already_tried),
            "suggestions": suggestions,
        }, indent=2, default=str))
        return

    # ── Text render ────────────────────────────────────────
    print(
        f"Transfer suggest: {from_store} -> {to_store}"
        + (f"  (engine={engine_filter})" if engine_filter else "")
    )
    print(
        f"  Source executed: {len(source_executed)}  "
        f"unique action types: {len(success_groups)}  "
        f"already tried on target: {len(already_tried)}"
    )
    print()
    if not suggestions:
        print(
            f"(no transfer candidates -- target store has tried "
            f"every action that succeeded on the source)"
        )
        return
    print(f"Top {len(suggestions)} suggestion(s):")
    for i, s in enumerate(suggestions, 1):
        rev_str = (
            f" revenue=${s['total_revenue']:,.2f}"
            if s["total_revenue"] else ""
        )
        outcome_str = (
            f" +{s['positive_outcomes']}/-{s['negative_outcomes']}"
        )
        print(
            f"  [{i}] {s['engine']}/{s['action_type']}"
        )
        print(
            f"      capability={s['capability']}  "
            f"runs={s['success_count']}{outcome_str}{rev_str}"
        )
        if s.get("sample_params"):
            keys = sorted(s["sample_params"].keys())[:5]
            print(f"      sample params: {', '.join(keys)}")
    # Drill-down hint: top suggestion is the highest-priority
    # transfer to actually run. Pre-fill the operator's next
    # command with --dry-run so the audit trail is preview-
    # first (no surprise enqueues).
    top = suggestions[0]
    print()
    print(
        f"  Next: `shopai transfer apply --from {from_store} "
        f"--to {to_store} --engine {top['engine']} "
        f"--action-type {top['action_type']} --dry-run`"
    )


def _cmd_transfer_apply(args) -> None:
    """Enqueue a transfer suggestion as a PENDING action on the
    target store.

    Closes the suggest→action loop: ``transfer suggest`` shows
    recommendations, this command turns one of them into a real
    pending action that operators review via ``shopai approvals
    show`` and approve/reject.

    Reads the most recent successful execution of the matching
    (engine, action_type) on the source store to pull a params
    template, then enqueues a new PENDING action on the target
    store with those params (or operator-supplied overrides).
    No Shopify mutation runs -- this is a queue write only.
    """
    as_json = bool(getattr(args, "json", False))
    from_store = args.from_store
    to_store = args.to_store
    engine = args.engine
    action_type = args.action_type

    def _emit_error(msg: str) -> None:
        if as_json:
            print(json.dumps(
                {"status": "error", "error": msg},
                indent=2, default=str,
            ))
        else:
            print(f"Error: {msg}")
        sys.exit(1)

    if from_store == to_store:
        _emit_error("--from and --to must be different stores")
        return

    # Wave 88: niche-compat gate. Resolve both stores' niches
    # via StoreManager; classify via the Wave 82 helper.
    # Cross-niche transfers refuse unless --allow-cross-niche.
    niche_compat = "unknown"
    from_niche = ""
    to_niche = ""
    allow_cross = bool(getattr(args, "allow_cross_niche", False))
    try:
        from engines._transfer_scanner import _classify_niche_compat
        sm_for_niche = _get_store_manager()
        from_row = sm_for_niche.get_store(from_store) or {}
        to_row = sm_for_niche.get_store(to_store) or {}
        from_niche = (from_row.get("niche") or "").strip().lower()
        to_niche = (to_row.get("niche") or "").strip().lower()
        niche_compat = _classify_niche_compat(
            from_niche, to_niche,
        )
    except Exception:  # noqa: BLE001
        niche_compat = "unknown"
    if niche_compat == "cross" and not allow_cross:
        _emit_error(
            f"cross-niche transfer refused: "
            f"{from_store}={from_niche} -> {to_store}={to_niche}. "
            "Re-run with --allow-cross-niche to override; or "
            "pick a same-niche source via "
            "`shopai transfer scan --same-niche`."
        )
        return

    # Optional operator-supplied param overrides.
    override_params: dict | None = None
    raw = getattr(args, "params_json", "") or ""
    if raw:
        try:
            parsed = json.loads(raw)
            if not isinstance(parsed, dict):
                _emit_error(
                    "--params-json must be a JSON object",
                )
                return
            override_params = parsed
        except json.JSONDecodeError as exc:
            _emit_error(f"--params-json is not valid JSON: {exc}")
            return

    try:
        from core.approval.queue import (
            ApprovalStatus, get_approval_queue,
        )
    except Exception as exc:  # noqa: BLE001
        _emit_error(f"approval queue unavailable: {exc}")
        return

    queue = get_approval_queue()

    # Find the most recent EXECUTED action on the source store
    # matching the engine + action_type. That's our template.
    try:
        source_actions = queue.list_by_status(
            ApprovalStatus.EXECUTED,
            engine=engine,
            store_id=from_store,
            limit=200,
        )
    except TypeError:
        _emit_error(
            "approval queue does not support per-store filter "
            "(needs PR #239 or later)"
        )
        return

    matching = [
        a for a in source_actions
        if a.action_type == action_type
    ]
    if not matching:
        _emit_error(
            f"no successful {action_type!r} found on source store "
            f"{from_store!r} for engine {engine!r}"
        )
        return

    # Reject if the same (engine, action_type) is already on
    # target store in ANY status (operator may have already
    # tried this transfer or run the action organically).
    for status in (
        ApprovalStatus.EXECUTED, ApprovalStatus.FAILED,
        ApprovalStatus.PENDING, ApprovalStatus.APPROVED,
        ApprovalStatus.REJECTED,
    ):
        try:
            existing = queue.list_by_status(
                status, engine=engine, store_id=to_store,
                limit=200,
            )
        except Exception as exc:  # noqa: BLE001
            logger.debug(
                "transfer apply: target probe raised: %s", exc,
            )
            existing = []
        if any(a.action_type == action_type for a in existing):
            _emit_error(
                f"{engine}/{action_type} already exists on target "
                f"store {to_store!r} (status={status.value}); "
                "skipping to avoid duplicate enqueue"
            )
            return

    template = matching[0]  # most recent by decided_at desc
    capability = template.capability
    base_params = dict(template.params or {})
    if override_params:
        base_params.update(override_params)

    operator_note = (
        getattr(args, "narrative", "") or ""
    ).strip()
    # Wave 88: encode niche-compat into the narrative so audit
    # trail captures which transfers were cross-niche overrides.
    compat_tag = ""
    if niche_compat == "match":
        compat_tag = f" niche=match({from_niche})"
    elif niche_compat == "cross":
        compat_tag = (
            f" niche=cross({from_niche}->{to_niche},"
            "override=allow-cross-niche)"
        )
    narrative = (
        f"Transfer suggestion: {engine}/{action_type} "
        f"from {from_store} to {to_store}.{compat_tag} "
        f"Source had {len(matching)} prior successful run(s)."
    )
    if operator_note:
        narrative = f"{operator_note}  ||  {narrative}"

    dry_run = bool(getattr(args, "dry_run", False))

    if dry_run:
        if as_json:
            print(json.dumps({
                "status": "dry_run",
                "would_enqueue": True,
                "engine": engine,
                "action_type": action_type,
                "capability": capability,
                "from_store": from_store,
                "to_store": to_store,
                "source_action_id": template.id,
                "source_run_count": len(matching),
                "params": base_params,
                "narrative": narrative,
                "niche_compat": niche_compat,
                "from_niche": from_niche,
                "to_niche": to_niche,
            }, indent=2, default=str))
            return
        print(
            f"DRY RUN -- would transfer: "
            f"{engine}/{action_type}  "
            f"{from_store} -> {to_store}"
        )
        print(
            f"  source template id: {template.id}  "
            f"capability: {capability}"
        )
        print(f"  source runs: {len(matching)}")
        print(f"  params:    {base_params}")
        print(f"  narrative: {narrative}")
        print()
        print("  Re-run without --dry-run to enqueue.")
        return

    try:
        action = queue.enqueue(
            engine=engine,
            action_type=action_type,
            capability=capability,
            params=base_params,
            narrative=narrative,
            store_id=to_store,
        )
    except Exception as exc:  # noqa: BLE001
        _emit_error(f"enqueue failed: {exc}")
        return

    if as_json:
        print(json.dumps({
            "status": "ok",
            "action_id": action.id,
            "engine": engine,
            "action_type": action_type,
            "capability": capability,
            "from_store": from_store,
            "to_store": to_store,
            "params": base_params,
            "narrative": narrative,
            "niche_compat": niche_compat,
            "from_niche": from_niche,
            "to_niche": to_niche,
        }, indent=2, default=str))
        return

    print(
        f"Transfer applied: {engine}/{action_type}  "
        f"{from_store} -> {to_store}"
    )
    print(f"  action_id: {action.id}")
    if niche_compat != "unknown":
        marker = "[==]" if niche_compat == "match" else "[!=]"
        print(
            f"  niche: {marker} "
            f"{from_niche or '-'} -> {to_niche or '-'}"
        )
    print(
        f"  source runs: {len(matching)}  "
        f"capability: {capability}"
    )
    print(f"  narrative:  {narrative}")
    print()
    print(
        "  Review with:  "
        f"shopai approvals show {action.id} --with-context"
    )


def _cmd_transfer_sources(args) -> None:
    """Rank stores in the fleet by transferable surface area
    toward the target.

    Operators currently have to guess which source store to point
    ``transfer suggest --from`` at. This command tells them: 'these
    are the stores with the most successful actions that target
    hasn't tried yet'. Run before ``transfer suggest`` to pick a
    high-yield source.

    Scoring per candidate source store:
      - transferable_count = unique (engine, action_type) tuples
        that EXECUTED on source AND have NOT been tried on target
        in any status (mirrors the exclusion logic in
        ``transfer suggest``).
      - source_executed_total = total EXECUTED action count on
        source (raw activity signal).
    Ranking: transferable_count desc, then source_executed_total
    desc, then source_id asc.
    """
    as_json = bool(getattr(args, "json", False))
    to_store = (getattr(args, "to_store", "") or "").strip()
    k = max(1, int(getattr(args, "k", 5) or 5))

    def _emit_error(msg: str) -> None:
        if as_json:
            print(json.dumps(
                {"status": "error", "error": msg},
                indent=2, default=str,
            ))
        else:
            print(f"Error: {msg}")
        sys.exit(1)

    if not to_store:
        _emit_error("--to is required")
        return

    try:
        from core.approval.queue import (
            ApprovalStatus, get_approval_queue,
        )
    except Exception as exc:  # noqa: BLE001
        _emit_error(f"approval queue unavailable: {exc}")
        return

    sm = _get_store_manager()
    fleet = sm.list_stores() or []
    candidate_ids = [
        s.get("store_id") for s in fleet
        if s.get("store_id") and s.get("store_id") != to_store
    ]

    queue = get_approval_queue()

    # Build the target's "already tried" set: every (engine,
    # action_type) tuple in ANY status on the target. Same
    # exclusion semantics as ``transfer suggest``.
    target_tried: set[tuple[str, str]] = set()
    for status in (
        ApprovalStatus.EXECUTED, ApprovalStatus.FAILED,
        ApprovalStatus.PENDING, ApprovalStatus.APPROVED,
        ApprovalStatus.REJECTED, ApprovalStatus.EXPIRED,
    ):
        try:
            rows = queue.list_by_status(
                status, store_id=to_store, limit=2000,
            )
        except TypeError:
            _emit_error(
                "approval queue does not support per-store filter "
                "(needs PR #239 or later)"
            )
            return
        except Exception as exc:  # noqa: BLE001
            logger.debug(
                "transfer sources target probe raised: %s", exc,
            )
            rows = []
        for a in rows:
            target_tried.add((a.engine, a.action_type))

    # For each candidate source, count transferable actions.
    sources: list[dict] = []
    for sid in candidate_ids:
        try:
            src_rows = queue.list_by_status(
                ApprovalStatus.EXECUTED,
                store_id=sid, limit=2000,
            )
        except Exception as exc:  # noqa: BLE001
            logger.debug(
                "transfer sources source probe raised: %s", exc,
            )
            src_rows = []

        unique_actions: set[tuple[str, str]] = set()
        transferable: set[tuple[str, str]] = set()
        for a in src_rows:
            key = (a.engine, a.action_type)
            unique_actions.add(key)
            if key not in target_tried:
                transferable.add(key)

        sources.append({
            "store_id": sid,
            "source_executed_total": len(src_rows),
            "source_unique_actions": len(unique_actions),
            "transferable_count": len(transferable),
            "sample_transferable": sorted(
                f"{e}/{at}" for e, at in transferable
            )[:5],
        })

    sources.sort(key=lambda s: (
        -s["transferable_count"],
        -s["source_executed_total"],
        s["store_id"],
    ))
    top = sources[:k]

    envelope = {
        "to_store": to_store,
        "k": k,
        "target_already_tried_count": len(target_tried),
        "candidate_count": len(candidate_ids),
        "sources": top,
    }

    if as_json:
        print(json.dumps(envelope, indent=2, default=str))
        return

    print(
        f"Transfer sources for target '{to_store}' "
        f"(top {len(top)} of {len(candidate_ids)} candidates):"
    )
    print()
    if not top:
        print("  No candidate stores in fleet.")
        return
    for i, s in enumerate(top, start=1):
        print(
            f"  [{i}] {s['store_id']}  "
            f"transferable={s['transferable_count']}  "
            f"(of {s['source_unique_actions']} unique actions, "
            f"{s['source_executed_total']} total executed)"
        )
        if s["sample_transferable"]:
            sample = ", ".join(s["sample_transferable"])
            print(f"      sample: {sample}")
    print()
    print(
        f"  Next: `shopai transfer suggest --from "
        f"{top[0]['store_id']} --to {to_store}`"
    )


def _cmd_transfer_history(args) -> None:
    """List recent cross-store transfer apply events.

    Scans ``pending_actions`` for rows whose ``narrative`` starts
    with ``Transfer suggestion:`` -- the marker that
    ``shopai transfer apply`` writes when it enqueues. Parses the
    narrative to extract from/to stores, then surfaces a chronological
    audit trail of cross-store transfers.

    Filters: ``--from``, ``--to``, ``--engine`` narrow the scan;
    ``--limit`` caps row count (default 20).
    """
    as_json = bool(getattr(args, "json", False))
    from_store = (getattr(args, "from_store", "") or "").strip()
    to_store = (getattr(args, "to_store", "") or "").strip()
    engine = (getattr(args, "engine", "") or "").strip()
    limit = max(1, int(getattr(args, "limit", 20) or 20))

    try:
        from core.approval.queue import get_approval_queue
    except Exception as exc:  # noqa: BLE001
        if as_json:
            print(json.dumps(
                {"status": "error", "error": str(exc)},
                indent=2, default=str,
            ))
        else:
            print(f"Error: approval queue unavailable: {exc}")
        sys.exit(1)
        return

    rows: list[dict] = []
    try:
        from core.transfer_narrative import SQL_LIKE_CLAUSE
        queue = get_approval_queue()
        clauses = [SQL_LIKE_CLAUSE]
        params: list = []
        if engine:
            clauses.append("engine = ?")
            params.append(engine)
        if to_store:
            # store_id on the row IS the target store (transfer
            # apply always enqueues with store_id=to_store).
            clauses.append("store_id = ?")
            params.append(to_store)
        params.append(limit)
        sql = (
            "SELECT id, engine, action_type, capability, "
            "store_id, status, narrative, proposed_at, "
            "decided_at FROM pending_actions WHERE "
            + " AND ".join(f"({c})" for c in clauses)
            + " ORDER BY proposed_at DESC LIMIT ?"
        )
        with queue._conn:
            raw_rows = queue._conn.execute(sql, params).fetchall()
        for r in raw_rows:
            parsed_from = _parse_from_store_from_narrative(
                r["narrative"] or "",
            )
            # --from filter is applied AFTER narrative parse since
            # the source store isn't in any indexed column.
            if from_store and parsed_from != from_store:
                continue
            rows.append({
                "action_id": r["id"],
                "engine": r["engine"],
                "action_type": r["action_type"],
                "capability": r["capability"],
                "from_store": parsed_from,
                "to_store": r["store_id"],
                "status": r["status"],
                "proposed_at": r["proposed_at"],
                "decided_at": r["decided_at"],
                "narrative": r["narrative"] or "",
            })
    except Exception as exc:  # noqa: BLE001
        if as_json:
            print(json.dumps(
                {"status": "error", "error": str(exc)},
                indent=2, default=str,
            ))
        else:
            print(f"Error: queue scan failed: {exc}")
        sys.exit(1)
        return

    envelope = {
        "filters": {
            "from_store": from_store,
            "to_store": to_store,
            "engine": engine,
            "limit": limit,
        },
        "count": len(rows),
        "rows": rows,
    }

    if as_json:
        print(json.dumps(envelope, indent=2, default=str))
        return

    if not rows:
        bits = []
        if from_store:
            bits.append(f"from={from_store}")
        if to_store:
            bits.append(f"to={to_store}")
        if engine:
            bits.append(f"engine={engine}")
        scope = f" ({', '.join(bits)})" if bits else ""
        print(f"No transfer history{scope}.")
        return

    print(f"Transfer history ({len(rows)} row(s)):")
    print()
    now = time.time()
    for r in rows:
        ts = r["proposed_at"] or 0.0
        try:
            age_h = max(0.0, (now - float(ts)) / 3600.0)
            age_str = (
                f"{age_h:.1f}h ago" if age_h < 48
                else f"{age_h / 24:.1f}d ago"
            )
        except (TypeError, ValueError):
            age_str = "?"
        print(
            f"  {r['engine']}/{r['action_type']}  "
            f"{r['from_store'] or '?'} -> {r['to_store'] or '?'}  "
            f"[{r['status']}]  {age_str}"
        )
        print(f"      action_id: {r['action_id']}")
    # Drill-down hint: transfer history shows WHAT was
    # enqueued; transfer outcomes shows whether those
    # transfers actually paid off (cross-store learning
    # measurement). Natural follow-up question.
    print()
    print(
        "  Drill down: `shopai transfer outcomes` "
        "to measure payoff."
    )


def _parse_from_store_from_narrative(narrative: str) -> str:
    """Extract the source store from a transfer apply narrative.

    Thin wrapper around
    :func:`core.transfer_narrative.parse_source_store` so the
    callers (transfer history, transfer outcomes) don't have to
    do their own imports. The shared module owns the format
    contract; this file consumes it.
    """
    from core.transfer_narrative import parse_source_store
    return parse_source_store(narrative)



def _cmd_transfer_outcomes(args) -> None:
    """Close the empire-AGI loop: for transferred actions that
    EXECUTED on the target store, surface their measured outcomes
    so operators can see whether cross-store learning is paying off.

    Workflow:
      1. Scan ``pending_actions`` for EXECUTED rows whose narrative
         marks them as transfer-applied (same parser as ``transfer
         history``).
      2. For each, fetch outcomes via ``queue.get_outcomes()``.
      3. Aggregate counts (positive / negative / neutral) and
         revenue. Per-row + overall rollup.

    Filters mirror ``transfer history``: ``--from``, ``--to``,
    ``--engine``, ``--limit``.
    """
    as_json = bool(getattr(args, "json", False))
    from_store = (getattr(args, "from_store", "") or "").strip()
    to_store = (getattr(args, "to_store", "") or "").strip()
    engine = (getattr(args, "engine", "") or "").strip()
    limit = max(1, int(getattr(args, "limit", 20) or 20))

    def _emit_error(msg: str) -> None:
        if as_json:
            print(json.dumps(
                {"status": "error", "error": msg},
                indent=2, default=str,
            ))
        else:
            print(f"Error: {msg}")
        sys.exit(1)

    try:
        from core.approval.queue import get_approval_queue
    except Exception as exc:  # noqa: BLE001
        _emit_error(f"approval queue unavailable: {exc}")
        return

    try:
        from core.transfer_narrative import SQL_LIKE_CLAUSE
        queue = get_approval_queue()
        clauses = [
            "status = 'executed'",
            SQL_LIKE_CLAUSE,
        ]
        params: list = []
        if engine:
            clauses.append("engine = ?")
            params.append(engine)
        if to_store:
            clauses.append("store_id = ?")
            params.append(to_store)
        params.append(limit)
        sql = (
            "SELECT id, engine, action_type, capability, "
            "store_id, narrative, decided_at "
            "FROM pending_actions WHERE "
            + " AND ".join(clauses)
            + " ORDER BY decided_at DESC LIMIT ?"
        )
        with queue._conn:
            raw_rows = queue._conn.execute(sql, params).fetchall()
    except Exception as exc:  # noqa: BLE001
        _emit_error(f"queue scan failed: {exc}")
        return

    rows: list[dict] = []
    rollup = {
        "actions_with_outcomes": 0,
        "actions_without_outcomes": 0,
        "positive_total": 0,
        "negative_total": 0,
        "neutral_total": 0,
        "revenue_total": 0.0,
    }

    for r in raw_rows:
        parsed_from = _parse_from_store_from_narrative(
            r["narrative"] or "",
        )
        if from_store and parsed_from != from_store:
            continue

        try:
            outcomes = queue.get_outcomes(r["id"]) or []
        except Exception as exc:  # noqa: BLE001
            logger.debug(
                "transfer outcomes: get_outcomes(%s) raised: %s",
                r["id"], exc,
            )
            outcomes = []

        from core.approval.outcome_aggregator import (
            aggregate_outcomes,
        )
        per_row = aggregate_outcomes(outcomes)

        if outcomes:
            rollup["actions_with_outcomes"] += 1
        else:
            rollup["actions_without_outcomes"] += 1
        rollup["positive_total"] += per_row.positive
        rollup["negative_total"] += per_row.negative
        rollup["neutral_total"] += per_row.neutral
        rollup["revenue_total"] += per_row.revenue

        rows.append({
            "action_id": r["id"],
            "engine": r["engine"],
            "action_type": r["action_type"],
            "capability": r["capability"],
            "from_store": parsed_from,
            "to_store": r["store_id"],
            "decided_at": r["decided_at"],
            "outcome_count": len(outcomes),
            "positive_outcomes": per_row.positive,
            "negative_outcomes": per_row.negative,
            "neutral_outcomes": per_row.neutral,
            "revenue": per_row.revenue,
        })

    envelope = {
        "filters": {
            "from_store": from_store,
            "to_store": to_store,
            "engine": engine,
            "limit": limit,
        },
        "count": len(rows),
        "rollup": rollup,
        "rows": rows,
    }

    if as_json:
        print(json.dumps(envelope, indent=2, default=str))
        return

    if not rows:
        bits = []
        if from_store:
            bits.append(f"from={from_store}")
        if to_store:
            bits.append(f"to={to_store}")
        if engine:
            bits.append(f"engine={engine}")
        scope = f" ({', '.join(bits)})" if bits else ""
        print(f"No executed transfers{scope}.")
        return

    print(
        f"Transfer outcomes ({len(rows)} executed transfer(s)):"
    )
    print()
    for r in rows:
        if r["outcome_count"] == 0:
            polarity = "no outcomes yet"
        else:
            parts = []
            if r["positive_outcomes"]:
                parts.append(f"+{r['positive_outcomes']}")
            if r["negative_outcomes"]:
                parts.append(f"-{r['negative_outcomes']}")
            if r["neutral_outcomes"]:
                parts.append(f"~{r['neutral_outcomes']}")
            polarity = " ".join(parts) or "0"
        rev_str = (
            f"  rev=${r['revenue']:.2f}"
            if r["revenue"] else ""
        )
        print(
            f"  {r['engine']}/{r['action_type']}  "
            f"{r['from_store'] or '?'} -> {r['to_store'] or '?'}  "
            f"[{polarity}]{rev_str}"
        )
        print(f"      action_id: {r['action_id']}")
    print()
    print(
        f"Rollup: {rollup['actions_with_outcomes']} with outcomes, "
        f"{rollup['actions_without_outcomes']} without.  "
        f"+{rollup['positive_total']} / "
        f"-{rollup['negative_total']} / "
        f"~{rollup['neutral_total']}  "
        f"rev=${rollup['revenue_total']:.2f}"
    )


def _cmd_transfer_credit(args) -> None:
    """Attribute downstream transfer outcomes back to source
    actions.

    Walks the chain backward via ``core.transfer_credit``: for
    every target-side transfer-applied action, parses the
    narrative to find the source (engine, action_type, store)
    and aggregates the action's outcomes back to that source
    tuple. Operators see "loyalty/mint on store-A inspired 5
    successful transfers with $250 attributed revenue."
    """
    as_json = bool(getattr(args, "json", False))
    source_store = (
        getattr(args, "source_store", "") or ""
    ).strip()
    engine = (getattr(args, "engine", "") or "").strip()
    limit = max(1, int(getattr(args, "limit", 20) or 20))

    def _emit_error(msg: str) -> None:
        if as_json:
            print(json.dumps(
                {"status": "error", "error": msg},
                indent=2, default=str,
            ))
        else:
            print(f"Error: {msg}")
        sys.exit(1)

    try:
        from core.approval.queue import get_approval_queue
        from core.transfer_credit import compute_transfer_credits
    except Exception as exc:  # noqa: BLE001
        _emit_error(f"approval queue unavailable: {exc}")
        return

    queue = get_approval_queue()

    try:
        credits = compute_transfer_credits(
            queue,
            source_store=source_store or None,
            engine=engine or None,
        )
    except Exception as exc:  # noqa: BLE001
        _emit_error(f"credit graph computation failed: {exc}")
        return

    top = credits[:limit]
    rows = [
        {
            "source_store": c.source_store,
            "engine": c.engine,
            "action_type": c.action_type,
            "transfer_count": c.transfer_count,
            "executed_count": c.executed_count,
            "positive_outcomes": c.positive_outcomes,
            "negative_outcomes": c.negative_outcomes,
            "revenue": c.revenue,
            "score": c.score,
        }
        for c in top
    ]

    envelope = {
        "filters": {
            "source_store": source_store,
            "engine": engine,
            "limit": limit,
        },
        "total_returned": len(rows),
        "total_keys": len(credits),
        "rows": rows,
    }

    if as_json:
        print(json.dumps(envelope, indent=2, default=str))
        return

    if not rows:
        bits = []
        if source_store:
            bits.append(f"source={source_store}")
        if engine:
            bits.append(f"engine={engine}")
        scope = f" ({', '.join(bits)})" if bits else ""
        print(f"No transfer credit attributable{scope}.")
        return

    label = (
        f"Transfer credit ({len(rows)} of "
        f"{len(credits)} source action(s) ranked):"
    )
    print(label)
    print()
    for i, r in enumerate(rows, start=1):
        score_str = (
            "n/a" if r["score"] is None
            else f"{r['score']:.0%}"
        )
        rev_str = (
            f"  rev=${r['revenue']:,.2f}"
            if r["revenue"]
            else ""
        )
        print(
            f"  [{i}] {r['source_store']}/{r['engine']}/"
            f"{r['action_type']}"
        )
        print(
            f"      transfers={r['transfer_count']}  "
            f"executed={r['executed_count']}  "
            f"+{r['positive_outcomes']} / "
            f"-{r['negative_outcomes']}  "
            f"score={score_str}{rev_str}"
        )


def _build_health_sections() -> dict[str, Any]:
    """Helper used by ``_cmd_status`` to build the new
    health sections (substrate / cycle / bridge). Each
    subsection probes its source independently; any subsystem
    failure marks its section as checked=False without
    breaking the rest.

    Returns a dict with shape:
      {fleet, substrate, cycle, bridge, overall}
    where ``overall`` is one of ``ok`` / ``warn`` / ``error``.
    """
    envelope: dict[str, Any] = {
        "fleet": {"checked": False},
        "substrate": {"checked": False},
        "cycle": {"checked": False},
        "bridge": {"checked": False},
        "overall": "unknown",
    }

    # ── Fleet section ───────────────────────────────────────
    try:
        sm = _get_store_manager()
        stores = sm.list_stores() or []
        try:
            from data_pipeline.store.sync_service import (
                SyncService,
            )
            sync = SyncService().get_status() or {}
            sync_stores = sync.get("stores") or []
        except Exception:
            sync_stores = []
        last_sync_map = {
            s.get("store_id"): s.get("last_sync")
            for s in sync_stores
        }
        ages = []
        for s in stores:
            sid = s.get("store_id", "")
            ls = last_sync_map.get(sid)
            if ls is not None:
                ages.append(time.time() - float(ls))
        envelope["fleet"] = {
            "checked": True,
            "store_count": len(stores),
            "max_sync_age_hours": (
                round(max(ages) / 3600.0, 1)
                if ages else None
            ),
            "stores_never_synced": sum(
                1 for s in stores
                if last_sync_map.get(s.get("store_id"))
                is None
            ),
        }
    except Exception as exc:  # noqa: BLE001
        logger.debug("status: fleet raised: %s", exc)
        envelope["fleet"] = {
            "checked": False, "error": str(exc),
        }

    # ── Substrate section ──────────────────────────────────
    try:
        from core.capability_planner import (
            auto_demote as _ad,
            capability_degradations,
        )
        from core.capability_planner.\
capability_overrides import load_overrides
        overrides = load_overrides()
        n_override = len(overrides.entries)
        n_demoted = len(overrides.demoted_names())
        n_promoted = len(overrides.promoted_names())
        try:
            degs = capability_degradations(
                recent_window_seconds=86400 * 7,
                baseline_window_seconds=86400 * 30,
            )
            n_degs = len(degs)
        except Exception:
            n_degs = 0
        try:
            n_dem_cand = sum(
                1 for c in _ad.find_demote_candidates()
                if c.get("blocked_by") is None
            )
        except Exception:
            n_dem_cand = 0
        try:
            n_rel_cand = len(
                _ad.find_release_candidates(),
            )
        except Exception:
            n_rel_cand = 0
        envelope["substrate"] = {
            "checked": True,
            "override_total": n_override,
            "demoted": n_demoted,
            "promoted": n_promoted,
            "recent_degradations": n_degs,
            "demote_candidates": n_dem_cand,
            "release_candidates": n_rel_cand,
        }
    except Exception as exc:  # noqa: BLE001
        logger.debug("status: substrate raised: %s", exc)
        envelope["substrate"] = {
            "checked": False, "error": str(exc),
        }

    # ── Cycle section ──────────────────────────────────────
    try:
        from core.autonomous import (
            cycle_alerts as _ca,
            cycle_history as _ch,
        )
        stats = _ch.cycle_stats(since_seconds=86400)
        alerts_list = _ca.compute_cycle_alerts(
            window_seconds=86400 * 7,
        )
        last_age_h = None
        if stats.get("last_run_at"):
            last_age_h = round(
                (time.time() - float(stats["last_run_at"]))
                / 3600.0, 1,
            )
        # Threshold state -- effective value + whether a
        # persistent override is set + whether auto-relax
        # bridge is enabled.
        try:
            from core.autonomous import (
                auto_relax as _ar,
                cycle_overrides as _co,
            )
            ovr = _co.load_overrides()
            cycle_threshold = {
                "effective": _co.resolve_threshold(),
                "override_set": (
                    "auto_execute_threshold" in ovr
                ),
                "auto_relax_enabled": _ar.is_enabled(),
            }
        except Exception as exc:  # noqa: BLE001
            logger.debug(
                "status: threshold info raised: %s", exc,
            )
            cycle_threshold = None
        # Cross-store transfer activity (24h rollup) --
        # cron operator wants to see "the cycle proposed N
        # transfers since yesterday".
        try:
            from core.autonomous import (
                transfer_history as _th,
            )
            tr_stats = _th.transfer_stats(
                since_seconds=86400,
            )
            transfers_24h = tr_stats.get("total", 0)
        except Exception:
            transfers_24h = 0
        # Fleet revenue trend over the last 7 days
        # (the autonomous loop's ROI signal).
        try:
            from core.autonomous import (
                cycle_revenue_history as _crh,
            )
            rev_trend = _crh.revenue_trend(
                since_seconds=86400 * 7,
            )
        except Exception:
            rev_trend = None
        # Pause state -- show if active so operators see
        # "cycle is halted" at a glance.
        try:
            from core.autonomous import (
                cycle_pause as _cp,
            )
            pause_state = _cp.get_pause_state()
        except Exception:
            pause_state = {"active": False}
        try:
            pause_freq = _cp.pause_frequency(
                since_seconds=86400 * 7,
            )
        except Exception:
            pause_freq = None
        envelope["cycle"] = {
            "checked": True,
            "runs_24h": stats["total_runs"],
            "executed_runs_24h": stats["executed_runs"],
            "last_run_age_hours": last_age_h,
            "alert_count": len(alerts_list),
            "alert_kinds": [a.kind for a in alerts_list],
            "threshold": cycle_threshold,
            "transfers_24h": transfers_24h,
            "revenue_trend_7d": rev_trend,
            "pause": pause_state,
            "pause_frequency_7d": pause_freq,
        }
    except Exception as exc:  # noqa: BLE001
        logger.debug("status: cycle raised: %s", exc)
        envelope["cycle"] = {
            "checked": False, "error": str(exc),
        }

    # ── Bridge section ─────────────────────────────────────
    try:
        from core.capability_planner import (
            auto_demote as _ad,
            auto_demote_history as _adh,
        )
        config = _ad.config_summary()
        # Activity in the last 24h
        events_24h = _adh.recent_history(
            since_seconds=86400,
        )
        thrashing = _adh.find_thrashing(
            window_seconds=86400 * 14,
        )
        envelope["bridge"] = {
            "checked": True,
            "gate_enabled": config["enabled"],
            "drop_threshold": config["drop_threshold"],
            "recovery_threshold": config[
                "recovery_threshold"
            ],
            "demoted_24h": sum(
                1 for e in events_24h
                if e.kind == "demote"
            ),
            "released_24h": sum(
                1 for e in events_24h
                if e.kind == "release"
            ),
            "thrashing_count": len(thrashing),
        }
    except Exception as exc:  # noqa: BLE001
        logger.debug("status: bridge raised: %s", exc)
        envelope["bridge"] = {
            "checked": False, "error": str(exc),
        }

    # ── Engine health regressions + chronics (count) ───────
    # Cheap enough (engine_health_history reads) to include
    # in the verdict + score, so either signal trips
    # --line / --quiet without a separate command.
    regression_count = 0
    chronic_count = 0
    try:
        from core.approval.engine_health_history import (
            find_regressions,
            find_chronic_warnings,
        )
        regs = find_regressions(
            min_drop=3.0,
            baseline_window_seconds=86400.0 * 7.0,
            latest_window_seconds=86400.0 * 1.0,
            min_baseline_samples=3,
        )
        regression_count = len(regs)
        chronics = find_chronic_warnings(
            sample_window_seconds=86400.0 * 7.0,
            min_samples=3,
            healthy_score_floor=7,
        )
        chronic_count = len(chronics)
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "status: engine health count raised: %s", exc,
        )
    envelope["regression_count"] = regression_count
    envelope["chronic_count"] = chronic_count

    # Engine outcome-trend alerts (compute_engine_alerts)
    # are a DIFFERENT signal than regressions/chronic --
    # they come from approval-queue outcome scores, not
    # engine_health scores. Separate count for cron
    # monitors.
    outcome_alert_count = 0
    try:
        from core.approval.outcome_trends import (
            compute_engine_alerts,
        )
        from core.approval.queue import get_approval_queue
        outcome_alert_count = len(compute_engine_alerts(
            get_approval_queue(),
            recent_hours=24.0,
            baseline_hours=168.0,
            threshold=0.2,
            min_recent=3,
        ))
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "status: outcome alert count raised: %s", exc,
        )
    envelope["outcome_alert_count"] = outcome_alert_count

    # ── Overall verdict ────────────────────────────────────
    # OK if every section is checked and no cycle alerts +
    # no thrashing + not paused + no regressions + no
    # chronic warnings. WARN if any of: cycle alerts,
    # thrashing, paused, regressions, chronic warnings.
    # ERROR if any section failed to load.
    sections = [
        envelope["fleet"],
        envelope["substrate"],
        envelope["cycle"],
        envelope["bridge"],
    ]
    cycle_pause = (
        envelope["cycle"].get("pause") or {}
    )
    if any(not s.get("checked") for s in sections):
        envelope["overall"] = "error"
    elif (
        envelope["cycle"].get("alert_count", 0) > 0
        or envelope["bridge"].get("thrashing_count", 0) > 0
        or cycle_pause.get("active", False)
        or regression_count > 0
        or chronic_count > 0
        or outcome_alert_count > 0
    ):
        envelope["overall"] = "warn"
    else:
        envelope["overall"] = "ok"

    # Composite health score (0-100). Single number for
    # operators to track over time / wire to dashboards.
    # Starts at 100, penalized by each problem signal.
    score = 100
    if any(not s.get("checked") for s in sections):
        # Subsystem failures dominate the score
        score -= 40
    alerts = envelope["cycle"].get("alert_count", 0)
    score -= min(30, alerts * 10)
    thrash = envelope["bridge"].get(
        "thrashing_count", 0,
    )
    score -= min(20, thrash * 10)
    if cycle_pause.get("active", False):
        score -= 15
    # Each regression is -5pts, capped at -20 (so 4+
    # regressions all bottom out together rather than
    # dwarfing every other signal).
    score -= min(20, regression_count * 5)
    # Chronic warnings (stuck-state) are softer than
    # regressions (active deterioration): -3pts each,
    # capped at -15. A chronic warning is still a real
    # problem but the merchant isn't actively dying.
    score -= min(15, chronic_count * 3)
    # Engine outcome alerts (queue-level outcome score
    # degradations) are operationally similar to chronic
    # warnings but at the outcome layer, not the
    # engine_health layer. Same penalty band.
    score -= min(15, outcome_alert_count * 3)
    rt = (
        envelope["cycle"].get("revenue_trend_7d") or {}
    )
    if rt and rt.get("snapshots", 0) >= 2:
        delta_pct = float(rt.get("delta_pct", 0) or 0)
        if delta_pct < -5:
            score -= 10  # significant decline
        elif delta_pct > 5:
            score = min(100, score + 5)  # bonus growth
    envelope["health_score"] = max(0, min(100, score))
    return envelope


def _render_health_sections(envelope: dict[str, Any]) -> None:
    """Text-mode renderer for the substrate/cycle/bridge
    health sections produced by ``_build_health_sections``.
    Designed to render BELOW the existing ``shopai status``
    output -- adds a Health header + per-section lines."""
    tag = {
        "ok": "[OK]",
        "warn": "[WARN]",
        "error": "[ERR]",
        "unknown": "[?]",
    }.get(envelope["overall"], "[?]")
    score = envelope.get("health_score")
    if isinstance(score, int):
        print(f"Health {tag}  score={score}/100")
    else:
        print(f"Health {tag}")

    fleet = envelope["fleet"]
    if fleet.get("checked"):
        age_str = (
            f"max sync age {fleet['max_sync_age_hours']}h"
            if fleet.get("max_sync_age_hours") is not None
            else "no sync data"
        )
        print(
            f"  Fleet:     {fleet['store_count']} store(s)  "
            f"{age_str}  "
            f"{fleet['stores_never_synced']} never-synced"
        )
    else:
        print(
            f"  Fleet:     ERROR ({fleet.get('error')})"
        )

    sub = envelope["substrate"]
    if sub.get("checked"):
        print(
            f"  Substrate: {sub['override_total']} override(s) "
            f"({sub['demoted']}d/{sub['promoted']}p)  "
            f"{sub['recent_degradations']} degradation(s)  "
            f"{sub['demote_candidates']} dem-cand  "
            f"{sub['release_candidates']} rel-cand"
        )
    else:
        print(
            f"  Substrate: ERROR ({sub.get('error')})"
        )

    cyc = envelope["cycle"]
    if cyc.get("checked"):
        last = (
            f"{cyc['last_run_age_hours']}h ago"
            if cyc.get("last_run_age_hours") is not None
            else "never"
        )
        alerts_str = ""
        if cyc["alert_count"] > 0:
            alerts_str = (
                f"  [{cyc['alert_count']} alert(s): "
                f"{', '.join(cyc['alert_kinds'])}]"
            )
        thr = cyc.get("threshold") or {}
        thr_str = ""
        if thr:
            tag = ""
            if thr.get("override_set"):
                tag = "*"
            relax = ""
            if thr.get("auto_relax_enabled"):
                relax = " (auto-relax ON)"
            thr_str = (
                f"  threshold {thr['effective']:.2f}"
                f"{tag}{relax}"
            )
        tx_str = ""
        if cyc.get("transfers_24h", 0) > 0:
            tx_str = (
                f"  {cyc['transfers_24h']} transfer(s)"
            )
        rev_str = ""
        rt = cyc.get("revenue_trend_7d") or {}
        if rt and rt.get("snapshots", 0) >= 2:
            sign = "+" if rt["delta"] >= 0 else ""
            rev_str = (
                f"  rev 7d: {sign}${rt['delta']:,.0f} "
                f"({sign}{rt['delta_pct']:.1f}%)"
            )
        pause_str = ""
        ps = cyc.get("pause") or {}
        if ps.get("active"):
            pause_str = "  [PAUSED]"
        regr_str = ""
        regr_count = int(
            envelope.get("regression_count", 0) or 0
        )
        if regr_count > 0:
            regr_str = f"  [{regr_count} regression(s)]"
        chronic_str = ""
        chronic_count = int(
            envelope.get("chronic_count", 0) or 0
        )
        if chronic_count > 0:
            chronic_str = f"  [{chronic_count} chronic]"
        oa_str = ""
        oa_count = int(
            envelope.get("outcome_alert_count", 0) or 0
        )
        if oa_count > 0:
            oa_str = f"  [{oa_count} outcome alert(s)]"
        print(
            f"  Cycle:     {cyc['runs_24h']} run(s)/24h  "
            f"last: {last}{alerts_str}{thr_str}{tx_str}"
            f"{rev_str}{pause_str}{regr_str}{chronic_str}"
            f"{oa_str}"
        )
    else:
        print(
            f"  Cycle:     ERROR ({cyc.get('error')})"
        )

    br = envelope["bridge"]
    if br.get("checked"):
        gate = "ON" if br["gate_enabled"] else "OFF"
        thrash = ""
        if br["thrashing_count"] > 0:
            thrash = (
                f"  [{br['thrashing_count']} thrashing]"
            )
        print(
            f"  Bridge:    gate {gate}  "
            f"24h: {br['demoted_24h']}d/"
            f"{br['released_24h']}r{thrash}"
        )
    else:
        print(
            f"  Bridge:    ERROR ({br.get('error')})"
        )

    if envelope["overall"] == "warn":
        print()
        # Tailor the hint to the dominant warn signal so
        # operators get the most actionable next command,
        # not a generic 'run daily-brief'.
        regr_count = int(
            envelope.get("regression_count", 0) or 0
        )
        chronic_count = int(
            envelope.get("chronic_count", 0) or 0
        )
        outcome_count = int(
            envelope.get("outcome_alert_count", 0) or 0
        )
        if regr_count > 0:
            cmd = "shopai approvals health-regressions"
            print(
                f"  Next: engine health degraded -- "
                f"run `{cmd}` for the affected engines."
            )
        elif chronic_count > 0:
            cmd = "shopai approvals chronic-warnings"
            print(
                f"  Next: engine health degraded -- "
                f"run `{cmd}` for the affected engines."
            )
        elif outcome_count > 0:
            print(
                "  Next: engine outcome scores degrading "
                "-- run `shopai engine alerts` for the "
                "affected engines."
            )
        else:
            print(
                "  Next: investigate alerts above + run "
                "``shopai daily-brief`` for activity "
                "detail."
            )
    elif envelope["overall"] == "error":
        print()
        print(
            "  Next: subsystem failed to load -- check "
            "logs / `data/` permissions."
        )


def _cmd_niche(args) -> None:
    """Wave 74 + 77 + 83: niche operator discovery + update +
    auto-suggest."""
    from engines._niche_priority import (
        niche_cluster_focus, supported_niches,
    )

    as_json = bool(getattr(args, "json", False))
    show_one = (getattr(args, "show", None) or "").strip()
    by_store = bool(getattr(args, "by_store", False))
    set_pair = getattr(args, "set", None)
    suggest_store = (
        getattr(args, "suggest", None) or ""
    ).strip()
    apply_suggestion = bool(getattr(args, "apply", False))

    # Wave 83: --suggest STORE_ID auto-detects from product
    # catalog. Optional --apply commits via Wave 77 path.
    if suggest_store:
        from engines._niche_detector import suggest_niche_for_store
        sm = _get_store_manager()
        det = suggest_niche_for_store(
            suggest_store, store_manager=sm,
        )
        if det is None:
            msg = f"Store '{suggest_store}' not found"
            if as_json:
                print(json.dumps({
                    "status": "error", "error": msg,
                }, indent=2))
            else:
                print(f"Error: {msg}")
            sys.exit(1)
            return
        applied = False
        if apply_suggestion and det.is_actionable:
            res = sm.update_store_niche(
                suggest_store, det.suggested,
            )
            applied = not res.get("error")
        payload = {
            "store_id": suggest_store,
            "suggested": det.suggested,
            "confidence": det.confidence,
            "products_analyzed": det.products_analyzed,
            "total_matches": det.total_matches,
            "top_score_ratio": det.top_score_ratio,
            "scores": det.scores,
            "actionable": det.is_actionable,
            "applied": applied,
        }
        if as_json:
            print(json.dumps(payload, indent=2, default=str))
            return
        print(
            f"Niche suggestion for store '{suggest_store}':"
        )
        print()
        print(
            f"  Analyzed:    {det.products_analyzed} product(s)"
        )
        print(
            f"  Top matches: {det.total_matches} keyword hit(s)"
        )
        if det.confidence == "no_data":
            print()
            print(
                "  Verdict: NO DATA -- catalog empty or no "
                "niche keywords matched. Seed products first "
                "or set manually:"
            )
            print(
                f"    shopai niche --set {suggest_store} "
                "<beauty|fashion|home|tech|food>"
            )
            return
        marker = {
            "high": "[HI ]",
            "medium": "[MED]",
            "low": "[LOW]",
        }.get(det.confidence, "[ ? ]")
        print(
            f"  Suggested:   {marker} {det.suggested} "
            f"(confidence={det.confidence}, "
            f"top_ratio={det.top_score_ratio:.0%})"
        )
        # Per-niche breakdown when there's something interesting
        breakdown = sorted(
            ((n, s) for n, s in det.scores.items() if s > 0),
            key=lambda kv: -kv[1],
        )
        if breakdown:
            print()
            print("  Scores:")
            for niche, score in breakdown:
                print(f"    {niche:<10}  {score:>4}")
        print()
        if applied:
            print(
                f"  Applied: store '{suggest_store}' niche "
                f"now set to '{det.suggested}'."
            )
        elif apply_suggestion and not det.is_actionable:
            print(
                "  --apply refused: confidence too low. "
                "Seed more products or set manually."
            )
        elif det.is_actionable:
            print(
                f"  Apply: `shopai niche --suggest "
                f"{suggest_store} --apply` (commits via "
                "Wave 77 in-place update)"
            )
        else:
            print(
                "  Confidence too low to auto-apply. "
                "Catalog is heterogeneous -- pick a niche "
                "manually via `shopai niche --set`."
            )
        return

    # Wave 77: --set STORE NICHE updates an existing store
    if set_pair:
        store_id, new_niche = set_pair[0], set_pair[1]
        valid_niches = set(supported_niches()) | {"general"}
        new_niche_norm = new_niche.strip().lower()
        if new_niche_norm not in valid_niches:
            msg = (
                f"Invalid niche '{new_niche}'. "
                f"Supported: {sorted(valid_niches)}"
            )
            if as_json:
                print(json.dumps({
                    "status": "error", "error": msg,
                }, indent=2))
            else:
                print(f"Error: {msg}")
            sys.exit(1)
            return
        sm = _get_store_manager()
        result = sm.update_store_niche(
            store_id, new_niche_norm,
        )
        if as_json:
            print(json.dumps(result, indent=2, default=str))
            return
        if result.get("error"):
            print(f"Error: {result['error']}")
            sys.exit(1)
            return
        print(
            f"Store '{store_id}' niche updated to "
            f"'{new_niche_norm}'."
        )
        focus = niche_cluster_focus(new_niche_norm)
        if focus:
            top3 = " -> ".join(focus[:3])
            print(f"  Cluster priority: {top3}")
        return

    # --by-store mode: list stores grouped by niche
    if by_store:
        sm = _get_store_manager()
        try:
            stores = sm.list_stores() or []
        except Exception:  # noqa: BLE001
            stores = []
        by_niche: dict[str, list[str]] = {}
        unset: list[str] = []
        for s in stores:
            sid = s.get("store_id") or ""
            n = (s.get("niche") or "").strip().lower()
            if not n or n == "general":
                unset.append(sid)
            else:
                by_niche.setdefault(n, []).append(sid)
        if as_json:
            print(json.dumps({
                "by_niche": by_niche,
                "unset_or_general": unset,
            }, indent=2, default=str))
            return
        print("Stores by niche:")
        print()
        for niche in sorted(by_niche):
            ids = ", ".join(sorted(by_niche[niche]))
            print(f"  {niche:<10}  {ids}")
        if unset:
            print()
            print(
                f"  (unset / general): {', '.join(sorted(unset))}"
            )
            print()
            print(
                "  Hint: `shopai store add --niche beauty ...` "
                "to bias future cycles."
            )
        return

    # --show: drill one niche
    if show_one:
        focus = niche_cluster_focus(show_one)
        if as_json:
            print(json.dumps({
                "niche": show_one.lower(),
                "cluster_focus": focus,
            }, indent=2))
            return
        if not focus:
            print(
                f"No preference defined for niche '{show_one}' "
                "(uses base lifecycle priority)."
            )
            return
        print(f"Niche '{show_one.lower()}' cluster priorities:")
        print()
        for i, cluster in enumerate(focus, 1):
            print(f"  {i}. {cluster}")
        return

    # Default: list all supported
    niches = supported_niches()
    if as_json:
        print(json.dumps({
            "niches": [
                {
                    "name": n,
                    "cluster_focus": niche_cluster_focus(n),
                }
                for n in niches
            ],
        }, indent=2))
        return
    print(
        f"Supported niches ({len(niches)})  "
        "-- Wave 73 niche-aware orchestrator"
    )
    print()
    print(f"  {'niche':<10}  top 3 clusters")
    for n in niches:
        focus = niche_cluster_focus(n)
        top3 = " -> ".join(focus[:3])
        print(f"  {n:<10}  {top3}")
    print()
    print(
        "  Drill: `shopai niche --show <name>` -- full list"
    )
    print(
        "  Stores: `shopai niche --by-store` -- per-store tags"
    )


def _cmd_cro_variants(args) -> None:
    """W963-11: variant candidate generator."""
    from engines.cro_variants import CroVariantsEngine

    product_id = getattr(args, "product_id", None)
    title = getattr(args, "title", None)
    description = getattr(args, "description", None)
    category = getattr(args, "category", None)
    price = getattr(args, "price", None)
    strategies = getattr(args, "strategies", "")
    as_json = bool(getattr(args, "json", False))

    payload: dict[str, Any] = {"data": {}}
    if product_id:
        payload["data"]["product_id"] = product_id
    if title or description or category or price is not None:
        # Build synthetic product from CLI flags.
        product: dict[str, Any] = {}
        if title:
            product["title"] = title
        if description:
            product["description"] = description
        if category:
            product["category"] = category
        if price is not None:
            product["price"] = float(price)
        payload["data"]["product"] = product
    if strategies:
        payload["data"]["strategies"] = strategies

    result = CroVariantsEngine().run(payload)

    if as_json:
        print(json.dumps(result, indent=2, default=str))
        return

    data = result.get("data") or {}
    if result.get("status") != "success":
        err = result.get("error") or "unknown"
        print(f"cro variants: ERROR  {err}")
        return

    title_out = data.get("product_title", "?")
    cat = data.get("product_category", "")
    px = data.get("product_price", 0.0)
    variants = data.get("variants") or {}

    print(
        f"CRO variants for: {title_out}  "
        f"(category={cat or '?'}  current=${px:.2f})"
    )
    print()
    if "title" in variants:
        print("  Title variants:")
        for v in variants["title"]:
            print(
                f"    [{v.get('angle'):<8}] "
                f"{v.get('text')}"
            )
        print()
    if "description" in variants:
        print("  Description variants:")
        for v in variants["description"]:
            text = v.get("text", "")
            preview = text[:140] + (
                "..." if len(text) > 140 else ""
            )
            print(f"    [{v.get('strategy'):<13}] {preview}")
        print()
    if "price" in variants:
        print("  Price variants:")
        for v in variants["price"]:
            print(
                f"    [{v.get('label'):<13}] "
                f"${v.get('price'):.2f}"
            )
        print()
    print(f"  NEXT: {data.get('next_action', '')}")


def _cmd_cold_start_orchestrate(args) -> None:
    """W963-14: end-to-end cold-start chain."""
    from engines.cold_start_orchestrator import (
        ColdStartOrchestratorEngine,
    )

    store_id = getattr(args, "store_id", None)
    niche = getattr(args, "niche", "beauty")
    blog_id = getattr(args, "blog_id", None)
    apply_flag = bool(getattr(args, "yes", False))
    as_json = bool(getattr(args, "json", False))

    payload: dict[str, Any] = {
        "data": {
            "niche": niche,
            "apply": apply_flag,
        },
    }
    if store_id:
        payload["data"]["store_id"] = store_id
    if blog_id:
        payload["data"]["blog_id"] = blog_id

    result = ColdStartOrchestratorEngine().run(payload)

    if as_json:
        print(json.dumps(result, indent=2, default=str))
        return

    data = result.get("data") or {}
    if result.get("status") != "success":
        err = result.get("error") or "unknown"
        print(f"cold-start: ERROR  {err}")
        return

    print(f"Cold-start orchestrator")
    print()
    print(f"  Headline: {data.get('headline', '?')}")
    print(f"  Store:    {data.get('store_id') or '(fleet)'}")
    print(f"  Niche:    {data.get('niche', '?')}")
    print(
        f"  Mode:     {'COMMIT' if data.get('apply_mode') else 'PREVIEW'}"
    )
    print()

    steps = data.get("steps") or {}

    diag = steps.get("diagnose") or {}
    print(
        f"  Diagnose:      verdict={diag.get('verdict', '?')}  "
        f"gates={diag.get('gates_passed', 0)}/"
        f"{diag.get('gates_total', 6)}"
    )
    if "product_seed" in steps:
        ps = steps["product_seed"]
        print(
            f"  Product seed:  "
            f"candidates={ps.get('candidates_generated', 0)}  "
            f"pending={ps.get('pending_actions', 0)}"
        )
    bs = steps.get("blog_seed") or {}
    print(
        f"  Blog seed:     "
        f"candidates={bs.get('candidates_generated', 0)}  "
        f"pending={bs.get('pending_actions', 0)}"
    )
    cro = steps.get("cro") or {}
    print(
        f"  CRO preview:   "
        f"sample={cro.get('sample_product', '?')[:40]}  "
        f"title={cro.get('title_variant_count', 0)} "
        f"desc={cro.get('description_variant_count', 0)} "
        f"price={cro.get('price_variant_count', 0)}"
    )
    ch = steps.get("channels") or {}
    print(
        f"  Channels:      "
        f"ads={'OK' if ch.get('ads_ready') else 'XX'}  "
        f"email={'OK' if ch.get('email_ready') else 'XX'}  "
        f"pinterest={'OK' if ch.get('pinterest_ready') else 'XX'}  "
        f"tiktok={'OK' if ch.get('tiktok_ready') else 'XX'}"
    )
    er = steps.get("earnings") or {}
    print(
        f"  Earnings 24h:  "
        f"{er.get('currency', 'USD')} "
        f"{er.get('revenue_24h', 0.0):.2f}  "
        f"orders={er.get('orders_24h', 0)}  "
        f"verdict={er.get('verdict', '?')}"
    )
    print()

    actions = data.get("next_actions") or []
    if actions:
        print(f"  Next actions ({len(actions)}):")
        for i, a in enumerate(actions, 1):
            print(f"    {i}. {a}")
    else:
        print("  No next actions -- store earning + healthy.")


def _cmd_chat_respond(args) -> None:
    """W963-13: customer message intent classification + draft."""
    from engines.customer_chat import CustomerChatEngine

    message = getattr(args, "message", "")
    customer_name = getattr(args, "customer_name", None)
    order_id = getattr(args, "order_id", None)
    store_name = getattr(args, "store_name", None)
    use_llm = bool(getattr(args, "use_llm", False))
    as_json = bool(getattr(args, "json", False))

    payload: dict[str, Any] = {
        "data": {
            "message": message,
            "use_llm": use_llm,
        },
    }
    if customer_name:
        payload["data"]["customer_name"] = customer_name
    if order_id:
        payload["data"]["order_id"] = order_id
    if store_name:
        payload["data"]["store_name"] = store_name

    result = CustomerChatEngine().run(payload)

    if as_json:
        print(json.dumps(result, indent=2, default=str))
        return

    data = result.get("data") or {}
    if result.get("status") != "success":
        err = result.get("error") or "unknown"
        print(f"chat respond: ERROR  {err}")
        return

    intent = data.get("intent", "?")
    conf = data.get("intent_confidence", 0.0)
    review = data.get("requires_human_review", False)
    used_llm = data.get("used_llm", False)

    print(f"Customer chat response")
    print()
    print(f"  Message:      \"{message}\"")
    print(f"  Intent:       {intent}  (confidence={conf:.2f})")
    print(
        f"  Review:       "
        f"{'⚠️ HUMAN REVIEW REQUIRED' if review else 'OK to send'}"
    )
    print(
        f"  LLM refined:  "
        f"{'yes' if used_llm else 'no (template baseline)'}"
    )
    print()
    print(f"  Draft response:")
    print(f"  ---")
    for line in data.get("draft_response", "").splitlines():
        print(f"  {line}")
    print(f"  ---")
    print()
    print(f"  NEXT: {data.get('next_action', '')}")


