def _cmd_blog_candidates(args) -> None:
    """W963-6: SEO blog content seed generator."""
    from engines.content_publisher import ContentPublisherEngine

    niche = getattr(args, "niche", None)
    count = int(getattr(args, "count", 10) or 10)
    apply_flag = bool(getattr(args, "apply", False))
    blog_id = getattr(args, "blog_id", None)
    as_json = bool(getattr(args, "json", False))

    if apply_flag and not blog_id:
        print(
            "blog-candidates: --apply requires --blog-id "
            "(gid://shopify/Blog/...). Find your blog id via "
            "Shopify Admin -> Online Store -> Blog Posts "
            "-> select blog -> URL contains the id."
        )
        return

    payload: dict[str, Any] = {"data": {"count": count}}
    if niche:
        payload["data"]["niche"] = niche
    if apply_flag:
        payload["data"]["apply_candidates"] = True
        payload["data"]["blog_id"] = blog_id

    result = ContentPublisherEngine().run(payload)

    if as_json:
        print(json.dumps(result, indent=2, default=str))
        return

    data = result.get("data") or {}
    if result.get("status") != "success" or not data:
        err = result.get("error") or "unknown error"
        print(f"blog-candidates: ERROR  {err}")
        return

    niche_out = data.get("niche") or ""
    returned = data.get("count_returned", 0)
    requested = data.get("count_requested", 0)
    candidates = data.get("candidates", [])
    pending = data.get("pending_actions") or []
    next_action = data.get("next_action", "")

    if not niche_out:
        print(f"Blog-candidates  {next_action}")
        return

    print(
        f"Blog-candidates  niche={niche_out}  "
        f"returned={returned}/{requested}"
        + (f"  pending={len(pending)}" if pending else "")
    )
    print()
    for i, c in enumerate(candidates, 1):
        title = c.get("title", "(untitled)")
        kw = c.get("keyword", "")
        tags = ", ".join((c.get("tags") or [])[:3])
        excerpt = c.get("meta_excerpt", "")
        print(f"  {i:>2}. {title}")
        print(f"      target keyword: {kw}")
        if tags:
            print(f"      tags: {tags}")
        if excerpt:
            preview = excerpt[:100] + ("..." if len(excerpt) > 100 else "")
            print(f"      excerpt: {preview}")
        print()
    if pending:
        print(f"  Enqueued {len(pending)} pending article(s):")
        for p in pending[:3]:
            print(
                f"    - {p.get('pending_action_id', '?')}: "
                f"{p.get('narrative', '')[:70]}"
            )
        if len(pending) > 3:
            print(f"    ... and {len(pending) - 3} more")
        print()
    print(f"  NEXT: {next_action}")


def _cmd_earn_bootstrap(args) -> None:
    """W963-5: one-command cold-start chain orchestrator."""
    from engines.earn_bootstrap import EarnBootstrapEngine

    niche = getattr(args, "niche", None)
    count = int(getattr(args, "count", 20) or 20)
    store_id = getattr(args, "store_id", None)
    yes_flag = bool(getattr(args, "yes", False))
    as_json = bool(getattr(args, "json", False))

    payload: dict[str, Any] = {"data": {"count": count}}
    if niche:
        payload["data"]["niche"] = niche
    if store_id:
        payload["data"]["store_id"] = store_id
    if yes_flag:
        payload["data"]["apply"] = True

    result = EarnBootstrapEngine().run(payload)

    if as_json:
        print(json.dumps(result, indent=2, default=str))
        return

    data = result.get("data") or {}
    if result.get("status") != "success" or not data:
        err = result.get("error") or "unknown error"
        print(f"earn-bootstrap: ERROR  {err}")
        return

    chain_v = data.get("chain_verdict", "unknown")
    diag = data.get("diagnostic") or {}
    summary = data.get("candidates_summary") or {}
    pending = data.get("pending_actions") or []
    next_steps = data.get("next_steps") or []

    verdict_mk = {
        "ready":        "[$$]",
        "cold_seeded":  "[>>]",
        "cold_pending": "[..]",
        "cold_skipped": "[X ]",
        "partial":      "[~~]",
        "unknown":      "[ ?]",
    }.get(chain_v, "[ ?]")

    print(
        f"Earn-Bootstrap  niche={niche or '(none)'}  "
        f"{verdict_mk} {chain_v}"
    )
    print()
    print("  Diagnostic:")
    print(
        f"    verdict={diag.get('verdict', '?')}  "
        f"gates={diag.get('passed', 0)}/{diag.get('total', 0)}"
    )
    next_a = diag.get("next_action", "")
    if next_a:
        print(f"    -> {next_a}")
    print()

    if summary:
        top = summary.get("top_names") or []
        print(
            f"  Candidates generated: {summary.get('count', 0)}"
        )
        for n in top[:3]:
            print(f"    - {n}")
        pr = summary.get("price_range") or {}
        if pr:
            print(
                f"    price range: ${pr.get('min', 0):.0f} - "
                f"${pr.get('max', 0):.0f}"
            )
        print()

    if pending:
        print(f"  Enqueued {len(pending)} pending action(s):")
        for p in pending[:3]:
            print(
                f"    - {p.get('pending_action_id', '?')}: "
                f"{p.get('narrative', '')[:60]}"
            )
        if len(pending) > 3:
            print(f"    ... and {len(pending) - 3} more")
        print()

    print("  Next steps:")
    for step in next_steps:
        print(f"    {step}")


def _cmd_earnings(args) -> None:
    """W963-4: shopai earnings — output-side measurement."""
    from engines.earnings_report import EarningsReportEngine

    hours = getattr(args, "hours", None)
    days = float(getattr(args, "days", 1.0) or 1.0)
    window_hours = float(hours) if hours is not None else days * 24.0
    store_id = getattr(args, "store_id", None)
    as_json = bool(getattr(args, "json", False))

    payload: dict[str, Any] = {
        "data": {"window_hours": window_hours},
    }
    if store_id:
        payload["data"]["store_id"] = store_id

    result = EarningsReportEngine().run(payload)

    if as_json:
        print(json.dumps(result, indent=2, default=str))
        return

    data = result.get("data") or {}
    if result.get("status") != "success" or not data:
        err = result.get("error") or "unknown error"
        print(f"earnings: ERROR  {err}")
        return

    sid = data.get("store_id") or "(default)"
    wh = data.get("window_hours", 0.0)
    current = data.get("current") or {}
    previous = data.get("previous") or {}
    verdict = data.get("verdict", "unknown")
    delta = data.get("delta", 0.0)
    delta_pct = data.get("delta_pct", 0.0)
    cur_rev = current.get("revenue", 0.0)
    prev_rev = previous.get("revenue", 0.0)
    cur_count = current.get("order_count", 0)
    prev_count = previous.get("order_count", 0)
    cur_aov = current.get("avg_order_value", 0.0)
    currency = (
        current.get("currency")
        or previous.get("currency")
        or "USD"
    )

    verdict_mk = {
        "earning":   "[$$]",
        "flat":      "[~~]",
        "declining": "[\\\\]",
        "cold":      "[..]",
        "unknown":   "[ ?]",
    }.get(verdict, "[ ?]")

    delta_sign = "+" if delta >= 0 else ""
    print(
        f"Earnings  store={sid}  window={wh:g}h  "
        f"{verdict_mk} {verdict}"
    )
    print()
    print(
        f"  Current window:  "
        f"{currency} {cur_rev:>9.2f}  "
        f"{cur_count:>3} order(s)  AOV={cur_aov:.2f}"
    )
    print(
        f"  Previous window: "
        f"{currency} {prev_rev:>9.2f}  "
        f"{prev_count:>3} order(s)"
    )
    print(
        f"  Delta:           "
        f"{currency} {delta_sign}{delta:>8.2f}  "
        f"({delta_sign}{delta_pct:.1f}%)"
    )
    print()
    if verdict == "cold":
        print(
            "  Cold — no orders. Check: products exist?  "
            "(`shopai revenue-readiness`)  Ads firing?  "
            "(`shopai marketing-status`)"
        )
    elif verdict == "declining":
        print(
            "  Declining — investigate: "
            "`shopai engine alerts` + `shopai cycle status`"
        )
    elif verdict == "earning":
        print("  Money in. Keep the cycle going.")


def _cmd_product_candidates(args) -> None:
    """W963-2: cold-start product candidate generator.

    Read-only. Emits N candidates for the operator to review.
    A future Phase 2 will wire SHOPIFY_CREATE_PRODUCT (status=
    DRAFT) behind the approval queue with a --apply flag.
    """
    from engines.product_sourcer import ProductSourcerEngine

    niche = getattr(args, "niche", None)
    count = int(getattr(args, "count", 20) or 20)
    price_max = getattr(args, "price_max", None)
    as_json = bool(getattr(args, "json", False))
    apply_flag = bool(getattr(args, "apply", False))
    mint_direct = bool(getattr(args, "mint_direct", False))

    if mint_direct and not apply_flag:
        print(
            "product-candidates: --mint-direct requires --apply"
        )
        return

    payload: dict[str, Any] = {"data": {}}
    if niche:
        payload["data"]["niche"] = niche
    if count:
        payload["data"]["count"] = count
    if price_max is not None:
        payload["data"]["price_max"] = price_max
    if apply_flag:
        payload["data"]["apply_candidates"] = True
        # Default: require_approval=True (queue path). Only flip
        # to False when operator explicitly passed --mint-direct.
        payload["data"]["require_approval"] = not mint_direct

    result = ProductSourcerEngine().run(payload)

    if as_json:
        print(json.dumps(result, indent=2, default=str))
        return

    data = result.get("data") or {}
    if result.get("status") != "success" or not data:
        err = result.get("error") or "unknown error"
        print(f"product-candidates: ERROR  {err}")
        return

    niche_out = data.get("niche") or ""
    returned = data.get("count_returned", 0)
    requested = data.get("count_requested", 0)
    candidates = data.get("candidates", [])
    next_action = data.get("next_action", "")

    if not niche_out:
        print(f"Product-candidates  {next_action}")
        return

    pending = data.get("pending_actions") or []
    minted = data.get("minted_drafts") or []

    print(
        f"Product-candidates  niche={niche_out}  "
        f"returned={returned}/{requested}"
        + (f"  pending={len(pending)}" if pending else "")
        + (f"  minted={len(minted)}" if minted else "")
    )
    print()
    if not candidates:
        print(f"  (no candidates)  -> {next_action}")
        return
    for i, c in enumerate(candidates, 1):
        price = c.get("suggested_price", 0)
        name = c.get("name", "(unnamed)")
        cat = c.get("category", "")
        tags = ", ".join((c.get("tags") or [])[:3])
        print(f"  {i:>2}. {name}")
        print(
            f"      ${price:>6.2f}  [{cat}]  "
            f"price_range=${c.get('price_min', 0):.0f}-"
            f"${c.get('price_max', 0):.0f}  "
            f"tags={tags}"
        )
        desc = c.get("description", "")
        if desc:
            print(f"      \"{desc}\"")
        vendor = c.get("vendor_hint", "")
        if vendor:
            print(f"      vendor: {vendor}")
        print()
    if pending:
        print(f"  Enqueued {len(pending)} pending action(s):")
        for p in pending[:5]:
            print(
                f"    - {p.get('pending_action_id', '?')}: "
                f"{p.get('narrative', '')[:70]}"
            )
        if len(pending) > 5:
            print(f"    ... and {len(pending) - 5} more")
        print()
    if minted:
        ok = sum(1 for m in minted if m.get("status") == "minted")
        err = sum(1 for m in minted if m.get("status") == "error")
        print(f"  Mint results: {ok} created, {err} failed")
        for m in minted[:3]:
            status = m.get("status", "?")
            name = m.get("params", {}).get("title", "?")
            err_text = m.get("error", "") or ""
            tail = (
                f" ({err_text[:50]})"
                if status == "error" else ""
            )
            print(f"    - {status}: {name[:40]}{tail}")
        print()
    print(f"  NEXT: {next_action}")


def _cmd_revenue_readiness(args) -> None:
    """W963-1: revenue-readiness diagnostic.

    Returns the 6-gate verdict for the supplied --store (or the
    fleet-default zero-stats baseline when omitted). The
    diagnostic is read-only — no Shopify writes.
    """
    from engines.revenue_readiness import RevenueReadinessEngine

    store_id = getattr(args, "store_id", None)
    as_json = bool(getattr(args, "json", False))

    payload = {"data": {"store_id": store_id} if store_id else {}}
    result = RevenueReadinessEngine().run(payload)

    if as_json:
        print(json.dumps(result, indent=2, default=str))
        return

    data = result.get("data") or {}
    if result.get("status") != "success" or not data:
        err = result.get("error") or "unknown error"
        print(f"revenue-readiness: ERROR  {err}")
        return

    verdict = data.get("verdict") or "unknown"
    passed = data.get("passed", 0)
    total = data.get("total", 0)
    sid = data.get("store_id") or "(fleet)"

    verdict_marker = {
        "earning_active": "[$$]",
        "growing":         "[>>]",
        "building_traction": "[+ ]",
        "cold_start":      "[..]",
        "unknown":         "[ ?]",
    }.get(verdict, "[ ?]")

    print(
        f"Revenue-readiness  store={sid}  "
        f"{verdict_marker} {verdict}  ({passed}/{total} gates)"
    )
    print()
    for g in data.get("gates", []):
        marker = {
            "ready":   "[OK ]",
            "partial": "[~~]",
            "missing": "[XX]",
        }.get(g.get("status"), "[ ?]")
        name = g.get("name", "?")
        detail = g.get("detail", "")
        print(f"  {marker} {name:<22} {detail}")
        action = g.get("next_action") or ""
        if action and g.get("status") != "ready":
            print(f"    -> {action}")
    print()
    next_action = data.get("next_action") or ""
    if next_action:
        print(f"  NEXT: {next_action}")
    else:
        print("  All gates passed — monitor + iterate.")


def _cmd_go_live(args) -> None:
    """Wave 55: go-live readiness pre-flight."""
    from engines._go_live_check import (
        run_go_live_check, summarize,
    )

    as_json = bool(getattr(args, "json", False))
    checks = run_go_live_check()
    summary = summarize(checks)

    if as_json:
        print(json.dumps({
            "summary": summary,
            "checks": [
                {
                    "name": c.name, "status": c.status,
                    "detail": c.detail, "fix": c.fix,
                }
                for c in checks
            ],
        }, indent=2, default=str))
        return

    print("Go-live readiness check")
    print()
    for c in checks:
        marker = {
            "pass": "[OK ]",
            "warn": "[WRN]",
            "fail": "[BAD]",
        }.get(c.status, "[ ? ]")
        print(
            f"  {marker} {c.name:<26} {c.detail}"
        )
        if c.fix and c.status != "pass":
            print(f"    fix: {c.fix}")
    print()
    verdict_marker = (
        "[OK ]" if summary["verdict"] == "ready_to_go_live"
        else "[BAD]"
    )
    print(
        f"  {verdict_marker} VERDICT: "
        f"{summary['verdict']}  "
        f"(pass={summary['pass']} "
        f"warn={summary['warn']} "
        f"fail={summary['fail']})"
    )
    if summary["verdict"] == "ready_to_go_live":
        print()
        print(
            "  Next: `shopai cycle schedule` and install "
            "the emitted cron line."
        )
    else:
        print()
        print(
            "  Resolve [BAD] items before scheduling live "
            "cycles. [WRN] are advisory."
        )


