def _cmd_mind_explain(args) -> None:
    """Explain a goal: show its plan + imagined outcome."""
    mind = _get_mind()
    if mind.goal_manager is None:
        print("No goal manager wired into the Mind.")
        return
    goal = mind.goal_manager.get(args.goal_id)
    if goal is None:
        print(f"Goal {args.goal_id!r} not found.")
        return

    print()
    print("─" * 70)
    print(f"  GOAL: {goal['what']}")
    print("─" * 70)
    print(f"  id:         {goal['id']}")
    print(f"  state:      {goal['state']}")
    print(f"  source:     {goal.get('source') or '(manual)'}")
    print(f"  priority:   {goal['priority']:.2f}")
    print(f"  impact:     {goal['impact']:.2f}")
    print(f"  urgency:    {goal['urgency']:.2f}")
    print(f"  confidence: {goal['confidence']:.2f}")
    print(f"  cost:       {goal['cost']:.2f}")
    print(f"  progress:   {goal['progress']:.0%}")
    if goal.get("why"):
        print(f"  why:        {goal['why']}")

    if mind.planner is not None:
        plan = mind.planner.plan(goal)
        print()
        print(f"Plan ({plan.backend}, {plan.step_count()} steps):")
        for i, step in enumerate(plan.steps, 1):
            print(f"  {i}. {step.description}")
            if step.rationale:
                print(f"      ↳ {step.rationale[:60]}")

        if mind.imagination is not None:
            imagined = mind.imagination.imagine_plan(plan)
            print()
            print(
                f"Imagined: score={imagined.expected_score:.2f}, "
                f"cost={imagined.expected_cost:.2f}, "
                f"confidence={imagined.overall_confidence:.2f}"
            )

    children = mind.goal_manager.children(goal["id"])
    if children:
        print()
        print(f"Sub-goals ({len(children)}):")
        for c in children:
            print(f"  [{c['state']}] {c['what']}")

    events = mind.goal_manager.events(goal["id"], limit=10)
    if events:
        print()
        print(f"Recent events ({len(events)}):")
        for e in events[:5]:
            print(f"  {e['event_type']:14s} {e['old_value']} → {e['new_value']}")
    print()


def _cmd_mind_think(args) -> None:
    """Ad-hoc free-form question through the cognitive context.

    Builds a `self_context` block from the SelfModel narrative +
    top goals, renders the `mind.think` prompt template, and asks
    the LLM via the requested role.
    """
    question = " ".join(args.question).strip()
    if not question:
        print("Empty question; nothing to think about.")
        return

    mind = _get_mind()

    # Build the context block
    context_parts: list[str] = []
    if not args.no_context:
        if mind.self_model is not None:
            try:
                narrative = mind.self_model.narrative()
                if narrative and "no data" not in narrative.lower():
                    context_parts.append(f"Who I am: {narrative}")
            except Exception:  # noqa: BLE001
                pass
        if mind.goal_manager is not None:
            try:
                active = mind.goal_manager.active(limit=5)
                if active:
                    goal_lines = "\n".join(
                        f"  - {g['what']} (priority {g['priority']:.2f})"
                        for g in active[:5]
                    )
                    context_parts.append(f"Current goals:\n{goal_lines}")
            except Exception:  # noqa: BLE001
                pass

    self_context = "\n\n".join(context_parts)
    if self_context:
        self_context = self_context + "\n\n"

    # Render via the prompt library
    try:
        from core.system.prompt_library import render_prompt
    except Exception:
        print("PromptLibrary not available.")
        return

    rendered = render_prompt(
        "mind.think",
        self_context=self_context,
        question=question,
    )
    if rendered is None:
        print("mind.think prompt template missing.")
        return

    # Resolve the LLM
    try:
        from core.system.llm_adapter import get_llm
        llm = get_llm()
    except Exception:
        print("LLM adapter not available.")
        return

    if not llm.is_available():
        print(
            "No LLM providers configured. Set SHOPAI_OLLAMA_URL or "
            "OPENAI_API_KEY or ANTHROPIC_API_KEY to enable thinking."
        )
        return

    print()
    print(f"Q: {question}")
    print()
    print("...thinking...")

    response = llm.ask(
        role=args.role,
        prompt=rendered.user,
        system_prompt=rendered.system,
    )

    print()
    if not response.success:
        print(f"LLM error: {response.error}")
        return
    print(response.text.strip())
    print()
    print(
        f"  ({response.provider}/{response.model}, "
        f"{response.tokens_used} tokens, {response.duration_s:.2f}s"
        f"{', via fallback' if response.fallback_used else ''})"
    )


def _cmd_mind_llm_status(args=None) -> None:
    """Show LLM provider availability and stats."""
    try:
        from core.system.llm_adapter import get_llm
        llm = get_llm()
    except Exception as exc:
        print(f"LLM adapter unavailable: {exc}")
        return

    info = llm.auto_configure() if not llm._checked else None
    stats = llm.get_stats()

    print()
    print("─" * 70)
    print("  LLM PROVIDER STATUS")
    print("─" * 70)
    print()
    print(f"Configured providers ({len(stats['configured'])}):")
    for name in stats["configured"]:
        cfg = llm._configs.get(name)
        if cfg:
            print(f"  - {name:25s} {cfg.provider}/{cfg.model}")
    print()
    print(f"Local Ollama models: {', '.join(stats['available_local']) or '(none)'}")
    print()
    print("Role mapping:")
    for role, model in sorted(stats["role_map"].items()):
        print(f"  {role:12s} → {model}")
    print()
    print(f"Fallback chain: {' → '.join(stats['fallback_chain'])}")
    print()
    if stats["models"]:
        print("Per-model stats:")
        for model, s in sorted(stats["models"].items()):
            avg_lat = s["total_time"] / s["calls"] if s["calls"] else 0
            print(
                f"  {model:25s} calls={s['calls']:4d} "
                f"errors={s['errors']:3d} "
                f"tokens={s['tokens']:6d} "
                f"avg={avg_lat:.2f}s"
            )
    else:
        print("Per-model stats: (no calls yet)")
    print()


# ── Sync Commands ────────────────────────────────────────────

def _cmd_sync(args) -> None:
    sm = _get_store_manager()
    from data_pipeline.store.sync_service import SyncService
    sync = SyncService(sm)

    if args.auto:
        print(f"Starting auto-sync (every {args.interval}s)...")
        print("Press Ctrl+C to stop.\n")
        sync.start_auto_sync(args.interval)
        try:
            while True:
                time.sleep(1)
        except KeyboardInterrupt:
            sync.stop_auto_sync()
            print("\nAuto-sync stopped.")
        return

    store_id = args.store_id or sm.active_store_id
    if not store_id:
        print("No store selected.")
        return

    print(f"Syncing {store_id}...")
    result = sync.sync_store(store_id)
    if result.get("status") == "success":
        synced = result.get("synced", {})
        print(f"✓ Sync complete ({result.get('duration_s', 0):.1f}s)")
        for dtype, info in synced.items():
            count = info.get("count", 0)
            errors = info.get("errors", []) or info.get("error", "")
            status = f"{count} records" if not errors else f"{count} records (errors: {errors})"
            print(f"  {dtype}: {status}")
    else:
        err = result.get("error", "unknown")
        print(f"✗ Sync failed: {err}")
        # Drill-down hint: connection-class errors point at
        # store connect; OAuth/scope-class errors point at
        # the live scope drift check. Both are read-only and
        # produce actionable diagnostics.
        err_lower = str(err).lower()
        print()
        if (
            "scope" in err_lower
            or "access_denied" in err_lower
        ):
            print(
                "  Next: `shopai shopify-scopes-live-check` "
                "(scope drift between manifest + live install)"
            )
        else:
            print(
                f"  Next: `shopai store connect {store_id}` "
                "(verify auth + endpoint reachability)"
            )


# ── Engine Commands ──────────────────────────────────────────

def _cmd_engines(*, by_goal: bool = False, unmapped: bool = False) -> None:
    from engines.registry import engine_count, list_engines

    engines = list_engines()

    if unmapped:
        # Show only engines absent from ENGINE_GOAL_MAP.
        from core.goals.engine_goal_map import ENGINE_GOAL_MAP
        without_goal = [
            name for name in engines if name not in ENGINE_GOAL_MAP
        ]
        if not without_goal:
            print("All registered engines have a primary-goal mapping.")
            return
        print(
            f"Unmapped engines ({len(without_goal)} of "
            f"{len(engines)} registered):"
        )
        for i, name in enumerate(without_goal, 1):
            print(f"  {i:3d}. {name}")
        return

    if by_goal:
        # Group by primary goal. Engines not in ENGINE_GOAL_MAP land
        # under "unmapped" so the operator can see what's not yet
        # attributable to brain-stack EMA.
        from core.goals.engine_goal_map import ENGINE_GOAL_MAP

        by: dict[str, list[str]] = {}
        for name in engines:
            goal = ENGINE_GOAL_MAP.get(name, "unmapped")
            by.setdefault(goal, []).append(name)

        # Stable order: known goals alphabetical, "unmapped" last.
        ordered_goals = sorted(g for g in by if g != "unmapped")
        if "unmapped" in by:
            ordered_goals.append("unmapped")

        print(f"Registered engines: {engine_count()} (grouped by goal)\n")
        for goal in ordered_goals:
            engines_for = by[goal]
            print(f"{goal} ({len(engines_for)}):")
            for name in sorted(engines_for):
                print(f"  {name}")
            print()
        return

    print(f"Registered engines: {engine_count()}\n")
    for i, name in enumerate(engines, 1):
        print(f"  {i:3d}. {name}")
    # Drill-down hint: bare list is alphabetical and doesn't
    # reveal which engines are actually doing work. Point at
    # `engines-stats` for the activity-ranked view, which
    # also surfaces wiring status.
    print()
    print(
        "  Drill down: `shopai engines-stats` for activity-"
        "ranked view + writeback wiring."
    )


def _engine_pulse_history_rows(
    engine: str, *, history_days: int,
) -> list[dict]:
    """Fetch + flatten engine_health_history events for the
    ``--history`` flag. Returns newest-first list of
    ``{recorded_at, recorded_at_iso, score, verdict}`` dicts.
    Source-failure isolated: a missing history module returns
    an empty list."""
    try:
        from core.approval.engine_health_history import recent_history
        days = max(1, int(history_days))
        events = recent_history(
            engine, since_seconds=86400.0 * days,
        )
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "engine pulse history fetch raised: %s", exc,
        )
        return []
    out: list[dict] = []
    for e in events:
        ts = float(getattr(e, "recorded_at", 0.0) or 0.0)
        iso = (
            time.strftime(
                "%Y-%m-%d %H:%M:%S", time.gmtime(ts),
            )
            if ts > 0 else "-"
        )
        out.append({
            "recorded_at": ts,
            "recorded_at_iso": iso,
            "score": int(getattr(e, "score", 0) or 0),
            "verdict": str(getattr(e, "verdict", "") or ""),
        })
    return out


def _cmd_engine_pulse(args) -> None:
    """Composite engine-health verdict.

    Single-engine mode: calls
    ``core.approval.engine_health.score_engine`` and renders a
    short, opinionated, cron-friendly summary. Exit code 1 when
    the verdict is ``unhealthy``, 0 otherwise.

    Fleet mode (``--fleet``): scores every engine in
    ``ENGINE_GOAL_MAP``, renders a leaderboard ranked by score
    ascending (sickest first). Exit code 1 if ANY engine is
    unhealthy, so monitoring pipelines fail-fast on fleet
    degradation.
    """
    as_json = bool(getattr(args, "json", False))
    fleet = bool(getattr(args, "fleet", False))
    if fleet:
        _engine_pulse_fleet(args, as_json=as_json)
        return

    # Fleet-only flags silently no-op in single-engine
    # mode. Warn so operators who passed them notice.
    ignored: list[str] = []
    if getattr(args, "verdict", None):
        ignored.append("--verdict")
    if getattr(args, "regressing", False):
        ignored.append("--regressing")
    if getattr(args, "chronic", False):
        ignored.append("--chronic")
    if ignored and not as_json:
        print(
            f"Warning: {', '.join(ignored)} requires "
            "--fleet. Flag(s) ignored in single-engine "
            "mode."
        )

    engine_name = getattr(args, "engine_name", None)
    if not engine_name:
        print(
            "Usage: shopai engine pulse <engine_name>  "
            "(or --fleet for the leaderboard)"
        )
        sys.exit(2)
        return

    from core.approval.engine_health import score_engine

    health = score_engine(engine_name)
    payload = health.to_dict()

    # Wave 20: attribution attached to JSON for tooling
    payload["attribution"] = None
    try:
        from engines._revenue_attribution import attribute_revenue
        ar_report = attribute_revenue(window_hours=168.0)
        for e in ar_report.per_engine:
            if e.engine == engine_name:
                payload["attribution"] = {
                    "attributed_revenue": round(
                        e.attributed_revenue, 2,
                    ),
                    "attributed_orders": e.attributed_orders,
                    "confidence": e.confidence,
                    "cluster": e.cluster,
                    "window_hours": 168.0,
                }
                break
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "engine_pulse json attribution probe raised: %s",
            exc,
        )

    history_rows: list[dict] = []
    if getattr(args, "history", False):
        history_rows = _engine_pulse_history_rows(
            engine_name,
            history_days=int(
                getattr(args, "history_days", 30) or 30,
            ),
        )
        payload["history"] = history_rows

    # Health-state flags (regressing / chronic / outcome
    # alert) -- JSON consumers care about these too;
    # they're already rendered in the text path
    # (c0d7c163) but were missing from the JSON envelope.
    # The three classes are distinct signals -- see
    # project_engine_health_observability.md for details.
    payload["regressing"] = False
    payload["chronic"] = False
    payload["outcome_alert"] = False
    try:
        from core.approval.engine_health_history import (
            find_regressions, find_chronic_warnings,
        )
        if any(
            r.engine == engine_name
            for r in find_regressions(
                min_drop=3.0,
                baseline_window_seconds=86400.0 * 7.0,
                latest_window_seconds=86400.0 * 1.0,
                min_baseline_samples=3,
            )
        ):
            payload["regressing"] = True
        if any(
            w.engine == engine_name
            for w in find_chronic_warnings(
                sample_window_seconds=86400.0 * 7.0,
                min_samples=3,
                healthy_score_floor=7,
            )
        ):
            payload["chronic"] = True
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "engine_pulse health-state probe (json) "
            "raised: %s", exc,
        )
    try:
        from core.approval.outcome_trends import (
            compute_engine_alerts,
        )
        from core.approval.queue import get_approval_queue
        if any(
            a.engine == engine_name
            for a in compute_engine_alerts(
                get_approval_queue(),
                recent_hours=24.0,
                baseline_hours=168.0,
                threshold=0.2,
                min_recent=3,
            )
        ):
            payload["outcome_alert"] = True
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "engine_pulse outcome_alert probe (json) "
            "raised: %s", exc,
        )

    # Writeback wire-up state (935a8116 + 5dc310e4 added
    # this to engine summary; mirror here so engine pulse
    # has the same JSON shape).
    payload["writeback"] = None
    try:
        from engines._writeback_audit import (
            audit_writeback_coverage,
        )
        wb_report = audit_writeback_coverage("engines")
        wb = next(
            (
                s for s in wb_report.engines
                if s.name == engine_name
            ),
            None,
        )
        if wb:
            payload["writeback"] = {
                "status": wb.status,
                "writers": list(wb.writer_files),
                "opt_ins": list(wb.opt_in_flags),
            }
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "engine_pulse writeback probe (json) "
            "raised: %s", exc,
        )

    if as_json:
        print(json.dumps(payload, indent=2, default=str))
    else:
        print(
            f"Engine pulse: {health.engine}  "
            f"score={health.score}/10  "
            f"verdict={health.verdict}"
        )
        if health.concerns:
            print()
            print("Concerns:")
            for c in health.concerns:
                print(f"  - {c}")
        sig = health.signals
        print()
        print("Signals:")
        print(
            f"  executed={sig.get('executed', 0)}  "
            f"failed={sig.get('failed', 0)}  "
            f"pending={sig.get('pending', 0)}"
        )
        os_val = sig.get("outcome_score")
        os_str = f"{float(os_val):.0%}" if os_val is not None else "n/a"
        print(
            f"  outcome_score={os_str}  "
            f"alert_streak_7d={sig.get('alert_streak_7d', 0)}  "
            f"alert_paused={sig.get('alert_paused', False)}"
        )
        # Writeback state -- does this engine actually act on
        # Shopify, or is it advisory-only? Operators
        # investigating a sick engine want to know whether the
        # 'sick' affects production writes or just
        # recommendations.
        try:
            from engines._writeback_audit import (
                audit_writeback_coverage,
            )
            wb_report = audit_writeback_coverage("engines")
            wb = next(
                (
                    s for s in wb_report.engines
                    if s.name == health.engine
                ),
                None,
            )
            if wb:
                writer_str = (
                    ", ".join(wb.writer_files)
                    if wb.writer_files else "none"
                )
                opt_str = (
                    ", ".join(wb.opt_in_flags)
                    if wb.opt_in_flags else "none"
                )
                print(
                    f"  writeback={wb.status}  "
                    f"writers=[{writer_str}]  "
                    f"opt_ins=[{opt_str}]"
                )
                # Smoke-test hint for wired engines mirrors
                # the engine summary line (032cfa49) so both
                # per-engine surfaces converge on the same
                # discovery path.
                if (
                    wb.status == "wired"
                    and any(
                        f.startswith("apply_")
                        for f in wb.opt_in_flags
                    )
                ):
                    print(
                        f"    Smoke-test: `shopai engine "
                        f"try-wireup {health.engine}` (dry-run)"
                    )
        except Exception as exc:  # noqa: BLE001
            logger.debug(
                "engine_pulse writeback probe raised: %s",
                exc,
            )
        # Wave 30: per-engine revenue history trend (opt-in
        # via --revenue-history). Renders before the current
        # snapshot line so operators see the trend first then
        # the latest number.
        if getattr(args, "revenue_history", False):
            try:
                from engines._attribution_snapshot import (
                    engine_revenue_history,
                )
                rev_rows = engine_revenue_history(
                    health.engine, limit=30,
                )
                if rev_rows:
                    print(
                        f"  Revenue history ({len(rev_rows)} "
                        f"data point(s), oldest first):"
                    )
                    import time as _t
                    now = _t.time()
                    for row in rev_rows[-15:]:
                        age = now - row["captured_at"]
                        if age < 3600:
                            age_str = f"{int(age/60)}m"
                        elif age < 86400:
                            age_str = f"{age/3600:.1f}h"
                        else:
                            age_str = f"{age/86400:.1f}d"
                        print(
                            f"    {age_str:<6} ago  "
                            f"${row['attributed_revenue']:>8,.2f}  "
                            f"orders={row['attributed_orders']:>3}  "
                            f"({row['confidence']})"
                        )
            except Exception as exc:  # noqa: BLE001
                logger.debug(
                    "engine_pulse revenue history "
                    "probe raised: %s", exc,
                )
        # Wave 20: revenue attribution probe -- has this engine
        # actually MADE money in the last 7 days? Cheap (uses
        # the cached attribution path; one Shopify call if no
        # snapshot exists yet).
        try:
            from engines._revenue_attribution import attribute_revenue
            ar_report = attribute_revenue(window_hours=168.0)
            engine_attr = next(
                (
                    e for e in ar_report.per_engine
                    if e.engine == health.engine
                ),
                None,
            )
            if engine_attr is not None and engine_attr.attributed_orders > 0:
                cluster_str = (
                    f" (cluster: {engine_attr.cluster})"
                    if engine_attr.cluster else ""
                )
                print(
                    f"  Revenue (7d): "
                    f"${engine_attr.attributed_revenue:,.2f}  "
                    f"orders={engine_attr.attributed_orders}  "
                    f"confidence={engine_attr.confidence}"
                    f"{cluster_str}"
                )
            elif ar_report.total_orders_in_window > 0:
                # Fleet has orders, this engine isn't attributed
                print(
                    f"  Revenue (7d): "
                    f"$0  (no attributed orders -- "
                    f"engine doesn't write tags, or tags "
                    f"don't match orders)"
                )
            # else: total fleet has zero orders, don't render
            # (nothing meaningful to say yet)
        except Exception as exc:  # noqa: BLE001
            logger.debug(
                "engine_pulse revenue probe raised: %s", exc,
            )
        # Engine-health state -- is THIS engine flagged as
        # regressing or chronically sick? Saves the operator
        # a separate ``approvals chronic-warnings`` call when
        # they're already drilling into one engine.
        try:
            from core.approval.engine_health_history import (
                find_regressions, find_chronic_warnings,
            )
            engine_name = health.engine
            regr_match = next(
                (
                    r for r in find_regressions(
                        min_drop=3.0,
                        baseline_window_seconds=86400.0 * 7.0,
                        latest_window_seconds=86400.0 * 1.0,
                        min_baseline_samples=3,
                    )
                    if r.engine == engine_name
                ),
                None,
            )
            chronic_match = next(
                (
                    w for w in find_chronic_warnings(
                        sample_window_seconds=86400.0 * 7.0,
                        min_samples=3,
                        healthy_score_floor=7,
                    )
                    if w.engine == engine_name
                ),
                None,
            )
            state_bits: list[str] = []
            if regr_match:
                state_bits.append(
                    f"REGRESSING (-{regr_match.drop:.1f}pts "
                    f"from baseline {regr_match.baseline_score:.1f})"
                )
            if chronic_match:
                state_bits.append(
                    f"CHRONIC (avg {chronic_match.avg_score:.1f}/10, "
                    f"n={chronic_match.samples})"
                )
            if state_bits:
                print(
                    f"  Health state: {' + '.join(state_bits)}"
                )
                # Hint: ``--history`` shows the trajectory
                # so operators investigating WHY can see
                # when the regression / chronic state
                # started.
                if not getattr(args, "history", False):
                    print(
                        f"    Run with --history to see "
                        f"the score trajectory."
                    )
        except Exception as exc:  # noqa: BLE001
            logger.debug(
                "engine_pulse health state probe raised: %s",
                exc,
            )
        # History trail -- newest first. Render as a tight
        # date / score / verdict table so trends are scannable.
        if getattr(args, "history", False):
            print()
            if history_rows:
                hd = int(getattr(args, "history_days", 30) or 30)
                # Cap text rendering at 30 events so a busy
                # daily-brief cadence (>1 event/day) doesn't
                # produce a wall of identical rows. JSON
                # output remains full.
                cap = 30
                shown = history_rows[:cap]
                more = max(
                    0, len(history_rows) - len(shown),
                )
                print(
                    f"History (last {hd}d, "
                    f"{len(history_rows)} event(s)"
                    + (
                        f", showing newest {len(shown)}"
                        if more else ""
                    )
                    + "):"
                )
                for r in shown:
                    ts_str = r["recorded_at_iso"]
                    print(
                        f"  {ts_str:<19s}  "
                        f"{r['score']:>2d}/10  "
                        f"{r['verdict']}"
                    )
                if more:
                    print(f"  ... +{more} older event(s)")
            else:
                print(
                    "History: (no recorded events in window)"
                )
        # Drill-down hint: pulse answers WHEN this engine is
        # sick / healthy; fleet answers WHERE. Complementary
        # surfaces. Render after the (optional) history trail
        # so it's the last line operators see.
        print()
        print(
            f"  Drill down: `shopai engine fleet "
            f"{health.engine}`"
        )

    if health.verdict == "unhealthy":
        sys.exit(1)


def _engine_pulse_fleet(args, *, as_json: bool) -> None:
    """Score every engine in ENGINE_GOAL_MAP, render leaderboard
    sorted by score asc (sickest first).
    """
    from core.approval.engine_health import score_engine
    from core.goals.engine_goal_map import ENGINE_GOAL_MAP

    verdict_filter = getattr(args, "verdict", None) or None

    # Single-engine flags silently no-op in fleet mode.
    # Warn so operators who passed them notice (mirror of
    # the inverse warning in _cmd_engine_pulse single
    # path).
    if (
        getattr(args, "history", False)
        and not as_json
    ):
        print(
            "Warning: --history is single-engine only "
            "and is ignored in --fleet mode."
        )

    results: list[dict] = []
    for engine in sorted(ENGINE_GOAL_MAP):
        try:
            health = score_engine(engine)
        except Exception as exc:  # noqa: BLE001
            logger.debug(
                "engine pulse fleet: score_engine raised for %s: %s",
                engine, exc,
            )
            continue
        if verdict_filter and health.verdict != verdict_filter:
            continue
        results.append(health.to_dict())

    # Rank: score asc, then engine name asc as tiebreak so order
    # is deterministic.
    results.sort(key=lambda r: (int(r["score"]), r["engine"]))

    # Pre-compute the regression + chronic sets so each row
    # can be tagged in one pass without N queue walks.
    regressing_set: set[str] = set()
    chronic_set: set[str] = set()
    try:
        from core.approval.engine_health_history import (
            find_regressions, find_chronic_warnings,
        )
        regressing_set = {
            r.engine for r in find_regressions(
                min_drop=3.0,
                baseline_window_seconds=86400.0 * 7.0,
                latest_window_seconds=86400.0 * 1.0,
                min_baseline_samples=3,
            )
        }
        chronic_set = {
            w.engine for w in find_chronic_warnings(
                sample_window_seconds=86400.0 * 7.0,
                min_samples=3,
                healthy_score_floor=7,
            )
        }
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "engine_pulse_fleet health probes raised: %s",
            exc,
        )

    # Pre-compute writeback status per engine (single
    # audit_writeback_coverage call covers the whole
    # fleet -- O(1) vs N).
    writeback_by_engine: dict[str, str] = {}
    try:
        from engines._writeback_audit import (
            audit_writeback_coverage,
        )
        wb_report = audit_writeback_coverage("engines")
        for s in wb_report.engines:
            writeback_by_engine[s.name] = s.status
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "engine_pulse_fleet writeback probe raised: %s",
            exc,
        )

    # Pre-compute outcome_alert set -- single
    # compute_engine_alerts call covers the whole fleet.
    outcome_alert_set: set[str] = set()
    try:
        from core.approval.outcome_trends import (
            compute_engine_alerts,
        )
        from core.approval.queue import get_approval_queue
        outcome_alert_set = {
            a.engine for a in compute_engine_alerts(
                get_approval_queue(),
                recent_hours=24.0,
                baseline_hours=168.0,
                threshold=0.2,
                min_recent=3,
            )
        }
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "engine_pulse_fleet outcome_alert probe "
            "raised: %s", exc,
        )

    # Apply --regressing / --chronic filters (after the
    # set is computed). Both can be combined (intersection
    # of the verdict + state filters).
    only_regressing = bool(
        getattr(args, "regressing", False),
    )
    only_chronic = bool(getattr(args, "chronic", False))
    if only_regressing:
        results = [
            r for r in results
            if r.get("engine", "") in regressing_set
        ]
    if only_chronic:
        results = [
            r for r in results
            if r.get("engine", "") in chronic_set
        ]

    if as_json:
        for row in results:
            engine = row.get("engine", "")
            row["regressing"] = engine in regressing_set
            row["chronic"] = engine in chronic_set
            row["outcome_alert"] = (
                engine in outcome_alert_set
            )
            # Writeback status string (matches the
            # uniform shape from engine pulse single
            # mode -- 'wired' / 'advisory' / 'partial' /
            # 'unknown').
            row["writeback_status"] = (
                writeback_by_engine.get(engine, "unknown")
            )
        print(json.dumps({
            "fleet": results,
            "verdict_counts": _verdict_rollup(results),
        }, indent=2, default=str))
    else:
        if not results:
            # Be specific about why no engines matched --
            # operators running --regressing on a quiet
            # fleet expect a "healthy" message, not just
            # "(no match)".
            reasons: list[str] = []
            if verdict_filter:
                reasons.append(
                    f"verdict={verdict_filter}"
                )
            if only_regressing:
                reasons.append("regressing")
            if only_chronic:
                reasons.append("chronic")
            if reasons:
                print(
                    f"(no engines match filter: "
                    f"{', '.join(reasons)})"
                )
                if only_regressing or only_chronic:
                    print(
                        "  Fleet is currently clear on "
                        "this signal class."
                    )
            else:
                print("(no engines match)")
        else:
            rollup = _verdict_rollup(results)
            print(
                f"Fleet pulse ({len(results)} engine(s)):  "
                f"healthy={rollup['healthy']}  "
                f"warning={rollup['warning']}  "
                f"unhealthy={rollup['unhealthy']}"
            )
            print()
            for r in results:
                concerns = r.get("concerns") or []
                concerns_str = (
                    f"  [{'; '.join(concerns[:2])}]"
                    if concerns else ""
                )
                tag_str = ""
                engine = r.get("engine", "")
                if engine in regressing_set:
                    tag_str += "  [REG]"
                if engine in chronic_set:
                    tag_str += "  [CHR]"
                print(
                    f"  {r['score']:>2d}/10  "
                    f"{r['verdict']:<9s}  "
                    f"{r['engine']:<28s}"
                    f"{concerns_str}{tag_str}"
                )
            # Drill-down hint: leaderboard is sorted sickest
            # first, so results[0] is the worst-off engine.
            # Point operator at the single-engine pulse with
            # history trail for the natural "what went wrong
            # and when?" follow-up.
            sickest = results[0].get("engine")
            if sickest:
                print()
                print(
                    f"  Drill down: `shopai engine pulse "
                    f"{sickest} --history`"
                )

    if any(r["verdict"] == "unhealthy" for r in results):
        sys.exit(1)


def _verdict_rollup(results: list[dict]) -> dict[str, int]:
    """Aggregate verdict counts; used by both text + JSON modes."""
    rollup = {"healthy": 0, "warning": 0, "unhealthy": 0}
    for r in results:
        v = r.get("verdict")
        if v in rollup:
            rollup[v] += 1
    return rollup


def _try_wireup_all(
    *, yes: bool, store_id: str | None, as_json: bool,
) -> None:
    """Iterate every wired engine and report per-engine status.

    Fleet smoke-test surface for the Phase 7 wireup pattern.
    Each engine's plan resolves independently; failures
    (unknown apply_flag, raise on yes-mode, etc.) are
    reported per-engine and don't abort the loop -- a CI
    gate using this command should look at the overall
    summary line + exit code.

    Exit 0 when every wired engine resolved cleanly;
    exit 1 when any engine raised during resolution OR
    raised during a --yes invocation.
    """
    try:
        from engines._writeback_audit import (
            audit_writeback_coverage,
        )
        report = audit_writeback_coverage("engines")
    except Exception as exc:  # noqa: BLE001
        if as_json:
            print(json.dumps({
                "status": "error",
                "error": f"writeback_audit_failed: {exc}",
            }, indent=2))
        else:
            print(f"Error: writeback audit failed: {exc}")
        sys.exit(1)
        return

    wired = sorted(
        (s for s in report.engines if s.status == "wired"),
        key=lambda s: s.name,
    )

    # Build tag map ONCE per fleet pass (single AST scan across
    # 42 applier files).
    tag_map: dict[str, list[str]] = {}
    try:
        from engines._tag_catalog import catalog_tags
        tag_cat = catalog_tags("engines")
        for tag_entry in tag_cat.entries:
            tag_map.setdefault(tag_entry.engine, []).append(
                tag_entry.tag,
            )
        tag_map = {
            eng: sorted(set(tags))
            for eng, tags in tag_map.items()
        }
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "try-wireup --all tag-catalog probe raised: %s", exc,
        )

    results: list[dict[str, Any]] = []
    any_error = False
    for wb in wired:
        entry: dict[str, Any] = {
            "engine": wb.name,
            "writers": list(wb.writer_files),
            "opt_in_flags": list(wb.opt_in_flags),
            "writes_tags": tag_map.get(wb.name, []),
        }
        apply_flag = next(
            (
                f for f in wb.opt_in_flags
                if f.startswith("apply_")
            ),
            None,
        )
        if apply_flag is None:
            entry["status"] = "error"
            entry["error"] = "no_apply_flag"
            any_error = True
            results.append(entry)
            continue
        entry["apply_flag"] = apply_flag

        if not yes:
            entry["status"] = "dry_run_ok"
            results.append(entry)
            continue

        # --yes path: actually invoke each engine.
        try:
            from engines.registry import get_engine
            engine = get_engine(wb.name)
        except Exception as exc:  # noqa: BLE001
            entry["status"] = "error"
            entry["error"] = f"engine_load: {exc}"
            any_error = True
            results.append(entry)
            continue
        if engine is None:
            entry["status"] = "error"
            entry["error"] = "engine_not_registered"
            any_error = True
            results.append(entry)
            continue

        try:
            from data_pipeline.store.data_provider import (
                DataProvider,
            )
            sm = _get_store_manager()
            data = (
                DataProvider(sm).get_data_for_engine(
                    wb.name, store_id,
                ) if store_id else {}
            )
        except Exception as exc:  # noqa: BLE001
            logger.debug(
                "try-wireup --all data raised for %s: %s",
                wb.name, exc,
            )
            data = {}
        if not isinstance(data, dict):
            data = {}
        data[apply_flag] = True

        try:
            engine_result = engine.run(data)
            entry["status"] = "ok"
            entry["engine_status"] = (
                engine_result.get("status", "?")
                if isinstance(engine_result, dict) else "?"
            )
        except Exception as exc:  # noqa: BLE001
            entry["status"] = "error"
            entry["error"] = f"engine_raised: {exc}"
            any_error = True
        results.append(entry)

    summary = {
        "total_wired": len(wired),
        "ok": sum(1 for r in results if r["status"] == "ok"),
        "dry_run_ok": sum(
            1 for r in results if r["status"] == "dry_run_ok"
        ),
        "errors": sum(
            1 for r in results if r["status"] == "error"
        ),
        "mode": "executed" if yes else "dry_run",
    }

    if as_json:
        print(json.dumps({
            "status": "ok" if not any_error else "error",
            "summary": summary,
            "engines": results,
        }, indent=2, default=str))
        if any_error:
            sys.exit(1)
        return

    mode_label = "EXECUTED" if yes else "DRY-RUN"
    print(
        f"Try-wireup all ({mode_label}): "
        f"{summary['total_wired']} wired engine(s)"
    )
    print()
    for r in results:
        status = r["status"]
        marker = (
            "[ok  ]" if status in ("ok", "dry_run_ok")
            else "[FAIL]"
        )
        engine_label = r["engine"][:30]
        line = f"  {marker} {engine_label:<30}  "
        if status == "ok":
            line += f"engine_status={r.get('engine_status', '?')}"
        elif status == "dry_run_ok":
            line += f"apply={r.get('apply_flag', '?')}"
        else:
            line += f"error={r.get('error', '?')}"
        print(line)
    print()
    if any_error:
        print(
            f"  Summary: {summary['errors']} engine(s) "
            "failed try-wireup."
        )
        sys.exit(1)
    if yes:
        print(
            f"  Summary: {summary['ok']} engine(s) "
            "invoked cleanly."
        )
    else:
        print(
            f"  Summary: {summary['dry_run_ok']} engine(s) "
            "have valid wireups (dry-run only)."
        )
        print(
            "  Re-run with --yes to actually invoke each."
        )


def _cmd_engine_try_wireup(args) -> None:
    """Smoke-test a wired engine's Phase 7 writeback.

    The Phase 7 wireups are DORMANT by default -- engines only
    fire their writeback when callers set the apply_* opt-in
    flag. The autonomous-cycle's ADVANCE phase doesn't set
    these flags (default OFF is the bible-mandated safety
    posture). So operators wanting to VERIFY a wireup works
    end-to-end need a manual recipe.

    This command resolves the opt-in flag name from
    writeback_audit, builds a minimal engine input with the
    flag set, and (with --yes) invokes the engine. Without
    --yes, it's a DRY-RUN: shows what WOULD fire without
    making writes.

    With --all, iterates every wired engine -- fleet smoke-
    test useful for CI. Per-engine failures don't abort the
    loop.

    Refuses non-wired engines -- advisory engines have no
    apply_* flag to set.
    """
    as_json = bool(getattr(args, "json", False))
    engine_name = (
        getattr(args, "engine_name", None) or ""
    ).strip()
    yes = bool(getattr(args, "yes", False))
    run_all = bool(getattr(args, "run_all", False))
    store_id = (
        getattr(args, "store", None)
        or _get_store_manager().active_store_id
    )

    def _emit_error(msg: str, exit_code: int = 1) -> None:
        if as_json:
            print(json.dumps(
                {"status": "error", "error": msg},
                indent=2, default=str,
            ))
        else:
            print(f"Error: {msg}")
        sys.exit(exit_code)

    if run_all:
        # Safety guard: --all --yes can fire 26+ live
        # Shopify mutations across every wired engine.
        # Require explicit confirmation via env var so an
        # accidental ``--yes`` doesn't carpet-bomb a live
        # store. Dry-run is unaffected (no writes).
        if yes and not os.environ.get(
            "SHOPAI_TRY_WIREUP_ALL_CONFIRM",
        ):
            _emit_error(
                "--all --yes can fire writes across every "
                "wired engine. Set "
                "SHOPAI_TRY_WIREUP_ALL_CONFIRM=1 to "
                "acknowledge the blast radius, or drop "
                "--yes for the safe dry-run.",
                exit_code=1,
            )
            return
        _try_wireup_all(
            yes=yes, store_id=store_id, as_json=as_json,
        )
        return

    if not engine_name:
        _emit_error(
            "engine_name is required (or pass --all to "
            "iterate every wired engine)"
        )
        return

    # Look up wireup state -- refuse non-wired engines.
    try:
        from engines._writeback_audit import (
            audit_writeback_coverage,
        )
        report = audit_writeback_coverage("engines")
        wb = next(
            (s for s in report.engines if s.name == engine_name),
            None,
        )
    except Exception as exc:  # noqa: BLE001
        _emit_error(f"writeback audit failed: {exc}")
        return

    if wb is None:
        _emit_error(
            f"unknown engine: {engine_name} "
            "(see `shopai engines`)"
        )
        return
    if wb.status != "wired":
        _emit_error(
            f"engine '{engine_name}' is {wb.status}; "
            "try-wireup only supports wired engines"
        )
        return

    # Pick the apply_* flag. Most wired engines have ONE
    # apply_* flag plus optionally require_approval. We set
    # the apply_* flag only; require_approval is left off so
    # this is a direct-mint test path.
    apply_flag = next(
        (f for f in wb.opt_in_flags if f.startswith("apply_")),
        None,
    )
    if apply_flag is None:
        _emit_error(
            f"engine '{engine_name}' is wired but has no "
            "apply_* opt-in flag (unexpected)"
        )
        return

    # Parse extra params.
    extra_params: dict[str, Any] = {}
    raw_params = getattr(args, "params", "") or ""
    if raw_params:
        try:
            parsed = json.loads(raw_params)
            if not isinstance(parsed, dict):
                _emit_error("--params must be a JSON object")
                return
            extra_params = parsed
        except json.JSONDecodeError as exc:
            _emit_error(f"--params is not valid JSON: {exc}")
            return

    # Build engine input. Pull store data via DataProvider
    # (same path shopai run uses) so the engine sees the
    # right shape.
    try:
        from data_pipeline.store.data_provider import (
            DataProvider,
        )
        sm = _get_store_manager()
        data = (
            DataProvider(sm).get_data_for_engine(
                engine_name, store_id,
            )
            if store_id else {}
        )
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "try-wireup data provider raised: %s", exc,
        )
        data = {}

    if not isinstance(data, dict):
        data = {}
    data.update(extra_params)
    data[apply_flag] = True

    # Pull this engine's tag namespaces from the AST catalog
    # so the dry-run preview shows EXACTLY what will land on
    # Shopify (operators don't have to grep the applier).
    engine_tags: list[str] = []
    try:
        from engines._tag_catalog import catalog_tags
        tag_cat = catalog_tags("engines")
        engine_tags = sorted({
            e.tag for e in tag_cat.entries
            if e.engine == engine_name
        })
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "try-wireup tag-catalog probe raised: %s", exc,
        )

    plan = {
        "engine": engine_name,
        "store_id": store_id,
        "apply_flag": apply_flag,
        "writers": wb.writer_files,
        "opt_in_flags": wb.opt_in_flags,
        "data_keys": sorted(data.keys()),
        "writes_tags": engine_tags,
    }

    if not yes:
        if as_json:
            print(json.dumps(
                {"status": "dry_run", "plan": plan},
                indent=2, default=str,
            ))
            return
        print(f"Engine try-wireup: {engine_name}  (DRY-RUN)")
        print()
        print(f"  Status:      wired")
        print(f"  Apply flag:  data.{apply_flag}=True")
        print(
            f"  Writers:     {', '.join(wb.writer_files)}"
        )
        if engine_tags:
            print(
                f"  Writes tag(s): {', '.join(engine_tags)}"
            )
        print(f"  Store_id:    {store_id or '(none)'}")
        print(f"  Data keys:   {sorted(data.keys())}")
        print()
        print(
            "  Pass --yes to actually invoke (will call "
            "Shopify if the engine's writer reaches a "
            "real router)."
        )
        return

    # Actually invoke.
    try:
        from engines.registry import get_engine
        engine = get_engine(engine_name)
    except Exception as exc:  # noqa: BLE001
        _emit_error(f"engine load failed: {exc}")
        return
    if engine is None:
        _emit_error(f"engine '{engine_name}' not registered")
        return

    try:
        result = engine.run(data)
    except Exception as exc:  # noqa: BLE001
        logger.debug("try-wireup engine raised: %s", exc)
        if as_json:
            print(json.dumps({
                "status": "error",
                "error": f"engine_raised: {exc}",
                "plan": plan,
            }, indent=2, default=str))
        else:
            print(f"Engine raised: {exc}")
        sys.exit(1)
        return

    if as_json:
        print(json.dumps({
            "status": "ok",
            "plan": plan,
            "result": result,
        }, indent=2, default=str))
        return

    print(f"Engine try-wireup: {engine_name}  (EXECUTED)")
    print()
    rstatus = (
        result.get("status", "?")
        if isinstance(result, dict) else "?"
    )
    print(f"  Engine status: {rstatus}")
    if isinstance(result, dict):
        result_data = result.get("data") or {}
        # Surface the writer's results array if present
        # (each Phase 7 minter / applier returns one).
        for key in (
            "minted_codes", "apply_results", "payout_results",
            "tagged_winners", "minted_count", "applied",
        ):
            if key in result_data:
                val = result_data[key]
                if isinstance(val, list):
                    print(
                        f"  {key}: {len(val)} item(s)"
                    )
                else:
                    print(f"  {key}: {val}")
        if result.get("error"):
            print(f"  Engine error: {result['error']}")
    print()
    print(
        f"  Drill down: `shopai engine summary "
        f"{engine_name}`"
    )


def _cmd_engine_summary(args) -> None:
    """Per-engine drilldown: queue counts + recent actions + outcomes.

    Combines three existing queue probes into one summary:
      - ``stats_by_engine()`` for per-status counts.
      - ``list_by_status(EXECUTED, engine=N, limit=recent_n)`` for
        the most recent activity.
      - ``engine_outcome_stats()`` for the effectiveness signal.

    Useful as the "is this engine pulling its weight?" verdict for
    operators triaging which engines deserve more / less autonomy.
    """
    as_json = bool(getattr(args, "json", False))
    engine_name = args.engine_name
    recent_n = max(1, int(getattr(args, "recent_n", 5) or 5))

    try:
        from core.approval.queue import (
            ApprovalStatus, get_approval_queue,
        )
    except Exception as exc:  # noqa: BLE001
        msg = f"approval queue unavailable: {exc}"
        if as_json:
            print(json.dumps(
                {"status": "error", "error": msg},
                indent=2, default=str,
            ))
        else:
            print(msg)
        sys.exit(1)
        return

    queue = get_approval_queue()

    # Per-status counts for this engine.
    all_engine_stats = queue.stats_by_engine() or {}
    per_engine = all_engine_stats.get(engine_name, {})
    counts = {
        s.value: int(per_engine.get(s.value, 0))
        for s in ApprovalStatus
    }
    total_activity = sum(counts.values())

    # Outcome rollup (success / failure / revenue).
    outcomes = queue.engine_outcome_stats(engine_name) or {}

    # Quarantine + alert-history block (PR-#306-era addition).
    # Answers the operator question "is this engine paused, and
    # why?" without requiring a separate ``approvals quarantine
    # --list`` invocation.
    quarantine_info: dict = {}
    try:
        from core.approval import quarantine as qm
        qstate = qm.load_state()
        quarantine_info = {
            "exempt": qstate.is_exempt(engine_name),
            "released": qstate.is_released(engine_name),
            "alert_paused": qstate.is_alert_paused(engine_name),
        }
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "engine summary quarantine probe raised: %s", exc,
        )

    # Writeback wire-up state -- computed once and reused
    # by both JSON envelope + text-mode rendering.
    writeback_info: dict = {
        "status": "unknown", "writers": [], "opt_ins": [],
    }
    try:
        from engines._writeback_audit import (
            audit_writeback_coverage,
        )
        wb_report = audit_writeback_coverage("engines")
        wb = next(
            (
                s for s in wb_report.engines
                if s.name == engine_name
            ),
            None,
        )
        if wb:
            writeback_info = {
                "status": wb.status,
                "writers": list(wb.writer_files),
                "opt_ins": list(wb.opt_in_flags),
            }
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "engine summary writeback probe raised: %s",
            exc,
        )

    # Health-state flags (regressing / chronic / outcome
    # alert) -- matches the engine pulse JSON shape
    # (e76ab5f2 + 1670e1c2) so summary + pulse stay
    # uniform for JSON consumers.
    regressing = False
    chronic = False
    outcome_alert = False
    try:
        from core.approval.engine_health_history import (
            find_regressions, find_chronic_warnings,
        )
        if any(
            r.engine == engine_name
            for r in find_regressions(
                min_drop=3.0,
                baseline_window_seconds=86400.0 * 7.0,
                latest_window_seconds=86400.0 * 1.0,
                min_baseline_samples=3,
            )
        ):
            regressing = True
        if any(
            w.engine == engine_name
            for w in find_chronic_warnings(
                sample_window_seconds=86400.0 * 7.0,
                min_samples=3,
                healthy_score_floor=7,
            )
        ):
            chronic = True
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "engine summary health-state probe raised: %s",
            exc,
        )
    try:
        from core.approval.outcome_trends import (
            compute_engine_alerts,
        )
        from core.approval.queue import get_approval_queue
        if any(
            a.engine == engine_name
            for a in compute_engine_alerts(
                get_approval_queue(),
                recent_hours=24.0,
                baseline_hours=168.0,
                threshold=0.2,
                min_recent=3,
            )
        ):
            outcome_alert = True
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "engine summary outcome_alert probe raised: %s",
            exc,
        )

    alert_streak = 0
    last_alert_at: float | None = None
    recent_alerts: list[dict] = []
    try:
        from core.approval import alert_history
        consecutive = (
            alert_history.consecutive_runs_per_engine(
                window_seconds=86400.0 * 7.0,
            )
        )
        alert_streak = int(consecutive.get(engine_name, 0))
        events = alert_history.recent_history(
            since_seconds=86400.0 * 365.0,
        )
        for e in events:
            if e.engine != engine_name:
                continue
            if last_alert_at is None:
                last_alert_at = e.recorded_at
            # Cap at 5 most recent for this engine. The trajectory
            # tells operators if alerts are accelerating or dying
            # down, not just whether they fired.
            if len(recent_alerts) < 5:
                recent_alerts.append({
                    "recorded_at": float(
                        getattr(e, "recorded_at", 0.0) or 0.0,
                    ),
                    "drop": float(
                        getattr(e, "drop", 0.0) or 0.0,
                    ),
                    "recent_score": float(
                        getattr(e, "recent_score", 0.0) or 0.0,
                    ),
                    "baseline_score": float(
                        getattr(e, "baseline_score", 0.0) or 0.0,
                    ),
                    "store_id": getattr(e, "store_id", None),
                })
            if (
                last_alert_at is not None
                and len(recent_alerts) >= 5
            ):
                break
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "engine summary alert_history probe raised: %s", exc,
        )
    if quarantine_info:
        quarantine_info["alert_streak_7d"] = alert_streak
        quarantine_info["last_alert_at"] = last_alert_at
        quarantine_info["recent_alerts"] = recent_alerts

    # Recent actions across the two most informative statuses --
    # EXECUTED first (the "what's been shipped" feed) then FAILED
    # (the "what's been breaking" feed). Capped at recent_n total.
    recent: list[dict] = []
    for status in (ApprovalStatus.EXECUTED, ApprovalStatus.FAILED):
        try:
            actions = queue.list_by_status(
                status, engine=engine_name, limit=recent_n,
            )
        except Exception as exc:  # noqa: BLE001
            logger.debug(
                "engine summary list_by_status raised: %s", exc,
            )
            continue
        for a in actions:
            recent.append({
                "action_id": a.id,
                "action_type": a.action_type,
                "capability": a.capability,
                "status": a.status.value,
                "decided_at": a.decided_at,
                "decided_by": a.decided_by,
                "error": (a.result or {}).get("error")
                         if a.result else None,
            })
    # Sort newest-first by decided_at, then truncate.
    recent.sort(key=lambda r: -(r.get("decided_at") or 0))
    recent = recent[:recent_n]

    if as_json:
        print(json.dumps({
            "engine": engine_name,
            "counts_by_status": counts,
            "total_activity": total_activity,
            "outcomes": outcomes,
            "quarantine": quarantine_info,
            "writeback": writeback_info,
            "regressing": regressing,
            "chronic": chronic,
            "outcome_alert": outcome_alert,
            "recent": recent,
        }, indent=2, default=str))
        return

    # ── Text render ────────────────────────────────────────
    print(f"Engine: {engine_name}")
    print()
    if not total_activity:
        print(
            f"  (no recorded activity yet for {engine_name})"
        )
        # Even with no activity, surface the engine's
        # static state -- operators want to know whether
        # the engine is wired/advisory/quarantined when
        # they're asking 'why is this engine quiet?'.
        if writeback_info.get("status") != "unknown":
            print(
                f"  writeback: {writeback_info['status']}  "
                f"(writers={len(writeback_info['writers'])}, "
                f"opt_ins={len(writeback_info['opt_ins'])})"
            )
            if writeback_info.get("opt_ins"):
                flags = ", ".join(
                    f"data.{f}=True"
                    for f in writeback_info["opt_ins"]
                )
                print(f"    Enable via: {flags}")
                print(
                    f"    Smoke-test: `shopai engine "
                    f"try-wireup {engine_name}` (dry-run)"
                )
                try:
                    from engines._tag_catalog import catalog_tags
                    tag_cat = catalog_tags("engines")
                    engine_tags = sorted({
                        e.tag for e in tag_cat.entries
                        if e.engine == engine_name
                    })
                    if engine_tags:
                        print(
                            f"    Writes tag(s): "
                            f"{', '.join(engine_tags)}"
                        )
                except Exception as exc:  # noqa: BLE001
                    logger.debug(
                        "engine summary tag-catalog probe raised: %s",
                        exc,
                    )
        if quarantine_info:
            flags = [
                f for f in (
                    "exempt", "released", "alert_paused",
                ) if quarantine_info.get(f)
            ]
            if flags:
                print(
                    f"  quarantine: {', '.join(flags)}"
                )
        # Surface engine-health state even with no activity
        # -- a regressing/chronic engine that's been
        # quarantined might show 'no activity' but the
        # underlying scores still exist.
        state_bits: list[str] = []
        if regressing:
            state_bits.append("REGRESSING")
        if chronic:
            state_bits.append("CHRONIC")
        if state_bits:
            print(
                f"  health state: {' + '.join(state_bits)}"
            )
        return
    print("Queue counts:")
    for status_value, n in counts.items():
        if n:
            print(f"  {status_value:<10s} {n}")
    print(f"  TOTAL      {total_activity}")
    print()
    pos = outcomes.get("positive_count", 0)
    neg = outcomes.get("negative_count", 0)
    neu = outcomes.get("neutral_count", 0)
    total_oc = outcomes.get("total_outcomes", 0)
    revenue = outcomes.get("total_revenue", 0.0)
    score = outcomes.get("outcome_score")
    print("Outcomes:")
    print(
        f"  positive={pos}  negative={neg}  "
        f"neutral={neu}  total={total_oc}"
    )
    print(f"  revenue: ${revenue:,.2f}")
    if score is not None:
        print(f"  effectiveness score: {score:.1%}")
    else:
        print("  effectiveness score: n/a (no polarised outcomes)")
    print()
    # Static-context line in the with-activity path too --
    # operators inspecting a sick engine want to know
    # whether it's wired/advisory just as much as on the
    # no-activity path.
    if writeback_info.get("status") != "unknown":
        print(
            f"Writeback: {writeback_info['status']}  "
            f"(writers={len(writeback_info['writers'])}, "
            f"opt_ins={len(writeback_info['opt_ins'])})"
        )
        # Surface the actual opt-in flag names so operators
        # know HOW to trigger the writeback. Wired engines
        # without this hint require grepping the source.
        if writeback_info.get("opt_ins"):
            flags = ", ".join(
                f"data.{f}=True"
                for f in writeback_info["opt_ins"]
            )
            print(f"  Enable via: {flags}")
        # Surface the tag namespaces this engine writes -- so
        # operators know what Shopify-admin filter to use after
        # the engine fires. Pulled from the AST-derived catalog
        # (engines/_tag_catalog.py) so it stays accurate.
        try:
            from engines._tag_catalog import catalog_tags
            tag_cat = catalog_tags("engines")
            engine_tags = sorted({
                e.tag for e in tag_cat.entries
                if e.engine == engine_name
            })
            if engine_tags:
                print(
                    f"  Writes tag(s): {', '.join(engine_tags)}"
                )
        except Exception as exc:  # noqa: BLE001
            logger.debug(
                "engine summary tag-catalog probe raised: %s",
                exc,
            )
        print()
    # Health state -- regressing/chronic mirror of the
    # no-activity path's surfacing (8717ffb7).
    state_bits: list[str] = []
    if regressing:
        state_bits.append("REGRESSING")
    if chronic:
        state_bits.append("CHRONIC")
    if state_bits:
        print(
            f"Health state: {' + '.join(state_bits)}"
        )
        print(
            f"  Drill down: `shopai engine pulse "
            f"{engine_name} --history`"
        )
        print()
    if quarantine_info:
        # Compose a one-line status -- skip the section entirely
        # when there's nothing to say (healthy + no recent alerts).
        flags = []
        if quarantine_info.get("exempt"):
            flags.append("exempt")
        if quarantine_info.get("released"):
            flags.append("released")
        if quarantine_info.get("alert_paused"):
            flags.append("alert_paused")
        streak = quarantine_info.get("alert_streak_7d", 0)
        last = quarantine_info.get("last_alert_at")
        recent_alerts_list = (
            quarantine_info.get("recent_alerts") or []
        )
        if flags or streak > 0:
            print("Quarantine:")
            if flags:
                print(f"  Flags: {', '.join(flags)}")
            if streak > 0:
                print(f"  Alert streak (last 7d): {streak} day(s)")
            if last:
                age = time.time() - float(last)
                ago = (
                    f"{int(age)}s ago" if age < 60
                    else f"{int(age/60)}m ago" if age < 3600
                    else f"{int(age/3600)}h ago" if age < 86400
                    else f"{int(age/86400)}d ago"
                )
                print(f"  Last alert firing: {ago}")
            if recent_alerts_list:
                print(
                    f"  Recent alerts ({len(recent_alerts_list)}):"
                )
                now = time.time()
                for ev in recent_alerts_list:
                    ts = ev.get("recorded_at") or 0
                    age = now - float(ts) if ts else 0
                    ago_short = (
                        f"{int(age/3600)}h ago" if age < 86400
                        else f"{int(age/86400)}d ago"
                    )
                    drop = float(ev.get("drop", 0.0) or 0.0)
                    sid = ev.get("store_id")
                    scope = f"@{sid}" if sid else "(fleet)"
                    rs = float(ev.get("recent_score", 0.0))
                    bs = float(ev.get("baseline_score", 0.0))
                    print(
                        f"    {ago_short:<10s} {scope:<14s} "
                        f"drop={drop:.0%}  "
                        f"recent={rs:.2f} baseline={bs:.2f}"
                    )
            print()
    if recent:
        print(f"Recent activity ({len(recent)}):")
        now = time.time()
        for r in recent:
            ts = r.get("decided_at") or 0
            age = now - float(ts) if ts else 0
            ago = (
                f"{int(age)}s ago" if age < 60
                else f"{int(age/60)}m ago" if age < 3600
                else f"{int(age/3600)}h ago" if age < 86400
                else f"{int(age/86400)}d ago"
            )
            line = (
                f"  {r['status']:<9s} "
                f"{r['action_type']:<28s} {ago}"
            )
            if r.get("error"):
                line += f"  err={r['error']}"
            print(line)
        # Drill-down hint: summary shows WHAT this engine is
        # doing; fleet shows WHERE it's doing it. Operator's
        # natural next question. Suppressed when health-state
        # already shows a drill-down (pulse --history covers
        # the regressing/chronic angle).
        if not state_bits:
            print(
                f"  Drill down: `shopai engine fleet "
                f"{engine_name}`"
            )


def _cmd_engine_guardrail(args) -> None:
    """Show AGI v2 guardrail state + recent-block counts across
    all engines that have opted in.

    Default text view renders one row per engine: env-var state
    (ON/OFF) + count of guardrail-blocked actions in the recent
    window. ``--json`` emits the raw report.

    The block count reads ``pending_actions`` rows whose ``result_json``
    payload's error field starts with ``agi_guardrail_blocked:`` --
    that's the marker the v2 wiring records when it refuses to
    mint.
    """
    as_json = bool(getattr(args, "json", False))
    window_hours = max(1, int(getattr(args, "window_hours", 24) or 24))
    cutoff = time.time() - window_hours * 3600.0

    # Engines that have v2 guardrail wiring. Source of truth:
    # ``engines._agi_context.GUARDRAIL_ENGINES`` -- the roster
    # is owned by the AGI-context module so new engines wiring
    # in v2 don't need a parallel update here.
    try:
        from engines._agi_context import GUARDRAIL_ENGINES
        guardrail_engines = list(GUARDRAIL_ENGINES)
    except Exception as exc:  # noqa: BLE001
        # Pre-PR-#272 codebase doesn't have the roster. Fall
        # back to the hardcoded list so older deployments
        # still render their state.
        logger.debug(
            "engine guardrail roster import failed: %s", exc,
        )
        guardrail_engines = [
            "loyalty",
            "cart_recovery",
            "browse_recovery",
            "email_marketing",
            "wholesale_b2b",
            "discount_strategy",
        ]

    # Per-engine env-var state.
    try:
        from engines._agi_context import guardrail_enabled
    except Exception as exc:  # noqa: BLE001
        # Pre-PR-#247 codebase doesn't have the helper. Fall
        # back to manual env var read.
        logger.debug(
            "engine guardrail status: import failed: %s", exc,
        )

        def guardrail_enabled(name: str) -> bool:
            return os.environ.get(
                f"SHOPAI_{name.upper()}_AGI_GUARDRAIL", "",
            ) in {"1", "true", "yes", "on"}

    # Recent-block counts: scan pending_actions for failures
    # tagged with the agi_guardrail_blocked marker.
    blocks_by_engine: dict[str, int] = {e: 0 for e in guardrail_engines}
    try:
        from core.approval.queue import get_approval_queue
        queue = get_approval_queue()
        with queue._conn:
            rows = queue._conn.execute(
                """SELECT engine, COUNT(*) as n
                   FROM pending_actions
                   WHERE status = 'failed'
                     AND decided_at >= ?
                     AND decision_reason LIKE 'agi_guardrail_blocked:%'
                   GROUP BY engine""",
                (cutoff,),
            ).fetchall()
        for r in rows:
            if r["engine"] in blocks_by_engine:
                blocks_by_engine[r["engine"]] = int(r["n"])
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "engine guardrail status: queue read raised: %s", exc,
        )

    # Quarantine flags per engine -- v2 guardrail and quarantine
    # are parallel pause mechanisms (one refuses at decision time,
    # the other rejects at enqueue). Operators should see both
    # in one view to understand "why isn't this engine acting?".
    qstate = None
    try:
        from core.approval import quarantine as qm
        qstate = qm.load_state()
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "engine guardrail quarantine probe raised: %s", exc,
        )

    def _engine_flags(name: str) -> list[str]:
        if qstate is None:
            return []
        out: list[str] = []
        if qstate.is_alert_paused(name):
            out.append("alert_paused")
        if qstate.is_exempt(name):
            out.append("exempt")
        if qstate.is_released(name):
            out.append("released")
        return out

    report = [
        {
            "engine": engine,
            "guardrail_enabled": guardrail_enabled(engine),
            "blocks_in_window": blocks_by_engine.get(engine, 0),
            "env_var": f"SHOPAI_{engine.upper()}_AGI_GUARDRAIL",
            "quarantine_flags": _engine_flags(engine),
        }
        for engine in guardrail_engines
    ]

    # Optional: recent block events with reason + age. Useful
    # operator triage when an engine spirals -- "why did the
    # guardrail block this mint?" with the exact action_type
    # and avg_relevance from the recorded reason string.
    recent_n = max(0, int(getattr(args, "recent_n", 0) or 0))
    recent_blocks: list[dict] = []
    if recent_n > 0:
        try:
            from core.approval.queue import get_approval_queue
            queue = get_approval_queue()
            with queue._conn:
                rows = queue._conn.execute(
                    """SELECT id, engine, action_type, decided_at,
                              decision_reason
                       FROM pending_actions
                       WHERE status = 'failed'
                         AND decided_at >= ?
                         AND decision_reason LIKE
                             'agi_guardrail_blocked:%'
                       ORDER BY decided_at DESC
                       LIMIT ?""",
                    (cutoff, recent_n),
                ).fetchall()
            recent_blocks = [
                {
                    "action_id": r["id"],
                    "engine": r["engine"],
                    "action_type": r["action_type"],
                    "decided_at": r["decided_at"],
                    "reason": r["decision_reason"],
                }
                for r in rows
            ]
        except Exception as exc:  # noqa: BLE001
            logger.debug(
                "engine guardrail recent: queue read raised: %s",
                exc,
            )

    if as_json:
        envelope: dict = {
            "window_hours": window_hours,
            "engines": report,
        }
        if recent_n > 0:
            envelope["recent_blocks"] = recent_blocks
        print(json.dumps(envelope, indent=2, default=str))
        return

    enabled_count = sum(1 for e in report if e["guardrail_enabled"])
    total_blocks = sum(e["blocks_in_window"] for e in report)
    print(
        f"AGI v2 guardrail status (window: {window_hours}h)"
    )
    print(
        f"  {enabled_count}/{len(report)} engine(s) enabled; "
        f"{total_blocks} block(s) recorded"
    )
    print()
    print(
        f"  {'ENGINE':<22s} {'STATE':<6s} {'BLOCKS':>7s}  "
        f"{'QUARANTINE':<14s} ENV VAR"
    )
    print("  " + "-" * 85)
    for e in report:
        state = "ON" if e["guardrail_enabled"] else "off"
        marker = "*" if e["guardrail_enabled"] else " "
        qflags = ",".join(e.get("quarantine_flags") or [])[:14] or "-"
        print(
            f"  {marker}{e['engine']:<21s} {state:<6s} "
            f"{e['blocks_in_window']:>7d}  "
            f"{qflags:<14s} {e['env_var']}"
        )
    print()
    if recent_n > 0 and recent_blocks:
        print(f"Recent blocks (last {len(recent_blocks)}):")
        now = time.time()
        for b in recent_blocks:
            ts = b.get("decided_at") or 0
            age = now - float(ts) if ts else 0
            ago = (
                f"{int(age)}s ago" if age < 60
                else f"{int(age/60)}m ago" if age < 3600
                else f"{int(age/3600)}h ago" if age < 86400
                else f"{int(age/86400)}d ago"
            )
            # The reason string is the full audit line written
            # by explain_guardrail_block -- e.g.
            # "agi_guardrail_blocked: similar=4 negative=true
            #  positive=false avg_relevance=0.85"
            print(
                f"  {b['engine']:<22s} {b['action_type']:<28s} "
                f"{ago}"
            )
            print(f"      {b['reason']}")
        print()
    elif recent_n > 0:
        print(f"Recent blocks: (none in last {window_hours}h)")
        print()
    # Drill-down hint: when blocks exist but --recent-n wasn't
    # passed, point operators at the detail view they need
    # (which engine + action got refused + why).
    if total_blocks > 0 and recent_n == 0:
        print(
            f"  Drill down: `shopai engine guardrail "
            f"--recent-n {min(total_blocks, 10)}` for "
            "per-block detail."
        )
    if enabled_count == 0:
        print(
            "  Enable any engine via env var, e.g.:\n"
            "    export SHOPAI_LOYALTY_AGI_GUARDRAIL=1"
        )


def _cmd_engine_fleet(args) -> None:
    """Show one engine's activity + outcomes across every store
    in the fleet -- the empire-AGI 'where is this engine winning
    or losing?' diagnostic.

    Inverse of ``transfer suggest``: that asks 'what should I
    copy?', this asks 'on which stores does this engine already
    perform?'. Surfaces per-store rows (executed / failed /
    polarity / revenue) plus a fleet rollup so operators can
    spot patterns: engine X is great everywhere except store B
    (investigate config), engine Y only works on store C
    (consider quarantining elsewhere).
    """
    as_json = bool(getattr(args, "json", False))
    engine_name = (
        getattr(args, "engine_name", "") or ""
    ).strip()
    window_hours = max(
        1, int(getattr(args, "window_hours", 168) or 168),
    )
    cutoff = time.time() - window_hours * 3600.0

    def _emit_error(msg: str) -> None:
        if as_json:
            print(json.dumps(
                {"status": "error", "error": msg},
                indent=2, default=str,
            ))
        else:
            print(f"Error: {msg}")
        sys.exit(1)

    if not engine_name:
        _emit_error("engine_name is required")
        return

    try:
        from core.approval.queue import get_approval_queue
    except Exception as exc:  # noqa: BLE001
        _emit_error(f"approval queue unavailable: {exc}")
        return

    sm = _get_store_manager()
    fleet_stores = sm.list_stores() or []
    known_store_ids = {
        s.get("store_id") for s in fleet_stores if s.get("store_id")
    }

    by_store: dict[str, dict] = {}

    def _bucket(sid: str) -> dict:
        if sid not in by_store:
            by_store[sid] = {
                "store_id": sid,
                "executed": 0,
                "failed": 0,
                "pending": 0,
                "positive_outcomes": 0,
                "negative_outcomes": 0,
                "neutral_outcomes": 0,
                "revenue": 0.0,
            }
        return by_store[sid]

    try:
        queue = get_approval_queue()
        with queue._conn:
            rows = queue._conn.execute(
                """SELECT id, store_id, status, decided_at,
                          proposed_at
                   FROM pending_actions
                   WHERE engine = ?
                     AND (decided_at >= ? OR
                          (decided_at IS NULL
                           AND proposed_at >= ?))""",
                (engine_name, cutoff, cutoff),
            ).fetchall()
        from core.approval.outcome_aggregator import (
            aggregate_outcomes,
        )
        for r in rows:
            sid = r["store_id"] or "(unscoped)"
            bucket = _bucket(sid)
            status = (r["status"] or "").lower()
            if status == "executed":
                bucket["executed"] += 1
                try:
                    outcomes = queue.get_outcomes(r["id"]) or []
                except Exception as exc:  # noqa: BLE001
                    logger.debug(
                        "engine fleet outcomes raised: %s", exc,
                    )
                    outcomes = []
                rollup = aggregate_outcomes(outcomes)
                bucket["positive_outcomes"] += rollup.positive
                bucket["negative_outcomes"] += rollup.negative
                bucket["neutral_outcomes"] += rollup.neutral
                bucket["revenue"] += rollup.revenue
            elif status == "failed":
                bucket["failed"] += 1
            elif status in {"pending", "approved"}:
                bucket["pending"] += 1
    except Exception as exc:  # noqa: BLE001
        _emit_error(f"queue scan failed: {exc}")
        return

    # Ensure every fleet store shows up, even with zero activity.
    for sid in known_store_ids:
        _bucket(sid)

    # Outcome score: positive / (positive + negative); None when
    # no polarised events. Computed AFTER the fleet-stores backfill
    # so every bucket carries the field.
    for b in by_store.values():
        pos = b["positive_outcomes"]
        neg = b["negative_outcomes"]
        b["outcome_score"] = (
            pos / (pos + neg) if (pos + neg) > 0 else None
        )

    # Rollup over the fleet.
    rollup = {
        "stores_with_activity": sum(
            1 for b in by_store.values()
            if (b["executed"] + b["failed"] + b["pending"]) > 0
        ),
        "total_executed": sum(
            b["executed"] for b in by_store.values()
        ),
        "total_failed": sum(
            b["failed"] for b in by_store.values()
        ),
        "total_pending": sum(
            b["pending"] for b in by_store.values()
        ),
        "total_positive": sum(
            b["positive_outcomes"] for b in by_store.values()
        ),
        "total_negative": sum(
            b["negative_outcomes"] for b in by_store.values()
        ),
        "total_revenue": sum(
            b["revenue"] for b in by_store.values()
        ),
    }

    # Sort: most-active first, with executed > failed > pending,
    # then revenue tiebreak.
    ranked = sorted(
        by_store.values(),
        key=lambda b: (
            -(b["executed"] + b["failed"] + b["pending"]),
            -b["executed"], -b["revenue"], b["store_id"],
        ),
    )

    # Quarantine banner: this engine's fleet-wide quarantine
    # state surfaces at the top so operators reading the
    # per-store table know upfront whether the engine is
    # acting at all (or just being rejected at enqueue).
    quarantine_flags: list[str] = []
    try:
        from core.approval import quarantine as qm
        qstate = qm.load_state()
        if qstate.is_exempt(engine_name):
            quarantine_flags.append("exempt")
        if qstate.is_released(engine_name):
            quarantine_flags.append("released")
        if qstate.is_alert_paused(engine_name):
            quarantine_flags.append("alert_paused")
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "engine fleet quarantine probe raised: %s", exc,
        )

    envelope = {
        "engine": engine_name,
        "window_hours": window_hours,
        "quarantine_flags": quarantine_flags,
        "rollup": rollup,
        "stores": ranked,
    }

    if as_json:
        print(json.dumps(envelope, indent=2, default=str))
        return

    print(
        f"Engine '{engine_name}' across fleet "
        f"(last {window_hours}h):"
    )
    if quarantine_flags:
        print(
            f"  ! Quarantine: {', '.join(quarantine_flags)}"
        )
    print()
    print(
        f"  {'STORE':<22s} {'EXEC':>5s} {'FAIL':>5s} "
        f"{'PEND':>5s} {'+':>4s} {'-':>4s} "
        f"{'SCORE':>6s} {'REVENUE':>11s}"
    )
    print("  " + "-" * 72)
    for b in ranked:
        score_str = (
            "n/a" if b["outcome_score"] is None
            else f"{b['outcome_score']:.0%}"
        )
        print(
            f"  {b['store_id']:<22s} "
            f"{b['executed']:>5d} "
            f"{b['failed']:>5d} "
            f"{b['pending']:>5d} "
            f"{b['positive_outcomes']:>4d} "
            f"{b['negative_outcomes']:>4d} "
            f"{score_str:>6s} "
            f"${b['revenue']:>10,.2f}"
        )
    print()
    score_str = (
        "n/a" if (rollup["total_positive"]
                  + rollup["total_negative"]) == 0
        else (
            f"{rollup['total_positive'] / (rollup['total_positive'] + rollup['total_negative']):.0%}"
        )
    )
    print(
        f"  Rollup:  "
        f"{rollup['stores_with_activity']} store(s) with activity, "
        f"{rollup['total_executed']} executed, "
        f"{rollup['total_failed']} failed, "
        f"score={score_str}, "
        f"rev=${rollup['total_revenue']:,.2f}"
    )
    # Drill-down hint: fleet view shows WHERE; pulse history
    # shows WHEN. Operator's natural follow-up is "has this
    # engine always behaved like this on these stores?".
    if rollup["stores_with_activity"] > 0:
        print(
            f"    Drill down: `shopai engine pulse "
            f"{engine_name} --history`"
        )


def _cmd_engine_compare(args) -> None:
    """Head-to-head fleet comparison of two engines.

    For each engine, compute fleet-wide totals over the window:
    executed / failed / pending counts + outcome polarity +
    revenue. Surface side-by-side with a winner per metric so
    operators see at a glance "engine A executes more but
    engine B has better outcome polarity -- maybe B's the
    right pick for new stores".
    """
    as_json = bool(getattr(args, "json", False))
    engine_a = (getattr(args, "engine_a", "") or "").strip()
    engine_b = (getattr(args, "engine_b", "") or "").strip()
    window_hours = max(
        1, int(getattr(args, "window_hours", 168) or 168),
    )
    cutoff = time.time() - window_hours * 3600.0

    def _emit_error(msg: str) -> None:
        if as_json:
            print(json.dumps(
                {"status": "error", "error": msg},
                indent=2, default=str,
            ))
        else:
            print(f"Error: {msg}")
        sys.exit(1)

    if not engine_a or not engine_b:
        _emit_error("both engine_a and engine_b are required")
        return
    if engine_a == engine_b:
        _emit_error("engine_a and engine_b must be different")
        return

    try:
        from core.approval.queue import get_approval_queue
    except Exception as exc:  # noqa: BLE001
        _emit_error(f"approval queue unavailable: {exc}")
        return

    queue = get_approval_queue()

    def _profile(engine: str) -> dict:
        bucket = {
            "engine": engine,
            "executed": 0, "failed": 0, "pending": 0,
            "positive_outcomes": 0,
            "negative_outcomes": 0,
            "neutral_outcomes": 0,
            "revenue": 0.0,
        }
        try:
            with queue._conn:
                rows = queue._conn.execute(
                    """SELECT id, status FROM pending_actions
                       WHERE engine = ?
                         AND (decided_at >= ? OR
                              (decided_at IS NULL
                               AND proposed_at >= ?))""",
                    (engine, cutoff, cutoff),
                ).fetchall()
        except Exception as exc:  # noqa: BLE001
            logger.debug(
                "engine compare scan raised: %s", exc,
            )
            rows = []
        from core.approval.outcome_aggregator import (
            aggregate_outcomes,
        )
        for r in rows:
            status = (r["status"] or "").lower()
            if status == "executed":
                bucket["executed"] += 1
                try:
                    outcomes = queue.get_outcomes(r["id"]) or []
                except Exception as exc:  # noqa: BLE001
                    logger.debug(
                        "engine compare outcomes raised: %s", exc,
                    )
                    outcomes = []
                rollup = aggregate_outcomes(outcomes)
                bucket["positive_outcomes"] += rollup.positive
                bucket["negative_outcomes"] += rollup.negative
                bucket["neutral_outcomes"] += rollup.neutral
                bucket["revenue"] += rollup.revenue
            elif status == "failed":
                bucket["failed"] += 1
            elif status in {"pending", "approved"}:
                bucket["pending"] += 1
        pos = bucket["positive_outcomes"]
        neg = bucket["negative_outcomes"]
        bucket["outcome_score"] = (
            pos / (pos + neg) if (pos + neg) > 0 else None
        )
        return bucket

    prof_a = _profile(engine_a)
    prof_b = _profile(engine_b)

    # Quarantine flags side-by-side: an engine winning on score
    # but currently alert_paused is worth flagging visibly so
    # operators don't pick the paused one.
    qstate = None
    try:
        from core.approval import quarantine as qm
        qstate = qm.load_state()
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "engine compare quarantine probe raised: %s", exc,
        )
    for prof in (prof_a, prof_b):
        engine = prof["engine"]
        flags: list[str] = []
        if qstate is not None:
            if qstate.is_exempt(engine):
                flags.append("exempt")
            if qstate.is_released(engine):
                flags.append("released")
            if qstate.is_alert_paused(engine):
                flags.append("alert_paused")
        prof["flags"] = flags

    def _winner(key: str, higher_is_better: bool = True) -> str:
        va = prof_a.get(key)
        vb = prof_b.get(key)
        # Treat None as "no data" -> not winner
        if va is None and vb is None:
            return "tie"
        if va is None:
            return engine_b
        if vb is None:
            return engine_a
        if va == vb:
            return "tie"
        if higher_is_better:
            return engine_a if va > vb else engine_b
        return engine_a if va < vb else engine_b

    winners = {
        "executed": _winner("executed"),
        "failed": _winner("failed", higher_is_better=False),
        "positive_outcomes": _winner("positive_outcomes"),
        "negative_outcomes": _winner(
            "negative_outcomes", higher_is_better=False,
        ),
        "outcome_score": _winner("outcome_score"),
        "revenue": _winner("revenue"),
    }

    envelope = {
        "engine_a": prof_a,
        "engine_b": prof_b,
        "window_hours": window_hours,
        "winners": winners,
    }

    if as_json:
        print(json.dumps(envelope, indent=2, default=str))
        return

    print(
        f"Engine compare (last {window_hours}h):  "
        f"{engine_a}  vs  {engine_b}"
    )
    print()

    def _score_str(s):
        return "n/a" if s is None else f"{s:.0%}"

    flags_a = ",".join(prof_a.get("flags") or []) or "-"
    flags_b = ",".join(prof_b.get("flags") or []) or "-"
    rows = [
        ("executed", prof_a["executed"], prof_b["executed"],
         winners["executed"], False),
        ("failed", prof_a["failed"], prof_b["failed"],
         winners["failed"], False),
        ("pending", prof_a["pending"], prof_b["pending"],
         "-", False),
        ("positive_outcomes",
         prof_a["positive_outcomes"],
         prof_b["positive_outcomes"],
         winners["positive_outcomes"], False),
        ("negative_outcomes",
         prof_a["negative_outcomes"],
         prof_b["negative_outcomes"],
         winners["negative_outcomes"], False),
        ("outcome_score",
         _score_str(prof_a["outcome_score"]),
         _score_str(prof_b["outcome_score"]),
         winners["outcome_score"], False),
        ("revenue",
         f"${prof_a['revenue']:,.2f}",
         f"${prof_b['revenue']:,.2f}",
         winners["revenue"], False),
        ("flags", flags_a, flags_b, "-", False),
    ]

    a_label = engine_a[:15]
    b_label = engine_b[:15]
    print(
        f"  {'METRIC':<20s} {a_label:>15s} {b_label:>15s} "
        f"{'WINNER':>20s}"
    )
    print("  " + "-" * 73)
    for metric, va, vb, w, _ in rows:
        print(
            f"  {metric:<20s} {str(va):>15s} {str(vb):>15s} "
            f"{w[:20]:>20s}"
        )
    # Overall winner roll-up -- count metric-level wins.
    # The 'WINNER' column is per-row; this is the
    # one-line summary an operator wants for
    # 'which engine is better overall?'.
    a_wins = sum(1 for w in winners.values() if w == engine_a)
    b_wins = sum(1 for w in winners.values() if w == engine_b)
    ties = sum(1 for w in winners.values() if w == "tie")
    print()
    if a_wins > b_wins:
        verdict = f"{engine_a} wins"
    elif b_wins > a_wins:
        verdict = f"{engine_b} wins"
    else:
        verdict = "even (no clear winner)"
    print(
        f"  Overall: {verdict}  "
        f"({engine_a}={a_wins} wins, "
        f"{engine_b}={b_wins} wins, "
        f"{ties} ties out of {len(winners)} metrics)"
    )
    # Drill-down hint: when there's a clear winner, the
    # natural next move is `engine fleet <winner>` to see
    # WHERE the winner is winning. Tied comparisons point
    # at engine_a's summary (deterministic anchor).
    if a_wins > b_wins:
        drill_engine = engine_a
    elif b_wins > a_wins:
        drill_engine = engine_b
    else:
        drill_engine = engine_a
    print(
        f"    Drill down: `shopai engine fleet "
        f"{drill_engine}`"
    )


def _cmd_engine_ranking(args) -> None:
    """Rank every active engine fleet-wide by outcome score +
    executed count.

    Operators want a single-glance answer to 'which engines are
    actually working across my fleet?'. ``engine summary`` is
    per-engine drill; ``engine compare`` is two-engine head-
    to-head; this is the fleet-wide leaderboard.

    Per-engine bucket (over the window):
      - executed / failed / pending
      - positive_outcomes / negative_outcomes / neutral_outcomes
      - outcome_score = positive / (positive + negative); None
        on no polarised events
      - revenue summed across outcome metrics

    Ranking: engines with a non-None outcome_score first (sorted
    by score desc), then engines with no polarised events
    (sorted by executed desc). Ties broken by executed desc,
    then by engine name asc for determinism.
    """
    as_json = bool(getattr(args, "json", False))
    window_hours = max(
        1, int(getattr(args, "window_hours", 168) or 168),
    )
    limit = max(1, int(getattr(args, "limit", 20) or 20))
    cutoff = time.time() - window_hours * 3600.0

    def _emit_error(msg: str) -> None:
        if as_json:
            print(json.dumps(
                {"status": "error", "error": msg},
                indent=2, default=str,
            ))
        else:
            print(f"Error: {msg}")
        sys.exit(1)

    try:
        from core.approval.queue import get_approval_queue
    except Exception as exc:  # noqa: BLE001
        _emit_error(f"approval queue unavailable: {exc}")
        return

    queue = get_approval_queue()
    by_engine: dict[str, dict] = {}

    def _bucket(name: str) -> dict:
        if name not in by_engine:
            by_engine[name] = {
                "engine": name,
                "executed": 0, "failed": 0, "pending": 0,
                "positive_outcomes": 0,
                "negative_outcomes": 0,
                "neutral_outcomes": 0,
                "revenue": 0.0,
            }
        return by_engine[name]

    try:
        with queue._conn:
            rows = queue._conn.execute(
                """SELECT id, engine, status FROM pending_actions
                   WHERE (decided_at >= ? OR
                          (decided_at IS NULL
                           AND proposed_at >= ?))""",
                (cutoff, cutoff),
            ).fetchall()
    except Exception as exc:  # noqa: BLE001
        _emit_error(f"queue scan failed: {exc}")
        return

    from core.approval.outcome_aggregator import (
        aggregate_outcomes,
    )
    for r in rows:
        engine = r["engine"] or "(unknown)"
        bucket = _bucket(engine)
        status = (r["status"] or "").lower()
        if status == "executed":
            bucket["executed"] += 1
            try:
                outcomes = queue.get_outcomes(r["id"]) or []
            except Exception as exc:  # noqa: BLE001
                logger.debug(
                    "engine ranking outcomes raised: %s", exc,
                )
                outcomes = []
            rollup = aggregate_outcomes(outcomes)
            bucket["positive_outcomes"] += rollup.positive
            bucket["negative_outcomes"] += rollup.negative
            bucket["neutral_outcomes"] += rollup.neutral
            bucket["revenue"] += rollup.revenue
        elif status == "failed":
            bucket["failed"] += 1
        elif status in {"pending", "approved"}:
            bucket["pending"] += 1

    for b in by_engine.values():
        pos = b["positive_outcomes"]
        neg = b["negative_outcomes"]
        b["outcome_score"] = (
            pos / (pos + neg) if (pos + neg) > 0 else None
        )

    # Quarantine flags: lazy probe so a corrupt state file
    # doesn't break the ranking. Each engine gets a ``flags``
    # list of any of {exempt, released, alert_paused} so the
    # leaderboard shows what's paused at a glance.
    qstate = None
    try:
        from core.approval import quarantine as qm
        qstate = qm.load_state()
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "engine ranking quarantine probe raised: %s", exc,
        )
    for b in by_engine.values():
        engine = b["engine"]
        flags: list[str] = []
        if qstate is not None:
            if qstate.is_exempt(engine):
                flags.append("exempt")
            if qstate.is_released(engine):
                flags.append("released")
            if qstate.is_alert_paused(engine):
                flags.append("alert_paused")
        b["flags"] = flags

    # Ranking: scored engines first (by score desc), then
    # unscored (by executed desc). Stable tiebreaks for
    # determinism.
    def _key(b):
        score = b["outcome_score"]
        return (
            0 if score is not None else 1,  # scored first
            -(score if score is not None else 0),  # higher score
            -b["executed"],
            b["engine"],
        )

    ranked = sorted(by_engine.values(), key=_key)
    top = ranked[:limit]

    envelope = {
        "window_hours": window_hours,
        "limit": limit,
        "engine_count": len(by_engine),
        "engines": top,
    }

    if as_json:
        print(json.dumps(envelope, indent=2, default=str))
        return

    if not top:
        # Empty-state UX: tell the operator WHY there's nothing
        # to rank + what to try next. Bare "No engine activity"
        # leaves them stuck.
        # Probe the queue for any historical activity so we can
        # distinguish "fresh install / never ran" from "ran but
        # not in this window".
        ever_ran = 0
        try:
            with queue._conn:
                row = queue._conn.execute(
                    "SELECT COUNT(*) AS n FROM pending_actions "
                    "WHERE status = 'executed'",
                ).fetchone()
            ever_ran = int(row["n"]) if row else 0
        except Exception as exc:  # noqa: BLE001
            logger.debug(
                "engine ranking empty-probe raised: %s", exc,
            )
        print(f"No engine activity in last {window_hours}h.")
        if ever_ran == 0:
            print()
            print(
                "  No executed actions in the approval queue yet."
            )
            print("  Likely cause: autonomous cycle hasn't fired.")
            print()
            print("  Next steps:")
            print(
                "    * shopai cycle verify        "
                "(preflight check)"
            )
            print(
                "    * shopai cycle run --yes     "
                "(run one cycle live)"
            )
            print(
                "    * shopai autonomy-status     "
                "(what's armed / fires today)"
            )
            print(
                "    * shopai go-live             "
                "(am I ready to schedule cron?)"
            )
        else:
            print()
            print(
                f"  {ever_ran} historical executed action(s) "
                "exist; try a wider window."
            )
            print()
            print("  Next steps:")
            print(
                "    * shopai engine ranking "
                "--window-hours 720    (30 days)"
            )
            print(
                "    * shopai engine ranking "
                "--window-hours 2160   (90 days)"
            )
            print(
                "    * shopai daily-brief         "
                "(yesterday's rollup)"
            )
        return

    print(
        f"Engine ranking (last {window_hours}h, "
        f"{len(by_engine)} engine(s) active):"
    )
    print()
    print(
        f"  {'RANK':>4s}  {'ENGINE':<22s} {'EXEC':>5s} "
        f"{'FAIL':>5s} {'+':>4s} {'-':>4s} {'SCORE':>6s} "
        f"{'REVENUE':>11s}  FLAGS"
    )
    print("  " + "-" * 76)
    for i, b in enumerate(top, start=1):
        score_str = (
            "n/a" if b["outcome_score"] is None
            else f"{b['outcome_score']:.0%}"
        )
        flags_str = ",".join(b.get("flags") or []) or ""
        print(
            f"  [{i:>2d}]  {b['engine']:<22s} "
            f"{b['executed']:>5d} {b['failed']:>5d} "
            f"{b['positive_outcomes']:>4d} "
            f"{b['negative_outcomes']:>4d} "
            f"{score_str:>6s} "
            f"${b['revenue']:>10,.2f}  {flags_str}"
        )
    # Top-engine highlight + truncation count -- helps
    # operators see who's the leader at a glance instead
    # of squinting at row 1.
    if top:
        leader = top[0]
        score_str = (
            "n/a" if leader["outcome_score"] is None
            else f"{leader['outcome_score']:.0%}"
        )
        truncated = max(0, len(ranked) - len(top))
        print()
        line = (
            f"  Top: {leader['engine']} "
            f"(score={score_str}, "
            f"executed={leader['executed']}, "
            f"revenue=${leader['revenue']:,.2f})"
        )
        if truncated:
            line += f"  -- +{truncated} more not shown"
        print(line)
        # Drill-down hint: operator sees the leader, the
        # natural next question is "what is this engine
        # actually doing?". engine summary is the per-engine
        # decision + outcome breakdown.
        print(
            f"    Drill down: `shopai engine summary "
            f"{leader['engine']}`"
        )


def _cmd_engine_alerts(args) -> None:
    """Flag engines whose recent outcome score has degraded
    relative to a longer baseline window.

    For each engine with executed activity in the recent
    window, compute outcome_score over BOTH the recent window
    (default 24h) and a baseline window (default 168h = 7 days).
    Alert when:
      - recent has at least ``--min-recent`` polarised outcomes
        (signal isn't pure noise)
      - baseline also has at least ``--min-recent`` polarised
        outcomes (we have something to compare against)
      - baseline_score - recent_score >= ``--threshold``

    Pure read from ``pending_actions`` + ``action_outcomes``.
    Cheap to run; suitable for cron alongside ``daily-brief``.
    """
    as_json = bool(getattr(args, "json", False))
    recent_hours = max(
        1, int(getattr(args, "recent_hours", 24) or 24),
    )
    baseline_hours = max(
        1, int(getattr(args, "baseline_hours", 168) or 168),
    )
    threshold = max(
        0.0, float(getattr(args, "threshold", 0.2) or 0.2),
    )
    min_recent = max(
        1, int(getattr(args, "min_recent", 3) or 3),
    )

    def _emit_error(msg: str) -> None:
        if as_json:
            print(json.dumps(
                {"status": "error", "error": msg},
                indent=2, default=str,
            ))
        else:
            print(f"Error: {msg}")
        sys.exit(1)

    if baseline_hours <= recent_hours:
        _emit_error(
            "--baseline-hours must exceed --recent-hours "
            "(otherwise the baseline overlaps the recent window)"
        )
        return

    # Delegate the detection logic to the shared module
    # (PR #282). Module raises ValueError on baseline<=recent
    # which we already validated above. Other queue exceptions
    # propagate -- we catch them here for the CLI envelope.
    try:
        from core.approval.outcome_trends import (
            compute_engine_alerts,
            compute_engine_alerts_per_store,
        )
        from core.approval.queue import get_approval_queue
    except Exception as exc:  # noqa: BLE001
        _emit_error(f"approval queue unavailable: {exc}")
        return

    queue = get_approval_queue()
    per_store = bool(getattr(args, "per_store", False))

    try:
        if per_store:
            engine_alerts = compute_engine_alerts_per_store(
                queue,
                recent_hours=float(recent_hours),
                baseline_hours=float(baseline_hours),
                threshold=threshold,
                min_recent=min_recent,
            )
        else:
            engine_alerts = compute_engine_alerts(
                queue,
                recent_hours=float(recent_hours),
                baseline_hours=float(baseline_hours),
                threshold=threshold,
                min_recent=min_recent,
            )
    except Exception as exc:  # noqa: BLE001
        _emit_error(f"queue scan failed: {exc}")
        return

    # Count distinct engines surveyed (same baseline window).
    # The module doesn't expose this; one cheap COUNT keeps the
    # envelope's ``engine_count`` field stable for callers.
    # Defensive: ``row["n"]`` might come back as a non-number
    # under MagicMock-based test fakes, so we type-check before
    # coercing.
    baseline_cutoff = time.time() - baseline_hours * 3600.0
    engine_count = 0
    try:
        with queue._conn:
            row = queue._conn.execute(
                """SELECT COUNT(DISTINCT engine) AS n
                   FROM pending_actions
                   WHERE status = 'executed'
                     AND decided_at >= ?""",
                (baseline_cutoff,),
            ).fetchone()
        if row is not None:
            raw_n = (
                row["n"] if hasattr(row, "__getitem__") else None
            )
            if isinstance(raw_n, (int, float)):
                engine_count = int(raw_n)
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "engine alerts engine_count probe raised: %s", exc,
        )

    # Quarantine flags per alerted engine: an alert against an
    # already-paused engine is informational only (the bridge
    # has already acted). Surface the flag so operators can
    # de-prioritise those.
    qstate = None
    try:
        from core.approval import quarantine as qm
        qstate = qm.load_state()
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "engine alerts quarantine probe raised: %s", exc,
        )

    def _engine_flags(name: str) -> list[str]:
        if qstate is None:
            return []
        out: list[str] = []
        if qstate.is_exempt(name):
            out.append("exempt")
        if qstate.is_released(name):
            out.append("released")
        if qstate.is_alert_paused(name):
            out.append("alert_paused")
        return out

    alerts = [
        {
            "engine": a.engine,
            "store_id": getattr(a, "store_id", None),
            "recent_executed": a.recent_executed,
            "baseline_executed": a.baseline_executed,
            "recent_score": a.recent_score,
            "baseline_score": a.baseline_score,
            "recent_polarised": a.recent_polarised,
            "baseline_polarised": a.baseline_polarised,
            "drop": a.drop,
            "kind": a.kind,
            "detail": a.detail,
            "flags": _engine_flags(a.engine),
        }
        for a in engine_alerts
    ]

    envelope = {
        "recent_hours": recent_hours,
        "baseline_hours": baseline_hours,
        "threshold": threshold,
        "min_recent": min_recent,
        "per_store": per_store,
        "engine_count": engine_count,
        "alert_count": len(alerts),
        "alerts": alerts,
    }

    if as_json:
        print(json.dumps(envelope, indent=2, default=str))
        return

    print(
        f"Engine alerts (recent={recent_hours}h, "
        f"baseline={baseline_hours}h, threshold={threshold:.0%}):"
    )
    print()
    if not alerts:
        if engine_count == 0:
            print(f"No engine activity in last {baseline_hours}h.")
        else:
            print(
                f"No alerts. {engine_count} engine(s) surveyed; "
                "no recent score drops past threshold."
            )
        return

    suffix = " (per-store)" if per_store else ""
    print(f"  {len(alerts)} alert(s) flagged{suffix}:")
    for a in alerts:
        store_label = (
            f"@{a['store_id']}" if a.get("store_id")
            else ""
        )
        engine_label = f"{a['engine']}{store_label}"
        flags_str = (
            f"  [{','.join(a['flags'])}]"
            if a.get("flags") else ""
        )
        print(
            f"  [{a['drop']:.0%} drop] {engine_label:<32s}  "
            f"{a['detail']}{flags_str}"
        )
        print(
            f"      recent executed={a['recent_executed']} "
            f"({a['recent_polarised']} polarised)  "
            f"baseline executed={a['baseline_executed']} "
            f"({a['baseline_polarised']} polarised)"
        )
    # Drill-down hint for the top-impacted engine, matching
    # the pattern across daily-brief / show / fleet / cycle
    # (a1deb294 et al). Points at engine pulse --history
    # for time-series inspection.
    if alerts:
        top = alerts[0]
        print()
        print(
            f"  Drill down: `shopai engine pulse "
            f"{top['engine']} --history`"
        )


def _cmd_engines_writebacks(args) -> None:
    """Catalog Phase 6/7 writeback wireup state per engine.

    Operators want a one-glance answer to: "which engines act
    autonomously on Shopify, and which are advisory-only?".
    This surface gives them three buckets:

      * ``wired``: full Phase 6/7 — writer module exists AND
        flow.py has the opt-in flag. Engine acts on Shopify
        when the operator opts in.
      * ``advisory``: no writer module + no opt-in flag.
        Engine only emits recommendations; operator must
        action manually.
      * ``partial``: half-wired — writer OR opt-in flag, not
        both. Indicates incomplete rollout; the next thing to
        fix.

    Today's catalog (per scan): ~24 wired / 111 advisory / 0
    partial. The wired set covers ~18% of engines; subsequent
    Phase 7 candidates (e.g. dropshipping, gift_card,
    subscription) will push that higher.
    """
    from engines._writeback_audit import audit_writeback_coverage

    try:
        report = audit_writeback_coverage("engines")
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "writeback audit raised: %s", exc,
        )
        if getattr(args, "json", False):
            print(json.dumps({"error": str(exc)}, indent=2))
        else:
            print(f"Writeback audit unavailable: {exc}")
        return

    filter_mode = getattr(args, "filter", "all") or "all"
    if filter_mode == "all":
        engines_filtered = report.engines
    else:
        engines_filtered = [
            s for s in report.engines if s.status == filter_mode
        ]

    # Build tag map ONCE (single AST scan), then attach per
    # engine. Cheap enough for the full catalog (~25 files).
    tag_map: dict[str, list[str]] = {}
    try:
        from engines._tag_catalog import catalog_tags
        tag_cat = catalog_tags("engines")
        for entry in tag_cat.entries:
            tag_map.setdefault(entry.engine, []).append(entry.tag)
        # dedup + sort per engine
        tag_map = {
            eng: sorted(set(tags))
            for eng, tags in tag_map.items()
        }
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "engines-writebacks tag-catalog probe raised: %s", exc,
        )

    if getattr(args, "json", False):
        print(json.dumps({
            "summary": {
                "total_engines": report.total_engines,
                "wired": report.wired_count,
                "advisory": report.advisory_count,
                "partial": report.partial_count,
            },
            "filter": filter_mode,
            "engines": [
                {
                    "name": s.name,
                    "status": s.status,
                    "writer_files": s.writer_files,
                    "opt_in_flags": s.opt_in_flags,
                    "writes_tags": tag_map.get(s.name, []),
                }
                for s in engines_filtered
            ],
        }, indent=2, default=str))
        return

    # Text render
    coverage_pct = (
        round(100 * report.wired_count / report.total_engines)
        if report.total_engines else 0
    )
    tag_writers = sum(1 for tags in tag_map.values() if tags)
    print(
        f"Engine writeback coverage: "
        f"{report.wired_count}/{report.total_engines} wired "
        f"({coverage_pct}%) — "
        f"{report.advisory_count} advisory, "
        f"{report.partial_count} partial"
    )
    if tag_writers > 0:
        print(
            f"  Of the wired engines, "
            f"{tag_writers} write Shopify tags. "
            f"Run `shopai engine tag-catalog` for the full namespace map."
        )

    if not engines_filtered:
        print()
        print(f"No engines match filter '{filter_mode}'.")
        return

    if filter_mode != "all":
        print(
            f"\nFiltered to status='{filter_mode}' "
            f"({len(engines_filtered)} engines):"
        )

    # Sort: wired first, then partial, then advisory; within
    # each bucket alphabetical
    status_rank = {"wired": 0, "partial": 1, "advisory": 2}
    sorted_engines = sorted(
        engines_filtered,
        key=lambda s: (status_rank.get(s.status, 9), s.name),
    )

    print()
    print("  engine                          status     writers  opt-ins")
    for s in sorted_engines:
        marker = (
            "!" if s.status == "partial"
            else " "
        )
        engine_label = s.name[:30]
        writers_count = len(s.writer_files)
        opt_ins_count = len(s.opt_in_flags)
        print(
            f"{marker} {engine_label:<30}  "
            f"{s.status:<9}  "
            f"{writers_count:>7}  "
            f"{opt_ins_count:>7}"
        )

    if filter_mode == "all" and report.partial_count > 0:
        print()
        print(
            f"NOTE: {report.partial_count} engine(s) are "
            "partially wired -- pass --filter partial to "
            "investigate."
        )

    # Drill-down hint: when filtered to wired engines, point at
    # `engine summary <first>` so operators can drill into the
    # actual writeback activity of any wired engine.
    if (
        filter_mode == "wired"
        and sorted_engines
    ):
        first = sorted_engines[0].name
        print()
        print(
            f"  Drill down: `shopai engine summary {first}`"
        )
        # Fleet smoke-test surface (7d2f2c51). Lets operators
        # verify every wired engine in one shot -- CI gate
        # for Phase 7 regressions.
        print(
            "  Smoke-test all: `shopai engine try-wireup "
            "--all` (dry-run)"
        )


def _cmd_engine_tag_catalog(args) -> None:
    """List every Shopify tag namespace written by a Phase 7 wireup.

    Phase 7 wireups tag products / customers / orders with
    structured ``namespace:value`` tags so operators can filter
    the Shopify admin catalog without re-running engines. This
    command builds the catalog from the actual ``*_applier.py``
    sources -- accurate by construction, no manual list to keep
    in sync.

    Output groups by tag namespace (e.g. ``risk:``, ``cohort:``)
    and shows which engine writes each tag + the Shopify entity
    it lands on (product / customer / order).

    Dynamic tags (built from runtime values via f-strings) are
    rendered as ``namespace:*`` -- the engine knows the prefix
    but the suffix depends on data.
    """
    from engines._tag_catalog import catalog_tags

    try:
        catalog = catalog_tags("engines")
    except Exception as exc:  # noqa: BLE001
        logger.debug("tag catalog raised: %s", exc)
        if getattr(args, "json", False):
            print(json.dumps({"error": str(exc)}, indent=2))
        else:
            print(f"Tag catalog unavailable: {exc}")
        return

    # Optional --namespace filter -- reverse-lookup from a tag
    # the operator sees in Shopify admin to the engine that
    # wrote it.
    ns_filter = (getattr(args, "namespace", None) or "").strip()
    if ns_filter:
        # Match: namespace key contains the filter OR any tag in
        # the namespace contains the filter (case-insensitive).
        f_lower = ns_filter.lower()
        filtered_namespaces = {
            ns: entries
            for ns, entries in catalog.by_namespace.items()
            if (
                f_lower in ns.lower()
                or any(f_lower in e.tag.lower() for e in entries)
            )
        }
        # Re-aggregate by_target from filtered entries
        filtered_entries = [
            e for entries in filtered_namespaces.values()
            for e in entries
        ]
        filtered_by_target: dict[str, list] = {}
        for e in filtered_entries:
            filtered_by_target.setdefault(e.target, []).append(e)
    else:
        filtered_namespaces = dict(catalog.by_namespace)
        filtered_entries = list(catalog.entries)
        filtered_by_target = dict(catalog.by_target)

    if getattr(args, "json", False):
        print(json.dumps({
            "summary": {
                "engines_scanned": catalog.engines_scanned,
                "total_tags": len(filtered_entries),
                "total_namespaces": len(filtered_namespaces),
                "by_target": {
                    t: len(es) for t, es in filtered_by_target.items()
                },
                "filter": ns_filter or None,
            },
            "namespaces": {
                ns: sorted({e.tag for e in entries})
                for ns, entries in sorted(filtered_namespaces.items())
            },
            "entries": [
                {
                    "tag": e.tag,
                    "engine": e.engine,
                    "capability": e.capability,
                    "target": e.target,
                }
                for e in filtered_entries
            ],
        }, indent=2, default=str))
        return

    if ns_filter:
        print(
            f"Shopify tag catalog -- "
            f"{len(filtered_entries)} tags matching '{ns_filter}' "
            f"across {len(filtered_namespaces)} namespace(s)"
        )
    else:
        print(
            f"Shopify tag catalog -- {catalog.total_tags} tags "
            f"across {catalog.total_namespaces} namespaces "
            f"({catalog.engines_scanned} engines scanned)"
        )
    print()

    if not filtered_namespaces:
        print(f"  No tags match '{ns_filter}'.")
        print(
            "  Run `shopai engine tag-catalog` without --namespace "
            "to see all 30+ namespaces."
        )
        return

    # Render by target (product / customer / order)
    target_order = ["product", "customer", "order", "unknown"]
    for target in target_order:
        entries = filtered_by_target.get(target, [])
        if not entries:
            continue
        print(f"  {target}: {len(entries)} tag(s)")
    print()

    # Render width: align tag lists at a consistent column so
    # the eye scans tags, not namespace label widths.
    print("  By namespace:")
    max_ns_width = max(
        (len(ns) for ns in filtered_namespaces),
        default=0,
    )
    for ns, entries in sorted(filtered_namespaces.items()):
        tags = sorted({e.tag for e in entries})
        engines = sorted({e.engine for e in entries})
        target = entries[0].target if entries else "unknown"
        # Two-space gap between label and content; no colon
        # after the label so it doesn't look like Shopify filter
        # syntax (which is `tag:<value>`, where <value> is the
        # full tag itself, NOT the namespace).
        ns_label = f"{ns}".ljust(max_ns_width + 2)
        print(
            f"    {ns_label}"
            f"{', '.join(tags)}"
            f"  ({target}; {', '.join(engines)})"
        )

    print()
    print(
        "  Filter the Shopify admin catalog by full tag: "
        "`tag:profit:high_roi`, `tag:shopai-segment-vip`, etc."
    )
    # Drill-down hint: try-wireup verifies any wired engine
    # actually fires its tag.
    if catalog.entries:
        first = catalog.entries[0].engine
        print(
            f"  Drill down: `shopai engine try-wireup {first}` "
            "(dry-run)"
        )


def _cmd_cluster_list(args) -> None:
    """List all 10 Tier 2b clusters with member counts + KPIs."""
    from engines._clusters import list_clusters
    from engines._cluster_captain import cluster_health
    from engines._cluster_memory import (
        enrich_with_attribution,
        fleet_cluster_health,
    )
    from engines._cluster_bus import bus_stats

    with_attr = bool(getattr(args, "with_attribution", False))
    attr_window = float(
        getattr(args, "attribution_window_hours", 168.0) or 168.0
    )

    # Wave 80: per-store niche bias annotation. Resolve the
    # store's niche + map cluster name -> rank in the niche
    # priority. Best-effort -- bare cluster list keeps working
    # when --store is omitted or the lookup fails.
    niche_rank_by_cluster: dict[str, int] = {}
    niche_store: dict[str, str] = {}
    store_arg = (getattr(args, "store", "") or "").strip()
    if store_arg:
        try:
            from engines._niche_priority import niche_cluster_focus
            sm = _get_store_manager()
            row = sm.get_store(store_arg)
            niche = ((row or {}).get("niche") or "").strip().lower()
            niche_store = {
                "store_id": store_arg, "niche": niche,
            }
            if niche and niche != "general":
                focus = niche_cluster_focus(niche)
                niche_rank_by_cluster = {
                    name: i + 1 for i, name in enumerate(focus)
                }
        except Exception:  # noqa: BLE001
            niche_rank_by_cluster = {}

    clusters = list_clusters()
    # Pull memory rollup ONCE for the fleet (single SQL hit)
    memory_by_cluster: dict = {}
    try:
        healths = fleet_cluster_health()
        if with_attr:
            enrich_with_attribution(
                healths, window_hours=attr_window,
            )
        for h in healths:
            memory_by_cluster[h.cluster] = h
    except Exception:  # noqa: BLE001
        memory_by_cluster = {}

    # Pull bus emit-counts per cluster (last 24h)
    bus_emits: dict[str, int] = {}
    try:
        b = bus_stats(window_hours=24.0)
        bus_emits = dict(b.get("by_emitter", {}))
    except Exception:  # noqa: BLE001
        bus_emits = {}

    rows: list[dict] = []
    for c in clusters:
        h = cluster_health(c.name)
        m = memory_by_cluster.get(c.name)
        rows.append({
            "name": c.name,
            "kpi": c.kpi,
            "total_members": h["total_members"],
            "wired_members": h["wired_members"],
            "risk_buckets": h["risk_buckets"],
            "description": c.description,
            "verdict": m.health_verdict if m else "unknown",
            "revenue_verdict": (
                m.revenue_verdict if m else "unknown"
            ),
            "executed": m.total_executed if m else 0,
            "positive_ratio": m.positive_ratio if m else 0.0,
            "revenue": m.total_revenue if m else 0.0,
            "attributed_revenue": (
                m.attributed_revenue if m else 0.0
            ),
            "attribution_orders": (
                m.attribution_orders if m else 0
            ),
            "bus_emits_24h": bus_emits.get(c.name, 0),
            "niche_rank": niche_rank_by_cluster.get(c.name),
        })

    if getattr(args, "json", False):
        payload = {
            "summary": {
                "total_clusters": len(rows),
                "total_engines_mapped": sum(
                    r["total_members"] for r in rows
                ),
                "wired_total": sum(
                    r["wired_members"] for r in rows
                ),
            },
            "clusters": rows,
        }
        if niche_store:
            payload["niche_bias"] = niche_store
        print(json.dumps(payload, indent=2, default=str))
        return

    print(
        f"Tier 2b clusters: {len(rows)} concerns covering "
        f"{sum(r['total_members'] for r in rows)} engines "
        f"({sum(r['wired_members'] for r in rows)} wired)"
    )
    if niche_store:
        n = niche_store.get("niche") or ""
        sid = niche_store.get("store_id") or ""
        if n and n != "general":
            print(
                f"  Niche bias: store {sid} -> {n} "
                f"(clusters with [Nk] are rank k in the niche "
                f"priority)"
            )
        else:
            print(
                f"  Niche bias: store {sid} has no niche set "
                f"(use `shopai niche --set {sid} <niche>` to "
                f"bias orchestration)"
            )
    print()
    if with_attr:
        print(
            "  cluster        wired   "
            "add/mod/dst  verdict      execd   rev   bus24h "
            "attrib7d  orders  revenue_verdict"
        )
    else:
        print(
            "  cluster        wired   "
            "add/mod/dst  verdict      execd   rev   bus24h"
        )
    revenue_verdict_marker = {
        "earning": "[OK ]",
        "flat": "[ - ]",
        "declining": "[BAD]",
        "unknown": "[ ? ]",
    }
    for r in rows:
        rb = r["risk_buckets"]
        risk_str = (
            f"{rb.get('additive', 0)}/"
            f"{rb.get('modification', 0)}/"
            f"{rb.get('destructive', 0)}"
        )
        verdict_marker = {
            "healthy": "[OK ]",
            "warning": "[WRN]",
            "unhealthy": "[BAD]",
            "unknown": "[ - ]",
        }.get(r["verdict"], "[ ? ]")
        rev_str = (
            f"${r['revenue']:.0f}" if r["revenue"] > 0 else "-"
        )
        bus_str = (
            str(r["bus_emits_24h"])
            if r["bus_emits_24h"] > 0 else "-"
        )
        # Wave 80: prefix cluster name with [Nk] when this
        # store's niche prefers this cluster (k = 1..len).
        nrank = r.get("niche_rank")
        name_str = (
            f"[N{nrank}] {r['name']}" if nrank
            else f"     {r['name']}"
        ) if niche_rank_by_cluster else r["name"]
        name_width = 19 if niche_rank_by_cluster else 14
        line = (
            f"  {name_str:<{name_width}} {r['wired_members']:>4d}/"
            f"{r['total_members']:<2d}  "
            f"{risk_str:<10}  {verdict_marker} {r['verdict']:<9}  "
            f"{r['executed']:>5d}  {rev_str:<6} {bus_str}"
        )
        if with_attr:
            attr_rev = r["attributed_revenue"]
            attr_orders = r["attribution_orders"]
            attr_str = (
                f"${attr_rev:.0f}" if attr_rev > 0 else "-"
            )
            order_str = (
                str(attr_orders) if attr_orders > 0 else "-"
            )
            rv = r.get("revenue_verdict", "unknown")
            rv_marker = revenue_verdict_marker.get(rv, "[ ? ]")
            line = (
                f"{line}  {attr_str:<8}  {order_str:<6}  "
                f"{rv_marker} {rv}"
            )
        print(line)
    print()
    print(
        "  Drill: `shopai cluster show <name>` "
        "(detailed member view)"
    )
    print(
        "  Plan:  `shopai cluster plan <name>` "
        "(captain dispatch preview)"
    )
    if not with_attr:
        print(
            "  Attrib: `shopai cluster list --with-attribution` "
            "(ground-truth revenue per cluster)"
        )


def _cmd_cluster_show(args) -> None:
    """Show one cluster's detailed member breakdown."""
    from engines._cluster_captain import cluster_health
    from engines._cluster_memory import (
        cluster_health_rollup,
        enrich_with_attribution,
    )

    cluster_name = (args.cluster_name or "").strip()
    if not cluster_name:
        print("Error: cluster_name required")
        sys.exit(1)

    h = cluster_health(cluster_name)
    if "error" in h:
        print(f"Error: {h['error']}")
        print()
        print("Available clusters:")
        from engines._clusters import list_clusters
        for c in list_clusters():
            print(f"  {c.name}")
        sys.exit(1)

    # Wave 19: enrich with revenue picture. Best-effort -- if
    # attribution unavailable, the section just doesn't render.
    revenue_block: dict | None = None
    try:
        health = cluster_health_rollup(cluster_name)
        if health is not None:
            enrich_with_attribution(
                [health], window_hours=168.0,
            )
            # Sum per-engine attribution to surface top members
            from engines._revenue_attribution import attribute_revenue
            report = attribute_revenue(window_hours=168.0)
            wired_set = {
                row["engine"] for row in h["members"]
                if row.get("writeback") == "wired"
            }
            top_engines = []
            for e in report.per_engine:
                if e.engine in wired_set:
                    top_engines.append({
                        "engine": e.engine,
                        "attributed_revenue": round(
                            e.attributed_revenue, 2,
                        ),
                        "attributed_orders": e.attributed_orders,
                        "confidence": e.confidence,
                    })
                if len(top_engines) >= 5:
                    break
            revenue_block = {
                "attributed_revenue": health.attributed_revenue,
                "attribution_orders": health.attribution_orders,
                "attribution_confidence": (
                    health.attribution_confidence
                ),
                "attribution_window_hours": (
                    health.attribution_window_hours
                ),
                "revenue_verdict": health.revenue_verdict,
                "health_verdict": health.health_verdict,
                "top_engines": top_engines,
            }
    except Exception:  # noqa: BLE001
        revenue_block = None

    if getattr(args, "json", False):
        payload = dict(h)
        payload["revenue"] = revenue_block
        print(json.dumps(payload, indent=2, default=str))
        return

    print(f"Cluster: {h['cluster']}")
    print(f"  KPI:         {h['kpi']}")
    print(f"  Description: {h['description']}")
    print(
        f"  Members:     "
        f"{h['wired_members']}/{h['total_members']} wired "
        f"({h['advisory_members']} advisory)"
    )
    print(f"  Risk:        {h['risk_buckets']}")

    # Wave 32: per-cluster revenue trend (oldest first).
    # Opt-in to keep cluster show light by default.
    if getattr(args, "revenue_history", False):
        try:
            from engines._attribution_snapshot import (
                cluster_revenue_history,
            )
            rev_rows = cluster_revenue_history(cluster_name)
            if rev_rows:
                print()
                print(
                    f"  Revenue history ({len(rev_rows)} "
                    f"data point(s), oldest first):"
                )
                import time as _t
                now = _t.time()
                for row in rev_rows[-15:]:
                    age = now - row["captured_at"]
                    if age < 3600:
                        age_str = f"{int(age/60)}m"
                    elif age < 86400:
                        age_str = f"{age/3600:.1f}h"
                    else:
                        age_str = f"{age/86400:.1f}d"
                    print(
                        f"    {age_str:<6} ago  "
                        f"${row['attributed_revenue']:>9,.2f}  "
                        f"orders={row['attributed_orders']:>3}  "
                        f"({row['confidence']})"
                    )
        except Exception:  # noqa: BLE001
            pass

    if revenue_block is not None:
        print()
        print("  Revenue (7d):")
        verdict_marker = {
            "earning": "[OK ]",
            "flat": "[ - ]",
            "declining": "[BAD]",
            "unknown": "[ ? ]",
        }.get(revenue_block["revenue_verdict"], "[ ? ]")
        print(
            f"    Attributed:    "
            f"${revenue_block['attributed_revenue']:,.2f}   "
            f"orders={revenue_block['attribution_orders']}   "
            f"confidence={revenue_block['attribution_confidence']}"
        )
        print(
            f"    Revenue verdict: {verdict_marker} "
            f"{revenue_block['revenue_verdict']}"
        )
        print(
            f"    Health verdict:  {revenue_block['health_verdict']}"
        )
        if revenue_block["top_engines"]:
            print("    Top earners:")
            for te in revenue_block["top_engines"]:
                print(
                    f"      {te['engine'][:30]:<30}  "
                    f"${te['attributed_revenue']:>8,.2f}  "
                    f"orders={te['attributed_orders']}"
                )

    print()
    print("  engine                          writeback   risk")
    for row in h["members"]:
        engine = row["engine"][:30]
        wb = row["writeback"]
        risk = row["risk"]
        print(
            f"    {engine:<30}  {wb:<10}  {risk}"
        )


def _store_stats_for_captain(store_id: str | None) -> dict | None:
    """Wave 43: pull world_model.stats for a single store so
    cluster plan / cluster fire benefit from Wave 42's empty-
    input skip filter. None when store_id is missing or the
    snapshot raises."""
    if not store_id:
        return None
    try:
        from core.world_model import WorldModel
        snap = WorldModel().snapshot(store_id, skip_live=True)
        stats = snap.get("stats") if isinstance(snap, dict) else None
        return stats if isinstance(stats, dict) else None
    except Exception:  # noqa: BLE001
        return None


def _cmd_cluster_plan(args) -> None:
    """Generate + render a captain plan for one cluster."""
    from engines._cluster_captain import (
        make_captain_plan,
        SignalDrivenCaptainStrategy,
    )

    cluster_name = (args.cluster_name or "").strip()
    if not cluster_name:
        print("Error: cluster_name required")
        sys.exit(1)

    store_id = (
        getattr(args, "store", None)
        or _get_store_manager().active_store_id
    )

    # Parse --signals if supplied + switch to signal-driven
    # strategy. Otherwise use the default (deterministic
    # fire-all-wired).
    signals: dict | None = None
    strategy = None
    raw_signals = getattr(args, "signals", None) or ""
    if raw_signals:
        try:
            parsed = json.loads(raw_signals)
            if not isinstance(parsed, dict):
                print("Error: --signals must be a JSON object")
                sys.exit(1)
                return
            signals = parsed
            strategy = SignalDrivenCaptainStrategy()
        except json.JSONDecodeError as exc:
            print(f"Error: --signals invalid JSON: {exc}")
            sys.exit(1)
            return

    plan = make_captain_plan(
        cluster_name, store_id=store_id,
        signals=signals, strategy=strategy,
        store_stats=_store_stats_for_captain(store_id),
    )

    # Wave 81: surface niche bias for this cluster + store so
    # operator sees WHY the captain is firing what it is. The
    # orchestrator used the same merge_with_base call to pick
    # this cluster's slot in the rotation.
    niche_block: dict | None = None
    if store_id:
        try:
            from engines._niche_priority import niche_cluster_focus
            sm = _get_store_manager()
            row = sm.get_store(store_id)
            niche = ((row or {}).get("niche") or "").strip().lower()
            if niche and niche != "general":
                focus = niche_cluster_focus(niche)
                rank = next(
                    (i + 1 for i, name in enumerate(focus)
                     if name == cluster_name),
                    None,
                )
                niche_block = {
                    "store_id": store_id,
                    "niche": niche,
                    "rank": rank,
                    "in_bias": rank is not None,
                }
        except Exception:  # noqa: BLE001
            niche_block = None

    if getattr(args, "json", False):
        payload = {
            "cluster": plan.cluster,
            "store_id": plan.store_id,
            "fire_count": plan.fire_count,
            "auto_count": plan.auto_count,
            "members_to_fire": plan.members_to_fire,
            "modifications_queued": plan.modifications_queued,
            "members_to_skip": plan.members_to_skip,
            "notes": plan.notes,
        }
        if niche_block:
            payload["niche_bias"] = niche_block
        print(json.dumps(payload, indent=2, default=str))
        return

    print(f"Captain plan: {plan.cluster}  (store={plan.store_id or 'all'})")
    if niche_block:
        n = niche_block.get("niche") or ""
        rank = niche_block.get("rank")
        if rank:
            print(
                f"  Niche bias: store -> {n}; this cluster is "
                f"rank {rank} in the niche priority (Wave 73 "
                f"orchestrator favours it)"
            )
        else:
            print(
                f"  Niche bias: store -> {n}; this cluster is "
                f"NOT in the niche priority (base order applies)"
            )
    print()
    print(
        f"  Auto-fire (additive):     "
        f"{len(plan.members_to_fire):3d} engine(s)"
    )
    print(
        f"  Queued (modification):    "
        f"{len(plan.modifications_queued):3d} engine(s)"
    )
    print(
        f"  Skipped:                  "
        f"{len(plan.members_to_skip):3d} engine(s)"
    )
    if plan.notes:
        print(f"  Notes:                    {len(plan.notes):3d}")
    print()

    if plan.members_to_fire:
        print("  AUTO-FIRE (additive, captain decides):")
        for m in plan.members_to_fire:
            print(
                f"    [fire] {m['engine']:<28} "
                f"apply={m['apply_flag']}"
            )
        print()

    if plan.modifications_queued:
        print("  QUEUED for approval (modification tier):")
        for m in plan.modifications_queued:
            print(
                f"    [queue] {m['engine']:<27} "
                f"apply={m['apply_flag']}  ({m['risk']})"
            )
        print()

    if plan.members_to_skip:
        print("  SKIPPED:")
        for m in plan.members_to_skip[:8]:
            print(
                f"    [skip] {m['engine']:<28} "
                f"reason={m['reason']}"
            )
        if len(plan.members_to_skip) > 8:
            print(
                f"    ... and {len(plan.members_to_skip) - 8} "
                "more"
            )
        print()

    if plan.notes:
        print("  NOTES:")
        for n in plan.notes:
            print(f"    {n}")


def _cmd_outcomes_report(args) -> None:
    """Time-windowed outcome rollup.

    Per-cluster (default): rolls up all member engines'
    outcomes within the window.
    Per-engine (--engine): shows ONE engine's outcomes.
    """
    from engines._outcome_window import (
        engine_outcomes_window,
        cluster_outcomes_window,
        fleet_outcomes_window,
    )

    as_json = bool(getattr(args, "json", False))
    try:
        window_hours = float(
            getattr(args, "window", "168") or "168"
        )
    except (TypeError, ValueError):
        window_hours = 168.0

    engine_name = (getattr(args, "engine", None) or "").strip()
    cluster_name = (getattr(args, "cluster", None) or "").strip()
    store_id = (getattr(args, "store", None) or "").strip() or None

    # Mode: single-engine drill-down
    if engine_name:
        w = engine_outcomes_window(
            engine_name, window_hours=window_hours,
            store_id=store_id,
        )
        if as_json:
            print(json.dumps({
                "scope": w.scope,
                "window_hours": w.window_hours,
                "positive": w.positive_count,
                "negative": w.negative_count,
                "neutral": w.neutral_count,
                "total_outcomes": w.total_outcomes,
                "total_revenue": w.total_revenue,
                "positive_ratio": w.positive_ratio,
                "trending_positive": w.is_trending_positive,
                "trending_negative": w.is_trending_negative,
                "sample_rows": w.sample_rows,
            }, indent=2, default=str))
            return
        print(
            f"Engine outcomes: {engine_name}  "
            f"(window: {window_hours:.0f}h, store: "
            f"{store_id or 'fleet'})"
        )
        print()
        print(
            f"  Positive:  {w.positive_count:3d}    "
            f"Negative: {w.negative_count:3d}    "
            f"Neutral:  {w.neutral_count:3d}"
        )
        print(
            f"  Total:     {w.total_outcomes:3d}    "
            f"Revenue:  ${w.total_revenue:.2f}"
        )
        print(
            f"  Positive ratio: {w.positive_ratio:.2f}"
        )
        if w.is_trending_positive:
            print("  Trend: improving")
        elif w.is_trending_negative:
            print("  Trend: degrading")
        if w.sample_rows:
            print()
            print("  Recent outcomes:")
            for s in w.sample_rows[:5]:
                print(
                    f"    {s['polarity']:<10} "
                    f"topic={s['topic']:<20} "
                    f"rev=${s['revenue']:.2f}"
                )
        return

    # Mode: single cluster
    if cluster_name:
        w = cluster_outcomes_window(
            cluster_name, window_hours=window_hours,
            store_id=store_id,
        )
        if as_json:
            print(json.dumps({
                "scope": w.scope,
                "window_hours": w.window_hours,
                "positive": w.positive_count,
                "negative": w.negative_count,
                "neutral": w.neutral_count,
                "total_outcomes": w.total_outcomes,
                "total_revenue": w.total_revenue,
                "positive_ratio": w.positive_ratio,
            }, indent=2, default=str))
            return
        print(
            f"Cluster outcomes: {cluster_name}  "
            f"(window: {window_hours:.0f}h)"
        )
        print()
        print(
            f"  Positive:  {w.positive_count:3d}    "
            f"Negative: {w.negative_count:3d}    "
            f"Neutral:  {w.neutral_count:3d}"
        )
        print(
            f"  Total:     {w.total_outcomes:3d}    "
            f"Revenue:  ${w.total_revenue:.2f}"
        )
        print(
            f"  Positive ratio: {w.positive_ratio:.2f}"
        )
        return

    # Mode: fleet-wide rollup
    windows = fleet_outcomes_window(window_hours=window_hours)
    if as_json:
        print(json.dumps({
            "window_hours": window_hours,
            "clusters": [
                {
                    "scope": w.scope,
                    "positive": w.positive_count,
                    "negative": w.negative_count,
                    "neutral": w.neutral_count,
                    "total_outcomes": w.total_outcomes,
                    "total_revenue": w.total_revenue,
                    "positive_ratio": w.positive_ratio,
                    "trending_positive": w.is_trending_positive,
                    "trending_negative": w.is_trending_negative,
                }
                for w in windows
            ],
        }, indent=2, default=str))
        return

    print(
        f"Fleet outcomes  (window: {window_hours:.0f}h "
        f"= {window_hours/24:.1f} days)"
    )
    print()
    total_pos = sum(w.positive_count for w in windows)
    total_neg = sum(w.negative_count for w in windows)
    total_neu = sum(w.neutral_count for w in windows)
    total_rev = sum(w.total_revenue for w in windows)
    print(
        f"  Empire total: {total_pos+total_neg+total_neu} "
        f"outcomes, ${total_rev:.2f} revenue"
    )
    print(
        f"    positive={total_pos}  negative={total_neg}  "
        f"neutral={total_neu}"
    )
    print()
    print(
        f"  {'cluster':<14} {'pos':>4} {'neg':>4} "
        f"{'neu':>4} {'revenue':>10} trend"
    )
    for w in windows:
        cluster = w.scope.replace("cluster:", "")
        trend = (
            "improving" if w.is_trending_positive
            else "degrading" if w.is_trending_negative
            else "-"
        )
        rev_str = f"${w.total_revenue:.0f}"
        print(
            f"  {cluster:<14} "
            f"{w.positive_count:>4d} "
            f"{w.negative_count:>4d} "
            f"{w.neutral_count:>4d} "
            f"{rev_str:>10} {trend}"
        )
    print()
    print("  Drill: `shopai cluster-outcomes --cluster <name>`")
    print("         `shopai cluster-outcomes --engine <name>`")


