def _cmd_ai_strategy_status(args) -> None:
    """Show AI strategy state for the operator."""
    from engines._ai_strategies import _ai_enabled, _LLMClient

    as_json = bool(getattr(args, "json", False))

    enabled = _ai_enabled()
    has_api_key = bool(os.environ.get("OPENAI_API_KEY"))
    has_openai_lib = False
    try:
        import openai  # noqa: F401
        has_openai_lib = True
    except ImportError:
        pass

    llm = _LLMClient()
    available = llm.available
    model = os.environ.get(
        "SHOPAI_AI_STRATEGY_MODEL", "gpt-4o-mini",
    )
    timeout = float(
        os.environ.get("SHOPAI_AI_STRATEGY_TIMEOUT", "15")
        or "15"
    )

    effective_mode = (
        "ai" if (enabled and available) else "deterministic"
    )

    # Revenue-aware substrate wrappers (independent of AI gate).
    try:
        from engines._revenue_aware_orchestrator import (
            revenue_aware_enabled,
        )
        revenue_aware = revenue_aware_enabled()
    except Exception:  # noqa: BLE001
        revenue_aware = False
    try:
        from engines._revenue_aware_captain import (
            revenue_aware_captain_enabled,
        )
        revenue_aware_capt = revenue_aware_captain_enabled()
    except Exception:  # noqa: BLE001
        revenue_aware_capt = False

    if as_json:
        print(json.dumps({
            "effective_mode": effective_mode,
            "env_enabled": enabled,
            "has_openai_lib": has_openai_lib,
            "has_api_key": has_api_key,
            "llm_available": available,
            "model": model,
            "timeout_seconds": timeout,
            "revenue_aware_orchestrator": revenue_aware,
            "revenue_aware_captain": revenue_aware_capt,
        }, indent=2))
        return

    print("AI strategy status")
    print()
    print(f"  Effective mode:        {effective_mode}")
    print()
    print(f"  Env-var enabled:       "
          f"{'yes' if enabled else 'no'} "
          f"(SHOPAI_AI_STRATEGY={'1' if enabled else '0'})")
    print(f"  openai library:        "
          f"{'installed' if has_openai_lib else 'missing'}")
    print(f"  OPENAI_API_KEY set:    "
          f"{'yes' if has_api_key else 'no'}")
    print(f"  LLM available:         "
          f"{'yes' if available else 'no'}")
    print(f"  Model:                 {model}")
    print(f"  Timeout (seconds):     {timeout}")
    print()
    if effective_mode == "deterministic":
        print("  Reason for deterministic fallback:")
        if not enabled:
            print("    - SHOPAI_AI_STRATEGY env-var not set")
        if not has_openai_lib:
            print(
                "    - openai library not installed "
                "(pip install openai)"
            )
        if not has_api_key:
            print(
                "    - OPENAI_API_KEY env-var not set"
            )
        print()
    print("  To enable AI consult:")
    print("    pip install openai")
    print("    export OPENAI_API_KEY=sk-...")
    print("    export SHOPAI_AI_STRATEGY=1")
    print()
    print(
        "  Revenue-aware orchestrator:  "
        f"{'on' if revenue_aware else 'off'} "
        f"(SHOPAI_REVENUE_AWARE_ORCHESTRATOR="
        f"{'1' if revenue_aware else '0'})"
    )
    print(
        "    Re-ranks cluster_focus by attributed revenue; "
        "independent of AI gate"
    )
    print(
        "  Revenue-aware captain:       "
        f"{'on' if revenue_aware_capt else 'off'} "
        f"(SHOPAI_REVENUE_AWARE_CAPTAIN="
        f"{'1' if revenue_aware_capt else '0'})"
    )
    print(
        "    Re-orders cluster members by per-engine "
        "attribution"
    )
    print()
    print("  Test connectivity:  `shopai ai-strategy test`")


def _cmd_ai_strategy_test(args) -> None:
    """Test LLM connectivity with a known prompt."""
    from engines._ai_strategies import _LLMClient

    as_json = bool(getattr(args, "json", False))

    llm = _LLMClient()
    if not llm.available:
        msg = (
            "LLM not available. Run `shopai ai-strategy status` "
            "to see what's missing (openai lib / API key)."
        )
        if as_json:
            print(json.dumps(
                {"status": "error", "error": msg},
                indent=2,
            ))
        else:
            print(f"Error: {msg}")
        sys.exit(1)
        return

    system = (
        "You are a connectivity test. Return JSON: "
        "{\"ok\": true, \"answer\": <short string>}"
    )
    user = (
        "Reply with ok=true and answer='pong'. "
        "This is a smoke test for ShopAI's LLM substrate."
    )

    try:
        resp = llm.chat_json(system, user)
    except Exception as exc:  # noqa: BLE001
        if as_json:
            print(json.dumps(
                {"status": "error", "error": str(exc)},
                indent=2,
            ))
        else:
            print(f"Error: LLM call raised: {exc}")
        sys.exit(1)
        return

    if resp is None:
        if as_json:
            print(json.dumps({
                "status": "error",
                "error": "LLM returned None (network / parse)",
            }, indent=2))
        else:
            print("Error: LLM returned None")
        sys.exit(1)
        return

    if as_json:
        print(json.dumps({
            "status": "ok",
            "response": resp,
        }, indent=2, default=str))
        return

    print("AI strategy test  (LLM connectivity)")
    print()
    print(f"  Response: {json.dumps(resp)[:200]}")
    print()
    if resp.get("ok"):
        print("  [OK] LLM responding + returning valid JSON")
    else:
        print("  [WRN] LLM responded but ok=false")


def _cmd_cycle_status(args) -> None:
    """One-glance empire health dashboard."""
    import time as _time
    from engines._cycle_history import last_run, runs_for_store
    from engines._cluster_memory import fleet_cluster_health
    from engines._cluster_bus import bus_stats

    as_json = bool(getattr(args, "json", False))
    store_filter = (
        getattr(args, "store", None) or ""
    ).strip() or None

    # 1. Last cycle run (optionally per-store)
    if store_filter:
        runs = runs_for_store(store_filter, limit=1)
        last = runs[0] if runs else None
    else:
        last = last_run()
    last_block = None
    if last is not None:
        age = _time.time() - last.started_at
        if age < 3600:
            age_str = f"{int(age/60)}m ago"
        elif age < 86400:
            age_str = f"{age/3600:.1f}h ago"
        else:
            age_str = f"{age/86400:.1f}d ago"
        last_block = {
            "verdict": last.verdict,
            "age_str": age_str,
            "total_invoked": last.total_invoked,
            "total_ok": last.total_ok,
            "total_errors": last.total_errors,
            "mode": last.mode,
            "stores": last.total_stores,
        }

    # 2. Fleet cluster verdicts
    try:
        fleet_health = fleet_cluster_health()
    except Exception:  # noqa: BLE001
        fleet_health = []

    verdict_counts: dict[str, int] = {}
    for h in fleet_health:
        v = h.health_verdict
        verdict_counts[v] = verdict_counts.get(v, 0) + 1

    # 3. Bus activity (filterable per-store via subscribe)
    try:
        from engines._cluster_bus import subscribe_events
        if store_filter:
            events = subscribe_events(
                store_id=store_filter, window_hours=24.0,
            )
            by_topic: dict = {}
            by_emitter: dict = {}
            for e in events:
                by_topic[e.topic] = by_topic.get(e.topic, 0) + 1
                by_emitter[e.emitter_cluster] = (
                    by_emitter.get(e.emitter_cluster, 0) + 1
                )
            by_topic_sorted = dict(sorted(
                by_topic.items(), key=lambda kv: -kv[1],
            ))
            by_emitter_sorted = dict(sorted(
                by_emitter.items(), key=lambda kv: -kv[1],
            ))
            bus_block = {
                "total_events": len(events),
                "top_topic": (
                    list(by_topic_sorted.keys())[0]
                    if by_topic_sorted else None
                ),
                "top_emitter": (
                    list(by_emitter_sorted.keys())[0]
                    if by_emitter_sorted else None
                ),
            }
        else:
            bs = bus_stats(window_hours=24.0)
            bus_block = {
                "total_events": bs["total_events"],
                "top_topic": (
                    list(bs["by_topic"].keys())[0]
                    if bs["by_topic"] else None
                ),
                "top_emitter": (
                    list(bs["by_emitter"].keys())[0]
                    if bs["by_emitter"] else None
                ),
            }
    except Exception:  # noqa: BLE001
        bus_block = {"total_events": 0}

    # 4. Audit summary (cheap version: just count violations
    # since full audit re-run is expensive)
    audit_ok = True
    audit_violations = 0
    try:
        from engines._cluster_audit import audit_clusters
        cr = audit_clusters()
        audit_ok = not cr.has_violations
        audit_violations = len(cr.violations)
    except Exception:  # noqa: BLE001
        audit_ok = False

    # 5. AI strategy state
    try:
        from engines._ai_strategies import (
            _ai_enabled, _LLMClient,
        )
        ai_enabled_env = _ai_enabled()
        ai_available = _LLMClient().available
        ai_mode = (
            "ai" if (ai_enabled_env and ai_available)
            else "deterministic"
        )
    except Exception:  # noqa: BLE001
        ai_enabled_env = False
        ai_available = False
        ai_mode = "deterministic"

    # W846: substrate-fire summary block (last 24h)
    substrate_fire_block = None
    try:
        from core.automation.substrate_fire_log import (
            recent_substrate_fires,
        )
        sf_rows = recent_substrate_fires(
            window_hours=24.0,
            store_id=store_filter or None,
        )
        if sf_rows:
            substrate_fire_block = {
                "window_hours": 24.0,
                "total_outcomes": len(sf_rows),
                "fired": sum(
                    1 for r in sf_rows if r.get("invoked")
                ),
                "dry_run": sum(
                    1 for r in sf_rows
                    if r.get("reason") == "dry_run"
                ),
                "errors": sum(
                    1 for r in sf_rows
                    if r.get("reason") in (
                        "applier_error", "discoverer_error",
                    )
                ),
            }
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "cycle status substrate-fire block raised: %s",
            exc,
        )

    # 6. Revenue attribution (Shopify ground truth)
    attribution_block = None
    try:
        from engines._revenue_attribution import attribute_revenue
        ar = attribute_revenue(
            window_hours=168.0,
            store_id=store_filter,
        )
        attribution_block = {
            "window_hours": ar.window_hours,
            "total_orders_in_window": ar.total_orders_in_window,
            "total_revenue_in_window": round(
                ar.total_revenue_in_window, 2,
            ),
            "attributed_revenue": round(ar.attributed_revenue, 2),
            "attribution_rate": ar.attribution_rate,
            "cluster_count": len(ar.per_cluster),
            "top_cluster": (
                ar.per_cluster[0].cluster if ar.per_cluster else None
            ),
        }
    except Exception:  # noqa: BLE001
        attribution_block = None

    # 7. Cycle-over-cycle revenue delta (Wave 12). Surfaces
    # regression alerts inline so the empire dashboard catches
    # bad trends without operator drill-down.
    delta_block = None
    try:
        from engines._attribution_delta import latest_delta
        ld = latest_delta(store_id=store_filter)
        if ld is not None:
            delta_block = {
                "overall_revenue_delta": ld.overall_revenue_delta,
                "overall_revenue_delta_pct": (
                    ld.overall_revenue_delta_pct
                ),
                "alert_count": len(ld.alerts),
                "top_alert": (
                    ld.alerts[0].reason if ld.alerts else None
                ),
                "top_alert_scope": (
                    f"{ld.alerts[0].scope}:{ld.alerts[0].name}"
                    if ld.alerts else None
                ),
            }
    except Exception:  # noqa: BLE001
        delta_block = None

    if as_json:
        print(json.dumps({
            "last_run": last_block,
            "cluster_verdicts": verdict_counts,
            "bus_24h": bus_block,
            "audit_ok": audit_ok,
            "audit_violations": audit_violations,
            "attribution_168h": attribution_block,
            "substrate_fire_24h": substrate_fire_block,
            "cycle_delta": delta_block,
            "ai_strategy": {
                "mode": ai_mode,
                "env_enabled": ai_enabled_env,
                "llm_available": ai_available,
            },
        }, indent=2, default=str))
        return

    if store_filter:
        print(f"Empire status  (store filter: {store_filter})")
    else:
        print("Empire status")
    print()

    print("  Last cycle run:")
    if last_block is None:
        print("    (no runs recorded yet)")
        print(
            "    Start with: `shopai cycle verify --store X`"
        )
    else:
        verdict_marker = {
            "clean": "[OK ]",
            "mostly_ok": "[OK ]",
            "dry_run": "[ - ]",
            "empty": "[ - ]",
            "degraded": "[WRN]",
            "failed": "[BAD]",
        }.get(last_block["verdict"], "[ ? ]")
        print(
            f"    {verdict_marker} {last_block['verdict']:<10}  "
            f"{last_block['age_str']}  "
            f"({last_block['mode']}, "
            f"stores={last_block['stores']}, "
            f"invoked={last_block['total_invoked']}, "
            f"ok={last_block['total_ok']}, "
            f"err={last_block['total_errors']})"
        )
    print()

    print("  Revenue attribution (7d):")
    if attribution_block is None:
        print("    (attribution unavailable)")
    elif attribution_block["total_orders_in_window"] == 0:
        print("    (no orders in window)")
        print(
            "    Drill: `shopai store seed-products` "
            "+ go live to start earning"
        )
    else:
        orders = attribution_block["total_orders_in_window"]
        rev = attribution_block["total_revenue_in_window"]
        attr_rev = attribution_block["attributed_revenue"]
        attr_rate = attribution_block["attribution_rate"]
        clusters = attribution_block["cluster_count"]
        top = attribution_block.get("top_cluster")
        marker = "[OK ]" if attr_rev > 0 else "[WRN]"
        print(
            f"    {marker} ${attr_rev:,.2f} attributed   "
            f"({attr_rate * 100:.0f}% of ${rev:,.2f} "
            f"across {orders} orders)"
        )
        if clusters > 0 and top is not None:
            print(
                f"    top cluster: {top}  "
                f"({clusters} clusters matched)"
            )
        print(
            "    Drill: `shopai cycle attribution`"
        )
    print()

    # W846: substrate-fire summary (24h)
    if substrate_fire_block is not None:
        n_err = substrate_fire_block["errors"]
        n_fired = substrate_fire_block["fired"]
        n_dry = substrate_fire_block["dry_run"]
        n_total = substrate_fire_block["total_outcomes"]
        marker = (
            "[BAD]" if n_err
            else "[OK ]" if n_fired else "[ - ]"
        )
        print("  Substrate-fire (24h):")
        print(
            f"    {marker} {n_total} outcome(s)  "
            f"fired={n_fired}  dry_run={n_dry}  "
            f"errors={n_err}"
        )
        print(
            "    Drill: `shopai autonomy-fire-status "
            "--window-hours 24`"
        )
        print()

    if delta_block is not None:
        d_rev = delta_block["overall_revenue_delta"]
        d_pct = delta_block["overall_revenue_delta_pct"]
        alert_n = delta_block["alert_count"]
        print("  Cycle-over-cycle delta:")
        if d_pct is None:
            pct_str = "(n/a)"
        elif d_pct > 0:
            pct_str = f"+{d_pct * 100:.1f}%"
        else:
            pct_str = f"{d_pct * 100:.1f}%"
        marker = (
            "[BAD]" if alert_n > 0
            else ("[OK ]" if d_rev >= 0 else "[WRN]")
        )
        print(
            f"    {marker} ${d_rev:+,.2f}   {pct_str}   "
            f"alerts: {alert_n}"
        )
        if delta_block["top_alert_scope"]:
            print(
                f"    top alert: "
                f"{delta_block['top_alert_scope']} -- "
                f"{delta_block['top_alert']}"
            )
        print(
            "    Drill: `shopai cycle attribution-delta`"
        )
        print()

    print("  Cluster health (10 clusters):")
    if not verdict_counts:
        print("    (no history yet)")
    else:
        for v in ("healthy", "warning", "unhealthy", "unknown"):
            n = verdict_counts.get(v, 0)
            marker = {
                "healthy": "[OK ]",
                "warning": "[WRN]",
                "unhealthy": "[BAD]",
                "unknown": "[ - ]",
            }[v]
            print(f"    {marker} {v:<11}  {n} cluster(s)")
    print()

    print("  Horizontal bus (24h):")
    n_events = bus_block.get("total_events", 0)
    if n_events == 0:
        print(
            "    (no events -- run a cycle to populate)"
        )
    else:
        print(f"    {n_events} events")
        if bus_block.get("top_topic"):
            print(f"    top topic:   {bus_block['top_topic']}")
        if bus_block.get("top_emitter"):
            print(
                f"    top emitter: {bus_block['top_emitter']}"
            )
    print()

    print("  Institutional audits:")
    if audit_ok:
        print("    [OK ] cluster topology + risk taxonomy")
        print(
            "    (run `shopai audit` for all 9 gates)"
        )
    else:
        print(
            f"    [BAD] cluster topology has "
            f"{audit_violations} violation(s)"
        )
        print(
            "    Drill: `shopai audit --only cluster_topology`"
        )
    print()

    print("  AI strategy:")
    ai_marker = "[OK ]" if ai_mode == "ai" else "[ - ]"
    print(
        f"    {ai_marker} {ai_mode:<14}  "
        f"(env={'on' if ai_enabled_env else 'off'}, "
        f"llm={'available' if ai_available else 'no'})"
    )
    print(
        "    Drill: `shopai ai-strategy status`"
    )
    print()
    print("  Drill:")
    print("    shopai cluster list           -- per-cluster detail")
    print("    shopai cycle history          -- past runs")
    print("    shopai cluster bus --stats    -- bus aggregate")
    print("    shopai cycle verify --store X -- preflight check")


def _cmd_cycle_attribution_lifetime(args) -> None:
    """Cumulative AGI revenue contribution rollup."""
    import time as _time
    from engines._attribution_lifetime import (
        lifetime_per_cluster, lifetime_rollup,
    )

    store_id = (getattr(args, "store", None) or "").strip() or None
    limit = max(2, int(getattr(args, "limit", 200) or 200))
    by = (getattr(args, "by", None) or "fleet").strip().lower()
    as_json = bool(getattr(args, "json", False))

    if by == "cluster":
        rows = lifetime_per_cluster(
            limit=limit, store_id=store_id,
        )
        if as_json:
            print(json.dumps({
                "by": "cluster",
                "filter_store": store_id,
                "count": len(rows),
                "rows": rows,
            }, indent=2, default=str))
            return
        scope = f"store={store_id}" if store_id else "fleet-wide"
        print(
            f"AGI lifetime revenue contribution by cluster  "
            f"({scope})"
        )
        print()
        if not rows:
            print(
                "  (need at least 2 snapshots; run a few cycles "
                "first)"
            )
            return
        print(
            f"  {'cluster':<16} {'+gain':>12} {'-loss':>12} "
            f"{'net':>12}  cycle_pairs"
        )
        for r in rows:
            sign = "+" if r["net"] >= 0 else ""
            print(
                f"  {r['cluster']:<16} "
                f"${r['total_added']:>10,.2f}  "
                f"${r['total_lost']:>10,.2f}  "
                f"{sign}${r['net']:>10,.2f}  "
                f"{r['cycle_pairs_seen']}"
            )
        print()
        print(
            "  Note: 'lifetime' = snapshot retention window "
            "(last 200 cycles)."
        )
        return

    rollup = lifetime_rollup(limit=limit, store_id=store_id)

    if as_json:
        payload = {
            "cycle_pairs_seen": rollup.cycle_pairs_seen,
            "total_added": rollup.total_added,
            "total_lost": rollup.total_lost,
            "net": rollup.net,
            "largest_gain": rollup.largest_gain,
            "largest_loss": rollup.largest_loss,
            "filter_store": store_id,
        }
        print(json.dumps(payload, indent=2, default=str))
        return

    scope = f"store={store_id}" if store_id else "fleet-wide"
    print(f"AGI lifetime revenue contribution  ({scope})")
    print()
    print(
        f"  cycle pairs scanned:  {rollup.cycle_pairs_seen}"
    )
    if rollup.cycle_pairs_seen == 0:
        print()
        print(
            "  (need at least 2 snapshots; run a few cycles "
            "first)"
        )
        return
    print(
        f"  total gained:         "
        f"${rollup.total_added:>10,.2f}"
    )
    print(
        f"  total lost:           "
        f"${rollup.total_lost:>10,.2f}"
    )
    sign = "+" if rollup.net >= 0 else ""
    print(
        f"  net contribution:     "
        f"{sign}${rollup.net:>9,.2f}"
    )
    print()
    if rollup.largest_gain:
        gain_ts = rollup.largest_gain.get("captured_at", 0)
        age = _time.time() - gain_ts if gain_ts else 0
        age_str = (
            f"{int(age/3600)}h ago" if age < 86400
            else f"{age/86400:.1f}d ago"
        ) if gain_ts else "(unknown)"
        print(
            f"  largest gain:         "
            f"+${rollup.largest_gain['amount']:,.2f}  "
            f"{age_str}"
        )
    if rollup.largest_loss:
        loss_ts = rollup.largest_loss.get("captured_at", 0)
        age = _time.time() - loss_ts if loss_ts else 0
        age_str = (
            f"{int(age/3600)}h ago" if age < 86400
            else f"{age/86400:.1f}d ago"
        ) if loss_ts else "(unknown)"
        print(
            f"  largest loss:         "
            f"-${rollup.largest_loss['amount']:,.2f}  "
            f"{age_str}"
        )
    print()
    print(
        "  Note: 'lifetime' = snapshot retention window "
        "(last 200 cycles)."
    )


def _cmd_cycle_revenue_fleet(args) -> None:
    """Cross-store empire revenue rollup.

    Each store's latest attribution snapshot rendered side-by-
    side, sorted by attributed_revenue desc. Builds on
    per-store snapshots (Wave 14).
    """
    import time as _time
    from engines._attribution_snapshot import (
        fleet_attribution_rollup,
    )

    as_json = bool(getattr(args, "json", False))
    rollup = fleet_attribution_rollup()

    if as_json:
        print(json.dumps(rollup, indent=2, default=str))
        return

    print("Empire revenue (per store)")
    print()
    print(
        f"  stores with snapshots:  {rollup['store_count']}"
    )
    print(
        f"  total attributed:       "
        f"${rollup['total_attributed']:,.2f}"
    )
    print(
        f"  total orders captured:  {rollup['total_orders']}"
    )
    print()

    if not rollup["stores"]:
        print(
            "  (no per-store snapshots yet)"
        )
        print()
        print(
            "  Per-store snapshots are captured automatically "
            "on `cycle run --yes`. Run a live cycle, then "
            "revisit."
        )
        return

    print(
        f"  {'store':<22} {'attributed':>12} "
        f"{'orders':>7} {'rate':>6}  top_cluster   top_engine"
    )
    now = _time.time()
    for row in rollup["stores"]:
        age = now - row["captured_at"]
        if age < 3600:
            age_suffix = f" ({int(age/60)}m)"
        elif age < 86400:
            age_suffix = f" ({age/3600:.1f}h)"
        else:
            age_suffix = f" ({age/86400:.1f}d)"
        store_label = (
            (row["store_id"] or "")[:18] + age_suffix
        )[:22]
        rate = row["attribution_rate"] or 0.0
        top_c = (row["top_cluster"] or "-")[:14]
        top_e = (row["top_engine"] or "-")[:16]
        print(
            f"  {store_label:<22} "
            f"${row['attributed_revenue']:>10,.2f} "
            f"{row['attributed_orders']:>7} "
            f"{rate*100:>5.1f}%  "
            f"{top_c:<14} {top_e}"
        )
    print()
    print("  Drill:")
    print(
        "    shopai cycle attribution --store X      "
        "-- per-store cluster detail"
    )
    print(
        "    shopai cycle attribution-history --store X "
        "-- per-store trend"
    )


def _cmd_cycle_attribution_delta(args) -> None:
    """Diff the two most-recent attribution snapshots.

    Surfaces revenue regression alerts so operators can react
    before a regression compounds.
    """
    from engines._attribution_delta import latest_delta

    store_id = (getattr(args, "store", None) or "").strip() or None
    regression_pct = float(
        getattr(args, "regression_pct", 0.25) or 0.25,
    )
    min_orders = int(getattr(args, "min_orders", 3) or 3)
    as_json = bool(getattr(args, "json", False))

    delta = latest_delta(
        store_id=store_id,
        regression_pct=regression_pct,
        min_orders=min_orders,
    )

    if delta is None:
        if as_json:
            print(json.dumps({
                "status": "insufficient_snapshots",
                "filter_store": store_id,
            }, indent=2))
        else:
            print("Attribution delta")
            if store_id:
                print(f"  filter: store={store_id}")
            print()
            print(
                "  (need at least 2 snapshots; run a few cycles "
                "first)"
            )
            print()
            print(
                "  shopai cycle attribution-history  "
                "-- see current snapshots"
            )
        return

    if as_json:
        payload = {
            "filter_store": store_id,
            "prior_snapshot_id": delta.prior_snapshot_id,
            "latest_snapshot_id": delta.latest_snapshot_id,
            "prior_attributed_revenue": delta.prior_attributed_revenue,
            "latest_attributed_revenue": delta.latest_attributed_revenue,
            "overall_revenue_delta": delta.overall_revenue_delta,
            "overall_revenue_delta_pct": delta.overall_revenue_delta_pct,
            "alerts": [
                {
                    "scope": a.scope, "name": a.name,
                    "prior_revenue": a.prior_revenue,
                    "latest_revenue": a.latest_revenue,
                    "delta_pct": a.delta_pct,
                    "reason": a.reason,
                }
                for a in delta.alerts
            ],
            "per_cluster": [
                {
                    "cluster": c.cluster,
                    "prior_revenue": c.prior_revenue,
                    "latest_revenue": c.latest_revenue,
                    "revenue_delta": c.revenue_delta,
                    "revenue_delta_pct": c.revenue_delta_pct,
                    "direction": c.direction,
                }
                for c in delta.per_cluster
            ],
            "per_engine": [
                {
                    "engine": e.engine,
                    "cluster": e.cluster,
                    "prior_revenue": e.prior_revenue,
                    "latest_revenue": e.latest_revenue,
                    "revenue_delta": e.revenue_delta,
                    "revenue_delta_pct": e.revenue_delta_pct,
                    "direction": e.direction,
                }
                for e in delta.per_engine
            ],
        }
        print(json.dumps(payload, indent=2, default=str))
        return

    print("Attribution delta (cycle-over-cycle)")
    if store_id:
        print(f"  filter: store={store_id}")
    print()
    print(
        f"  prior:   ${delta.prior_attributed_revenue:>10,.2f}   "
        f"(snapshot {delta.prior_snapshot_id})"
    )
    print(
        f"  latest:  ${delta.latest_attributed_revenue:>10,.2f}   "
        f"(snapshot {delta.latest_snapshot_id})"
    )
    pct = delta.overall_revenue_delta_pct
    if pct is None:
        pct_str = "(n/a)"
    elif pct > 0:
        pct_str = f"+{pct * 100:.1f}%"
    else:
        pct_str = f"{pct * 100:.1f}%"
    marker = "[OK ]" if delta.overall_revenue_delta >= 0 else "[WRN]"
    print(
        f"  delta:   {marker} ${delta.overall_revenue_delta:+,.2f}   "
        f"{pct_str}"
    )
    print()

    if delta.alerts:
        print(
            f"  ALERTS ({len(delta.alerts)} regression"
            f"{'s' if len(delta.alerts) > 1 else ''}):"
        )
        for a in delta.alerts:
            print(f"    [BAD] {a.scope}:{a.name}  -- {a.reason}")
        print()
    else:
        print("  No regressions above threshold")
        print()

    # Show top 5 movers per cluster
    print("  Top movers (cluster):")
    if not delta.per_cluster:
        print("    (no cluster data)")
    else:
        for c in delta.per_cluster[:5]:
            arrow = {
                "up": "+", "down": "-", "new": "*",
                "dropped": "x", "flat": "=",
            }.get(c.direction, "?")
            print(
                f"    [{arrow}] {c.cluster:<14} "
                f"${c.prior_revenue:>8,.2f} -> "
                f"${c.latest_revenue:>8,.2f}   "
                f"({c.direction})"
            )
    print()
    print("  Drill:")
    print(
        "    shopai cycle attribution-history  "
        "-- full trend"
    )
    print(
        "    shopai cycle attribution --by engine  "
        "-- per-engine current"
    )


def _cmd_cycle_attribution_history(args) -> None:
    """Show attribution trend across recent cycle runs.

    Sourced from data/attribution_snapshots.json, populated at
    cycle-run time. Lets operators see whether the autonomous
    loop is moving revenue (not just current snapshot).
    """
    import time as _time
    from engines._attribution_snapshot import attribution_trend

    limit = max(1, int(getattr(args, "limit", 20) or 20))
    store_id = (getattr(args, "store", None) or "").strip() or None
    as_json = bool(getattr(args, "json", False))

    trend = attribution_trend(limit=limit, store_id=store_id)

    if as_json:
        print(json.dumps({
            "filter_store": store_id,
            "limit": limit,
            "count": len(trend),
            "trend": trend,
        }, indent=2, default=str))
        return

    print(f"Attribution history  ({len(trend)} snapshots)")
    if store_id:
        print(f"  filter: store={store_id}")
    print()
    if not trend:
        print("  (no snapshots recorded yet)")
        print()
        print(
            "  Snapshots are captured at cycle-run time. Run a "
            "live cycle:"
        )
        print(
            "    SHOPAI_CYCLE_RUN_CONFIRM=1 shopai cycle run --yes"
        )
        return

    print(
        f"  {'when':<22} {'attributed':>12} "
        f"{'orders':>7} {'rate':>6}  top_cluster   top_engine"
    )
    now = _time.time()
    for row in trend:
        age = now - row["captured_at"]
        if age < 3600:
            age_str = f"{int(age/60)}m ago"
        elif age < 86400:
            age_str = f"{age/3600:.1f}h ago"
        else:
            age_str = f"{age/86400:.1f}d ago"
        rev = row["attributed_revenue"]
        orders = row["total_orders_in_window"]
        rate = row["attribution_rate"]
        top_c = (row["top_cluster"] or "-")[:14]
        top_e = (row["top_engine"] or "-")[:16]
        print(
            f"  {age_str:<22} ${rev:>10,.2f} "
            f"{orders:>7} {rate*100:>5.1f}%  "
            f"{top_c:<14} {top_e}"
        )
    print()
    print(
        "  Drill: `shopai cycle attribution` "
        "(current snapshot)"
    )
    print(
        "  Cycles: `shopai cycle history` "
        "(invocation history)"
    )


def _cmd_cycle_attribution(args) -> None:
    """Show revenue attributed to each cluster from Shopify orders.

    Joins recent orders to clusters via tag catalog. The ground-
    truth answer to "is the cycle making money?" -- distinct from
    self-reported outcome metrics that engines emit via
    record_outcome.
    """
    from engines._revenue_attribution import attribute_revenue

    window_hours = float(
        getattr(args, "window_hours", 168.0) or 168.0
    )
    store_id = (getattr(args, "store", None) or "").strip() or None
    by = (getattr(args, "by", None) or "cluster").strip().lower()
    top = int(getattr(args, "top", 20) or 20)
    as_json = bool(getattr(args, "json", False))

    try:
        report = attribute_revenue(
            window_hours=window_hours,
            store_id=store_id,
        )
    except Exception as exc:  # noqa: BLE001
        if as_json:
            print(json.dumps({"error": str(exc)}, indent=2))
        else:
            print(f"  ERROR: attribution failed: {exc}")
        return

    if as_json:
        payload = {
            "window_hours": report.window_hours,
            "store_id": store_id,
            "aggregation": by,
            "total_orders_in_window": report.total_orders_in_window,
            "total_revenue_in_window": round(
                report.total_revenue_in_window, 2,
            ),
            "attributed_revenue": round(
                report.attributed_revenue, 2,
            ),
            "attribution_rate": report.attribution_rate,
            "per_cluster": [
                {
                    "cluster": c.cluster,
                    "attributed_revenue": round(
                        c.attributed_revenue, 2,
                    ),
                    "attributed_orders": c.attributed_orders,
                    "confidence": c.confidence,
                    "tag_matches": c.tag_matches,
                }
                for c in report.per_cluster
            ],
            "per_engine": [
                {
                    "engine": e.engine,
                    "cluster": e.cluster,
                    "attributed_revenue": round(
                        e.attributed_revenue, 2,
                    ),
                    "attributed_orders": e.attributed_orders,
                    "confidence": e.confidence,
                    "tag_matches": e.tag_matches,
                }
                for e in report.per_engine
            ],
        }
        print(json.dumps(payload, indent=2, default=str))
        return

    label = "engine" if by == "engine" else "cluster"
    print(f"Revenue attribution by {label}")
    scope = f"store={store_id}" if store_id else "fleet-wide"
    print(
        f"  scope:  {scope}   "
        f"window: {window_hours:g}h"
    )
    print(
        f"  orders: {report.total_orders_in_window}   "
        f"revenue: ${report.total_revenue_in_window:,.2f}"
    )
    print(
        f"  attributed: ${report.attributed_revenue:,.2f}   "
        f"rate: {report.attribution_rate * 100:.1f}%"
    )
    print()

    if by == "engine":
        if not report.per_engine:
            print("  (no orders matched any engine's tags)")
            print()
            print(
                "  Tags get written by engine appliers. If you "
                "have live orders but $0 attributed, check:"
            )
            print(
                "    shopai engine try-wireup --all  "
                "-- ensures appliers fire"
            )
            return
        print(
            f"  {'engine':<28} {'cluster':<14} "
            f"{'revenue':>12} {'orders':>7} {'confidence':<10}"
        )
        for e in report.per_engine[:top]:
            cluster_str = e.cluster or "-"
            print(
                f"  {e.engine[:28]:<28} {cluster_str[:14]:<14} "
                f"${e.attributed_revenue:>10,.2f} "
                f"{e.attributed_orders:>7} "
                f"{e.confidence:<10}"
            )
        if len(report.per_engine) > top:
            print(
                f"  ... {len(report.per_engine) - top} "
                "more engines (use --top N)"
            )
        print()
        print("  Drill:")
        print(
            "    shopai cycle attribution      "
            "-- cluster-level rollup"
        )
        return

    if not report.per_cluster:
        print("  (no orders matched any cluster's tags)")
        print()
        print(
            "  Tags get written by engine appliers. If you have "
            "live orders but $0 attributed, check:"
        )
        print(
            "    shopai capabilities run pattern-z-audit "
            "-- ensures writers record outcomes"
        )
        return

    print(
        f"  {'cluster':<16} {'revenue':>12} "
        f"{'orders':>7} {'confidence':<10}"
    )
    for c in report.per_cluster:
        print(
            f"  {c.cluster:<16} "
            f"${c.attributed_revenue:>10,.2f} "
            f"{c.attributed_orders:>7} "
            f"{c.confidence:<10}"
        )
    print()
    print("  Drill:")
    print(
        "    shopai cycle attribution --by engine  "
        "-- per-engine breakdown"
    )
    print(
        "    shopai cluster show <name>    "
        "-- per-cluster member detail"
    )
    print(
        "    shopai cluster-outcomes       "
        "-- self-reported outcome metrics"
    )


def _cmd_cycle_history(args) -> None:
    """Show recent cycle run history.

    Sourced from data/cycle_history.json populated by
    `cycle run --yes`. Dry-run cycles don't get recorded.
    """
    import time as _time
    from engines._cycle_history import (
        recent_runs, runs_for_store,
    )

    limit = max(1, int(getattr(args, "limit", 10) or 10))
    store_id = (getattr(args, "store", None) or "").strip() or None
    as_json = bool(getattr(args, "json", False))

    if store_id:
        runs = runs_for_store(store_id, limit=limit)
    else:
        runs = recent_runs(limit=limit)

    if as_json:
        print(json.dumps({
            "filter_store": store_id,
            "limit": limit,
            "count": len(runs),
            "runs": [r.to_dict() for r in runs],
        }, indent=2, default=str))
        return

    print(f"Cycle history  ({len(runs)} runs)")
    if store_id:
        print(f"  filter: store={store_id}")
    print()
    if not runs:
        print("  (no cycle runs recorded yet)")
        print()
        print(
            "  Run one live: SHOPAI_CYCLE_RUN_CONFIRM=1 "
            "shopai cycle run --yes"
        )
        return

    print(
        f"  {'when':<22} {'mode':<8} {'stores':>6} "
        f"{'invoked':>7} {'ok':>4} {'err':>4} verdict"
    )
    now = _time.time()
    for r in runs:
        age = now - r.started_at
        if age < 60:
            when = f"{int(age)}s ago"
        elif age < 3600:
            when = f"{int(age/60)}m ago"
        elif age < 86400:
            when = f"{age/3600:.1f}h ago"
        else:
            when = f"{age/86400:.1f}d ago"
        print(
            f"  {when:<22} {r.mode:<8} "
            f"{r.total_stores:>6d} {r.total_invoked:>7d} "
            f"{r.total_ok:>4d} {r.total_errors:>4d} "
            f"{r.verdict}"
        )
    # Wave 38: surface error reasons inline when the
    # most-recent run had failures. Without this, operators
    # see "10 errors" and have no clue what to fix.
    if runs and runs[0].total_errors > 0:
        top_errors: dict[str, int] = {}
        sample_lines: list[str] = []
        for store_entry in runs[0].per_store or []:
            for inv in store_entry.get("results", []) or []:
                err = inv.get("error")
                status = inv.get("status", "?")
                if status in ("success", "ok"):
                    continue
                # Trim error to a hashable line
                line = (
                    str(err)[:80] if err
                    else f"(no error captured, status={status})"
                )
                top_errors[line] = top_errors.get(line, 0) + 1
                if len(sample_lines) < 3:
                    sample_lines.append(
                        f"  {inv.get('engine', '?'):<22} "
                        f"{status:<10} {line}"
                    )
        if top_errors:
            print()
            print(
                f"  Last-run failure reasons "
                f"({sum(top_errors.values())} error(s)):"
            )
            for line in sample_lines:
                print(line)
            top_three = sorted(
                top_errors.items(),
                key=lambda kv: -kv[1],
            )[:3]
            if any(v > 1 for _, v in top_three):
                print()
                print("  Recurring (n>1):")
                for line, n in top_three:
                    if n > 1:
                        print(f"    {n}x  {line}")
    print()
    print(
        "  Drill: `shopai cycle history --store <id>`  "
        "(per-store)"
    )


def _cmd_cycle_verify(args) -> None:
    """End-to-end smoke test of the cycle pipeline.

    Walks each tier + reports per-step status. Doesn't fire
    anything live -- just verifies each piece works for the
    given store. Use this BEFORE scheduling the cycle.
    """
    from engines._clusters import list_clusters
    from engines._cluster_captain import (
        make_captain_plan,
    )
    from engines._store_supervisor import make_supervisor_plan

    sm = _get_store_manager()
    store_id = (
        (getattr(args, "store", None) or "").strip()
        or sm.active_store_id
    )
    as_json = bool(getattr(args, "json", False))

    checks: list[dict] = []
    overall_ok = True

    def _check(name: str, status: str, detail: str = "") -> None:
        nonlocal overall_ok
        checks.append({
            "step": name, "status": status, "detail": detail,
        })
        if status not in ("ok", "skip"):
            overall_ok = False

    # 1. Store exists
    if not store_id:
        _check("store_id", "fail", "no store_id (active or supplied)")
    else:
        stores = {s.get("store_id") for s in sm.list_stores() or []}
        if store_id in stores:
            _check("store_id", "ok", store_id)
        else:
            _check(
                "store_id", "fail",
                f"store '{store_id}' not in fleet",
            )

    # 2. World-model snapshot
    wm: dict = {}
    if store_id:
        try:
            from core.world_model import WorldModel
            wm = WorldModel().snapshot(store_id, skip_live=True)
            stats = wm.get("stats", {})
            _check(
                "world_model",
                "ok",
                (
                    f"products={stats.get('products', 0)} "
                    f"orders={stats.get('orders', 0)} "
                    f"revenue=${stats.get('total_revenue', 0):.2f}"
                ),
            )
        except Exception as exc:  # noqa: BLE001
            _check("world_model", "fail", str(exc))

    # 3. Tier 1 orchestrator + Tier 2a supervisor
    try:
        from engines._orchestrator import make_fleet_plan
        fp = make_fleet_plan(
            world_models={store_id: wm} if store_id else {},
            cycle_label="verify",
        )
        if fp.priorities:
            prio = fp.priorities[0]
            _check(
                "tier1_orchestrator",
                "ok",
                f"priority={prio.priority} -- {prio.rationale}",
            )
        else:
            _check(
                "tier1_orchestrator", "skip",
                "no world-model -> no priority",
            )

        if fp.supervisor_plans:
            sp = fp.supervisor_plans[0]
            _check(
                "tier2a_supervisor",
                "ok",
                (
                    f"{len(sp.active_clusters)} clusters active, "
                    f"{sp.total_to_fire} engines to fire"
                ),
            )
        else:
            _check(
                "tier2a_supervisor", "skip",
                "no supervisor plan",
            )
    except Exception as exc:  # noqa: BLE001
        _check("tier1_orchestrator", "fail", str(exc))

    # 4. Each cluster captain plans cleanly
    captain_results = []
    for cluster in list_clusters():
        try:
            cp = make_captain_plan(
                cluster.name, store_id=store_id,
            )
            captain_results.append({
                "cluster": cluster.name,
                "fire": cp.fire_count,
                "queued": len(cp.modifications_queued),
                "skipped": len(cp.members_to_skip),
            })
        except Exception as exc:  # noqa: BLE001
            captain_results.append({
                "cluster": cluster.name,
                "error": str(exc),
            })
            overall_ok = False
    failed_captains = [
        c["cluster"] for c in captain_results
        if "error" in c
    ]
    if failed_captains:
        _check(
            "tier2b_captains",
            "fail",
            f"failed: {failed_captains}",
        )
    else:
        total_fire = sum(c.get("fire", 0) for c in captain_results)
        _check(
            "tier2b_captains",
            "ok",
            f"{len(captain_results)} captains plan cleanly, "
            f"{total_fire} engines to fire",
        )

    # 5. DataProvider can hydrate (sample one engine)
    try:
        from data_pipeline.store.data_provider import DataProvider
        if store_id:
            data = DataProvider(sm).get_data_for_engine(
                "loyalty", store_id,
            )
            _check(
                "data_provider",
                "ok" if isinstance(data, dict) else "fail",
                (
                    f"loyalty data hydrated ({len(data)} keys)"
                    if isinstance(data, dict)
                    else "DataProvider returned non-dict"
                ),
            )
        else:
            _check(
                "data_provider", "skip", "no store_id",
            )
    except Exception as exc:  # noqa: BLE001
        _check("data_provider", "fail", str(exc))

    # 6. Approval queue accessible
    try:
        from core.approval.queue import get_approval_queue
        queue = get_approval_queue()
        stats = queue.stats_by_engine() or {}
        _check(
            "approval_queue",
            "ok",
            f"{len(stats)} engines have queue activity",
        )
    except Exception as exc:  # noqa: BLE001
        _check("approval_queue", "fail", str(exc))

    # 7. All 9 institutional audits
    try:
        audit_results = []
        for name in _AUDIT_ORDER:
            r = _run_one_audit(name)
            audit_results.append((name, r.get("ok", False)))
        failed_audits = [
            n for n, ok in audit_results if not ok
        ]
        if failed_audits:
            _check(
                "institutional_audits",
                "fail",
                f"failed: {failed_audits}",
            )
        else:
            _check(
                "institutional_audits",
                "ok",
                f"{len(audit_results)}/{len(audit_results)} green",
            )
    except Exception as exc:  # noqa: BLE001
        _check("institutional_audits", "fail", str(exc))

    # 8. Wave 41: dry-run-invoke every engine in the captain
    # plan (opt-in via --invoke). apply_* flags are NOT set
    # so engines run in their advisory branch -- they read
    # data, run their decision logic, return an envelope, but
    # don't fire Shopify writes. Captures latent failures
    # (engine raises, returns Pattern Q violation, returns
    # status=error/fail) so operators see them BEFORE going
    # live.
    invoke_results: list[dict] = []
    if getattr(args, "invoke", False) and store_id:
        try:
            from data_pipeline.store.data_provider import DataProvider
            from engines.registry import get_engine
        except Exception as exc:  # noqa: BLE001
            _check(
                "engine_invocations", "fail",
                f"registry/provider unavailable: {exc}",
            )
        else:
            provider = DataProvider(sm)
            invoke_ok = 0
            invoke_err = 0
            invoke_skip = 0
            # Iterate the captain plans we already computed
            sp_for_store = (
                fp.supervisor_plans[0]
                if fp.supervisor_plans else None
            )
            if sp_for_store is not None:
                for cp in sp_for_store.captain_plans:
                    for m in (
                        cp.members_to_fire
                        + cp.modifications_queued
                    ):
                        engine_name = m["engine"]
                        entry: dict = {
                            "cluster": cp.cluster,
                            "engine": engine_name,
                        }
                        try:
                            data = provider.get_data_for_engine(
                                engine_name, store_id,
                            )
                            if not isinstance(data, dict):
                                data = {}
                            # NOTE: apply_* NOT set -- advisory
                            # mode. This is the safety guarantee
                            # of cycle verify --invoke.
                        except Exception as exc:  # noqa: BLE001
                            entry["status"] = "data_error"
                            entry["error"] = str(exc)[:200]
                            invoke_err += 1
                            invoke_results.append(entry)
                            continue
                        try:
                            engine = get_engine(engine_name)
                            if engine is None:
                                entry["status"] = "not_registered"
                                invoke_err += 1
                                invoke_results.append(entry)
                                continue
                            result = engine.run(data)
                            if isinstance(result, dict):
                                status = result.get("status", "?")
                                entry["status"] = status
                                if status in ("success", "ok"):
                                    invoke_ok += 1
                                else:
                                    invoke_err += 1
                                    err = result.get("error")
                                    if err:
                                        entry["error"] = (
                                            str(err)[:200]
                                        )
                            else:
                                entry["status"] = "non_dict"
                                invoke_err += 1
                        except Exception as exc:  # noqa: BLE001
                            entry["status"] = "engine_raised"
                            entry["error"] = str(exc)[:200]
                            invoke_err += 1
                        invoke_results.append(entry)
            else:
                invoke_skip += 1
            if invoke_err == 0:
                _check(
                    "engine_invocations", "ok",
                    f"{invoke_ok} engines respond cleanly "
                    "(advisory mode)",
                )
            else:
                _check(
                    "engine_invocations", "fail",
                    f"{invoke_err}/{invoke_ok + invoke_err} "
                    "engines fail in advisory mode",
                )

    if as_json:
        print(json.dumps({
            "store_id": store_id,
            "overall_ok": overall_ok,
            "checks": checks,
            "captain_results": captain_results,
            "invoke_results": invoke_results,
        }, indent=2, default=str))
        if not overall_ok:
            sys.exit(1)
        return

    print(
        f"Cycle verify -- "
        f"store: {store_id or '(none)'}"
    )
    print()
    for c in checks:
        marker = (
            "[ok  ]" if c["status"] == "ok"
            else "[skip]" if c["status"] == "skip"
            else "[FAIL]"
        )
        print(
            f"  {marker} {c['step']:<22} {c['detail']}"
        )
    # Wave 41: when --invoke ran, surface per-engine failures
    # so operators see WHICH engines failed + their reasons.
    if invoke_results:
        failed = [
            r for r in invoke_results
            if r.get("status") not in ("success", "ok")
        ]
        if failed:
            print()
            print(
                f"  Engine failures ({len(failed)} of "
                f"{len(invoke_results)}):"
            )
            for r in failed[:10]:
                err = r.get("error", "(no error captured)")
                print(
                    f"    {r['cluster']:<14} "
                    f"{r['engine']:<28} "
                    f"{r.get('status', '?'):<14} {err[:100]}"
                )
            if len(failed) > 10:
                print(
                    f"    ... {len(failed) - 10} more"
                )
    print()
    if overall_ok:
        print(
            "  All checks passed -- cycle pipeline ready."
        )
        print(
            f"  Next: `shopai cycle run --store {store_id}`"
            " (dry-run)"
        )
    else:
        print(
            "  At least one check failed -- fix gaps before "
            "running the cycle live."
        )
        sys.exit(1)


def _cmd_cycle_schedule(args) -> None:
    """Print ready-to-paste schedule config for the empire cycle."""
    import os as _os
    freq = (getattr(args, "frequency", None) or "hourly").strip()
    # W959 bugfix: auto-detect platform if user didn't specify.
    # Pre-fix the default was "cron" regardless of host OS, so
    # Windows operators got Linux/Mac syntax that wouldn't work.
    raw_platform = getattr(args, "platform", None)
    if raw_platform:
        platform = raw_platform.strip()
    else:
        import sys as _sys
        platform = (
            "windows-task" if _sys.platform == "win32"
            else "cron"
        )
    log_file = getattr(args, "log_file", None)

    repo_root = _os.path.dirname(_os.path.abspath(__file__))
    cycle_cmd = (
        f"SHOPAI_CYCLE_RUN_CONFIRM=1 python "
        f"{repo_root}/cli.py cycle run --yes"
    )

    print(f"Empire cycle schedule ({freq}, {platform})")
    print()

    if platform == "cron":
        cron_spec = _CRON_FREQUENCY[freq]
        line = f"{cron_spec} {cycle_cmd}"
        if log_file:
            line += f" >> {log_file} 2>&1"
        print("  Append this line to your crontab:")
        print()
        print(f"    {line}")
        print()
        print(
            "  Install:  crontab -l | { cat; echo '...'; }"
            " | crontab -"
        )

    elif platform == "systemd":
        unit_name = "shopai-cycle"
        print(
            f"  Create /etc/systemd/system/{unit_name}.service:"
        )
        print()
        print("    [Unit]")
        print("    Description=ShopAI empire cycle")
        print()
        print("    [Service]")
        print("    Type=oneshot")
        print(f"    WorkingDirectory={repo_root}")
        print('    Environment="SHOPAI_CYCLE_RUN_CONFIRM=1"')
        print(
            f"    ExecStart=/usr/bin/python {repo_root}/cli.py "
            "cycle run --yes"
        )
        print()
        print(
            f"  Then /etc/systemd/system/{unit_name}.timer:"
        )
        print()
        print("    [Unit]")
        print("    Description=ShopAI empire cycle timer")
        print()
        print("    [Timer]")
        print(
            f"    OnCalendar={_SYSTEMD_ON_CALENDAR[freq]}"
        )
        print("    Persistent=true")
        print()
        print("    [Install]")
        print("    WantedBy=timers.target")
        print()
        print(
            "  Install:  sudo systemctl daemon-reload && "
            f"sudo systemctl enable --now {unit_name}.timer"
        )

    elif platform == "windows-task":
        trigger = _WINDOWS_TASK_TRIGGER[freq]
        py = _os.path.join(_os.path.dirname(sys.executable), "python.exe")
        print("  Run this in an elevated PowerShell:")
        print()
        ps_cmd = (
            f'$env:SHOPAI_CYCLE_RUN_CONFIRM=1; '
            f'& "{py}" "{repo_root}\\cli.py" cycle run --yes'
        )
        if log_file:
            ps_cmd += f' *>> "{log_file}"'
        print(
            f'    schtasks /create /tn "ShopAI-Cycle" '
            f'/tr "powershell.exe -NoProfile -Command \"{ps_cmd}\"" '
            f"{trigger} /f"
        )

    elif platform == "powershell":
        print("  PowerShell-loop variant (foreground):")
        print()
        print(
            f'    while ($true) {{ '
            f'$env:SHOPAI_CYCLE_RUN_CONFIRM=1; '
            f'py "{repo_root}\\cli.py" cycle run --yes; '
            f'Start-Sleep -Seconds {_freq_to_seconds(freq)} '
            f'}}'
        )

    print()
    print(
        "  Test first (dry-run):  "
        f"python {repo_root}/cli.py cycle run"
    )
    print(
        "  Test live, once:       "
        f"{cycle_cmd}"
    )
    # Wave 54: also suggest notify-check companion line. Push
    # alerts when cron dies or revenue regresses are no good
    # if operator only sees them by running daily-brief.
    notify_cmd = (
        f"python {repo_root}/cli.py notify check"
    )
    if platform == "cron":
        print()
        print(
            "  Optional notify-check companion (15-min "
            "cadence; alerts to SHOPAI_NOTIFY_WEBHOOK_URL):"
        )
        print()
        notify_line = f"*/15 * * * * {notify_cmd}"
        if log_file:
            notify_line += f" >> {log_file} 2>&1"
        print(f"    {notify_line}")
        print()
        print(
            "  Set webhook URL first:"
        )
        print(
            '    export SHOPAI_NOTIFY_WEBHOOK_URL='
            '"https://hooks.slack.com/..."'
        )
    elif platform == "windows-task":
        print()
        print(
            "  Optional notify-check companion (15-min, "
            "fires Slack/Pushbullet/etc):"
        )
        py = _os.path.join(
            _os.path.dirname(sys.executable), "python.exe",
        )
        notify_ps = (
            f'& "{py}" "{repo_root}\\cli.py" notify check'
        )
        print(
            f'    schtasks /create /tn "ShopAI-Notify" '
            f'/tr "powershell.exe -NoProfile -Command \"{notify_ps}\"" '
            "/sc minute /mo 15 /f"
        )
    elif platform == "systemd":
        print()
        print(
            "  Optional notify-check companion (15-min timer)"
        )
        print("  -- mirror the .service/.timer pattern above, ")
        print(
            "     swap ExecStart for "
            f"`{notify_cmd}` and OnCalendar=*:0/15"
        )


def _freq_to_seconds(freq: str) -> int:
    return {
        "hourly": 3600,
        "every-15min": 900,
        "daily": 86400,
        "every-6h": 21600,
    }.get(freq, 3600)


def _cmd_cycle_run(args) -> None:
    """One full empire cycle: Tier 1 -> Tier 2a -> Tier 2b
    -> Tier 3 -> Tier 4.

    Reads fleet world-model, runs Tier 1 orchestrator to
    plan per-store, then for each store-cluster pair invokes
    the captain plan. Additive members fire directly.
    Modification members are invoked with
    require_approval=True (engine internally enqueues).
    Destructive members skipped (operator-only).

    Default: DRY-RUN. --yes + env-var actually fires.
    """
    import time as _time
    from engines._orchestrator import (
        make_fleet_plan, fleet_summary,
    )
    from core.world_model import WorldModel

    sm = _get_store_manager()
    only_store = (getattr(args, "store", None) or "").strip()
    yes = bool(getattr(args, "yes", False))
    as_json = bool(getattr(args, "json", False))

    # Step 1: pull world-models
    world_models: dict[str, dict] = {}
    try:
        wm = WorldModel()
        if only_store:
            world_models[only_store] = wm.snapshot(
                only_store, skip_live=True,
            )
        else:
            for s in sm.list_stores() or []:
                sid = s.get("store_id")
                if sid:
                    world_models[sid] = wm.snapshot(
                        sid, skip_live=True,
                    )
    except Exception as exc:  # noqa: BLE001
        logger.debug("cycle run world-model raised: %s", exc)

    # Step 2: Tier 1 plan
    cycle_label = _time.strftime(
        "%Y-%m-%dT%H:%M:%S", _time.gmtime(),
    )
    fleet_plan = make_fleet_plan(
        world_models=world_models, cycle_label=cycle_label,
    )
    summary = fleet_summary(fleet_plan)

    # Surface AI-strategy state (enabled / available)
    ai_mode = (
        "ai"
        if os.environ.get("SHOPAI_AI_STRATEGY")
        else "deterministic"
    )

    if not yes:
        # Dry-run: just show the plan
        if as_json:
            print(json.dumps({
                "mode": "dry_run",
                "ai_strategy": ai_mode,
                "cycle_label": fleet_plan.cycle_label,
                "summary": summary,
            }, indent=2, default=str))
            return
        print(
            f"Empire cycle (DRY-RUN) -- "
            f"{fleet_plan.cycle_label}  "
            f"[strategy: {ai_mode}]"
        )
        print()
        print(f"  Stores planned:       {summary['total_stores']}")
        print(
            f"  Total auto-fire:      {summary['total_to_fire']} "
            "engine(s)"
        )
        print(
            f"  Total approval-queue: "
            f"{summary['total_modifications']} engine(s)"
        )
        print()
        if summary["stores"]:
            print(
                f"  {'store_id':<25} {'priority':<11} "
                f"{'clusters':>8} {'fire':>5} {'queue':>6}"
            )
            for row in summary["stores"]:
                print(
                    f"  {row['store_id'][:25]:<25} "
                    f"{row['priority']:<11} "
                    f"{row['active_clusters']:>8d}  "
                    f"{row['fire']:>4d} {row['queued']:>5d}"
                )
        print()
        print(
            "  To run live: SHOPAI_CYCLE_RUN_CONFIRM=1 "
            "shopai cycle run --yes"
        )
        return

    # --yes path: actually invoke
    if not os.environ.get("SHOPAI_CYCLE_RUN_CONFIRM"):
        msg = (
            "Empire cycle live mode requires "
            "SHOPAI_CYCLE_RUN_CONFIRM=1 env var. This fires "
            "engines across the WHOLE FLEET; set the env var "
            "to acknowledge the blast radius."
        )
        if as_json:
            print(json.dumps(
                {"status": "error", "error": msg},
                indent=2, default=str,
            ))
        else:
            print(f"Error: {msg}")
        sys.exit(1)
        return

    # Iterate per-store; for each store's SupervisorPlan,
    # iterate per cluster; for each captain plan, invoke
    # members (additive direct, modification w/ require_approval)
    try:
        from data_pipeline.store.data_provider import DataProvider
        from engines.registry import get_engine
    except Exception as exc:  # noqa: BLE001
        msg = f"runtime registry/provider unavailable: {exc}"
        if as_json:
            print(json.dumps(
                {"status": "error", "error": msg},
                indent=2, default=str,
            ))
        else:
            print(f"Error: {msg}")
        sys.exit(1)
        return

    per_store_results: list[dict] = []
    any_error = False
    for sp in fleet_plan.supervisor_plans:
        store_id = sp.store_id
        store_results: list[dict] = []
        for cp in sp.captain_plans:
            invocations = []
            for m in cp.members_to_fire:
                invocations.append({
                    "engine": m["engine"],
                    "apply_flag": m["apply_flag"],
                    "risk": m.get("risk"),
                    "require_approval": False,
                })
            for m in cp.modifications_queued:
                invocations.append({
                    "engine": m["engine"],
                    "apply_flag": m["apply_flag"],
                    "risk": m.get("risk"),
                    "require_approval": True,
                })

            for member in invocations:
                engine_name = member["engine"]
                apply_flag = member["apply_flag"]
                require_approval = member["require_approval"]
                entry: dict = {
                    "store_id": store_id,
                    "cluster": cp.cluster,
                    "engine": engine_name,
                    "apply_flag": apply_flag,
                    "risk": member.get("risk"),
                    "approval_required": require_approval,
                }
                try:
                    data = (
                        DataProvider(sm).get_data_for_engine(
                            engine_name, store_id,
                        ) if store_id else {}
                    )
                    if not isinstance(data, dict):
                        data = {}
                    data[apply_flag] = True
                    if require_approval:
                        data["require_approval"] = True
                except Exception as exc:  # noqa: BLE001
                    entry["status"] = "data_error"
                    entry["error"] = str(exc)
                    any_error = True
                    store_results.append(entry)
                    continue

                try:
                    engine = get_engine(engine_name)
                    if engine is None:
                        entry["status"] = "not_registered"
                        any_error = True
                        store_results.append(entry)
                        continue
                    result = engine.run(data)
                    if isinstance(result, dict):
                        entry["status"] = result.get("status", "?")
                        # Wave 38: capture WHY when status != ok.
                        # Per Pattern Q, engines return
                        # {status, data, meta, error}; the error
                        # field carries the diagnostic. Without
                        # this, cycle history is "10 errors" with
                        # no clue what failed.
                        err = result.get("error")
                        if err and entry["status"] != "success":
                            entry["error"] = (
                                str(err)[:500]
                                if not isinstance(err, dict)
                                else err
                            )
                        # Capture a slim meta for forensics:
                        # which engine actually ran, what it
                        # produced. Bound to 200 chars to keep
                        # history file size manageable.
                        meta = result.get("meta")
                        if isinstance(meta, dict):
                            entry["meta"] = {
                                k: v for k, v in meta.items()
                                if k in (
                                    "engine", "version",
                                    "duration_ms",
                                )
                            }
                    else:
                        entry["status"] = "?"
                        entry["error"] = (
                            f"engine returned non-dict: "
                            f"{type(result).__name__}"
                        )
                except Exception as exc:  # noqa: BLE001
                    entry["status"] = "engine_raised"
                    entry["error"] = str(exc)
                    any_error = True
                store_results.append(entry)

        per_store_results.append({
            "store_id": store_id,
            "total_invoked": len(store_results),
            "ok": sum(
                1 for r in store_results
                if r.get("status") in ("success", "ok")
            ),
            "errors": sum(
                1 for r in store_results
                if r.get("status") not in ("success", "ok")
            ),
            "results": store_results,
        })

    overall = {
        "cycle_label": fleet_plan.cycle_label,
        "stores": len(per_store_results),
        "total_invoked": sum(
            s["total_invoked"] for s in per_store_results
        ),
        "ok": sum(s["ok"] for s in per_store_results),
        "errors": sum(s["errors"] for s in per_store_results),
    }

    # Persist this run to history so operators can audit
    # "what fired this cycle?" later via `cycle history`.
    cycle_run_id = None
    try:
        from engines._cycle_history import record_cycle_run
        cycle_run = record_cycle_run(
            cycle_label=fleet_plan.cycle_label,
            mode="live",
            total_stores=len(per_store_results),
            total_invoked=overall["total_invoked"],
            total_ok=overall["ok"],
            total_errors=overall["errors"],
            per_store=per_store_results,
        )
        cycle_run_id = cycle_run.run_id if cycle_run else None
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "cycle history record failed: %s", exc,
        )

    # Capture attribution-as-of-now snapshot linked to this
    # cycle run. Closes the trend loop -- without persistence,
    # every attribution query is a fresh point with no history.
    # No-op under pytest (Pattern J guard inside the recorder).
    try:
        from engines._attribution_snapshot import record_snapshot
        # Fleet-wide snapshot (legacy)
        record_snapshot(
            window_hours=168.0,
            cycle_run_id=cycle_run_id,
        )
        # Per-store snapshots for multi-store empires. Each
        # captures attribution scoped to that store so cycle
        # status --store X has trend history. Failure on one
        # store doesn't block others.
        for sr in per_store_results:
            store_id = sr.get("store_id")
            if not store_id:
                continue
            try:
                record_snapshot(
                    window_hours=168.0,
                    store_id=store_id,
                    cycle_run_id=cycle_run_id,
                )
            except Exception as exc:  # noqa: BLE001
                logger.debug(
                    "per-store snapshot failed for %s: %s",
                    store_id, exc,
                )
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "attribution snapshot record failed: %s", exc,
        )

    # Propagate any regression alerts onto the cluster bus so
    # next cycle's captains can react. Substrate loop -- alerts
    # become decision-time signals, not just operator-facing.
    # Both fleet-wide (store_id=None) AND per-store delta are
    # checked so a regression on one store fires its store-
    # scoped event without bleeding into other stores.
    try:
        from engines._attribution_delta import (
            latest_delta, propagate_alerts_to_bus,
        )
        # Fleet-wide
        delta = latest_delta()
        if delta is not None and delta.has_alerts:
            n = propagate_alerts_to_bus(delta)
            logger.info(
                "propagated %d revenue-regression alert(s) "
                "to cluster bus", n,
            )
        # Per-store propagation: each store's regression fires
        # store-scoped events so per-store captains react.
        for sr in per_store_results:
            store_id = sr.get("store_id")
            if not store_id:
                continue
            try:
                store_delta = latest_delta(store_id=store_id)
                if store_delta is not None and store_delta.has_alerts:
                    n = propagate_alerts_to_bus(
                        store_delta, store_id=store_id,
                    )
                    logger.info(
                        "store=%s: propagated %d "
                        "regression alert(s)",
                        store_id, n,
                    )
            except Exception as exc:  # noqa: BLE001
                logger.debug(
                    "per-store delta propagation failed "
                    "for %s: %s", store_id, exc,
                )
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "regression alert propagation failed: %s", exc,
        )

    # Wave 47: per-store spend cap auto-pause. Fires after
    # the cycle records outcomes so spend metrics are up-to-
    # date. Pauses spend-class engines when daily/weekly cap
    # is exceeded.
    try:
        from engines._spend_cap import (
            maybe_auto_pause_on_overspend,
        )
        paused_spend = maybe_auto_pause_on_overspend()
        if paused_spend:
            logger.warning(
                "spend-cap auto-paused (fleet): %s",
                ", ".join(paused_spend),
            )
        for sr in per_store_results:
            store_id = sr.get("store_id")
            if not store_id:
                continue
            try:
                paused_store = maybe_auto_pause_on_overspend(
                    store_id=store_id,
                )
                if paused_store:
                    logger.warning(
                        "spend-cap auto-paused (store=%s): %s",
                        store_id, ", ".join(paused_store),
                    )
            except Exception as exc:  # noqa: BLE001
                logger.debug(
                    "per-store spend-cap failed for %s: %s",
                    store_id, exc,
                )
    except Exception as exc:  # noqa: BLE001
        logger.debug("spend-cap bridge failed: %s", exc)

    # Wave 21+22 closing chain: when an engine has fired
    # regression alerts across N consecutive cycles, auto-pause
    # it via the revenue-quarantine bridge. Env-gated default
    # OFF -- operators delegate the auto-pause decision
    # explicitly. Bridge handles both fleet and per-store
    # scopes; iterate same way as the propagation block above
    # so per-store regressions land in per-store pauses.
    try:
        from engines._revenue_quarantine import (
            maybe_auto_quarantine_from_revenue,
        )
        paused_fleet = maybe_auto_quarantine_from_revenue()
        if paused_fleet:
            logger.info(
                "revenue-regression auto-paused (fleet): %s",
                ", ".join(paused_fleet),
            )
        for sr in per_store_results:
            store_id = sr.get("store_id")
            if not store_id:
                continue
            try:
                paused_store = (
                    maybe_auto_quarantine_from_revenue(
                        store_id=store_id,
                    )
                )
                if paused_store:
                    logger.info(
                        "revenue-regression auto-paused "
                        "(store=%s): %s",
                        store_id, ", ".join(paused_store),
                    )
            except Exception as exc:  # noqa: BLE001
                logger.debug(
                    "per-store revenue-quarantine failed "
                    "for %s: %s", store_id, exc,
                )
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "revenue-quarantine bridge failed: %s", exc,
        )

    # Wave 106: refund_health auto-pause bridge. Mirrors the
    # revenue-quarantine block above. Env-gated -- default OFF
    # so existing cycles don't change behaviour.
    try:
        from engines.returns_management.refund_health import (
            maybe_auto_pause_refunds,
        )
        refund_report = maybe_auto_pause_refunds(
            window_hours=24.0,
        )
        if refund_report.bridge_fired:
            logger.info(
                "refund auto-pause bridge fired: %s",
                refund_report.bridge_reason,
            )
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "refund-quarantine bridge failed: %s", exc,
        )

    # Wave 114: budget auto-pause bridge. Same pattern as
    # the refund bridge above. Env-gated via
    # SHOPAI_AUTO_PAUSE_BUDGET_ON_FAILURE.
    try:
        from engines.roas_guardrails.budget_health import (
            maybe_auto_pause_budget,
        )
        budget_report = maybe_auto_pause_budget(
            window_hours=24.0,
        )
        if budget_report.bridge_fired:
            logger.info(
                "budget auto-pause bridge fired: %s",
                budget_report.bridge_reason,
            )
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "budget-quarantine bridge failed: %s", exc,
        )

    # Wave 130: fulfillment auto-pause bridge. Env-gated via
    # SHOPAI_AUTO_PAUSE_FULFILLMENT_ON_FAILURE.
    try:
        from engines.fulfillment_autonomy.fulfillment_health import (
            maybe_auto_pause_fulfillment,
        )
        ff_report = maybe_auto_pause_fulfillment(
            window_hours=24.0,
        )
        if ff_report.bridge_fired:
            logger.info(
                "fulfillment auto-pause bridge fired: %s",
                ff_report.bridge_reason,
            )
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "fulfillment-quarantine bridge failed: %s", exc,
        )

    # Wave 136: inventory auto-pause bridge.
    try:
        from engines.inventory_autonomy.inventory_health import (
            maybe_auto_pause_inventory,
        )
        inv_report = maybe_auto_pause_inventory(
            window_hours=24.0,
        )
        if inv_report.bridge_fired:
            logger.info(
                "inventory auto-pause bridge fired: %s",
                inv_report.bridge_reason,
            )
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "inventory-quarantine bridge failed: %s", exc,
        )

    # Wave 159: discount cleanup auto-pause bridge.
    try:
        from engines.discount_cleanup_autonomy.cleanup_health import (
            maybe_auto_pause_cleanup,
        )
        cu_report = maybe_auto_pause_cleanup(
            window_hours=24.0,
        )
        if cu_report.bridge_fired:
            logger.info(
                "discount cleanup auto-pause bridge fired: %s",
                cu_report.bridge_reason,
            )
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "discount-cleanup bridge failed: %s", exc,
        )

    # Wave 200: product SEO auto-pause bridge.
    try:
        from engines.product_seo_autonomy.seo_health import (
            maybe_auto_pause_seo,
        )
        seo_report = maybe_auto_pause_seo(window_hours=24.0)
        if seo_report.bridge_fired:
            logger.info(
                "product SEO auto-pause bridge fired: %s",
                seo_report.bridge_reason,
            )
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "product-seo bridge failed: %s", exc,
        )

    # Wave 179: order followup auto-pause bridge.
    try:
        from engines.order_followup_autonomy.followup_health import (
            maybe_auto_pause_followup,
        )
        fu_report = maybe_auto_pause_followup(
            window_hours=24.0,
        )
        if fu_report.bridge_fired:
            logger.info(
                "order followup auto-pause bridge fired: %s",
                fu_report.bridge_reason,
            )
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "order-followup bridge failed: %s", exc,
        )

    # Wave 397: customer outreach auto-pause bridge
    try:
        from engines.customer_outreach_autonomy.outreach_health import (  # noqa: E501
            maybe_auto_pause_outreach,
        )
        co_report = maybe_auto_pause_outreach(
            window_hours=24.0,
        )
        if co_report.bridge_fired:
            logger.info(
                "customer outreach auto-pause bridge fired: %s",
                co_report.bridge_reason,
            )
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "customer-outreach bridge failed: %s", exc,
        )

    # Wave 453: catalog quality auto-pause bridge
    try:
        from engines.catalog_quality_autonomy.quality_health import (  # noqa: E501
            maybe_auto_pause_quality,
        )
        cq_report = maybe_auto_pause_quality(
            window_hours=24.0,
        )
        if cq_report.bridge_fired:
            logger.info(
                "catalog quality auto-pause bridge fired: %s",
                cq_report.bridge_reason,
            )
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "catalog-quality bridge failed: %s", exc,
        )

    # Wave 779: shipping alert auto-pause bridge
    try:
        from engines.shipping_alert_autonomy.shipping_health import (  # noqa: E501
            maybe_auto_pause_shipping,
        )
        sa_report = maybe_auto_pause_shipping(
            window_hours=24.0,
        )
        if sa_report.bridge_fired:
            logger.info(
                "shipping alert auto-pause bridge fired: %s",
                sa_report.bridge_reason,
            )
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "shipping-alert bridge failed: %s", exc,
        )

    # W963-23/26: autopilot bridge -- fires welcome_series +
    # review_request batches inside the standard cycle.
    # Triple-gated: cycle's --yes + SHOPAI_CYCLE_RUN_CONFIRM=1
    # (already passed by this point), PLUS a separate
    # SHOPAI_CYCLE_AUTOPILOT_BRIDGE=1 env gate so operators
    # can wire autopilot for standalone use WITHOUT also
    # having the cycle fire it. And each writer stage still
    # has its own SHOPAI_AUTOPILOT_WELCOME/REVIEWS gate.
    #
    # When --store is set, fires single-store. When --store
    # is omitted AND SHOPAI_CYCLE_AUTOPILOT_FLEET=1 is set,
    # uses fleet_autopilot to iterate every store under its
    # active_store context (north-star empire mode). Without
    # the fleet gate, single-store fallback to default
    # credentials (legacy behaviour).
    bridge_enabled = os.environ.get(
        "SHOPAI_CYCLE_AUTOPILOT_BRIDGE", "",
    ).strip().lower() in ("1", "true", "yes", "on")
    if bridge_enabled:
        fleet_mode = (
            (not only_store)
            and os.environ.get(
                "SHOPAI_CYCLE_AUTOPILOT_FLEET", "",
            ).strip().lower() in ("1", "true", "yes", "on")
        )
        try:
            if fleet_mode:
                from engines.fleet_autopilot.runner import (
                    run_fleet_autopilot,
                )
                fr = run_fleet_autopilot(confirmed=True)
                if fr.sent_count_total > 0 or fr.errors_total > 0:
                    logger.info(
                        "fleet-autopilot bridge: %d store(s), "
                        "sent=%d errors=%d",
                        len(fr.by_store),
                        fr.sent_count_total,
                        fr.errors_total,
                    )
            else:
                from engines.autopilot.runner import run_autopilot
                ap_report = run_autopilot(
                    confirmed=True,
                    store_id=only_store or None,
                )
                fired = [
                    s.name for s in ap_report.stages if s.fired
                ]
                if fired:
                    logger.info(
                        "autopilot bridge fired stages: %s",
                        ",".join(fired),
                    )
        except Exception as exc:  # noqa: BLE001
            logger.debug(
                "autopilot bridge failed: %s", exc,
            )

    # Wave 854: auto-disarm bridge -- runs BEFORE the
    # substrate fire so chronically-degraded domains get
    # their armed flag revoked before they fire again.
    try:
        from core.automation.substrate_fire_auto_disarm import (  # noqa
            maybe_auto_disarm,
        )
        disarm_report = maybe_auto_disarm()
        if disarm_report.disarmed_count > 0:
            logger.info(
                "auto-disarm bridge fired: %d "
                "domain(s) revoked",
                disarm_report.disarmed_count,
            )
        elif disarm_report.would_disarm_count > 0:
            logger.info(
                "auto-disarm bridge OFF but %d "
                "domain(s) at threshold",
                disarm_report.would_disarm_count,
            )
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "auto-disarm bridge raised: %s", exc,
        )

    # Wave 822 + 839: armed substrate-domain fire
    # (discoverer -> applier). Fires fleet-wide first, then
    # per-store for every store in the world-model snapshot so
    # per-store attribution gets captured. The fleet-wide call
    # is back-compat with operators that haven't tagged stores.
    try:
        from core.automation.substrate_fire import (
            fire_armed_substrate_domains,
        )
        sub_report = fire_armed_substrate_domains()
        if sub_report.outcomes:
            logger.info(
                "substrate-fire (fleet): %d invoked, "
                "%d discovered rows",
                sub_report.total_invoked,
                sub_report.total_discovered_rows,
            )
        for sid in list(world_models.keys()):
            ps_report = fire_armed_substrate_domains(
                store_id=sid,
            )
            if ps_report.outcomes and (
                ps_report.total_discovered_rows > 0
                or ps_report.total_invoked > 0
            ):
                logger.info(
                    "substrate-fire (store=%s): "
                    "%d invoked, %d discovered rows",
                    sid,
                    ps_report.total_invoked,
                    ps_report.total_discovered_rows,
                )
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "substrate-fire bridge raised: %s", exc,
        )

    # Wave 251: post-cycle autonomy-doctor snapshot. Cheap
    # (cached AST audits + per-domain summary calls); catches
    # substrate breakage that bridge fire alone wouldn't expose.
    wiring_block: dict | None = None
    try:
        from core.automation.autonomy_doctor import (
            run_autonomy_doctor,
        )
        wiring = run_autonomy_doctor(window_hours=24.0)
        wiring_block = {
            "overall_cls": wiring.overall_cls,
            "ok": wiring.ok_count,
            "warn": wiring.warn_count,
            "fail": wiring.fail_count,
            "domain_count": len(wiring.domains),
        }
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "post-cycle wiring snapshot failed: %s", exc,
        )

    if as_json:
        print(json.dumps({
            "mode": "live",
            "summary": overall,
            "stores": per_store_results,
            "wiring": wiring_block,
        }, indent=2, default=str))
        if any_error:
            sys.exit(1)
        return

    print(
        f"Empire cycle (LIVE) -- {fleet_plan.cycle_label}"
    )
    print()
    print(
        f"  Stores processed:     {overall['stores']:3d}"
    )
    print(
        f"  Total invoked:        {overall['total_invoked']:3d} "
        "engine(s)"
    )
    print(
        f"  OK:    {overall['ok']:3d}      "
        f"Errors: {overall['errors']:3d}"
    )
    print()
    for sr in per_store_results:
        sid = sr["store_id"] or "(no-id)"
        print(
            f"  store: {sid:<25}  "
            f"invoked={sr['total_invoked']:3d}  "
            f"ok={sr['ok']:3d}  err={sr['errors']:3d}"
        )
    print()
    if wiring_block and (
        wiring_block["fail"] > 0 or wiring_block["warn"] > 0
    ):
        mark = (
            "[BAD]" if wiring_block["fail"] > 0 else "[WRN]"
        )
        print(
            f"  Wiring: {mark} "
            f"{wiring_block['fail']} fail / "
            f"{wiring_block['warn']} warn / "
            f"{wiring_block['ok']} ok  "
            "(drill: shopai autonomy-doctor)"
        )
    print(
        "  Drill: `shopai approvals list --status pending` "
        "(see modification-tier engine outputs awaiting "
        "approval)"
    )
    if any_error:
        sys.exit(1)


def _cmd_orchestrator_plan(args) -> None:
    """Build + render a FleetPlan from Tier 1 orchestrator.

    Pulls world-model snapshot for each store, runs the
    DeterministicOrchestratorStrategy to assign priorities,
    builds SupervisorPlan per store, aggregates into
    FleetPlan.
    """
    import time as _time
    from engines._orchestrator import (
        make_fleet_plan, fleet_summary,
    )
    from core.world_model import WorldModel

    sm = _get_store_manager()
    only_store = (getattr(args, "store", None) or "").strip()

    # Pull world-models for each store (or just the one)
    world_models: dict[str, dict] = {}
    try:
        wm = WorldModel()
        if only_store:
            world_models[only_store] = wm.snapshot(
                only_store, skip_live=True,
            )
        else:
            for s in sm.list_stores() or []:
                sid = s.get("store_id")
                if not sid:
                    continue
                world_models[sid] = wm.snapshot(
                    sid, skip_live=True,
                )
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "orchestrator plan world-model raised: %s", exc,
        )

    cycle_label = _time.strftime(
        "%Y-%m-%dT%H:%M:%S", _time.gmtime(),
    )
    plan = make_fleet_plan(
        world_models=world_models, cycle_label=cycle_label,
    )
    s = fleet_summary(plan)

    if getattr(args, "json", False):
        print(json.dumps({
            "cycle_label": plan.cycle_label,
            "summary": s,
            "priorities": [
                {
                    "store_id": p.store_id,
                    "priority": p.priority,
                    "cluster_focus": p.cluster_focus,
                    "rationale": p.rationale,
                    "signals": p.signals,
                }
                for p in plan.priorities
            ],
            "supervisor_plans": [
                {
                    "store_id": sp.store_id,
                    "active_clusters": sp.active_clusters,
                    "total_to_fire": sp.total_to_fire,
                    "total_modifications":
                        sp.total_modifications,
                }
                for sp in plan.supervisor_plans
            ],
        }, indent=2, default=str))
        return

    print(
        f"Empire orchestrator plan -- cycle {plan.cycle_label}"
    )
    print()
    print(f"  Total stores:        {s['total_stores']:3d}")
    print(f"  Total to fire:       {s['total_to_fire']:3d}")
    print(
        f"  Total modifications: "
        f"{s['total_modifications']:3d}"
    )
    print()
    if not s["stores"]:
        print("  (no stores in fleet)")
        if plan.notes:
            for n in plan.notes:
                print(f"  {n}")
        return
    print(
        f"  {'store_id':<25} {'priority':<11} "
        f"{'clusters':<10} {'fire':>4} {'queue':>5}"
    )
    for row in s["stores"]:
        sid = row["store_id"][:25]
        print(
            f"  {sid:<25} {row['priority']:<11} "
            f"{row['active_clusters']:>8d}  "
            f"{row['fire']:>4d} {row['queued']:>5d}"
        )
    print()
    print("  Per-store rationale:")
    for prio in plan.priorities:
        print(
            f"    {prio.store_id:<25} {prio.priority:<11} "
            f"{prio.rationale}"
        )
    print()
    print(
        "  Drill: `shopai store supervise <store_id>`"
    )
    print(
        "  Fire:  `shopai cluster fire <name> --store <id> --yes`"
    )


def _cmd_store_supervise(args) -> None:
    """Tier 2a per-store supervisor plan.

    Builds the per-cluster captain plan aggregate for one
    store-cycle. Doesn't execute -- shows what the supervisor
    WOULD do this cycle. Tier 1 orchestrator (future) or
    operator manually invokes the plan via `shopai cluster
    fire`.
    """
    from engines._store_supervisor import (
        make_supervisor_plan, supervisor_summary,
    )

    store_id = (
        getattr(args, "store_id", None)
        or _get_store_manager().active_store_id
    )

    # Parse --clusters CSV
    cluster_override: list[str] | None = None
    raw_clusters = getattr(args, "clusters", None) or ""
    if raw_clusters:
        cluster_override = [
            c.strip() for c in raw_clusters.split(",") if c.strip()
        ]

    # Parse --signals JSON
    signals_by_cluster: dict | None = None
    raw_signals = getattr(args, "signals", None) or ""
    if raw_signals:
        try:
            parsed = json.loads(raw_signals)
            if not isinstance(parsed, dict):
                print("Error: --signals must be a JSON object")
                sys.exit(1)
                return
            signals_by_cluster = parsed
        except json.JSONDecodeError as exc:
            print(f"Error: --signals invalid JSON: {exc}")
            sys.exit(1)
            return

    plan = make_supervisor_plan(
        store_id=store_id,
        signals_by_cluster=signals_by_cluster,
        cluster_override=cluster_override,
    )
    summary = supervisor_summary(plan)

    if getattr(args, "json", False):
        print(json.dumps({
            "store_id": plan.store_id,
            "summary": summary,
            "captain_plans": [
                {
                    "cluster": cp.cluster,
                    "fire_count": cp.fire_count,
                    "members_to_fire": cp.members_to_fire,
                    "modifications_queued": cp.modifications_queued,
                    "members_to_skip": cp.members_to_skip,
                }
                for cp in plan.captain_plans
            ],
            "skipped_clusters": plan.skipped_clusters,
        }, indent=2, default=str))
        return

    print(
        f"Store supervisor: {plan.store_id or '(active)'}"
    )
    print()
    print(
        f"  Active clusters:    {summary['active_clusters']:3d}"
    )
    print(
        f"  Skipped clusters:   {summary['skipped_clusters']:3d}"
    )
    print(
        f"  Total to fire:      {summary['total_to_fire']:3d} "
        "engine(s)"
    )
    print(
        f"  Modifications:      "
        f"{summary['total_modifications']:3d} "
        "engine(s) (need approval)"
    )
    print()
    print("  Cluster breakdown:")
    print(
        f"    {'cluster':<14}  fire  queued  skipped  notes"
    )
    for row in summary["cluster_breakdown"]:
        notes_str = (
            f"  {row['notes'][0][:40]}" if row["notes"] else ""
        )
        print(
            f"    {row['cluster']:<14}  "
            f"{row['fire']:>4d}  "
            f"{row['queued']:>6d}  "
            f"{row['skipped']:>7d}  "
            f"{notes_str}"
        )

    if plan.skipped_clusters:
        print()
        print("  Skipped clusters:")
        for s in plan.skipped_clusters:
            print(
                f"    {s['cluster']:<14}  reason={s['reason']}"
            )

    print()
    print("  Drill: `shopai cluster show <name>`")
    print("  Fire:  `shopai cluster fire <name> --yes`")


def _cmd_cluster_bus(args) -> None:
    """Operator surface for the cross-cluster event bus.

    Modes:
      - default: list recent events
      - --clear: wipe the bus (requires env var)
      - --emit EMITTER:TOPIC: manually inject one event
    """
    import time as _time
    from engines._cluster_bus import (
        emit_event,
        subscribe_events,
        clear_bus,
        cross_cluster_signals,
        bus_stats,
    )

    as_json = bool(getattr(args, "json", False))

    # Mode: stats summary
    if getattr(args, "stats", False):
        try:
            window_hours = float(
                getattr(args, "window", "24") or "24"
            )
        except (TypeError, ValueError):
            window_hours = 24.0
        stats = bus_stats(window_hours=window_hours)
        if as_json:
            print(json.dumps(stats, indent=2, default=str))
            return
        print(
            f"Cluster bus stats (window: {window_hours:.0f}h)"
        )
        print()
        print(f"  Total events: {stats['total_events']}")
        if stats["oldest_age_seconds"] is not None:
            print(
                f"  Oldest: "
                f"{stats['oldest_age_seconds']/3600:.1f}h ago"
            )
            print(
                f"  Newest: "
                f"{stats['newest_age_seconds']/60:.0f}m ago"
            )
        if stats["by_topic"]:
            print()
            print("  By topic:")
            for topic, n in stats["by_topic"].items():
                print(f"    {topic:<28} {n}")
        if stats["by_emitter"]:
            print()
            print("  By emitter cluster:")
            for emitter, n in stats["by_emitter"].items():
                print(f"    {emitter:<28} {n}")
        if stats["by_store"]:
            print()
            print("  By store:")
            for sid, n in stats["by_store"].items():
                print(f"    {sid:<28} {n}")
        return

    # Mode: emit one event manually
    emit_spec = (getattr(args, "emit", None) or "").strip()
    if emit_spec:
        if ":" not in emit_spec:
            msg = (
                f"--emit format must be 'emitter:topic'. "
                f"Got: {emit_spec!r}"
            )
            if as_json:
                print(json.dumps(
                    {"status": "error", "error": msg},
                    indent=2,
                ))
            else:
                print(f"Error: {msg}")
            sys.exit(1)
            return
        emitter, topic = emit_spec.split(":", 1)
        emitter = emitter.strip()
        topic = topic.strip()
        if not emitter or not topic:
            print("Error: emitter and topic both required")
            sys.exit(1)
            return
        try:
            payload = json.loads(
                getattr(args, "payload_json", None) or "{}"
            )
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError as exc:
            print(f"Error: --payload-json invalid: {exc}")
            sys.exit(1)
            return
        store_id = getattr(args, "store", None) or None
        event = emit_event(
            emitter_cluster=emitter,
            topic=topic,
            payload=payload,
            store_id=store_id,
        )
        if as_json:
            print(json.dumps({
                "status": "ok",
                "event": event.to_dict(),
            }, indent=2, default=str))
        else:
            print(
                f"Event emitted:  emitter={emitter}  "
                f"topic={topic}  store={store_id or '-'}"
            )
            print(
                f"  payload: {json.dumps(payload)}"
            )
            print(
                "  Verify: `shopai cluster bus --window 1`"
            )
        return

    if getattr(args, "clear", False):
        if not os.environ.get("SHOPAI_CLUSTER_BUS_CLEAR_CONFIRM"):
            msg = (
                "Bus --clear requires "
                "SHOPAI_CLUSTER_BUS_CLEAR_CONFIRM=1 env var. "
                "Wiping the bus drops all cross-cluster "
                "signal history."
            )
            if as_json:
                print(json.dumps(
                    {"status": "error", "error": msg},
                    indent=2,
                ))
            else:
                print(f"Error: {msg}")
            sys.exit(1)
            return
        ok = clear_bus()
        if as_json:
            print(json.dumps(
                {"status": "ok" if ok else "error",
                 "cleared": ok},
                indent=2,
            ))
        else:
            print(
                "Bus cleared." if ok
                else "Bus clear FAILED."
            )
        return

    try:
        window_hours = float(
            getattr(args, "window", "24") or "24"
        )
    except (TypeError, ValueError):
        window_hours = 24.0

    topic = getattr(args, "topic", None) or None
    emitter = getattr(args, "emitter", None) or None
    store_id = getattr(args, "store", None) or None

    events = subscribe_events(
        topic=topic,
        emitter_cluster=emitter,
        store_id=store_id,
        window_hours=window_hours,
    )

    # Compute the next-cycle signals view (what consumers
    # will see if Tier 1 runs right now)
    next_cycle_signals = cross_cluster_signals(
        store_id=store_id, window_hours=window_hours,
    )

    if as_json:
        print(json.dumps({
            "window_hours": window_hours,
            "filters": {
                "topic": topic, "emitter": emitter,
                "store_id": store_id,
            },
            "event_count": len(events),
            "next_cycle_signals": next_cycle_signals,
            "events": [
                {
                    "emitter_cluster": e.emitter_cluster,
                    "topic": e.topic,
                    "payload": e.payload,
                    "emitted_at": e.emitted_at,
                    "store_id": e.store_id,
                }
                for e in events
            ],
        }, indent=2, default=str))
        return

    print(
        f"Cluster event bus  (window: {window_hours:.0f}h)"
    )
    print()
    print(f"  Events: {len(events)}")
    if topic:
        print(f"  Filter topic:    {topic}")
    if emitter:
        print(f"  Filter emitter:  {emitter}")
    if store_id:
        print(f"  Filter store:    {store_id}")
    print()

    if not events:
        print("  (no events in window)")
        print()
        print(
            "  Captains auto-emit on non-zero signals. Run "
            "`shopai cycle run --yes` to start events flowing."
        )
        return

    # Per-event row
    print(
        f"  {'when':<20} {'emitter':<14} {'topic':<22} "
        f"{'store':<10} payload"
    )
    now = _time.time()
    for e in events[:20]:
        age = now - e.emitted_at
        if age < 60:
            ago = f"{int(age)}s ago"
        elif age < 3600:
            ago = f"{int(age/60)}m ago"
        else:
            ago = f"{age/3600:.1f}h ago"
        payload_str = json.dumps(e.payload)[:30]
        print(
            f"  {ago:<20} {e.emitter_cluster:<14} "
            f"{e.topic:<22} {(e.store_id or '-'):<10} "
            f"{payload_str}"
        )
    if len(events) > 20:
        print(f"  ... and {len(events) - 20} more")
    print()

    if next_cycle_signals:
        print("  Next-cycle signals (consumers will see):")
        for cluster, sigs in sorted(
            next_cycle_signals.items(),
        ):
            for name, val in sigs.items():
                print(f"    {cluster}:{name} = {val}")


def _cmd_cluster_fire(args) -> None:
    """Captain plan, dry-run preview OR actually invoke.

    Default: dry-run (same as `cluster plan`).
    --yes + SHOPAI_CLUSTER_FIRE_CONFIRM=1: actually invoke
    every additive member via engine.run() with the
    apply_X flag set. Modification members invoked with
    require_approval=True so they enqueue internally.
    """
    from engines._cluster_captain import (
        make_captain_plan,
        SignalDrivenCaptainStrategy,
    )

    cluster_name = (args.cluster_name or "").strip()
    if not cluster_name:
        print("Error: cluster_name required")
        sys.exit(1)

    store_id = (
        getattr(args, "store", None)
        or _get_store_manager().active_store_id
    )
    yes = bool(getattr(args, "yes", False))
    as_json = bool(getattr(args, "json", False))

    # Signal-driven strategy when --signals supplied
    signals: dict | None = None
    strategy = None
    raw_signals = getattr(args, "signals", None) or ""
    if raw_signals:
        try:
            parsed = json.loads(raw_signals)
            if not isinstance(parsed, dict):
                print("Error: --signals must be a JSON object")
                sys.exit(1)
                return
            signals = parsed
            strategy = SignalDrivenCaptainStrategy()
        except json.JSONDecodeError as exc:
            print(f"Error: --signals invalid JSON: {exc}")
            sys.exit(1)
            return

    plan = make_captain_plan(
        cluster_name, store_id=store_id,
        signals=signals, strategy=strategy,
        store_stats=_store_stats_for_captain(store_id),
    )

    if not yes:
        # Dry-run: same shape as `cluster plan`
        if as_json:
            print(json.dumps({
                "mode": "dry_run",
                "cluster": plan.cluster,
                "store_id": plan.store_id,
                "would_fire": plan.members_to_fire,
                "would_queue": plan.modifications_queued,
                "would_skip": plan.members_to_skip,
                "notes": plan.notes,
            }, indent=2, default=str))
            return
        print(
            f"Cluster fire: {plan.cluster}  (DRY-RUN, "
            f"store={plan.store_id or 'all'})"
        )
        print()
        print(
            f"  Would direct-fire (additive):  "
            f"{len(plan.members_to_fire):3d} engine(s)"
        )
        print(
            f"  Would approval-dispatch (mod): "
            f"{len(plan.modifications_queued):3d} engine(s) "
            "(invoked with require_approval=True)"
        )
        print(
            f"  Would skip:                    "
            f"{len(plan.members_to_skip):3d} engine(s)"
        )
        print()
        print(
            "  To actually invoke: SHOPAI_CLUSTER_FIRE_CONFIRM=1 "
            f"shopai cluster fire {plan.cluster} --yes"
        )
        return

    # --yes path: actually invoke additive members
    if not os.environ.get("SHOPAI_CLUSTER_FIRE_CONFIRM"):
        msg = (
            "Cluster fire blast-radius guard: --yes requires "
            "SHOPAI_CLUSTER_FIRE_CONFIRM=1 env var. Cluster "
            "fires can invoke many engines at once + write to "
            "Shopify; set the env var to acknowledge before "
            "actually invoking."
        )
        if as_json:
            print(json.dumps(
                {"status": "error", "error": msg},
                indent=2, default=str,
            ))
        else:
            print(f"Error: {msg}")
        sys.exit(1)
        return

    # Pull DataProvider once -- reused per engine
    try:
        from data_pipeline.store.data_provider import (
            DataProvider,
        )
        sm = _get_store_manager()
    except Exception as exc:  # noqa: BLE001
        msg = f"data provider unavailable: {exc}"
        if as_json:
            print(json.dumps(
                {"status": "error", "error": msg},
                indent=2, default=str,
            ))
        else:
            print(f"Error: {msg}")
        sys.exit(1)
        return

    try:
        from engines.registry import get_engine
    except Exception as exc:  # noqa: BLE001
        msg = f"engine registry unavailable: {exc}"
        if as_json:
            print(json.dumps(
                {"status": "error", "error": msg},
                indent=2, default=str,
            ))
        else:
            print(f"Error: {msg}")
        sys.exit(1)
        return

    # Build the unified invocation list:
    #   - additive members: apply_X=True (auto-fire)
    #   - modification members: apply_X=True + require_approval=True
    #     (engine internally enqueues to ApprovalQueue)
    invocations: list[dict] = []
    for m in plan.members_to_fire:
        invocations.append({
            "engine": m["engine"],
            "apply_flag": m["apply_flag"],
            "risk": m.get("risk"),
            "require_approval": False,
        })
    for m in plan.modifications_queued:
        invocations.append({
            "engine": m["engine"],
            "apply_flag": m["apply_flag"],
            "risk": m.get("risk"),
            "require_approval": True,
        })

    results: list[dict] = []
    any_error = False
    for member in invocations:
        engine_name = member["engine"]
        apply_flag = member["apply_flag"]
        require_approval = member["require_approval"]
        entry: dict = {
            "engine": engine_name,
            "apply_flag": apply_flag,
            "risk": member.get("risk"),
            "approval_required": require_approval,
        }
        try:
            data = (
                DataProvider(sm).get_data_for_engine(
                    engine_name, store_id,
                ) if store_id else {}
            )
            if not isinstance(data, dict):
                data = {}
            data[apply_flag] = True
            # Risk-tier translation: modification members
            # set require_approval=True so the engine's
            # internal applier enqueues to ApprovalQueue
            # rather than firing direct.
            if require_approval:
                data["require_approval"] = True
        except Exception as exc:  # noqa: BLE001
            entry["status"] = "data_error"
            entry["error"] = str(exc)
            any_error = True
            results.append(entry)
            continue

        try:
            engine = get_engine(engine_name)
            if engine is None:
                entry["status"] = "not_registered"
                any_error = True
                results.append(entry)
                continue
        except Exception as exc:  # noqa: BLE001
            entry["status"] = "load_error"
            entry["error"] = str(exc)
            any_error = True
            results.append(entry)
            continue

        try:
            result = engine.run(data)
            entry["status"] = (
                result.get("status", "?")
                if isinstance(result, dict) else "?"
            )
            # Surface any writer-result key the engine puts in
            # its output (apply_results, minted_codes,
            # tagged_*, payout_results, etc.)
            inner = (
                result.get("data") if isinstance(result, dict)
                else None
            )
            if isinstance(inner, dict):
                writer_keys = [
                    k for k in inner
                    if (
                        k.startswith("apply_")
                        or k.startswith("minted_")
                        or k.startswith("tagged_")
                        or k.startswith("payout_")
                    )
                ]
                writer_outputs: dict = {}
                for k in writer_keys:
                    v = inner[k]
                    if isinstance(v, list):
                        writer_outputs[k] = len(v)
                    else:
                        writer_outputs[k] = bool(v)
                if writer_outputs:
                    entry["writer_outputs"] = writer_outputs
        except Exception as exc:  # noqa: BLE001
            entry["status"] = "engine_raised"
            entry["error"] = str(exc)
            any_error = True
        results.append(entry)

    summary = {
        "cluster": plan.cluster,
        "store_id": store_id,
        "total_invoked": len(results),
        "ok": sum(
            1 for r in results
            if r.get("status") in ("success", "ok")
        ),
        "errors": sum(
            1 for r in results
            if r.get("status") not in ("success", "ok")
        ),
        "direct_fired": sum(
            1 for r in results if not r.get("approval_required")
        ),
        "approval_dispatched": sum(
            1 for r in results if r.get("approval_required")
        ),
        "skipped": len(plan.members_to_skip),
    }

    if as_json:
        print(json.dumps({
            "mode": "fired",
            "summary": summary,
            "fired": results,
            "modifications_queued": plan.modifications_queued,
            "skipped": plan.members_to_skip,
        }, indent=2, default=str))
        if any_error:
            sys.exit(1)
        return

    print(
        f"Cluster fire: {plan.cluster}  (LIVE, "
        f"store={plan.store_id or 'all'})"
    )
    print()
    print(
        f"  Invoked: {summary['total_invoked']} engine(s)"
    )
    print(
        f"    direct fire (additive):     "
        f"{summary['direct_fired']:3d}"
    )
    print(
        f"    approval dispatch (mod):    "
        f"{summary['approval_dispatched']:3d} "
        "(engines enqueue internally via require_approval)"
    )
    print(
        f"  OK:    {summary['ok']:3d}      "
        f"Errors: {summary['errors']:3d}"
    )
    print(f"  Skipped: {summary['skipped']}")
    print()
    for r in results:
        marker = (
            "[ok  ]" if r.get("status") in ("success", "ok")
            else "[FAIL]"
        )
        approval_marker = (
            " [APPR]" if r.get("approval_required") else ""
        )
        line = (
            f"  {marker}{approval_marker} {r['engine']:<26} "
            f"status={r.get('status', '?')}"
        )
        if r.get("writer_outputs"):
            line += f"  outputs={r['writer_outputs']}"
        if r.get("error"):
            line += f"  error={r['error'][:60]}"
        print(line)
    print()
    if summary["approval_dispatched"] > 0:
        print(
            "  [APPR] engines enqueued to ApprovalQueue. "
            "Review: `shopai approvals list --status pending`"
        )
    if any_error:
        sys.exit(1)


def _collect_engines_stats(top_n: int, filter_mode: str) -> dict:
    """Aggregate per-engine activity into a structured dict.

    Combines three signals per engine:
      - Wiring status (wired / advisory / partial) from
        engines._writeback_audit
      - Queue activity counts (pending / approved / rejected /
        executed / failed / expired) from ApprovalQueue.stats_by_engine
      - Total registered engine count

    The dict shape is stable: ``{summary, engines: [...]}``.
    Each engine entry has name + wiring + queue counts +
    derived "total_actions" + "successful_actions" fields.
    """
    out: dict = {
        "summary": {
            "total_engines": 0,
            "wired": 0,
            "advisory": 0,
            "partial": 0,
            "active": 0,
            "idle": 0,
        },
        "engines": [],
        "filter": filter_mode,
        "top_n": top_n,
    }

    # ── Registry ────────────────────────────────────────────
    try:
        from engines.registry import list_engines
        all_engine_names = sorted(list_engines())
        out["summary"]["total_engines"] = len(all_engine_names)
    except Exception as exc:  # noqa: BLE001
        logger.debug("engines registry probe raised: %s", exc)
        all_engine_names = []

    # ── Wiring (writeback audit) ────────────────────────────
    wiring_by_name: dict[str, str] = {}
    writers_by_name: dict[str, list[str]] = {}
    try:
        from engines._writeback_audit import audit_writeback_coverage
        wb = audit_writeback_coverage("engines")
        out["summary"]["wired"] = wb.wired_count
        out["summary"]["advisory"] = wb.advisory_count
        out["summary"]["partial"] = wb.partial_count
        for s in wb.engines:
            wiring_by_name[s.name] = s.status
            writers_by_name[s.name] = list(s.writer_files)
    except Exception as exc:  # noqa: BLE001
        logger.debug("writeback audit probe raised: %s", exc)

    # ── Queue activity ──────────────────────────────────────
    queue_stats: dict[str, dict] = {}
    try:
        from core.approval import get_approval_queue
        queue = get_approval_queue()
        queue_stats = queue.stats_by_engine() or {}
    except Exception as exc:  # noqa: BLE001
        logger.debug("queue probe raised: %s", exc)

    # ── Build per-engine entries ────────────────────────────
    entries: list[dict] = []
    for name in all_engine_names:
        stats = queue_stats.get(name, {})
        total_actions = sum(stats.values()) if stats else 0
        successful = (
            stats.get("executed", 0) + stats.get("approved", 0)
        )
        entry = {
            "name": name,
            "wiring": wiring_by_name.get(name, "unknown"),
            "writers": writers_by_name.get(name, []),
            "pending": stats.get("pending", 0),
            "approved": stats.get("approved", 0),
            "rejected": stats.get("rejected", 0),
            "executed": stats.get("executed", 0),
            "failed": stats.get("failed", 0),
            "expired": stats.get("expired", 0),
            "total_actions": total_actions,
            "successful_actions": successful,
        }
        entries.append(entry)

    out["summary"]["active"] = sum(
        1 for e in entries if e["total_actions"] > 0
    )
    out["summary"]["idle"] = (
        out["summary"]["total_engines"]
        - out["summary"]["active"]
    )

    # Filter
    if filter_mode == "active":
        entries = [e for e in entries if e["total_actions"] > 0]
    elif filter_mode == "idle":
        entries = [e for e in entries if e["total_actions"] == 0]

    # Sort by total_actions descending, then alpha for ties
    entries.sort(key=lambda e: (-e["total_actions"], e["name"]))

    out["engines"] = entries[:top_n] if top_n > 0 else entries
    return out


def _cmd_engines_stats(args) -> None:
    """Aggregate engine activity: per-engine queue counts +
    wiring status + activity totals.

    The "which engines are pulling weight?" command. Operators
    daily-glance see which engines are queueing actions and
    which are idle, alongside their Phase 6/7 wiring status.
    """
    top_n = int(getattr(args, "top", 10) or 10)
    filter_mode = getattr(args, "filter", "all") or "all"

    stats = _collect_engines_stats(top_n, filter_mode)

    if getattr(args, "json", False):
        print(json.dumps(stats, indent=2, default=str))
        return

    s = stats["summary"]
    print("ShopAI Engine Activity Stats")
    print()
    print(
        f"  Total engines: {s['total_engines']}"
    )
    print(
        f"    wired:    {s['wired']}, "
        f"advisory: {s['advisory']}, "
        f"partial: {s['partial']}"
    )
    print(
        f"    active:   {s['active']} "
        f"(at least 1 queue action), "
        f"idle: {s['idle']}"
    )

    entries = stats["engines"]
    if not entries:
        print()
        print(f"No engines match filter '{filter_mode}'.")
        return

    if filter_mode != "all":
        print()
        print(
            f"Filtered to {filter_mode}: showing "
            f"{len(entries)} engine(s) "
            f"(top {top_n}):"
        )
    else:
        print()
        print(
            f"Top {len(entries)} engines by queue activity:"
        )
    print()
    # Compact table
    header = (
        f"  {'engine':<28} {'wiring':<10} "
        f"{'exec':>5} {'fail':>5} {'pend':>5} {'total':>6}"
    )
    print(header)
    print(f"  {'-' * (len(header) - 2)}")
    for e in entries:
        engine_label = e["name"][:28]
        wiring = e["wiring"]
        print(
            f"  {engine_label:<28} {wiring:<10} "
            f"{e['executed']:>5} {e['failed']:>5} "
            f"{e['pending']:>5} {e['total_actions']:>6}"
        )
    # Drill-down hint: only when there's actual activity --
    # otherwise the table is alphabetical and the "top"
    # engine is just whatever sorts first. When activity
    # exists, entries[0] is the most-active engine; point
    # at its per-engine summary.
    if entries and entries[0]["total_actions"] > 0:
        leader = entries[0]["name"]
        print()
        print(
            f"  Drill down: `shopai engine summary {leader}`"
        )


def _render_catalog_markdown(report, entries) -> None:
    """Emit the catalog as a Markdown document.

    Renders a header summary + a table-of-contents anchor list +
    per-action sections with description, dispatcher, capability,
    claiming adapter(s), required scopes, and emitting engines.

    Deterministic ordering (entries already alphabetised by
    action_type from the builder) so the rendered doc is
    stable across runs -- a snapshot of the catalog can be
    committed and diffed.
    """
    print("# ShopAI Action Catalog")
    print()
    print(
        f"_{len(report.entries)} dispatcher(s) registered, "
        f"{len(entries)} shown after filters._"
    )
    if report.unknown_dispatchers:
        print()
        print(
            f"_{len(report.unknown_dispatchers)} dispatcher(s) "
            "could not be AST-resolved._"
        )
    print()
    print("## Index")
    print()
    for e in entries:
        # GitHub auto-slug: lowercase + non-alphanumerics -> '-'
        slug = e.action_type.lower().replace("_", "-")
        print(f"- [`{e.action_type}`](#{slug})")
    print()

    for e in entries:
        print(f"## `{e.action_type}`")
        print()
        if e.description:
            print(e.description)
            print()
        print(
            f"- **Dispatcher**: `{e.dispatcher_module}."
            f"{e.dispatcher_qualname}`"
        )
        caps = ", ".join(f"`{c}`" for c in e.capabilities) or "_(unresolved)_"
        print(f"- **Capability**: {caps}")
        if e.adapters:
            for a in e.adapters:
                scope_md = (
                    ", ".join(f"`{s}`" for s in a.required_scopes)
                    if a.required_scopes
                    else (
                        "_(scope-independent)_"
                        if a.scope_independent
                        else "_(no scopes declared)_"
                    )
                )
                print(
                    f"- **Adapter**: `{a.name}` "
                    f"(scopes: {scope_md})"
                )
        else:
            print(
                "- **Adapter**: _(no adapter claims this capability)_"
            )
        engines = (
            ", ".join(f"`{en}`" for en in e.emitting_engines)
            or "_(no engine emits this action)_"
        )
        print(f"- **Emitting engines**: {engines}")
        print()


def _render_catalog_by_capability(report, entries, args) -> None:
    """Group catalog entries by capability instead of action_type.

    Answers the operator question: 'which action_types route
    through SHOPIFY_UPDATE_PRODUCT?' Useful when reviewing a
    capability's footprint or planning scope-deprecation.

    Entries that route through multiple capabilities appear
    under each (rare today; only a few dispatchers like
    branchy mints have >1).

    Honors --json for machine consumption: emits
    ``{capability_name: [entries...]}``.
    """
    # cap_name -> [entries...]
    grouped: dict[str, list] = {}
    unrouted: list = []
    for e in entries:
        if not e.capabilities:
            unrouted.append(e)
            continue
        for cap in e.capabilities:
            grouped.setdefault(cap, []).append(e)

    if getattr(args, "json", False):
        payload = {
            "summary": {
                "total_dispatchers": len(report.entries),
                "distinct_capabilities": len(grouped),
                "unrouted_count": len(unrouted),
                "filtered_count": len(entries),
            },
            "by_capability": {
                cap: [
                    {
                        "action_type": e.action_type,
                        "description": e.description,
                        "adapters": [
                            a.name for a in e.adapters
                        ],
                        "aggregate_scopes": list(
                            e.aggregate_scopes,
                        ),
                        "emitting_engines": list(e.emitting_engines),
                    }
                    for e in sorted(
                        cap_entries,
                        key=lambda x: x.action_type,
                    )
                ]
                for cap, cap_entries in sorted(grouped.items())
            },
            "unrouted": [e.action_type for e in unrouted],
        }
        print(json.dumps(payload, indent=2, default=str))
        return

    print(
        f"ShopAI action catalog by capability -- "
        f"{len(grouped)} distinct capability(ies), "
        f"{len(entries)} action(s) total."
    )
    if unrouted:
        print(
            f"  ({len(unrouted)} dispatcher(s) unresolved -- "
            "no capability extracted)"
        )
    print()

    for cap_name in sorted(grouped.keys()):
        cap_entries = sorted(
            grouped[cap_name], key=lambda x: x.action_type,
        )
        # Pull adapter + scopes from the first entry (all entries
        # under one capability share the same adapter aggregation)
        first = cap_entries[0]
        adapter_names = sorted({a.name for a in first.adapters})
        scopes = (
            ", ".join(first.aggregate_scopes)
            if first.aggregate_scopes else "(none)"
        )
        adapters_str = (
            ", ".join(adapter_names) if adapter_names
            else "(no adapter)"
        )
        print(f"  {cap_name}")
        print(f"    adapter:    {adapters_str}")
        print(f"    scopes:     {scopes}")
        print(
            f"    actions ({len(cap_entries)}):"
        )
        for e in cap_entries:
            engines = (
                ", ".join(e.emitting_engines)
                or "(no engine)"
            )
            print(
                f"      {e.action_type:<28}  emitted by: {engines}"
            )
        print()

    if unrouted:
        print("  Unresolved dispatchers (no capability):")
        for e in unrouted:
            print(f"    {e.action_type}")


def _cmd_catalog(args) -> None:
    """Complete action surface in one operator readout.

    For every registered dispatcher, surfaces:
      - action_type + dispatcher fully-qualified name
      - the Capability enum value it routes through
      - claiming adapter(s) + their declared required_scopes
      - emitting engine(s) (which engines enqueue this action_type)

    Master-level visibility — the answer to 'what can ShopAI do?'
    Pure read-only; builds on top of every registry the doctor
    surfaces use (dispatcher registry, Capability enum, adapter
    classes, engines/ AST scan).

    Filters: --engine NAME (engines emitting), --action-type T
    (exact match).
    """
    try:
        from core.approval.catalog import build_catalog
        report = build_catalog()
    except Exception as exc:  # noqa: BLE001
        logger.debug("catalog build raised: %s", exc)
        if getattr(args, "json", False):
            print(json.dumps({"error": str(exc)}, indent=2))
        else:
            print(f"Catalog unavailable: {exc}")
        return

    engine_filter = getattr(args, "engine", None)
    action_type_filter = getattr(args, "action_type", None)
    entries = report.entries
    if engine_filter:
        entries = tuple(
            e for e in entries if engine_filter in e.emitting_engines
        )
    if action_type_filter:
        entries = tuple(
            e for e in entries if e.action_type == action_type_filter
        )

    if getattr(args, "markdown", False):
        _render_catalog_markdown(report, entries)
        return

    if getattr(args, "by_capability", False):
        _render_catalog_by_capability(report, entries, args)
        return

    if getattr(args, "json", False):
        payload = {
            "summary": {
                "total_dispatchers": len(report.entries),
                "unknown_dispatchers": list(
                    report.unknown_dispatchers,
                ),
                "filtered_count": len(entries),
            },
            "entries": [
                {
                    "action_type": e.action_type,
                    "description": e.description,
                    "dispatcher": (
                        f"{e.dispatcher_module}."
                        f"{e.dispatcher_qualname}"
                    ),
                    "capabilities": list(e.capabilities),
                    "adapters": [
                        {
                            "name": a.name,
                            "module": a.module,
                            "required_scopes": list(a.required_scopes),
                            "scope_independent": a.scope_independent,
                        }
                        for a in e.adapters
                    ],
                    "aggregate_scopes": list(e.aggregate_scopes),
                    "emitting_engines": list(e.emitting_engines),
                }
                for e in entries
            ],
        }
        print(json.dumps(payload, indent=2, default=str))
        return

    print(
        f"ShopAI action catalog -- "
        f"{len(report.entries)} dispatcher(s) registered"
    )
    if report.unknown_dispatchers:
        print(
            f"  ({len(report.unknown_dispatchers)} could not be "
            "AST-resolved; dispatcher source uses an unrecognised "
            "router-call pattern)"
        )
    if engine_filter or action_type_filter:
        filter_parts = []
        if engine_filter:
            filter_parts.append(f"engine={engine_filter}")
        if action_type_filter:
            filter_parts.append(f"action_type={action_type_filter}")
        print(
            f"  filtered to {' + '.join(filter_parts)}: "
            f"{len(entries)} entry(ies)"
        )
    print()

    if not entries:
        print("No catalog entries match the filter.")
        return

    for e in entries:
        cap_str = ", ".join(e.capabilities) or "(unresolved)"
        engines_str = (
            ", ".join(e.emitting_engines) or "(no engine emits)"
        )
        print(f"  {e.action_type}")
        if e.description:
            print(f"    description: {e.description}")
        print(f"    dispatcher:  {e.dispatcher_qualname}")
        print(f"    capability:  {cap_str}")
        if e.adapters:
            for a in e.adapters:
                scope_str = (
                    ", ".join(a.required_scopes)
                    if a.required_scopes
                    else (
                        "(scope-independent)"
                        if a.scope_independent
                        else "(no scopes declared)"
                    )
                )
                print(
                    f"    adapter:     {a.name}  ({scope_str})"
                )
        else:
            print("    adapter:     (no adapter claims this capability)")
        print(f"    engines:     {engines_str}")
        print()


def _collect_learning_stats(top_n: int) -> dict[str, Any]:
    """Aggregate the three Phase 8 learning sources into one
    structured dict.

    Each section is best-effort -- a missing or broken backend
    surfaces as ``{"error": "..."}`` for that section, leaves
    the others intact.
    """
    out: dict[str, Any] = {}

    # ── MemoryIntelligence ──────────────────────────────────
    try:
        from core.memory.intelligence import MemoryIntelligence
        mi = MemoryIntelligence()
        stats = mi.get_stats()
        meta = mi.get_meta_stats()
        # Top engines by total memory count
        by_cat = stats.get("by_category", {}) or {}
        top_cats = sorted(
            by_cat.items(), key=lambda kv: kv[1], reverse=True,
        )[:top_n]
        out["memory_intelligence"] = {
            "total_memories": stats.get("total_memories", 0),
            "by_level": stats.get("by_level", {}),
            "by_type": stats.get("by_type", {}),
            "promotions": stats.get("promotions", 0),
            "failures": stats.get("failures", 0),
            "avg_score": stats.get("avg_score", 0.0),
            "top_categories": [
                {"category": k, "count": v} for k, v in top_cats
            ],
            "most_used_count": len(meta.get("most_used", [])),
            "never_used_count": meta.get("never_used_count", 0),
        }
    except Exception as exc:  # noqa: BLE001
        logger.debug("MI stats raised: %s", exc)
        out["memory_intelligence"] = {"error": str(exc)}

    # ── DataArchitecture ───────────────────────────────────
    try:
        from core.data.architecture import DataArchitecture
        da = DataArchitecture()
        da_stats = da.get_stats()
        domains = da_stats.get("domains", {}) or {}
        top_domains = sorted(
            domains.items(),
            key=lambda kv: kv[1].get("total", 0),
            reverse=True,
        )[:top_n]
        out["data_architecture"] = {
            "total_records": da_stats.get("total_records", 0),
            "actions_tracked": da_stats.get("actions_tracked", 0),
            "results_attached": da_stats.get("results_attached", 0),
            "result_rate_pct": da_stats.get("result_rate", 0),
            "top_domains": [
                {
                    "domain": k,
                    "total": v.get("total", 0),
                    "avg_score": v.get("avg_score", 0.0),
                }
                for k, v in top_domains
            ],
        }
    except Exception as exc:  # noqa: BLE001
        logger.debug("DA stats raised: %s", exc)
        out["data_architecture"] = {"error": str(exc)}

    # ── LearningLoop ───────────────────────────────────────
    try:
        from core.brain.learning_loop import LearningLoop
        ll = LearningLoop()
        ll_stats = ll.get_stats() or {}
        memory = ll_stats.get("memory", {}) or {}
        out["learning_loop"] = {
            "total_learnings": ll_stats.get("total_learnings", 0),
            "by_layer": memory.get("by_layer", {}),
            "patterns": memory.get("patterns", 0),
            "rules": memory.get("rules", 0),
            "bad_data": memory.get("bad_data", 0),
        }
    except Exception as exc:  # noqa: BLE001
        logger.debug("LL stats raised: %s", exc)
        out["learning_loop"] = {"error": str(exc)}

    return out


def _cmd_learning(args) -> None:
    """Dispatch ``shopai learning <verb>`` subcommands."""
    verb = getattr(args, "learning_action", None)
    if verb == "stats":
        _cmd_learning_stats(args)
        return
    print(
        "Usage:\n"
        "  shopai learning stats [--top N] [--json]"
    )
    sys.exit(1)


def _cmd_learning_stats(args) -> None:
    """Surface what the Phase 8 autonomous learning loop has
    recorded across MemoryIntelligence + DataArchitecture +
    LearningLoop.

    The "what has the system learned?" command. Operators see
    the OUTPUT of the loop -- previously only the INPUT side
    (writebacks) was visible.
    """
    top_n = int(getattr(args, "top", 10) or 10)
    stats = _collect_learning_stats(top_n)

    if getattr(args, "json", False):
        print(json.dumps(stats, indent=2, default=str))
        return

    print("ShopAI Phase 8 Learning Stats")
    print()
    _render_learning_mi(stats.get("memory_intelligence", {}))
    print()
    _render_learning_da(stats.get("data_architecture", {}))
    print()
    _render_learning_ll(stats.get("learning_loop", {}))


def _render_learning_mi(section: dict) -> None:
    if "error" in section:
        print(
            f"[??] Memory Intelligence -- "
            f"{section['error']}"
        )
        return
    total = section.get("total_memories", 0)
    fails = section.get("failures", 0)
    avg = section.get("avg_score", 0.0)
    promotions = section.get("promotions", 0)
    by_level = section.get("by_level", {})
    by_type = section.get("by_type", {})
    print(
        f"Memory Intelligence -- {total} memories "
        f"(avg score {avg:.2f}, {fails} failures, "
        f"{promotions} promotions)"
    )
    if by_level:
        levels = ", ".join(
            f"{k}={v}" for k, v in sorted(by_level.items())
        )
        print(f"  by_level:  {levels}")
    if by_type:
        types = ", ".join(
            f"{k}={v}" for k, v in sorted(by_type.items())
        )
        print(f"  by_type:   {types}")
    cats = section.get("top_categories", [])
    if cats:
        print(f"  top engines by memory count:")
        for c in cats:
            print(f"    {c['category']:<28} {c['count']}")


def _render_learning_da(section: dict) -> None:
    if "error" in section:
        print(
            f"[??] Data Architecture -- "
            f"{section['error']}"
        )
        return
    total = section.get("total_records", 0)
    rate = section.get("result_rate_pct", 0)
    actions = section.get("actions_tracked", 0)
    attached = section.get("results_attached", 0)
    print(
        f"Data Architecture -- {total} records across 12 domains "
        f"({rate}% attach rate: {attached}/{actions} actions "
        "have results)"
    )
    domains = section.get("top_domains", [])
    if domains:
        print(f"  top domains:")
        for d in domains:
            print(
                f"    {d['domain']:<14} {d['total']:>6}  "
                f"avg_score {d['avg_score']:.2f}"
            )


def _render_learning_ll(section: dict) -> None:
    if "error" in section:
        print(
            f"[??] Learning Loop -- "
            f"{section['error']}"
        )
        return
    learnings = section.get("total_learnings", 0)
    patterns = section.get("patterns", 0)
    rules = section.get("rules", 0)
    bad = section.get("bad_data", 0)
    by_layer = section.get("by_layer", {})
    print(
        f"Learning Loop -- {learnings} learnings, "
        f"{patterns} patterns + {rules} rules detected"
        f" ({bad} bad-data entries flagged)"
    )
    if by_layer:
        layers = ", ".join(
            f"{k}={v}" for k, v in sorted(by_layer.items())
        )
        print(f"  memory layers: {layers}")


def _diff_snapshots(
    baseline: dict[str, Any],
    current: dict[str, Any],
) -> dict[str, Any]:
    """Compute the operator-visible delta between two snapshots.

    Surfaces the seven changes operators actually care about:

      - ``overall_ok`` flipped
      - engine counts changed (total / wired / advisory /
        partial)
      - catalog entries added / removed / changed
      - per-audit ``ok`` flipped (each of pattern_k / oauth /
        pattern_y / pattern_i / pattern_j)

    Intentionally NOT a deep recursive diff: a release-to-release
    review focuses on the seven listed signals; the raw JSON is
    still available via the regular snapshot output for deep
    forensic inspection. The diff envelope's ``has_changes`` flag
    drives the CLI exit code (1 on diff, 0 on clean).
    """
    diff: dict[str, Any] = {
        "baseline_generated_at": baseline.get("generated_at"),
        "current_generated_at": current.get("generated_at"),
        "changes": {},
        "has_changes": False,
    }

    # overall_ok
    if baseline.get("overall_ok") != current.get("overall_ok"):
        diff["changes"]["overall_ok"] = {
            "baseline": baseline.get("overall_ok"),
            "current": current.get("overall_ok"),
        }
        diff["has_changes"] = True

    # engine counts
    b_counts = baseline.get("engine_counts") or {}
    c_counts = current.get("engine_counts") or {}
    count_changes: dict[str, Any] = {}
    for key in ("total", "wired", "advisory", "partial"):
        if b_counts.get(key) != c_counts.get(key):
            count_changes[key] = {
                "baseline": b_counts.get(key),
                "current": c_counts.get(key),
            }
    if count_changes:
        diff["changes"]["engine_counts"] = count_changes
        diff["has_changes"] = True

    # catalog entries (compare by action_type key)
    b_entries = {
        e["action_type"]: e
        for e in (baseline.get("catalog") or {}).get("entries", [])
    }
    c_entries = {
        e["action_type"]: e
        for e in (current.get("catalog") or {}).get("entries", [])
    }
    added = sorted(set(c_entries) - set(b_entries))
    removed = sorted(set(b_entries) - set(c_entries))
    changed: list[dict[str, Any]] = []
    for action_type in sorted(set(b_entries) & set(c_entries)):
        b = b_entries[action_type]
        c = c_entries[action_type]
        # Compare the fields that matter for operator review:
        # capability, adapter list, scopes, emitting engines.
        # Ignore dispatcher qualname changes (refactors).
        per_change: dict[str, Any] = {}
        for field in (
            "capabilities",
            "aggregate_scopes",
            "emitting_engines",
        ):
            if list(b.get(field, [])) != list(c.get(field, [])):
                per_change[field] = {
                    "baseline": b.get(field),
                    "current": c.get(field),
                }
        b_adapters = sorted(
            (a.get("name", "") for a in b.get("adapters", [])),
        )
        c_adapters = sorted(
            (a.get("name", "") for a in c.get("adapters", [])),
        )
        if b_adapters != c_adapters:
            per_change["adapters"] = {
                "baseline": b_adapters,
                "current": c_adapters,
            }
        if per_change:
            changed.append({
                "action_type": action_type,
                "changes": per_change,
            })
    if added or removed or changed:
        diff["changes"]["catalog"] = {
            "added": added,
            "removed": removed,
            "changed": changed,
        }
        diff["has_changes"] = True

    # audits (each ok flag)
    b_audits = baseline.get("audits") or {}
    c_audits = current.get("audits") or {}
    audit_flips: dict[str, Any] = {}
    for name in sorted(set(b_audits) | set(c_audits)):
        b_ok = (b_audits.get(name) or {}).get("ok")
        c_ok = (c_audits.get(name) or {}).get("ok")
        if b_ok != c_ok:
            audit_flips[name] = {
                "baseline": b_ok,
                "current": c_ok,
            }
    if audit_flips:
        diff["changes"]["audits"] = audit_flips
        diff["has_changes"] = True

    return diff


def _cmd_snapshot(args) -> None:
    """Capture the complete system state in one committable JSON
    artifact.

    The snapshot bundles every existing audit, doctor, and
    catalog into a single deterministic dict suitable for git
    archival. Operators commit the snapshot when they release
    and diff future captures against it to surface drift.

    Fields:
      - ``generated_at``: ISO 8601 UTC timestamp
      - ``engine_counts``: total / wired / advisory / partial
      - ``catalog``: full action surface (dispatcher -> capability
        -> adapter -> scopes -> engines)
      - ``audits``: pattern_k / oauth / pattern_y / pattern_i /
        pattern_j summaries
      - ``doctor_shopify``: doctor section dict (without live
        drift if --skip-live)
      - ``doctor_approvals``: approval-queue doctor sections

    With ``--output FILE`` the snapshot is written to disk;
    otherwise it's emitted to stdout. ``--force`` overwrites
    existing files (matches the shopify-app-toml --force
    semantics).
    """
    import time as _time
    from datetime import datetime, timezone

    snapshot: dict[str, Any] = {
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "schema_version": 1,
    }

    # ── Engine counts (Phase 6/7 writeback wiring) ──────────
    try:
        from engines._writeback_audit import audit_writeback_coverage
        wb = audit_writeback_coverage("engines")
        snapshot["engine_counts"] = {
            "total": wb.total_engines,
            "wired": wb.wired_count,
            "advisory": wb.advisory_count,
            "partial": wb.partial_count,
        }
    except Exception as exc:  # noqa: BLE001
        logger.debug("engine count audit raised: %s", exc)
        snapshot["engine_counts"] = {"error": str(exc)}

    # ── Catalog ─────────────────────────────────────────────
    try:
        from core.approval.catalog import build_catalog
        catalog = build_catalog()
        snapshot["catalog"] = {
            "total_dispatchers": len(catalog.entries),
            "unknown_dispatchers": list(catalog.unknown_dispatchers),
            "entries": [
                {
                    "action_type": e.action_type,
                    "dispatcher": (
                        f"{e.dispatcher_module}."
                        f"{e.dispatcher_qualname}"
                    ),
                    "capabilities": list(e.capabilities),
                    "adapters": [
                        {
                            "name": a.name,
                            "required_scopes": list(a.required_scopes),
                            "scope_independent": a.scope_independent,
                        }
                        for a in e.adapters
                    ],
                    "aggregate_scopes": list(e.aggregate_scopes),
                    "emitting_engines": list(e.emitting_engines),
                }
                for e in catalog.entries
            ],
        }
    except Exception as exc:  # noqa: BLE001
        logger.debug("catalog raised: %s", exc)
        snapshot["catalog"] = {"error": str(exc)}

    # ── Audits summary ──────────────────────────────────────
    audits: dict[str, Any] = {}
    # Pattern K
    try:
        from core.approval.coverage_audit import audit_coverage
        from pathlib import Path as _P
        r = audit_coverage(_P("engines"))
        audits["pattern_k"] = {
            "ok": not r.has_gaps,
            "enqueue_sites": len(r.enqueued),
            "dispatchers_registered": len(r.registered),
            "missing": sorted(r.missing),
            "orphaned": sorted(r.orphaned),
        }
    except Exception as exc:  # noqa: BLE001
        audits["pattern_k"] = {"error": str(exc)}
    # OAuth scope coverage
    try:
        from core.adapters.shopify.scope_registry import collect_manifest
        m = collect_manifest()
        audits["oauth_scopes"] = {
            "ok": not m.undeclared_adapters,
            "total_adapters": m.total_adapters,
            "undeclared_adapters": m.undeclared_adapters,
            "scope_independent": list(
                m.scope_independent_adapters,
            ),
            "unique_scopes": sorted(m.all_scopes),
        }
    except Exception as exc:  # noqa: BLE001
        audits["oauth_scopes"] = {"error": str(exc)}
    # Pattern Y
    try:
        from core.adapters.coverage_audit import (
            audit_capability_coverage,
        )
        c = audit_capability_coverage()
        audits["pattern_y"] = {
            "ok": not c.has_gaps,
            "total_capabilities": c.total_shopify_capabilities,
            "claimed_count": c.claimed_count,
            "unclaimed": c.unclaimed,
            "orphan_claims": c.orphan_claims,
        }
    except Exception as exc:  # noqa: BLE001
        audits["pattern_y"] = {"error": str(exc)}
    # Pattern I
    try:
        from engines._engine_capability_audit import (
            audit_engine_capabilities,
        )
        i = audit_engine_capabilities()
        audits["pattern_i"] = {
            "ok": not i.has_gaps,
            "total_refs": i.total_refs,
            "distinct_capabilities": i.distinct_capabilities,
            "unknown_enum_member": [
                f"{r.capability_name} ({r.file}:{r.lineno})"
                for r in i.unknown_enum_member
            ],
            "unclaimed_by_adapter": [
                f"{r.capability_name} ({r.file}:{r.lineno})"
                for r in i.unclaimed_by_adapter
            ],
        }
    except Exception as exc:  # noqa: BLE001
        audits["pattern_i"] = {"error": str(exc)}
    # Pattern J
    try:
        from engines._pattern_j_audit import audit_pattern_j
        j = audit_pattern_j()
        audits["pattern_j"] = {
            "ok": not j.has_violations,
            "scanned_modules": j.scanned_modules,
            "recorder_sites": len(j.recorder_sites),
            "guarded_sites": len(j.guarded_sites),
            "unguarded_sites": [
                f"{s.file}:{s.lineno} {s.receiver_expr}.{s.method}()"
                for s in j.unguarded_sites
            ],
        }
    except Exception as exc:  # noqa: BLE001
        audits["pattern_j"] = {"error": str(exc)}
    snapshot["audits"] = audits

    # ── Doctor verdicts (re-use existing collectors) ───────
    try:
        shopify_ok, shopify_sections = _collect_doctor_sections(args)
        snapshot["doctor_shopify"] = {
            "ok": shopify_ok,
            "sections": shopify_sections,
        }
    except Exception as exc:  # noqa: BLE001
        snapshot["doctor_shopify"] = {"error": str(exc)}
    try:
        approvals_ok, approvals_sections = (
            _collect_approvals_doctor_sections(args)
        )
        snapshot["doctor_approvals"] = {
            "ok": approvals_ok,
            "sections": approvals_sections,
        }
    except Exception as exc:  # noqa: BLE001
        snapshot["doctor_approvals"] = {"error": str(exc)}

    snapshot["overall_ok"] = bool(
        snapshot.get("doctor_shopify", {}).get("ok", True)
        and snapshot.get("doctor_approvals", {}).get("ok", True)
    )

    # ── Diff mode: compare against a committed baseline ─────
    diff_path = getattr(args, "diff", None)
    if diff_path:
        from pathlib import Path as _DP
        baseline_path = _DP(diff_path)
        try:
            baseline = json.loads(
                baseline_path.read_text(encoding="utf-8"),
            )
        except FileNotFoundError:
            print(f"Baseline file not found: {baseline_path}")
            sys.exit(1)
        except json.JSONDecodeError as exc:
            print(f"Baseline is not valid JSON: {exc}")
            sys.exit(1)
        except OSError as exc:
            print(f"Failed to read {baseline_path}: {exc}")
            sys.exit(1)
        diff = _diff_snapshots(baseline, snapshot)
        diff_serialised = json.dumps(diff, indent=2, default=str) + "\n"
        target = getattr(args, "output", None)
        if not target:
            sys.stdout.write(diff_serialised)
        else:
            target_path = _DP(target)
            if (
                target_path.exists()
                and not getattr(args, "force", False)
            ):
                print(
                    f"Refusing to overwrite {target_path} -- "
                    "pass --force to overwrite, or pick a "
                    "different path."
                )
                sys.exit(1)
            try:
                target_path.parent.mkdir(
                    parents=True, exist_ok=True,
                )
                target_path.write_text(
                    diff_serialised, encoding="utf-8",
                )
            except OSError as exc:
                print(f"Failed to write {target_path}: {exc}")
                sys.exit(1)
            print(
                f"Wrote diff to {target_path} "
                f"({len(diff_serialised.splitlines())} lines)"
            )
        # Exit code reflects whether anything changed: 0 for
        # clean (no diff), 1 for diff present, 2 for hard errors
        # (which already exited above). Lets CI alert on drift.
        if diff.get("has_changes"):
            sys.exit(1)
        return

    serialised = json.dumps(snapshot, indent=2, default=str) + "\n"

    target = getattr(args, "output", None)
    if not target:
        sys.stdout.write(serialised)
        return

    from pathlib import Path as _P
    target_path = _P(target)
    if target_path.exists() and not getattr(args, "force", False):
        print(
            f"Refusing to overwrite {target_path} -- pass --force "
            "to overwrite, or pick a different path."
        )
        sys.exit(1)
    try:
        target_path.parent.mkdir(parents=True, exist_ok=True)
        target_path.write_text(serialised, encoding="utf-8")
    except OSError as exc:
        print(f"Failed to write {target_path}: {exc}")
        sys.exit(1)
    print(
        f"Wrote {target_path} "
        f"({len(serialised.splitlines())} lines)"
    )


def _cmd_engine_info(engine_name: str, as_json: bool = False) -> None:
    from engines.registry import get_engine
    try:
        engine = get_engine(engine_name)
    except KeyError:
        if as_json:
            print(json.dumps({
                "error": f"Unknown engine: {engine_name}"
            }))
        else:
            print(f"Unknown engine: {engine_name}")
        sys.exit(1)
    if engine is None:
        if as_json:
            print(json.dumps({
                "error": f"Unknown engine: {engine_name}"
            }))
        else:
            print(f"Unknown engine: {engine_name}")
        sys.exit(1)

    name = getattr(
        engine, "ENGINE_NAME",
        getattr(engine, "engine_name", engine_name),
    )
    payload = {
        "name": name,
        "class": engine.__class__.__name__,
        "inputs": getattr(engine, "required_input_fields", []),
        "outputs": getattr(engine, "required_output_fields", []),
    }

    # ── Writeback status (Phase 6/7 wiring) ──────────────────
    try:
        from engines._writeback_audit import audit_writeback_coverage
        wb_report = audit_writeback_coverage("engines")
        engine_wb = next(
            (s for s in wb_report.engines if s.name == engine_name),
            None,
        )
        if engine_wb is not None:
            payload["writeback"] = {
                "status": engine_wb.status,
                "writer_files": engine_wb.writer_files,
                "opt_in_flags": engine_wb.opt_in_flags,
            }
    except Exception as exc:  # noqa: BLE001
        logger.debug("writeback audit raised: %s", exc)

    # ── Action chain (from catalog) ──────────────────────────
    try:
        from core.approval.catalog import build_catalog
        catalog = build_catalog()
        emitted = [
            e for e in catalog.entries
            if engine_name in e.emitting_engines
        ]
        if emitted:
            payload["actions"] = [
                {
                    "action_type": e.action_type,
                    "capability": (
                        list(e.capabilities)[0]
                        if e.capabilities else None
                    ),
                    "adapter": (
                        e.adapters[0].name if e.adapters else None
                    ),
                    "scopes": list(e.aggregate_scopes),
                }
                for e in emitted
            ]
    except Exception as exc:  # noqa: BLE001
        logger.debug("catalog lookup raised: %s", exc)

    if as_json:
        print(json.dumps(payload, indent=2, default=str))
        return

    print(f"Engine: {payload['name']}")
    print(f"Class:  {payload['class']}")
    if payload["inputs"]:
        print(f"Inputs: {payload['inputs']}")
    if payload["outputs"]:
        print(f"Outputs: {payload['outputs']}")

    # Writeback wiring section
    wb = payload.get("writeback")
    if wb is not None:
        print()
        print(f"Writeback:  {wb['status']}")
        if wb["writer_files"]:
            print(f"  writers:  {', '.join(wb['writer_files'])}")
        if wb["opt_in_flags"]:
            print(f"  flags:    {', '.join(wb['opt_in_flags'])}")

    # Action chain section
    actions = payload.get("actions")
    if actions:
        print()
        print(f"Actions emitted ({len(actions)}):")
        for a in actions:
            cap = a.get("capability") or "(unresolved)"
            adapter = a.get("adapter") or "(no adapter)"
            scopes = (
                ", ".join(a["scopes"]) if a["scopes"]
                else "(none)"
            )
            print(f"  {a['action_type']}")
            print(f"    capability:  {cap}")
            print(f"    adapter:     {adapter}")
            print(f"    scopes:      {scopes}")

    _print_engine_brain_stack(engine_name)
    # Drill-down hint: engine-info shows config + brain-stack;
    # engine summary shows the operational view (queue counts,
    # recent activity, outcomes). Complementary surfaces.
    print()
    print(
        f"  Drill down: `shopai engine summary {engine_name}`"
    )


def _cmd_shopify_scopes(args) -> None:
    """Render the aggregated Shopify OAuth scope manifest.

    Answers "which OAuth scopes does this app need at install
    time?" without reading every adapter file's docstring.

    Three modes:
      - default: union list of every scope any adapter needs
        (operator-friendly install manifest)
      - ``--per-adapter``: grouped breakdown showing exactly
        which adapter pulls in which scope (useful for shrinking
        the install footprint by removing adapters)
      - ``--show-gaps``: lists adapters that haven't declared
        ``required_scopes`` yet (rollout tracking — the wireup
        is incremental and the gap report drives follow-up PRs)

    Over-requesting scopes makes merchants nervous and Shopify's
    review team flag it; under-requesting causes the adapter to
    fail with ACCESS_DENIED at first live call. This surface
    keeps the manifest correct as adapters change.
    """
    try:
        from core.adapters.shopify.scope_registry import collect_manifest
        manifest = collect_manifest()
    except Exception as exc:  # noqa: BLE001
        logger.debug("scope manifest collection raised: %s", exc)
        if getattr(args, "json", False):
            print(json.dumps({"error": str(exc)}, indent=2))
        else:
            print("Scope manifest unavailable")
        return

    if getattr(args, "json", False):
        payload = {
            "all_scopes": sorted(manifest.all_scopes),
            "by_scope": manifest.by_scope,
            "by_adapter": manifest.by_adapter,
            "undeclared_adapters": (
                manifest.undeclared_adapters
                if getattr(args, "show_gaps", False) else None
            ),
            "scope_independent_adapters": (
                manifest.scope_independent_adapters
            ),
            "total_adapters": manifest.total_adapters,
            "declared_adapter_count": (
                manifest.total_adapters
                - len(manifest.undeclared_adapters)
            ),
        }
        print(json.dumps(payload, indent=2, default=str))
        return

    declared_count = (
        manifest.total_adapters
        - len(manifest.undeclared_adapters)
    )
    independent_count = len(manifest.scope_independent_adapters)
    print(
        f"Shopify OAuth scope manifest "
        f"({declared_count}/{manifest.total_adapters} adapters "
        f"declared; {independent_count} scope-independent):"
    )
    print()

    if getattr(args, "per_adapter", False):
        # Grouped: adapter → its scopes
        declared = [
            (a, scopes)
            for a, scopes in manifest.by_adapter.items()
            if scopes
        ]
        declared.sort(key=lambda kv: kv[0])
        for adapter, scopes in declared:
            print(f"  {adapter}:")
            for s in scopes:
                print(f"    {s}")
    else:
        # Default: flat union, install-manifest-ready
        if not manifest.all_scopes:
            print("  (no scopes declared yet)")
        else:
            for s in sorted(manifest.all_scopes):
                # Show how many adapters pull this scope — helps
                # operators decide whether removing one adapter
                # could shrink the manifest.
                adapter_count = len(manifest.by_scope.get(s, []))
                print(f"  {s:<48} (used by {adapter_count})")

    if getattr(args, "show_gaps", False):
        gaps = manifest.undeclared_adapters
        print()
        print(
            f"Adapters without declared scopes ({len(gaps)}) — "
            "rollout gaps:"
        )
        if not gaps:
            print("  (none)")
        else:
            for a in gaps[:40]:
                print(f"  {a}")
            if len(gaps) > 40:
                print(f"  ... and {len(gaps) - 40} more")


def _cmd_shopify_scopes_audit(args) -> None:
    """CI gate: exit 1 if any Shopify adapter is missing a scope
    declaration.

    The companion to ``shopai approvals audit`` (PR #157 — the
    Pattern K dispatcher coverage gate). Every concrete Shopify
    adapter must declare one of:

      - ``required_scopes = frozenset({...})`` — the OAuth scopes
        it needs at install time
      - ``scope_independent = True`` — sentinel for app-level
        features (app billing, mobile platform) or context-
        dependent surfaces (bulk, generic_tags, shop) that
        legitimately need no extra OAuth scope

    Exit 0 = clean. Exit 1 = at least one adapter has neither
    set, which would silently become a "scope unknown" install
    risk. The audit prints the gap list so the failing CI run's
    output is actionable — operators can wire the missing
    declarations directly from the error message.
    """
    try:
        from core.adapters.shopify.scope_registry import collect_manifest
        manifest = collect_manifest()
    except Exception as exc:  # noqa: BLE001
        logger.debug("scope manifest collection raised: %s", exc)
        # Surface the failure but don't exit 1 — a broken
        # registry import is a different bug class from a
        # missing scope declaration. The test suite catches
        # the registry-broken case directly.
        if getattr(args, "json", False):
            print(json.dumps({"error": str(exc)}, indent=2))
        else:
            print(f"Scope audit unavailable: {exc}")
        return

    gaps = list(manifest.undeclared_adapters)
    if getattr(args, "json", False):
        print(json.dumps({
            "ok": not gaps,
            "undeclared_count": len(gaps),
            "undeclared_adapters": gaps,
            "total_adapters": manifest.total_adapters,
        }, indent=2))
        if gaps:
            sys.exit(1)
        return

    if not gaps:
        independent = len(manifest.scope_independent_adapters)
        print(
            f"Scope coverage OK — "
            f"{manifest.total_adapters}/{manifest.total_adapters} "
            f"adapters declared "
            f"({independent} scope-independent)."
        )
        return

    print(
        f"Scope coverage FAILED: {len(gaps)} adapter(s) missing "
        "scope declaration."
    )
    print()
    print("Undeclared adapters:")
    for a in gaps:
        print(f"  {a}")
    print()
    print(
        "Fix: add ``required_scopes = frozenset({\"...\"})`` "
        "(or ``scope_independent = True`` for app-level "
        "adapters) to each class. See PR #173 / #176 for "
        "examples."
    )
    sys.exit(1)


def _cmd_plan_auto_correlate(args) -> None:
    """Batch outcome correlation. Walks plan_history for
    events:
      - older than ``--auto-correlate-min-age`` (default 24h)
      - executed=True
      - outcome still ``executed_ok`` (or empty -- not yet
        correlated)
      - pre_stats populated (otherwise we can't correlate)

    For each, fetches the store's current stats + runs the
    same correlation logic as ``--correlate <id>``, updating
    the event's outcome in place.

    Cron-friendly: operators (or systemd timer) can run
    ``shopai plan --auto-correlate`` nightly and the
    learning loop self-updates without per-event work.
    """
    as_json = bool(getattr(args, "json", False))
    min_age = max(
        0, int(
            getattr(args, "auto_correlate_min_age", 86400)
            or 86400,
        ),
    )

    try:
        from core.capability_planner import (
            correlate_outcome_by_stats,
            recent_history,
        )
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "auto-correlate: import failed: %s", exc,
        )
        if as_json:
            print(json.dumps({
                "ok": False,
                "error": "correlate_unavailable",
                "message": str(exc),
            }, indent=2))
        else:
            print(f"auto-correlate unavailable: {exc}")
        return

    sm = _get_store_manager()
    # Wide look-back -- we want anything in the last 90
    # days that hasn't been correlated yet.
    events = recent_history(since_seconds=86400 * 90)
    now = time.time()

    # Filter to events that ARE candidates.
    OUTCOME_NOT_YET_CORRELATED = {
        "", "executed_ok",
    }
    candidates = []
    for e in events:
        ts = float(e.get("timestamp", 0) or 0)
        if (now - ts) < min_age:
            continue
        if not e.get("executed"):
            continue
        outcome = str(e.get("outcome") or "")
        if outcome not in OUTCOME_NOT_YET_CORRELATED:
            continue
        if not (e.get("pre_stats") or {}):
            continue
        candidates.append(e)

    # Cache per-store stats so we don't re-fetch for every
    # event on the same store.
    stats_cache: dict[str, dict[str, Any]] = {}
    results: list[dict[str, Any]] = []
    for e in candidates:
        sid = e.get("store_id", "") or ""
        if sid not in stats_cache:
            try:
                stats_cache[sid] = (
                    sm.get_stats(sid) or {}
                )
            except Exception as exc:  # noqa: BLE001
                logger.debug(
                    "auto-correlate: get_stats raised "
                    "for %s: %s", sid, exc,
                )
                stats_cache[sid] = {}
        cur = stats_cache[sid]
        result = correlate_outcome_by_stats(
            e.get("event_id", ""), cur,
        )
        results.append({
            "event_id": e.get("event_id", ""),
            "store_id": sid,
            "goal": e.get("goal", ""),
            "outcome": result.get("outcome"),
            "ok": result.get("ok", False),
            "revenue_delta_pct": result.get(
                "revenue_delta_pct"
            ),
            "error": result.get("error"),
        })

    summary = {
        "candidates": len(candidates),
        "correlated": sum(
            1 for r in results if r.get("ok")
        ),
        "skipped_no_pre_stats": sum(
            1 for r in results
            if r.get("error") == "no_pre_stats_baseline"
        ),
        "by_outcome": {},
    }
    for r in results:
        if not r.get("ok"):
            continue
        oc = str(r.get("outcome") or "")
        summary["by_outcome"][oc] = (
            summary["by_outcome"].get(oc, 0) + 1
        )

    if as_json:
        print(json.dumps({
            "summary": summary,
            "results": results,
            "min_age_seconds": min_age,
        }, indent=2, default=str))
        return

    if not candidates:
        print(
            f"Auto-correlate: no candidates "
            f"(events older than "
            f"{min_age // 3600}h + executed + "
            f"un-correlated + with pre_stats)."
        )
        return

    print(
        f"Auto-correlate: {summary['correlated']} "
        f"of {summary['candidates']} candidate event(s) "
        f"correlated."
    )
    for k, v in summary["by_outcome"].items():
        print(f"  {k}: {v}")
    if summary["skipped_no_pre_stats"]:
        print(
            f"  skipped (no pre_stats): "
            f"{summary['skipped_no_pre_stats']}"
        )


def _cmd_plan_correlate(args, event_id: str) -> None:
    """Outcome correlation v2. Look up a past plan event,
    fetch the store's current stats, compute the delta vs
    the pre-execution snapshot, and persist the result
    back to plan_history.
    """
    as_json = bool(getattr(args, "json", False))
    try:
        from core.capability_planner import (
            correlate_outcome_by_stats,
            recent_history,
        )
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "plan --correlate: import failed: %s", exc,
        )
        if as_json:
            print(json.dumps({
                "ok": False,
                "error": "correlate_unavailable",
                "message": str(exc),
            }, indent=2))
        else:
            print(f"correlate unavailable: {exc}")
        return

    # Find the event so we can resolve its store_id +
    # fetch current stats. Look back generously (90 days)
    # so older events aren't excluded.
    events = recent_history(since_seconds=86400 * 90)
    event = None
    for e in events:
        if e.get("event_id") == event_id:
            event = e
            break
    if event is None:
        if as_json:
            print(json.dumps({
                "ok": False,
                "error": "event_not_found",
                "event_id": event_id,
            }, indent=2))
        else:
            print(f"Plan event not found: {event_id}")
        sys.exit(1)

    target_store = event.get("store_id", "")
    sm = _get_store_manager()
    if not target_store:
        target_store = sm.active_store_id or ""

    try:
        current_stats = sm.get_stats(target_store) or {}
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "plan --correlate: get_stats raised: %s", exc,
        )
        current_stats = {}

    result = correlate_outcome_by_stats(
        event_id, current_stats,
    )

    if as_json:
        print(json.dumps({
            "event_id": event_id,
            "store_id": target_store,
            "current_stats": current_stats,
            "result": result,
        }, indent=2, default=str))
        if not result.get("ok"):
            sys.exit(1)
        return

    if not result.get("ok"):
        err = result.get("error", "unknown")
        if err == "no_pre_stats_baseline":
            print(
                f"Cannot correlate {event_id}: no pre-"
                f"execution stats snapshot was captured. "
                f"Pre-stats are recorded automatically by "
                f"``shopai plan --execute --yes`` runs "
                f"made after this feature was added."
            )
        else:
            print(f"Correlation failed: {err}")
        sys.exit(1)

    print(
        f"Plan {event_id} ({target_store}): "
        f"{result['outcome']}"
    )
    print(f"  {result['notes']}")
    print(
        f"  revenue Δ: ${result['revenue_delta']:,.2f} "
        f"({result['revenue_delta_pct']:+.1f}%)"
    )
    print(f"  orders Δ:  {result['orders_delta']:+.0f}")
    print(
        f"  products Δ: {result['products_delta']:+.0f}"
    )


def _cmd_plan_recommend(args) -> None:
    """Cross-store recommendation surface. Lists plans that
    SUCCEEDED elsewhere in the fleet, ranked by frequency +
    recency. The empire-AGI primitive: when launching a new
    store, find what's worked on other stores.
    """
    as_json = bool(getattr(args, "json", False))
    window = max(0, int(
        getattr(args, "recommend_window", 86400 * 30) or
        86400 * 30,
    ))
    top_n = max(1, int(
        getattr(args, "recommend_top", 10) or 10,
    ))
    # Resolve the store_id to EXCLUDE -- so recommendations
    # come from peer stores, not the operator's current one.
    sm = _get_store_manager()
    exclude_sid = (
        getattr(args, "store", None)
        or sm.active_store_id
        or ""
    )

    try:
        from core.capability_planner import successful_plans
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "plan recommend: import failed: %s", exc,
        )
        if as_json:
            print(json.dumps({
                "ok": False,
                "error": "planner_unavailable",
                "message": str(exc),
            }, indent=2))
        else:
            print(f"plan recommend unavailable: {exc}")
        return

    rows = successful_plans(
        since_seconds=window,
        exclude_store_id=exclude_sid,
        top_n=top_n,
    )

    if as_json:
        print(json.dumps({
            "exclude_store": exclude_sid,
            "window_seconds": window,
            "recommendations": rows,
        }, indent=2, default=str))
        return

    if not rows:
        print(
            f"No successful peer-store plans in the last "
            f"{window // 86400} day(s). Run "
            f"``shopai plan --execute --yes`` on other "
            f"stores to populate the history."
        )
        return

    print(
        f"Cross-store plan recommendations "
        f"({len(rows)} found in last "
        f"{window // 86400} day(s)):"
    )
    if exclude_sid:
        print(f"  Excluding own store: {exclude_sid}")
    print()
    for i, r in enumerate(rows, start=1):
        n_stores = len(r["stores"])
        print(
            f"  {i}. {r['goal']!r} -- "
            f"succeeded {r['success_count']}x across "
            f"{n_stores} store(s)"
        )
        print(
            f"     Capabilities: "
            f"{', '.join(r['capabilities'])}"
        )
        if r["cli_sequence"]:
            for c in r["cli_sequence"][:3]:
                print(f"     $ {c}")
    print()
    print(
        "To apply one of these to the current store, run "
        "``shopai plan \"<goal>\" --execute --yes``."
    )


def _cmd_plan_history(args) -> None:
    """Print recent plan invocations from
    ``data/plan_history.json``. Newest-first within the
    --history-window window (default 7 days)."""
    as_json = bool(getattr(args, "json", False))
    window = max(
        0,
        int(getattr(args, "history_window", 86400 * 7) or
            86400 * 7),
    )
    try:
        from core.capability_planner import (
            goal_breakdown,
            outcome_breakdown,
            recent_history,
        )
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "plan history: import failed: %s", exc,
        )
        if as_json:
            print(json.dumps({
                "ok": False,
                "error": "plan_history_unavailable",
                "message": str(exc),
            }, indent=2))
        else:
            print(f"plan history unavailable: {exc}")
        return

    events = recent_history(since_seconds=window)
    breakdown = outcome_breakdown(since_seconds=window)
    by_goal = goal_breakdown(since_seconds=window, top_n=5)

    if as_json:
        print(json.dumps({
            "events": events,
            "outcome_breakdown": breakdown,
            "top_goals": by_goal,
        }, indent=2, default=str))
        return

    if not events:
        print(
            f"No plan invocations in the last "
            f"{window // 86400} day(s). Try "
            f"--history-window <seconds> for a wider lens."
        )
        return
    print(
        f"Plan history -- {len(events)} invocation(s) "
        f"(last {window // 86400} day(s)):"
    )
    print()
    import time as _t
    # Show only the 20 most-recent events in the text view;
    # the JSON --json path carries everything.
    for e in events[:20]:
        ts = float(e.get("timestamp", 0) or 0)
        age_h = max(0, int((_t.time() - ts) / 3600))
        outcome = e.get("outcome") or "(no outcome)"
        executed = "yes" if e.get("executed") else "no"
        sid = e.get("store_id") or "-"
        goal = e.get("goal") or "-"
        print(
            f"  [{age_h:>3}h] [{outcome:>12}] "
            f"executed={executed:<3} store={sid:<16} "
            f"goal={goal}"
        )
        notes = e.get("notes")
        if notes:
            print(f"          notes: {notes}")
    if len(events) > 20:
        print(f"  ... +{len(events) - 20} more")

    # Aggregate footer
    print()
    print(
        f"Outcomes ({breakdown['executed_total']} "
        f"executed): "
        + ", ".join(
            f"{k}={v}"
            for k, v in breakdown["by_outcome"].items()
        )
    )
    if breakdown["executed_total"] > 0:
        pct = breakdown["success_rate"] * 100
        print(f"Success rate: {pct:.1f}%")
    if by_goal:
        print()
        print("Top goals (by frequency):")
        for r in by_goal:
            rate_pct = r["success_rate"] * 100
            print(
                f"  {r['count']:>3}x  "
                f"({rate_pct:>5.1f}% success)  "
                f"{r['goal']}"
            )


def _cmd_plan_template(args) -> None:
    """Manage named plan templates -- save/run/list/show/delete.

    Plan templates are operator shortcuts for repeated
    goal strings. Saved goals can be invoked by name
    (``run <name>``); the inner action goes through the
    same ``_cmd_plan`` path so all of the planner's
    composition, history, and learning loop behavior
    applies."""
    action = getattr(args, "plan_template_action", "") or ""
    as_json = bool(getattr(args, "json", False))

    try:
        from core.capability_planner import (
            plan_templates as _pt,
        )
    except Exception as exc:  # noqa: BLE001
        print(f"plan-template unavailable: {exc}")
        return

    if not action or action == "list":
        rows = _pt.list_templates()
        if as_json:
            print(json.dumps([
                {
                    "name": t.name,
                    "goal": t.goal,
                    "description": t.description,
                    "created_at": t.created_at,
                }
                for t in rows
            ], indent=2, default=str))
            return
        if not rows:
            print(
                "No plan templates saved. Use "
                "``shopai plan-template save <name> "
                "\"<goal>\"`` to add one."
            )
            return
        print(f"Plan templates ({len(rows)}):")
        for t in rows:
            print(f"  {t.name}")
            print(f"    goal: {t.goal}")
            if t.description:
                print(
                    f"    desc: {t.description}"
                )
        return

    if action == "save":
        name = getattr(args, "name", "") or ""
        goal = getattr(args, "goal", "") or ""
        desc = getattr(args, "description", "") or ""
        if not name or not goal:
            print("name and goal are required.")
            sys.exit(1)
            return
        ok = _pt.save_template(
            name, goal, description=desc,
        )
        if as_json:
            print(json.dumps({
                "ok": ok,
                "name": name,
                "goal": goal,
            }, indent=2))
            return
        if ok:
            print(f"Saved template '{name}'.")
        else:
            print(
                f"Failed to save '{name}' "
                "(test env, cap, or I/O)."
            )
        return

    if action == "delete":
        name = getattr(args, "name", "") or ""
        if not name:
            print("name is required.")
            sys.exit(1)
            return
        ok = _pt.delete_template(name)
        if as_json:
            print(json.dumps({
                "ok": ok, "name": name,
            }, indent=2))
            return
        if ok:
            print(f"Deleted template '{name}'.")
        else:
            print(
                f"No template '{name}' to delete "
                "(or test env)."
            )
        return

    if action == "show":
        name = getattr(args, "name", "") or ""
        t = _pt.load_template(name)
        if t is None:
            if as_json:
                print(json.dumps({
                    "ok": False,
                    "error": "not_found",
                    "name": name,
                }, indent=2))
            else:
                print(f"No template named '{name}'.")
            sys.exit(1)
            return
        if as_json:
            print(json.dumps({
                "name": t.name,
                "goal": t.goal,
                "description": t.description,
                "created_at": t.created_at,
            }, indent=2, default=str))
            return
        print(f"Template: {t.name}")
        print(f"  goal:        {t.goal}")
        if t.description:
            print(f"  description: {t.description}")
        if t.created_at:
            import datetime as _dt
            stamp = _dt.datetime.fromtimestamp(
                t.created_at,
            ).strftime("%Y-%m-%d %H:%M")
            print(f"  created:     {stamp}")
        return

    if action == "run":
        name = getattr(args, "name", "") or ""
        t = _pt.load_template(name)
        if t is None:
            print(f"No template named '{name}'.")
            sys.exit(1)
            return
        # Inflate to a plan call by constructing the inner
        # Namespace that ``_cmd_plan`` expects.
        import argparse as _ap
        inner = _ap.Namespace(
            goal=t.goal,
            execute=bool(getattr(args, "execute", False)),
            yes=bool(getattr(args, "yes", False)),
            json=as_json,
            close_audit_gaps=False,
            history=False,
            history_window=86400 * 7,
            correlate=None,
            auto_correlate=False,
            auto_correlate_min_age=86400,
            require_reliable=False,
            llm=False,
        )
        return _cmd_plan(inner)

    print(
        f"Unknown plan-template action: {action}. "
        "Try save/run/list/show/delete."
    )


def _cmd_plan(args) -> None:
    """Build a capability plan for a goal phrase or for the
    audit's failing checks.

    Two modes:
      - ``shopai plan "<goal>"`` -- free-form phrase ->
        substring-matched + composition-walked plan.
      - ``shopai plan --close-audit-gaps`` -- runs the audit
        first, then plans against the failing keys.

    Output is the same Plan dataclass either way (text +
    JSON). Future LLM-driven planner swaps in behind the
    same call shape.
    """
    as_json = bool(getattr(args, "json", False))
    close_gaps = bool(getattr(args, "close_audit_gaps", False))
    goal = (getattr(args, "goal", "") or "").strip()

    # ── --history mode: show recent plan invocations ────
    if bool(getattr(args, "history", False)):
        _cmd_plan_history(args)
        return

    # ── --recommend mode: cross-store learning surface ──
    if bool(getattr(args, "recommend", False)):
        _cmd_plan_recommend(args)
        return

    # ── --correlate <event_id>: outcome v2 ──────────────
    correlate_id = getattr(args, "correlate", None)
    if correlate_id:
        _cmd_plan_correlate(args, correlate_id)
        return

    # ── --auto-correlate: batch correlation -------------
    if bool(getattr(args, "auto_correlate", False)):
        _cmd_plan_auto_correlate(args)
        return

    try:
        from core.capability_planner import (
            plan_for_audit_gaps,
            plan_for_goal,
        )
    except Exception as exc:  # noqa: BLE001
        logger.debug("capability_planner import failed: %s", exc)
        print(f"plan unavailable: {exc}")
        return

    # Pre-execution audit snapshot when --close-audit-gaps
    # mode is on. Saved so the post-execution outcome
    # correlation can compare which gaps closed.
    pre_audit_failing: set[str] = set()
    if close_gaps:
        sm = _get_store_manager()
        store_id = (
            getattr(args, "store", None)
            or sm.active_store_id
        )
        try:
            from engines.store_setup.launch_audit import (
                audit_store,
            )
            audit = audit_store(store_id=store_id)
        except Exception as exc:  # noqa: BLE001
            logger.debug("plan audit raised: %s", exc)
            if as_json:
                print(json.dumps({
                    "ok": False,
                    "error": "audit_unavailable",
                    "message": str(exc),
                }, indent=2))
            else:
                print(f"audit unavailable: {exc}")
            return
        failing = [
            c.get("key", "")
            for c in (audit.get("checks") or [])
            if not c.get("ok")
        ]
        pre_audit_failing = set(failing)
        plan = plan_for_audit_gaps(failing)
    else:
        if not goal:
            print(
                "Usage: shopai plan \"<goal>\"  OR  "
                "shopai plan --close-audit-gaps"
            )
            sys.exit(1)
        # LLM-driven seed selection when --llm is set; falls
        # back to deterministic when Ollama isn't reachable.
        if bool(getattr(args, "llm", False)):
            try:
                from core.capability_planner import (
                    LLMPlanner,
                )
                plan = LLMPlanner(
                    model=getattr(
                        args, "llm_model", "qwen2.5",
                    ),
                ).plan_for_goal(goal)
            except Exception as exc:  # noqa: BLE001
                logger.debug(
                    "shopai plan --llm: planner raised: %s",
                    exc,
                )
                plan = plan_for_goal(goal)
        else:
            plan = plan_for_goal(goal)

    if bool(getattr(args, "execute", False)):
        # Resolve store_id for the per-step thread-local
        # scope (so Pattern Z records carry the right
        # store_id when the executed capability records to
        # MemoryIntel + DataArch + LearningLoop).
        if not close_gaps:
            # Goal mode -- we haven't initialised store_id
            # yet because the audit path is the only branch
            # that needed it earlier.
            sm = _get_store_manager()
            store_id = (
                getattr(args, "store", None)
                or sm.active_store_id
            )
        _run_plan_multi_step(
            plan,
            yes=bool(getattr(args, "yes", False)),
            as_json=as_json,
            store_id=store_id,
            pre_audit_failing=pre_audit_failing,
            require_reliable=bool(
                getattr(args, "require_reliable", False),
            ),
        )
        return

    if as_json:
        print(json.dumps(plan.to_dict(), indent=2, default=str))
        return

    if bool(getattr(args, "as_context", False)):
        _render_plan_as_context(plan)
        return

    # ── Text view ───────────────────────────────────────────
    print(f"Plan for: {plan.goal}")
    print()
    if plan.is_empty():
        print("  (no plan -- registry returned no matches)")
        for n in plan.notes:
            print(f"  note: {n}")
        return
    print("Steps:")
    for i, s in enumerate(plan.steps, start=1):
        cli = f"  ({s.cli_command})" if s.cli_command else ""
        print(f"  {i}. [{s.role}] {s.capability_name}{cli}")
        print(f"     -> {s.description}")
        if s.closes_audits:
            print(
                f"     closes: "
                f"{', '.join(s.closes_audits)}"
            )
        # Historical success-rate signal -- only render when
        # sample size >= 3 so single-event noise doesn't
        # mislead the operator.
        if s.history_sample_size >= 3:
            rate_pct = s.history_success_rate * 100
            print(
                f"     history: {rate_pct:.0f}% success "
                f"over {s.history_sample_size} past run(s)"
            )
    print()
    if plan.cli_sequence:
        print("Run:")
        for c in plan.cli_sequence:
            print(f"  $ {c}")
        print()
    if plan.audit_coverage:
        print(
            f"Audit coverage: "
            f"{', '.join(plan.audit_coverage)}"
        )
    if plan.notes:
        print()
        print("Notes:")
        for n in plan.notes:
            print(f"  - {n}")
    # Drill-down hint: when the plan has steps, suggest the
    # one-shot --execute path. Operator's natural follow-up
    # to seeing a plan is "actually run it" -- the harness
    # walks every step with proper Pattern Z + audit
    # bookkeeping.
    if plan.steps:
        if close_gaps:
            print()
            print(
                "  Next: `shopai plan --close-audit-gaps "
                "--execute` to walk the plan."
            )
        elif goal:
            print()
            print(
                f"  Next: `shopai plan \"{goal}\" --execute` "
                "to walk the plan."
            )


def _interval_to_cron(interval: str) -> str | None:
    """Parse a human interval like ``30m`` / ``1h`` /
    ``6h`` into a crontab field expression.

    Returns the crontab spec (e.g. ``*/30 * * * *`` for 30m,
    ``0 */6 * * *`` for 6h) or None on parse failure.
    """
    s = interval.strip().lower()
    if not s:
        return None
    try:
        if s.endswith("m"):
            n = int(s[:-1])
            if n < 1 or n > 59:
                return None
            return f"*/{n} * * * *"
        if s.endswith("h"):
            n = int(s[:-1])
            if n < 1 or n > 23:
                return None
            return f"0 */{n} * * *"
    except (ValueError, TypeError):
        return None
    return None


def _emit_crontab(cron_expr: str) -> str:
    """Build a complete crontab block: cycle on the
    requested interval + daily-brief once a day + a
    weekly health check."""
    return (
        "# ShopAI autonomous-cycle cron block. Install via\n"
        "# `crontab -e` or drop into `/etc/cron.d/shopai`.\n"
        "# Adjust PATH + working directory as needed.\n"
        f"{cron_expr}  cd /path/to/shopai && "
        "shopai autonomous-cycle --yes --json "
        ">> /var/log/shopai/cycle.log 2>&1\n"
        "0 8 * * *  cd /path/to/shopai && "
        "shopai daily-brief "
        ">> /var/log/shopai/brief.log 2>&1\n"
        "0 12 * * 0  cd /path/to/shopai && "
        "shopai status "
        ">> /var/log/shopai/status.log 2>&1\n"
    )


def _emit_systemd_units(interval: str) -> str:
    """Build matching .service + .timer unit blocks.
    Returns a single string with both blocks separated by a
    --- delimiter so the operator can split them out."""
    return (
        "# shopai-cycle.service\n"
        "# Save to /etc/systemd/system/shopai-cycle.service\n"
        "[Unit]\n"
        "Description=ShopAI autonomous cycle\n"
        "\n"
        "[Service]\n"
        "Type=oneshot\n"
        "WorkingDirectory=/path/to/shopai\n"
        "ExecStart=/usr/local/bin/shopai "
        "autonomous-cycle --yes --json\n"
        "User=shopai\n"
        "\n"
        "# ---\n"
        "# shopai-cycle.timer\n"
        "# Save to /etc/systemd/system/shopai-cycle.timer\n"
        "[Unit]\n"
        "Description=Trigger ShopAI autonomous cycle "
        f"every {interval}\n"
        "\n"
        "[Timer]\n"
        f"OnUnitActiveSec={interval}\n"
        "OnBootSec=2min\n"
        "Persistent=true\n"
        "Unit=shopai-cycle.service\n"
        "\n"
        "[Install]\n"
        "WantedBy=timers.target\n"
        "\n"
        "# Enable with:\n"
        "#   systemctl enable --now shopai-cycle.timer\n"
    )


def _cmd_autonomous_cycle(args) -> None:
    """Bundled autonomous loop. Runs three phases in
    sequence:

      1. ADVANCE: fleet-plan --execute --require-reliable
         (with --yes when supplied). Tries to advance every
         store via reliability-gated plan execution.
      2. DEFEND: capabilities auto-demote-degraded (with
         --yes when supplied). Demotes severely-regressed
         capabilities so the next ADVANCE phase stops
         seeding them. Env-gated; no-op without
         SHOPAI_AUTO_DEMOTE_DEGRADED=1.
      3. MEASURE: plan --auto-correlate. Updates the
         outcome of past plans whose measurement window
         has expired.

    Cron-friendly: a single ``shopai autonomous-cycle
    --yes`` call advances + defends + measures the fleet.
    The phases are decoupled (``--skip-advance`` /
    ``--skip-defend`` / ``--skip-correlate`` flags) so
    operators can wire different schedules if needed.

    Refuses to actually write unless --yes is set --
    default is a dry-run preview that shows what would
    happen across the fleet.
    """
    as_json = bool(getattr(args, "json", False))
    yes = bool(getattr(args, "yes", False))
    skip_advance = bool(
        getattr(args, "skip_advance", False),
    )
    skip_correlate = bool(
        getattr(args, "skip_correlate", False),
    )
    skip_defend = bool(
        getattr(args, "skip_defend", False),
    )
    skip_transfer = bool(
        getattr(args, "skip_transfer", False),
    )

    # --pause / --resume / --show-pause: operator
    # controls for halting the cycle.
    if bool(getattr(args, "pause", False)):
        import time as _time
        from core.autonomous import cycle_pause as _cp
        # Don't use ``or`` fallback -- it would silently
        # convert 0.0 into the default, hiding operator
        # error.
        raw_hours = getattr(args, "pause_hours", 1.0)
        try:
            hours = float(
                raw_hours
                if raw_hours is not None else 1.0
            )
        except (TypeError, ValueError):
            print(
                f"--pause-hours must be a number: "
                f"{raw_hours!r}"
            )
            sys.exit(1)
            return
        if hours <= 0 or hours > 720:
            print(
                f"--pause-hours must be in (0, 720]: "
                f"{hours}"
            )
            sys.exit(1)
            return
        until = _time.time() + hours * 3600.0
        reason = (
            getattr(args, "pause_reason", "") or ""
        )
        ok = _cp.pause(
            until_at=until, reason=reason,
        )
        if as_json:
            print(json.dumps({
                "ok": ok,
                "paused_until_at": until,
                "hours": hours,
                "reason": reason,
            }, indent=2))
        elif ok:
            print(
                f"Cycle paused for {hours}h "
                f"(until {_time.strftime('%Y-%m-%d %H:%M', _time.localtime(until))})"
            )
        else:
            print(
                "Pause failed (test env or I/O error)."
            )
        return

    if bool(getattr(args, "extend_pause", False)):
        from core.autonomous import cycle_pause as _cp
        raw_hours = getattr(args, "pause_hours", 1.0)
        try:
            hours = float(
                raw_hours
                if raw_hours is not None else 1.0
            )
        except (TypeError, ValueError):
            print(
                f"--pause-hours must be a number: "
                f"{raw_hours!r}"
            )
            sys.exit(1)
            return
        ok = _cp.extend(additional_hours=hours)
        if as_json:
            print(json.dumps({
                "ok": ok, "extended_by_hours": hours,
            }, indent=2))
        elif ok:
            state = _cp.get_pause_state()
            import time as _time
            until_str = _time.strftime(
                "%Y-%m-%d %H:%M",
                _time.localtime(
                    state["paused_until_at"],
                ),
            )
            print(
                f"Pause extended by {hours}h "
                f"(now ends {until_str})."
            )
        else:
            print(
                "Extend failed -- no active pause "
                "or test env."
            )
        return

    if bool(getattr(args, "resume", False)):
        from core.autonomous import cycle_pause as _cp
        ok = _cp.resume()
        if as_json:
            print(json.dumps({
                "ok": ok,
                "action": "resume",
            }, indent=2))
        elif ok:
            print("Cycle resumed.")
        else:
            print("No active pause to resume.")
        return

    if bool(getattr(args, "show_pause", False)):
        from core.autonomous import cycle_pause as _cp
        state = _cp.get_pause_state()
        try:
            freq = _cp.pause_frequency(
                since_seconds=86400 * 7,
            )
        except Exception as exc:  # noqa: BLE001
            logger.debug(
                "show-pause freq raised: %s", exc,
            )
            freq = {}
        if as_json:
            print(json.dumps({
                **state,
                "frequency_7d": freq,
            }, indent=2, default=str))
            return
        if not state["active"]:
            print("Cycle is NOT paused.")
            if freq.get("pause_count", 0):
                print(
                    f"  Last 7d: {freq['pause_count']} "
                    f"pause(s), "
                    f"{freq['total_downtime_hours']:.1f}h "
                    f"downtime"
                )
            return
        import time as _time
        until_at = float(state.get("paused_until_at", 0) or 0)
        until_str = _time.strftime(
            "%Y-%m-%d %H:%M:%S",
            _time.localtime(until_at),
        )
        # Mirror autonomous-cycle's skip-path render --
        # remaining + elapsed timing so operators don't
        # have to mentally subtract from absolute clock.
        now_ts = _time.time()
        remaining_h = max(0.0, (until_at - now_ts)) / 3600.0
        paused_at = float(state.get("paused_at", 0) or 0)
        elapsed_h = (
            max(0.0, (now_ts - paused_at)) / 3600.0
            if paused_at > 0 else 0.0
        )
        print(
            f"Cycle PAUSED until {until_str}  "
            f"({remaining_h:.1f}h remaining"
            + (
                f", paused {elapsed_h:.1f}h ago"
                if paused_at > 0 else ""
            )
            + ")"
        )
        if state.get("reason"):
            print(f"  Reason: {state['reason']}")
        if freq.get("pause_count", 0):
            print(
                f"  Last 7d: {freq['pause_count']} "
                f"pause(s), "
                f"{freq['total_downtime_hours']:.1f}h "
                f"downtime"
            )
        return

    if bool(getattr(args, "clear_pause_history", False)):
        from core.autonomous import cycle_pause as _cp
        if not yes:
            print(
                "Refusing to clear pause history without "
                "--yes. This is destructive."
            )
            sys.exit(1)
            return
        _cp.clear_history()
        if as_json:
            print(json.dumps({
                "ok": True,
                "action": "clear_pause_history",
            }, indent=2))
        else:
            print("Pause history cleared.")
        return

    if bool(getattr(args, "pause_history", False)):
        from core.autonomous import cycle_pause as _cp
        import time as _time
        window_days = max(
            1, int(
                getattr(
                    args, "pause_history_days", 30,
                ) or 30,
            ),
        )
        events = _cp.pause_history(
            since_seconds=window_days * 86400,
        )
        if as_json:
            print(json.dumps({
                "window_days": window_days,
                "events": events,
            }, indent=2, default=str))
            return
        print(
            f"Cycle pause history "
            f"(last {window_days} day(s)):"
        )
        if not events:
            print("  No pause events recorded.")
            return
        for e in events[:50]:
            ts = float(e.get("recorded_at", 0) or 0)
            when = _time.strftime(
                "%Y-%m-%d %H:%M",
                _time.localtime(ts),
            ) if ts else "?"
            kind = str(e.get("kind", "") or "").upper()
            reason = str(e.get("reason", "") or "")
            line = f"  [{when}] {kind}"
            if reason:
                line += f"  {reason[:60]}"
            until_at = e.get("paused_until_at")
            if (
                until_at
                and kind in ("PAUSE", "EXTEND")
            ):
                try:
                    line += (
                        "  -> "
                        + _time.strftime(
                            "%Y-%m-%d %H:%M",
                            _time.localtime(
                                float(until_at),
                            ),
                        )
                    )
                except (TypeError, ValueError):
                    pass
            print(line)
        return

    # --revenue-trend is read-only: fleet revenue
    # trend across cycle snapshots.
    if bool(getattr(args, "revenue_trend", False)):
        try:
            from core.autonomous import (
                cycle_revenue_history as _crh,
            )
        except Exception as exc:  # noqa: BLE001
            print(f"revenue-trend unavailable: {exc}")
            return
        window_days = max(
            1, int(
                getattr(
                    args, "history_window_days", 7,
                ) or 7,
            ),
        )
        trend = _crh.revenue_trend(
            since_seconds=window_days * 86400,
        )
        if as_json:
            print(json.dumps({
                "window_days": window_days,
                **trend,
            }, indent=2, default=str))
            return
        print(
            f"Fleet revenue trend "
            f"(last {window_days} day(s)):"
        )
        if trend["snapshots"] == 0:
            print("  No revenue snapshots recorded yet.")
            return
        print(
            f"  Snapshots:      {trend['snapshots']}"
        )
        print(
            f"  First revenue:  "
            f"${trend['first_revenue']:,.2f}"
        )
        print(
            f"  Last revenue:   "
            f"${trend['last_revenue']:,.2f}"
        )
        sign = "+" if trend["delta"] >= 0 else ""
        print(
            f"  Delta:          "
            f"{sign}${trend['delta']:,.2f} "
            f"({sign}{trend['delta_pct']:.1f}%)"
        )
        return

    # --diary is read-only: unified event log across all
    # history files.
    if bool(getattr(args, "diary", False)):
        try:
            from core.autonomous import (
                cycle_diary as _cd,
            )
        except Exception as exc:  # noqa: BLE001
            print(f"diary unavailable: {exc}")
            return
        window_days = max(
            1, int(
                getattr(
                    args, "history_window_days", 7,
                ) or 7,
            ),
        )
        limit = max(
            1, int(
                getattr(args, "history_limit", 50) or 50,
            ),
        )
        events = _cd.compile_diary(
            since_seconds=window_days * 86400,
            limit=limit * 5 if (
                getattr(args, "diary_filter", None)
            ) else limit,
        )
        # Apply source filter if requested. Pull more
        # events from compile_diary upstream (limit*5) so
        # post-filter we still have a reasonable count.
        filter_str = (
            getattr(args, "diary_filter", None) or ""
        )
        if filter_str:
            allowed = {
                s.strip().lower()
                for s in filter_str.split(",")
                if s.strip()
            }
            # Catch typos: surface unknown filter tokens
            # so a silent empty result doesn't masquerade
            # as "no events" when the operator typo'd.
            known = {
                "cycle", "demote", "promote", "relax",
                "transfer", "pause", "alert",
            }
            unknown = allowed - known
            if unknown:
                msg = (
                    f"Unknown --diary-filter source(s): "
                    f"{', '.join(sorted(unknown))}. "
                    f"Valid: {', '.join(sorted(known))}"
                )
                if as_json:
                    print(json.dumps({
                        "status": "error",
                        "error": msg,
                    }, indent=2, default=str))
                else:
                    print(msg)
                sys.exit(1)
                return
            events = [
                e for e in events
                if e.source.lower() in allowed
            ][:limit]
        # Per-source breakdown -- one-glance answer to "what
        # subsystems have been active this window?".
        source_counts: dict[str, int] = {}
        for e in events:
            source_counts[e.source] = (
                source_counts.get(e.source, 0) + 1
            )
        if as_json:
            print(json.dumps({
                "window_days": window_days,
                "source_counts": source_counts,
                "events": [
                    {
                        "recorded_at": e.recorded_at,
                        "source": e.source,
                        "kind": e.kind,
                        "detail": e.detail,
                        "metrics": e.metrics,
                    }
                    for e in events
                ],
            }, indent=2, default=str))
            return
        print(
            f"Autonomous loop diary "
            f"(last {window_days} day(s), newest first):"
        )
        print()
        if not events:
            print(
                "  No events recorded in the window."
            )
            return
        if source_counts:
            # Order by count desc so dominant sources are
            # immediately obvious.
            breakdown = ", ".join(
                f"{src}={n}"
                for src, n in sorted(
                    source_counts.items(),
                    key=lambda kv: (-kv[1], kv[0]),
                )
            )
            print(f"  By source: {breakdown}")
            print()
        import datetime as _dt
        for e in events:
            stamp = _dt.datetime.fromtimestamp(
                e.recorded_at,
            ).strftime("%Y-%m-%d %H:%M")
            print(f"  {stamp}  {e.detail}")
        return

    # --transfer-effectiveness is read-only.
    if bool(getattr(args, "transfer_effectiveness", False)):
        try:
            from core.autonomous import (
                cycle_transfer as _ct,
            )
            window_days = max(
                1, int(
                    getattr(
                        args, "history_window_days", 7,
                    ) or 7,
                ),
            )
            data = _ct.compute_effectiveness(
                since_seconds=window_days * 86400,
            )
        except Exception as exc:  # noqa: BLE001
            print(
                f"transfer-effectiveness raised: {exc}"
            )
            return
        if as_json:
            print(json.dumps({
                "window_days": window_days,
                **data,
            }, indent=2, default=str))
            return
        print(
            f"Transfer effectiveness "
            f"(last {window_days} day(s)):"
        )
        print(
            f"  Transfers:        "
            f"{data['transfers_total']}"
        )
        print(
            f"  With outcomes:    "
            f"{data['with_outcomes']}"
        )
        print(
            f"  Positive:         "
            f"{data['positive_count']}"
        )
        print(
            f"  Negative:         "
            f"{data['negative_count']}"
        )
        print(
            f"  Neutral:          "
            f"{data['neutral_count']}"
        )
        sign = (
            "+" if data["total_revenue"] >= 0 else ""
        )
        print(
            f"  Total revenue:    "
            f"{sign}${data['total_revenue']:,.2f}"
        )
        if data["by_source_store"]:
            print()
            print(
                "  Per-source breakdown:"
            )
            for src, stats in sorted(
                data["by_source_store"].items(),
                key=lambda kv: -kv[1]["transfers"],
            )[:5]:
                rev_sign = (
                    "+" if stats["revenue"] >= 0 else ""
                )
                print(
                    f"    {src}: "
                    f"{stats['transfers']} transfer(s), "
                    f"+{stats['positive']}/"
                    f"-{stats['negative']}, "
                    f"{rev_sign}${stats['revenue']:,.2f}"
                )
        return

    # --show-thresholds is a read-only inspector.
    if bool(getattr(args, "show_thresholds", False)):
        try:
            from core.autonomous import (
                cycle_overrides as _co,
            )
            data = {
                "auto_execute_threshold": (
                    _co.resolve_threshold()
                ),
                "auto_execute_min_sample": (
                    _co.resolve_min_sample()
                ),
                "overrides_file": _co.load_overrides(),
            }
        except Exception as exc:  # noqa: BLE001
            data = {"error": str(exc)}
        if as_json:
            print(json.dumps(data, indent=2, default=str))
        else:
            print("Effective cycle thresholds:")
            print(
                f"  auto_execute_threshold: "
                f"{data.get('auto_execute_threshold')}"
            )
            print(
                f"  auto_execute_min_sample: "
                f"{data.get('auto_execute_min_sample')}"
            )
            ovr = data.get("overrides_file") or {}
            if ovr:
                print("  Active overrides:")
                for k, v in ovr.items():
                    print(f"    {k} = {v}")
            else:
                print(
                    "  (no overrides set; using env / "
                    "defaults)"
                )
        return

    # --set-threshold writes a persistent override.
    if getattr(args, "set_threshold", None) is not None:
        new_val = float(args.set_threshold)
        if new_val < 0.0 or new_val > 1.0:
            print(
                f"Threshold must be in [0.0, 1.0]: "
                f"{new_val}"
            )
            sys.exit(1)
            return
        # W962-5 bugfix: lowering the auto-execute threshold
        # is a classifier bypass -- without these guards, an
        # operator (or runaway agent) could drop the floor
        # silently. Now require --yes + env-gate; hard floor
        # at 0.50 requires --force as well.
        import os as _os
        _yes = bool(getattr(args, "yes", False))
        _force = bool(getattr(args, "force", False))
        _confirm = (
            _os.environ.get(
                "SHOPAI_AUTONOMOUS_SET_THRESHOLD_CONFIRM", "",
            ) in ("1", "true", "yes")
        )
        _HARD_FLOOR = 0.50
        if not _yes:
            print(
                "ERROR: --set-threshold requires --yes. "
                "Pass --yes after verifying intent.",
                file=sys.stderr,
            )
            sys.exit(2)
        if not _confirm:
            print(
                "ERROR: set SHOPAI_AUTONOMOUS_SET_THRESHOLD_"
                "CONFIRM=1 to lower the auto-execute "
                "reliability floor.",
                file=sys.stderr,
            )
            sys.exit(2)
        if new_val < _HARD_FLOOR and not _force:
            print(
                f"ERROR: requested {new_val} below hard "
                f"floor {_HARD_FLOOR}. Pass --force to "
                "override (carries reputational risk -- "
                "agents below 50% reliability will execute "
                "irreversible mutations).",
                file=sys.stderr,
            )
            sys.exit(2)
        try:
            from core.autonomous import (
                cycle_overrides as _co,
            )
            ok = _co.set_override(
                "auto_execute_threshold", new_val,
            )
            if as_json:
                print(json.dumps({
                    "ok": ok,
                    "key": "auto_execute_threshold",
                    "value": new_val,
                }, indent=2))
            elif ok:
                print(
                    f"Persisted auto_execute_threshold = "
                    f"{new_val}"
                )
            else:
                print(
                    "Set failed (test environment or I/O)."
                )
        except Exception as exc:  # noqa: BLE001
            print(f"set-threshold failed: {exc}")
        return

    # --clear-threshold removes the persistent override.
    if bool(getattr(args, "clear_threshold", False)):
        try:
            from core.autonomous import (
                cycle_overrides as _co,
            )
            ok = _co.clear_override(
                "auto_execute_threshold",
            )
            if as_json:
                print(json.dumps({
                    "ok": ok,
                    "key": "auto_execute_threshold",
                }, indent=2))
            elif ok:
                print(
                    "Cleared auto_execute_threshold "
                    "override."
                )
            else:
                print(
                    "Nothing to clear (or test env)."
                )
        except Exception as exc:  # noqa: BLE001
            print(f"clear-threshold failed: {exc}")
        return

    # --clear-alerts wipes the persistent log and returns.
    # Operator escape hatch after addressing an underlying
    # issue, so the consecutive-day streak resets.
    if bool(getattr(args, "clear_alerts", False)):
        try:
            from core.autonomous import (
                cycle_alert_history as _cah,
            )
            _cah.clear()
            if as_json:
                print(json.dumps(
                    {"status": "cleared"},
                    indent=2,
                ))
            else:
                print("Cycle alert history cleared.")
        except Exception as exc:  # noqa: BLE001
            print(f"clear failed: {exc}")
        return

    # --alerts is a read-only shortcut: compute health
    # alerts from cycle_history and return.
    if bool(getattr(args, "alerts", False)):
        try:
            from core.autonomous import (
                cycle_alerts as _ca,
            )
        except Exception as exc:  # noqa: BLE001
            print(
                f"cycle alerts unavailable: {exc}"
            )
            return
        window_days = max(
            1, int(
                getattr(
                    args, "history_window_days", 7,
                ) or 7,
            ),
        )
        alerts_list = _ca.compute_cycle_alerts(
            window_seconds=window_days * 86400,
        )
        per_store_alerts = _ca.compute_per_store_alerts(
            window_seconds=window_days * 86400,
        )
        config = _ca.config_summary()
        # Consecutive-day counts from the persistent log.
        # Lets operators distinguish flares from patterns.
        try:
            from core.autonomous import (
                cycle_alert_history as _cah,
            )
            consecutive = _cah.consecutive_days_per_kind(
                window_seconds=window_days * 86400.0,
            )
        except Exception as exc:  # noqa: BLE001
            logger.debug(
                "alerts: consecutive_days raised: %s",
                exc,
            )
            consecutive = {}
        if as_json:
            print(json.dumps({
                "window_days": window_days,
                "config": config,
                "alerts": [
                    {
                        "kind": a.kind,
                        "detail": a.detail,
                        "metrics": a.metrics,
                    }
                    for a in alerts_list
                ],
                "per_store_alerts": [
                    {
                        "store_id": a.store_id,
                        "kind": a.kind,
                        "detail": a.detail,
                        "metrics": a.metrics,
                    }
                    for a in per_store_alerts
                ],
                "consecutive_days": consecutive,
            }, indent=2, default=str))
            return
        print(
            f"Autonomous cycle alerts "
            f"(last {window_days} day(s)):"
        )
        if not alerts_list and not per_store_alerts:
            print()
            print("  No alerts -- cycle looks healthy.")
            if consecutive:
                # Past firings, but currently quiet
                print()
                print("  Historical firings in window:")
                for kind, days in sorted(
                    consecutive.items(),
                ):
                    print(f"    [{kind}]  {days} day(s)")
            return
        for a in alerts_list:
            days = consecutive.get(a.kind, 0)
            streak = (
                f"  (firing {days}d streak)"
                if days >= 2 else ""
            )
            print(f"  [{a.kind}]  {a.detail}{streak}")
        if per_store_alerts:
            print()
            print(
                f"Per-store alerts ({len(per_store_alerts)}):"
            )
            for psa in per_store_alerts:
                print(
                    f"  [{psa.kind}]  "
                    f"{psa.store_id}: {psa.detail}"
                )
        return

    # --emit-cron emits a ready-to-install cron config and
    # returns. Doesn't run a cycle.
    if bool(getattr(args, "emit_cron", False)):
        fmt = str(
            getattr(args, "cron_format", "crontab")
            or "crontab",
        )
        interval = str(
            getattr(args, "cron_interval", "30m")
            or "30m",
        )
        cron_expr = _interval_to_cron(interval)
        if cron_expr is None:
            print(
                f"Invalid --cron-interval '{interval}'. "
                "Use forms like 5m / 30m / 1h / 6h."
            )
            sys.exit(1)
            return
        if fmt == "systemd":
            print(_emit_systemd_units(interval))
        else:
            print(_emit_crontab(cron_expr))
        return

    # --history is a read-only shortcut: print cycle log
    # and return. Doesn't run a cycle.
    if bool(getattr(args, "history", False)):
        try:
            from core.autonomous import cycle_history as _ch
        except Exception as exc:  # noqa: BLE001
            print(f"cycle history unavailable: {exc}")
            return
        window_days = max(
            1, int(
                getattr(
                    args, "history_window_days", 7,
                ) or 7,
            ),
        )
        limit = max(
            1, int(
                getattr(args, "history_limit", 10) or 10,
            ),
        )
        events = _ch.recent_history(
            since_seconds=window_days * 86400,
        )[:limit]
        stats = _ch.cycle_stats(
            since_seconds=window_days * 86400,
        )
        if as_json:
            print(json.dumps({
                "window_days": window_days,
                "stats": stats,
                "events": [
                    {
                        "recorded_at": e.recorded_at,
                        "executed": e.executed,
                        "advance": e.advance,
                        "defend": e.defend,
                        "correlate": e.correlate,
                        "flags": e.flags,
                    }
                    for e in events
                ],
            }, indent=2, default=str))
            return
        print(
            f"Autonomous cycle history "
            f"(last {window_days} day(s)):"
        )
        print(
            f"  Runs: {stats['total_runs']} total  "
            f"({stats['executed_runs']} executed, "
            f"{stats['dry_run_count']} dry-run)"
        )
        if stats["total_runs"] > 0:
            import datetime as _dt
            last = _dt.datetime.fromtimestamp(
                stats["last_run_at"],
            ).strftime("%Y-%m-%d %H:%M")
            print(f"  Last run: {last}")
            print(
                f"  Totals: "
                f"{stats['stores_advanced_total']} stores "
                f"advanced, "
                f"{stats['stores_refused_total']} refused, "
                f"{stats['demoted_total']} demoted, "
                f"{stats['released_total']} released, "
                f"{stats['correlated_total']} correlated"
            )
        if not events:
            print()
            print("  No recent invocations.")
            return
        print()
        print(f"Recent invocations (newest first):")
        import datetime as _dt
        for e in events:
            stamp = _dt.datetime.fromtimestamp(
                e.recorded_at,
            ).strftime("%Y-%m-%d %H:%M")
            mode = "EXEC" if e.executed else "DRY "
            adv = e.advance or {}
            dfn = e.defend or {}
            cor = e.correlate or {}
            print(
                f"  {stamp}  [{mode}]  "
                f"adv={adv.get('executed_ok', 0)}ok/"
                f"{adv.get('refused_reliability', 0)}ref  "
                f"def={dfn.get('demoted', 0)}d/"
                f"{dfn.get('released', 0)}r  "
                f"cor={cor.get('correlated', 0)}c"
            )
        return

    summary: dict[str, Any] = {
        "executed": yes,
        "advance": None,
        "transfer": None,
        "defend": None,
        "correlate": None,
    }

    # ── Pause check ───────────────────────────────────
    # If a pause is active, skip every phase + record an
    # explanatory entry. Operator can clear via --resume.
    try:
        from core.autonomous import cycle_pause as _cp
        pause_state = _cp.get_pause_state()
        if pause_state.get("active"):
            summary["paused"] = pause_state
            # Even on a paused cycle, expose engine-health
            # counts so cron monitors parsing the JSON
            # don't lose visibility of degradation
            # signals just because the cycle skipped.
            try:
                from core.approval.engine_health_history import (
                    find_regressions, find_chronic_warnings,
                )
                from core.approval.outcome_trends import (
                    compute_engine_alerts,
                )
                from core.approval.queue import (
                    get_approval_queue,
                )
                summary["engine_health"] = {
                    "regression_count": len(
                        find_regressions(
                            min_drop=3.0,
                            baseline_window_seconds=(
                                86400.0 * 7.0
                            ),
                            latest_window_seconds=(
                                86400.0 * 1.0
                            ),
                            min_baseline_samples=3,
                        ),
                    ),
                    "chronic_warning_count": len(
                        find_chronic_warnings(
                            sample_window_seconds=(
                                86400.0 * 7.0
                            ),
                            min_samples=3,
                            healthy_score_floor=7,
                        ),
                    ),
                    "outcome_alert_count": len(
                        compute_engine_alerts(
                            get_approval_queue(),
                            recent_hours=24.0,
                            baseline_hours=168.0,
                            threshold=0.2,
                            min_recent=3,
                        ),
                    ),
                }
            except Exception as exc:  # noqa: BLE001
                logger.debug(
                    "paused-cycle engine_health probe "
                    "raised: %s", exc,
                )
            if as_json:
                print(json.dumps(
                    summary, indent=2, default=str,
                ))
                return
            import time as _time
            until_at = float(
                pause_state.get("paused_until_at", 0) or 0,
            )
            until_str = _time.strftime(
                "%Y-%m-%d %H:%M",
                _time.localtime(until_at),
            )
            # Remaining + elapsed timing -- tells operators
            # at a glance how long the pause has left to
            # run vs how long ago it started.
            now_ts = _time.time()
            remaining_h = max(0.0, (until_at - now_ts)) / 3600.0
            paused_at = float(
                pause_state.get("paused_at", 0) or 0,
            )
            elapsed_h = (
                max(0.0, (now_ts - paused_at)) / 3600.0
                if paused_at > 0 else 0.0
            )
            print(
                f"Cycle PAUSED until {until_str}  "
                f"({remaining_h:.1f}h remaining"
                + (
                    f", paused {elapsed_h:.1f}h ago"
                    if paused_at > 0 else ""
                )
                + ")"
            )
            if pause_state.get("reason"):
                print(
                    f"  Reason: {pause_state['reason']}"
                )
            # Surface engine-health signals even on a
            # paused cycle -- the pause skips work but
            # the degradation signals still matter to
            # the operator.
            eh = summary.get("engine_health") or {}
            n_reg = int(
                eh.get("regression_count", 0) or 0,
            )
            n_chr = int(
                eh.get("chronic_warning_count", 0) or 0,
            )
            n_oa = int(
                eh.get("outcome_alert_count", 0) or 0,
            )
            if n_reg or n_chr or n_oa:
                parts: list[str] = []
                if n_reg:
                    parts.append(
                        f"{n_reg} regression(s)"
                    )
                if n_chr:
                    parts.append(f"{n_chr} chronic")
                if n_oa:
                    parts.append(
                        f"{n_oa} outcome alert(s)"
                    )
                print(
                    "  Engine health: "
                    + ", ".join(parts)
                )
            print(
                "  Run ``shopai autonomous-cycle "
                "--resume`` to clear."
            )
            return
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "autonomous-cycle: pause check raised: %s",
            exc,
        )

    # ── Revenue snapshot capture (cycle start) ─────────
    # Snapshot the fleet's total revenue + store count so
    # cycle_revenue_history can show whether the autonomous
    # loop is growing revenue over time. Best-effort; any
    # failure logged but doesn't break the cycle.
    try:
        sm_rev = _get_store_manager()
        stores_rev = sm_rev.list_stores() or []
        fleet_rev = 0.0
        per_store_rev: dict[str, float] = {}
        for s in stores_rev:
            sid = s.get("store_id") or ""
            if not sid:
                continue
            try:
                stats = sm_rev.get_stats(sid) or {}
                rev = float(
                    stats.get("total_revenue", 0) or 0,
                )
                fleet_rev += rev
                per_store_rev[sid] = rev
            except Exception as exc:  # noqa: BLE001
                logger.debug(
                    "autonomous-cycle: revenue lookup "
                    "raised for %s: %s", sid, exc,
                )
        from core.autonomous import (
            cycle_revenue_history as _crh,
        )
        _crh.record_snapshot(
            fleet_revenue=fleet_rev,
            store_count=len(stores_rev),
            per_store=per_store_rev,
        )
        summary["fleet_revenue"] = fleet_rev
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "autonomous-cycle: revenue snapshot "
            "raised: %s", exc,
        )

    # ── Advance phase ──────────────────────────────────
    if not skip_advance:
        try:
            sm = _get_store_manager()
            stores = sm.list_stores() or []
        except Exception as exc:  # noqa: BLE001
            stores = []
            logger.debug(
                "autonomous-cycle: list_stores raised: %s",
                exc,
            )

        try:
            from core.capability_planner import (
                plan_for_audit_gaps,
            )
            from core.context import active_store
            from engines.store_setup.launch_audit import (
                audit_store,
            )
        except Exception as exc:  # noqa: BLE001
            summary["advance"] = {
                "error": f"import_failed: {exc}",
            }
        else:
            stores_processed = 0
            executed_ok = 0
            refused = 0
            errored = 0
            # Per-store breakdown -- empire-AGI consumer
            # (world-model, transfer recommender) can use the
            # store_id -> outcome mapping rather than just the
            # aggregate counts.
            per_store: list[dict[str, Any]] = []
            for s in stores:
                sid = s.get("store_id") or ""
                if not sid:
                    continue
                stores_processed += 1
                store_entry: dict[str, Any] = {
                    "store_id": sid,
                    "outcome": "",
                    "plan_steps": 0,
                }
                try:
                    with active_store(sid):
                        audit = audit_store(
                            store_id=sid,
                        )
                        failing = [
                            c.get("key", "")
                            for c in (
                                audit.get("checks") or []
                            )
                            if not c.get("ok")
                        ]
                        plan = plan_for_audit_gaps(failing)
                except Exception as exc:  # noqa: BLE001
                    errored += 1
                    logger.debug(
                        "autonomous-cycle advance: "
                        "store %s raised: %s", sid, exc,
                    )
                    store_entry["outcome"] = "errored"
                    store_entry["error"] = str(exc)[:80]
                    per_store.append(store_entry)
                    continue
                store_entry["plan_steps"] = (
                    len(plan.steps) if plan else 0
                )
                if not plan or not plan.steps:
                    store_entry["outcome"] = "no_plan"
                    per_store.append(store_entry)
                    continue
                ex = _fleet_execute_one_store(
                    sid=sid,
                    plan=plan,
                    yes=yes,
                    require_reliable=True,
                )
                if ex.get("refused") == "reliability":
                    refused += 1
                    store_entry["outcome"] = "refused_reliability"
                    store_entry["ineligible_count"] = ex.get(
                        "ineligible_count", 0,
                    )
                elif ex.get("error"):
                    errored += 1
                    store_entry["outcome"] = "errored"
                    store_entry["error"] = str(
                        ex.get("error"),
                    )[:80]
                elif ex.get("ok"):
                    executed_ok += 1
                    store_entry["outcome"] = "executed"
                    store_entry["steps_run"] = ex.get(
                        "steps_run", 0,
                    )
                else:
                    store_entry["outcome"] = "unknown"
                per_store.append(store_entry)
            summary["advance"] = {
                "stores_processed": stores_processed,
                "executed_ok": executed_ok,
                "refused_reliability": refused,
                "errored": errored,
                "per_store": per_store,
            }

    # ── Transfer phase ─────────────────────────────────
    # For each store that had no advance plan (no audit
    # gaps OR refused), look for transferable winning
    # actions from peer stores. Enqueues -- never directly
    # writes Shopify. Env-gated; preview-only by default.
    if not skip_transfer:
        transfer_summary: dict[str, Any] = {
            "checked": True,
            "config": None,
            "per_store": [],
            "total_candidates": 0,
            "total_applied": 0,
        }
        try:
            from core.autonomous import (
                cycle_transfer as _ct,
            )
            transfer_summary["config"] = (
                _ct.config_summary()
            )
            # Build the list of stores to consider:
            # whichever stores ADVANCE skipped (no_plan
            # outcome or refused_reliability).
            adv = summary.get("advance") or {}
            per = adv.get("per_store") or []
            idle_store_ids = [
                row.get("store_id")
                for row in per
                if isinstance(row, dict)
                and row.get("store_id")
                and row.get("outcome") in (
                    "no_plan", "refused_reliability",
                )
            ]
            # Also need the full fleet list to pass as
            # peers.
            try:
                sm = _get_store_manager()
                fleet = sm.list_stores() or []
                fleet_ids = [
                    s.get("store_id")
                    for s in fleet
                    if s.get("store_id")
                ]
            except Exception as exc:  # noqa: BLE001
                logger.debug(
                    "autonomous-cycle: transfer fleet "
                    "lookup raised: %s", exc,
                )
                fleet_ids = []

            for sid in idle_store_ids:
                store_result = _ct.maybe_apply_transfers(
                    target_store_id=sid,
                    fleet_store_ids=fleet_ids,
                )
                transfer_summary["per_store"].append(
                    store_result,
                )
                transfer_summary["total_candidates"] += (
                    store_result.get(
                        "candidates_found", 0,
                    )
                )
                transfer_summary["total_applied"] += (
                    store_result.get("applied", 0)
                )
        except Exception as exc:  # noqa: BLE001
            logger.debug(
                "autonomous-cycle: transfer phase "
                "raised: %s", exc,
            )
            transfer_summary["error"] = (
                f"raised: {exc}"
            )
            transfer_summary["checked"] = False
        summary["transfer"] = transfer_summary

    # ── Defend phase ───────────────────────────────────
    # Bridges capability_degradations -> operator demote so
    # next cycle's plans stop seeding regressed capabilities.
    # Env-gated; without SHOPAI_AUTO_DEMOTE_DEGRADED=1, the
    # phase still computes candidates (visibility) but writes
    # nothing.
    if not skip_defend:
        try:
            from core.capability_planner import auto_demote
        except Exception as exc:  # noqa: BLE001
            summary["defend"] = {
                "error": f"import_failed: {exc}",
            }
        else:
            try:
                config = auto_demote.config_summary()
                candidates = (
                    auto_demote.find_demote_candidates()
                )
                release_candidates = (
                    auto_demote.find_release_candidates()
                )
                if yes:
                    demoted = (
                        auto_demote
                        .maybe_auto_demote_degraded()
                    )
                    # Release is always safe -- no env gate.
                    released = (
                        auto_demote.maybe_release_recovered()
                    )
                else:
                    demoted = []
                    released = []
                # Auto-promote (symmetric to auto-demote)
                # — when capability has high success rate
                # + enough samples, auto-promote. Env-gated.
                promoted: list[dict] = []
                promote_config: dict = {"enabled": False}
                try:
                    from core.capability_planner import (
                        auto_promote as _ap,
                    )
                    promote_config = _ap.config_summary()
                    promote_candidates = (
                        _ap.find_promote_candidates()
                    )
                    actionable_promotes = sum(
                        1 for c in promote_candidates
                        if c.get("blocked_by") is None
                    )
                    if yes:
                        promoted = (
                            _ap.maybe_auto_promote_reliable()
                        )
                except Exception as exc:  # noqa: BLE001
                    logger.debug(
                        "autonomous-cycle defend "
                        "auto_promote raised: %s", exc,
                    )
                    promote_candidates = []
                    actionable_promotes = 0
                summary["defend"] = {
                    "gate_enabled": config["enabled"],
                    "candidates": len(candidates),
                    "actionable": sum(
                        1 for c in candidates
                        if c["blocked_by"] is None
                    ),
                    "demoted": len(demoted),
                    "demoted_capabilities": [
                        d["capability"] for d in demoted
                    ],
                    "recovered_candidates": len(
                        release_candidates,
                    ),
                    "released": len(released),
                    "released_capabilities": [
                        r["capability"] for r in released
                    ],
                    "promote_gate_enabled": (
                        promote_config.get(
                            "enabled", False,
                        )
                    ),
                    "promote_candidates": len(
                        promote_candidates,
                    ),
                    "promote_actionable": (
                        actionable_promotes
                    ),
                    "promoted": len(promoted),
                    "promoted_capabilities": [
                        p["capability"] for p in promoted
                    ],
                }
            except Exception as exc:  # noqa: BLE001
                logger.debug(
                    "autonomous-cycle defend: raised: %s",
                    exc,
                )
                summary["defend"] = {
                    "error": f"raised: {exc}",
                }

    # ── Measure phase ──────────────────────────────────
    if not skip_correlate:
        try:
            from core.capability_planner import (
                correlate_outcome_by_stats,
                recent_history,
            )
        except Exception as exc:  # noqa: BLE001
            summary["correlate"] = {
                "error": f"import_failed: {exc}",
            }
        else:
            sm = _get_store_manager()
            events = recent_history(
                since_seconds=86400 * 90,
            )
            now = time.time()
            UNCORRELATED = {"", "executed_ok"}
            stats_cache: dict[str, dict[str, Any]] = {}
            candidates = 0
            correlated = 0
            outcomes: dict[str, int] = {}
            for e in events:
                ts = float(e.get("timestamp", 0) or 0)
                if (now - ts) < 86400:
                    continue
                if not e.get("executed"):
                    continue
                outcome = str(e.get("outcome") or "")
                if outcome not in UNCORRELATED:
                    continue
                if not (e.get("pre_stats") or {}):
                    continue
                candidates += 1
                sid = e.get("store_id", "") or ""
                if sid not in stats_cache:
                    try:
                        stats_cache[sid] = (
                            sm.get_stats(sid) or {}
                        )
                    except Exception as exc:  # noqa: BLE001
                        logger.debug(
                            "autonomous-cycle measure: "
                            "get_stats raised: %s",
                            exc,
                        )
                        stats_cache[sid] = {}
                result = correlate_outcome_by_stats(
                    e.get("event_id", ""),
                    stats_cache[sid],
                )
                if result.get("ok"):
                    correlated += 1
                    oc = str(result.get("outcome") or "")
                    outcomes[oc] = outcomes.get(oc, 0) + 1
            summary["correlate"] = {
                "candidates": candidates,
                "correlated": correlated,
                "by_outcome": outcomes,
            }

    # Persist this invocation to the cycle history audit log.
    # Pattern J guard short-circuits under pytest. Fail-open:
    # any persist error is logged but doesn't break the
    # cycle's response.
    try:
        from core.autonomous import cycle_history as _ch
        _ch.record_cycle(
            executed=yes,
            advance=summary.get("advance") or {},
            defend=summary.get("defend") or {},
            correlate=summary.get("correlate") or {},
            flags={
                "skip_advance": skip_advance,
                "skip_defend": skip_defend,
                "skip_correlate": skip_correlate,
            },
        )
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "autonomous-cycle: record_cycle raised: %s",
            exc,
        )

    # Compute + persist any cycle-health alerts that fired
    # as a RESULT of this run. Captures the longitudinal
    # signal (alerts firing on consecutive days = real
    # pattern; one-off = flare). Fail-open.
    try:
        from core.autonomous import (
            cycle_alerts as _cycle_alerts,
            cycle_alert_history as _cycle_alert_history,
        )
        fired = _cycle_alerts.compute_cycle_alerts(
            window_seconds=86400 * 7,
        )
        per_store_fired = (
            _cycle_alerts.compute_per_store_alerts(
                window_seconds=86400 * 7,
            )
        )
        # Persist both fleet + per-store alerts to the same
        # history file. Distinguishing data lives in
        # ``metrics`` (per-store rows tag store_id).
        rows_to_record: list[Any] = list(fired)
        for psa in per_store_fired:
            rows_to_record.append(_cycle_alerts.CycleAlert(
                kind=psa.kind,
                detail=psa.detail,
                metrics={
                    "store_id": psa.store_id,
                    **(psa.metrics or {}),
                },
            ))
        if rows_to_record:
            _cycle_alert_history.record_alerts(
                rows_to_record,
            )
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "autonomous-cycle: record alerts raised: %s",
            exc,
        )

    # Auto-relax / auto-restore bridge: env-gated
    # self-correcting layer. When low_advance_rate has been
    # firing for 3+ days, lower the persistent threshold.
    # When alerts have been quiet, raise it back. Fail-open.
    try:
        from core.autonomous import auto_relax as _ar
        relax_result = _ar.maybe_relax_and_restore()
        summary["auto_relax"] = relax_result
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "autonomous-cycle: auto_relax raised: %s",
            exc,
        )
        summary["auto_relax"] = {
            "checked": False,
            "error": f"raised: {exc}",
        }

    # Composite health score snapshot at cycle end.
    # Persists to ``health_score_history`` so operators can
    # graph score over time + spot drift.
    try:
        from core.autonomous import (
            health_score_history as _hsh,
        )
        # Recompute health sections after all phases ran
        # to capture the post-cycle state.
        try:
            health = _build_health_sections()
            score = health.get("health_score", 100)
            verdict = health.get("overall", "unknown")
            _hsh.record_snapshot(
                score=int(score), verdict=verdict,
            )
        except Exception as exc:  # noqa: BLE001
            logger.debug(
                "autonomous-cycle: health snapshot "
                "raised: %s", exc,
            )
    except ImportError as exc:
        logger.debug(
            "autonomous-cycle: health_score_history "
            "import failed: %s", exc,
        )

    # Add next-action recommendation to JSON envelope.
    try:
        from core.autonomous import cycle_next_action as _na
        rec = _na.recommend(summary)
        summary["next_action"] = {
            "priority": rec.priority,
            "detail": rec.detail,
            "cmd": rec.cmd,
        }
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "autonomous-cycle: next_action JSON raised: %s",
            exc,
        )

    # Engine-degradation counts in JSON shape -- mirror of
    # daily-brief totals (30876af5) + world-model fleet
    # aggregates (3f4e14cc). Lets cron monitoring
    # pipelines that parse cycle JSON detect engine
    # degradation without a separate command.
    engine_health_block: dict[str, Any] = {
        "regression_count": 0,
        "chronic_warning_count": 0,
        "outcome_alert_count": 0,
    }
    try:
        from core.approval.engine_health_history import (
            find_regressions, find_chronic_warnings,
        )
        engine_health_block["regression_count"] = len(
            find_regressions(
                min_drop=3.0,
                baseline_window_seconds=86400.0 * 7.0,
                latest_window_seconds=86400.0 * 1.0,
                min_baseline_samples=3,
            ),
        )
        engine_health_block["chronic_warning_count"] = len(
            find_chronic_warnings(
                sample_window_seconds=86400.0 * 7.0,
                min_samples=3,
                healthy_score_floor=7,
            ),
        )
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "autonomous-cycle: engine_health JSON "
            "raised: %s", exc,
        )
    try:
        from core.approval.outcome_trends import (
            compute_engine_alerts,
        )
        from core.approval.queue import get_approval_queue
        engine_health_block["outcome_alert_count"] = len(
            compute_engine_alerts(
                get_approval_queue(),
                recent_hours=24.0,
                baseline_hours=168.0,
                threshold=0.2,
                min_recent=3,
            ),
        )
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "autonomous-cycle: outcome_alert_count "
            "raised: %s", exc,
        )
    summary["engine_health"] = engine_health_block

    if as_json:
        print(json.dumps(summary, indent=2, default=str))
        return

    mode = "EXECUTED" if yes else "DRY-RUN"
    print(f"Autonomous cycle -- {mode}")
    print()
    adv = summary.get("advance")
    if adv:
        if adv.get("error"):
            print(f"  Advance: ERROR ({adv['error']})")
        else:
            print(
                f"  Advance: "
                f"{adv['executed_ok']} ok / "
                f"{adv['refused_reliability']} refused / "
                f"{adv['errored']} errored "
                f"({adv['stores_processed']} store(s))"
            )
            # Surface per-store outcomes when there's
            # HETEROGENEITY (refused or errored) AND
            # multiple stores -- single-store or uniform
            # all-ok stays terse.
            per_store = adv.get("per_store") or []
            has_problem = bool(
                adv.get("refused_reliability", 0)
                or adv.get("errored", 0)
            )
            if (
                isinstance(per_store, list)
                and len(per_store) > 1
                and has_problem
            ):
                for row in per_store:
                    if not isinstance(row, dict):
                        continue
                    sid = row.get("store_id", "?")
                    outcome = row.get("outcome", "?")
                    tag = {
                        "executed": "[ok  ]",
                        "refused": "[REFU]",
                        "errored": "[ERR ]",
                        "no_plan": "[skip]",
                    }.get(outcome, "[?   ]")
                    print(f"    {tag}  {sid}")
    trf = summary.get("transfer")
    if trf and trf.get("checked"):
        gate = (
            "ON" if trf.get("config", {}).get("enabled")
            else "OFF"
        )
        per_store_count = len(
            trf.get("per_store") or [],
        )
        if (
            trf.get("total_candidates", 0) > 0
            or trf.get("total_applied", 0) > 0
            or per_store_count > 0
        ):
            print(
                f"  Transfer:"
                f" {trf.get('total_applied', 0)} applied /"
                f" {trf.get('total_candidates', 0)} "
                f"candidate(s) across "
                f"{per_store_count} idle store(s)  "
                f"(gate {gate})"
            )
    dfn = summary.get("defend")
    if dfn:
        if dfn.get("error"):
            print(f"  Defend:  ERROR ({dfn['error']})")
        else:
            gate = "ON" if dfn["gate_enabled"] else "OFF"
            print(
                f"  Defend:  "
                f"{dfn['demoted']} demoted / "
                f"{dfn['actionable']} actionable / "
                f"{dfn['candidates']} candidates  "
                f"(gate {gate})"
            )
            if dfn.get("demoted_capabilities"):
                names = ", ".join(
                    dfn["demoted_capabilities"][:5],
                )
                if len(dfn["demoted_capabilities"]) > 5:
                    names += (
                        f", +{len(dfn['demoted_capabilities']) - 5} more"
                    )
                print(f"           -> {names}")
            n_rel = dfn.get("released", 0)
            n_rec = dfn.get("recovered_candidates", 0)
            if n_rel or n_rec:
                print(
                    f"  Release: "
                    f"{n_rel} released / "
                    f"{n_rec} recovered candidates"
                )
                if dfn.get("released_capabilities"):
                    names = ", ".join(
                        dfn["released_capabilities"][:5],
                    )
                    if len(
                        dfn["released_capabilities"]
                    ) > 5:
                        names += (
                            f", +"
                            f"{len(dfn['released_capabilities']) - 5} "
                            f"more"
                        )
                    print(f"           -> {names}")
            # Auto-promote: render when any candidate or
            # actual promote exists. Mirrors demote/release
            # rendering above.
            n_prom = dfn.get("promoted", 0)
            n_prom_cand = dfn.get("promote_candidates", 0)
            if n_prom or n_prom_cand:
                p_gate = (
                    "ON" if dfn.get(
                        "promote_gate_enabled", False,
                    ) else "OFF"
                )
                print(
                    f"  Promote: "
                    f"{n_prom} promoted / "
                    f"{dfn.get('promote_actionable', 0)} "
                    f"actionable / "
                    f"{n_prom_cand} candidates  "
                    f"(gate {p_gate})"
                )
                if dfn.get("promoted_capabilities"):
                    names = ", ".join(
                        dfn["promoted_capabilities"][:5],
                    )
                    if len(
                        dfn["promoted_capabilities"]
                    ) > 5:
                        names += (
                            f", +"
                            f"{len(dfn['promoted_capabilities']) - 5} "
                            f"more"
                        )
                    print(f"           -> {names}")
    cor = summary.get("correlate")
    if cor:
        if cor.get("error"):
            print(f"  Measure: ERROR ({cor['error']})")
        else:
            outcomes_str = ", ".join(
                f"{k}={v}"
                for k, v in cor.get(
                    "by_outcome", {},
                ).items()
            ) or "(no outcomes recorded)"
            print(
                f"  Measure: "
                f"{cor['correlated']}/"
                f"{cor['candidates']} correlated  "
                f"{outcomes_str}"
            )
    ar = summary.get("auto_relax")
    if ar and ar.get("checked") and ar.get(
        "direction",
    ) != "none":
        applied_tag = (
            "APPLIED" if ar.get("applied") else "DRY-RUN"
        )
        print(
            f"  Auto-relax [{applied_tag}]: "
            f"{ar['current_value']:.2f} -> "
            f"{ar['proposed_value']:.2f}  "
            f"({ar['direction']})"
        )
        print(f"           reason: {ar['reason']}")
    if not yes:
        print()
        print(
            "Dry-run only. Pass --yes to actually advance "
            "the fleet + persist correlation outcomes."
        )

    # Surface engine-degradation signals at end-of-cycle so
    # cron operators see them without opening daily-brief.
    # Three classes: regressions / chronic / outcome alerts.
    # Best-effort: any failure quietly skips the line.
    try:
        from core.approval.engine_health_history import (
            find_regressions, find_chronic_warnings,
        )
        regs_list = find_regressions(
            min_drop=3.0,
            baseline_window_seconds=86400.0 * 7.0,
            latest_window_seconds=86400.0 * 1.0,
            min_baseline_samples=3,
        )
        chronic_list = find_chronic_warnings(
            sample_window_seconds=86400.0 * 7.0,
            min_samples=3,
            healthy_score_floor=7,
        )
        # Also pull outcome alerts so the surface matches
        # the paused-path rendering (50e78263) + the JSON
        # (e21b2e4f) which carries all three counts.
        outcome_alerts_list: list[Any] = []
        try:
            from core.approval.outcome_trends import (
                compute_engine_alerts,
            )
            from core.approval.queue import (
                get_approval_queue,
            )
            outcome_alerts_list = compute_engine_alerts(
                get_approval_queue(),
                recent_hours=24.0,
                baseline_hours=168.0,
                threshold=0.2,
                min_recent=3,
            )
        except Exception as exc:  # noqa: BLE001
            logger.debug(
                "autonomous-cycle: outcome_alerts probe "
                "raised: %s", exc,
            )
        if regs_list or chronic_list or outcome_alerts_list:
            parts: list[str] = []
            if regs_list:
                parts.append(
                    f"{len(regs_list)} regression(s)"
                )
            if chronic_list:
                parts.append(
                    f"{len(chronic_list)} chronic"
                )
            if outcome_alerts_list:
                parts.append(
                    f"{len(outcome_alerts_list)} "
                    "outcome alert(s)"
                )
            top_engine = (
                regs_list[0].engine if regs_list
                else chronic_list[0].engine
                if chronic_list
                else outcome_alerts_list[0].engine
            )
            print()
            print(
                "  Engine health: "
                + ", ".join(parts)
            )
            print(
                f"    Drill down: `shopai engine pulse "
                f"{top_engine} --history`"
            )
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "autonomous-cycle: health probe raised: %s",
            exc,
        )

    # Surface a next-action recommendation based on this
    # cycle's outcomes + ambient state. Best-effort: any
    # error skips the line.
    try:
        from core.autonomous import cycle_next_action as _na
        rec = _na.recommend(summary)
        print()
        print(f"Next: [{rec.priority}] {rec.detail}")
        if rec.cmd:
            print(f"  $ {rec.cmd}")
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "autonomous-cycle: next_action raised: %s",
            exc,
        )


def _fleet_execute_one_store(
    *,
    sid: str,
    plan: Any,
    yes: bool,
    require_reliable: bool,
) -> dict[str, Any]:
    """Execute a per-store plan within the fleet-plan
    dispatcher. Returns a compact summary dict suitable for
    inclusion in ``per_store[i]["execution"]``.

    Failure-safe: any raise becomes ``{"error": "..."}``;
    reliability-gate refusal becomes
    ``{"refused": "reliability"}`` with the ineligible
    capability list.
    """
    try:
        from core.capability_executor import (
            CapabilityExecutor,
        )
        from core.context import active_store
    except Exception as exc:  # noqa: BLE001
        return {"error": f"import_failed: {exc}"}

    # Reliability gate (when configured)
    if require_reliable and yes:
        try:
            from core.autonomous.controller import (
                _compute_auto_execute_eligibility,
            )
            elig = _compute_auto_execute_eligibility(plan)
        except Exception as exc:  # noqa: BLE001
            return {"error": f"eligibility_failed: {exc}"}
        ineligible = [
            s for s in (elig.get("steps") or [])
            if not s.get("eligible")
        ]
        if ineligible:
            return {
                "refused": "reliability",
                "ineligible_count": len(ineligible),
                "ineligible": [
                    s.get("capability", "")
                    for s in ineligible
                ],
            }

    executor = CapabilityExecutor()
    steps_out: list[dict[str, Any]] = []
    overall_ok = True
    prior_results: dict[str, Any] = {}

    try:
        with active_store(sid):
            for step in plan.steps:
                args_dict = dict(step.suggested_args or {})
                if (
                    yes
                    and step.pipe_from
                    and step.pipe_as
                    and step.pipe_from in prior_results
                ):
                    args_dict[step.pipe_as] = (
                        prior_results[step.pipe_from]
                    )
                if yes:
                    result = executor.execute(
                        step.capability_name, args_dict,
                    )
                else:
                    result = executor.dry_run(
                        step.capability_name, args_dict,
                    )
                steps_out.append(result.to_dict())
                if result.ok and result.data is not None:
                    prior_results[
                        step.capability_name
                    ] = result.data
                if not result.ok and (
                    result.invocation_kind
                    != "cli_handler"
                ):
                    overall_ok = False
                    break
    except Exception as exc:  # noqa: BLE001
        return {"error": f"execute_raised: {exc}"}

    return {
        "executed": yes,
        "ok": overall_ok,
        "steps_run": len(steps_out),
    }


def _cmd_fleet_plan(args) -> None:
    """Empire-scale planner. For each store in the fleet,
    runs the planner -- either with the supplied goal
    phrase, or in audit-driven mode (consumes each store's
    failing audit checks).

    Output: per-store plan + a fleet-level summary
    (how many stores ready, how many need each kind of
    action).

    Read-only -- doesn't execute. Operators wanting to
    execute per-store should use ``shopai plan <goal>
    --execute --store <id>`` after reviewing the fleet
    plan.
    """
    as_json = bool(getattr(args, "json", False))
    goal = (getattr(args, "goal", "") or "").strip()
    execute = bool(getattr(args, "execute", False))
    yes = bool(getattr(args, "yes", False))
    require_reliable = bool(
        getattr(args, "require_reliable", False),
    )

    try:
        from core.capability_planner import (
            plan_for_audit_gaps,
            plan_for_goal,
        )
        from core.context import active_store
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "fleet-plan: import failed: %s", exc,
        )
        if as_json:
            print(json.dumps({
                "ok": False,
                "error": "planner_unavailable",
                "message": str(exc),
            }, indent=2))
        else:
            print(f"fleet-plan unavailable: {exc}")
        return

    sm = _get_store_manager()
    stores = sm.list_stores() or []

    per_store: list[dict] = []
    for s in stores:
        sid = s.get("store_id") or ""
        if not sid:
            continue
        plan: object | None = None
        try:
            with active_store(sid):
                if goal:
                    plan = plan_for_goal(goal)
                else:
                    # Audit-driven: consume this store's
                    # failing audit checks.
                    from engines.store_setup.launch_audit \
                        import audit_store
                    audit = audit_store(store_id=sid)
                    failing = [
                        c.get("key", "")
                        for c in (audit.get("checks") or [])
                        if not c.get("ok")
                    ]
                    plan = plan_for_audit_gaps(failing)
        except Exception as exc:  # noqa: BLE001
            logger.debug(
                "fleet-plan: store %s raised: %s", sid, exc,
            )
            per_store.append({
                "store_id": sid,
                "error": str(exc),
                "plan": None,
            })
            continue

        entry: dict[str, Any] = {
            "store_id": sid,
            "shop_url": s.get("shop_url", ""),
            "niche": s.get("niche") or None,
            "plan": plan.to_dict() if plan else None,
        }

        # Optional per-store execution.
        if execute and plan and (plan.steps or []):
            entry["execution"] = (
                _fleet_execute_one_store(
                    sid=sid,
                    plan=plan,
                    yes=yes,
                    require_reliable=require_reliable,
                )
            )

        per_store.append(entry)

    # Fleet rollup
    needs_action = [
        p for p in per_store
        if p.get("plan") and p["plan"].get("steps")
    ]
    rollup = {
        "stores_total": len(per_store),
        "stores_with_plan": len(needs_action),
        "stores_clean": len([
            p for p in per_store
            if p.get("plan") and not p["plan"].get("steps")
        ]),
        "stores_errored": len([
            p for p in per_store if p.get("error")
        ]),
    }
    # Execution rollup when --execute was set
    if execute:
        executions = [
            p["execution"] for p in per_store
            if isinstance(p.get("execution"), dict)
        ]
        rollup["executions"] = {
            "total": len(executions),
            "ok": sum(
                1 for e in executions if e.get("ok")
            ),
            "refused_reliability": sum(
                1 for e in executions
                if e.get("refused") == "reliability"
            ),
            "errored": sum(
                1 for e in executions if e.get("error")
            ),
        }

    if as_json:
        print(json.dumps({
            "goal": goal or "(audit-driven)",
            "rollup": rollup,
            "stores": per_store,
        }, indent=2, default=str))
        return

    # Text view
    label = goal or "(audit-driven)"
    print(f"Fleet plan -- goal: {label}")
    print(
        f"  Stores: {rollup['stores_total']}  "
        f"with-plan={rollup['stores_with_plan']}  "
        f"clean={rollup['stores_clean']}  "
        f"errored={rollup['stores_errored']}"
    )
    print()
    if execute and rollup.get("executions"):
        e = rollup["executions"]
        print(
            f"  Executions: ok={e['ok']}  "
            f"refused={e['refused_reliability']}  "
            f"errored={e['errored']}"
        )
    print()
    for p in per_store:
        sid = p.get("store_id", "?")
        if p.get("error"):
            print(f"  {sid}: ERROR ({p['error']})")
            continue
        plan_d = p.get("plan") or {}
        steps = plan_d.get("steps") or []
        cli_seq = plan_d.get("cli_sequence") or []
        if not steps:
            print(f"  {sid}: clean")
            continue
        # Execution outcome surface inline
        exec_summary = ""
        if execute and isinstance(
            p.get("execution"), dict,
        ):
            ex = p["execution"]
            if ex.get("refused") == "reliability":
                exec_summary = (
                    f"  [REFUSED reliability: "
                    f"{ex.get('ineligible_count', 0)} "
                    "step(s)]"
                )
            elif ex.get("error"):
                exec_summary = (
                    f"  [ERR: "
                    f"{str(ex['error'])[:40]}]"
                )
            elif ex.get("ok"):
                exec_summary = (
                    f"  [OK: ran {ex.get('steps_run', 0)} "
                    "step(s)]"
                )
            else:
                exec_summary = (
                    f"  [FAIL after "
                    f"{ex.get('steps_run', 0)} step(s)]"
                )
        print(f"  {sid}: {len(steps)} step(s){exec_summary}")
        for cmd in cli_seq[:2]:
            print(f"    $ {cmd}")


def _run_plan_multi_step(
    plan, *, yes: bool, as_json: bool,
    store_id: str | None = None,
    pre_audit_failing: set | None = None,
    require_reliable: bool = False,
) -> None:
    """Execute each step of a plan via the in-process
    capability executor, using ``suggested_args`` from the
    plan as kwargs.

    Steps whose module_path is a CLI handler are SKIPPED
    (the executor refuses them). Stops at the first
    invocation failure. Each step's outcome is captured +
    emitted in the per-step result.

    The execution is wrapped in ``active_store(store_id)``
    when a store_id is supplied (or available from the
    active store thread-local). This ensures per-store-aware
    capabilities (Pattern Z recording, world_model probes)
    see the right scope.

    Default DRY-RUN. With --yes, actually invokes; without,
    just resolves each step's module + reports.
    """
    try:
        from core.capability_executor import (
            CapabilityExecutor,
        )
        from contextlib import nullcontext
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "plan --execute: executor import failed: %s",
            exc,
        )
        if as_json:
            print(json.dumps({
                "ok": False,
                "error": "executor_unavailable",
                "message": str(exc),
            }, indent=2))
        else:
            print(f"executor unavailable: {exc}")
        sys.exit(1)

    # Resolve the per-store scope context manager. Missing
    # store_id -> nullcontext (no-op). Lazy import so the
    # planner stays usable in environments without
    # core.context available.
    if store_id:
        try:
            from core.context import active_store
            scope = active_store(store_id)
        except Exception as exc:  # noqa: BLE001
            logger.debug(
                "plan --execute: active_store import "
                "raised: %s", exc,
            )
            scope = nullcontext()
    else:
        scope = nullcontext()

    # ── Reliability gate (when --require-reliable) ─────
    # Refuse to execute when ANY step's history fails the
    # gate. Uses the same eligibility logic as Phase 2c.
    if require_reliable and yes:
        try:
            from core.autonomous.controller import (
                _compute_auto_execute_eligibility,
            )
            elig = _compute_auto_execute_eligibility(plan)
        except Exception as exc:  # noqa: BLE001
            logger.debug(
                "plan --require-reliable: import raised: "
                "%s", exc,
            )
            elig = {
                "steps": [], "threshold": 0.9,
                "min_sample": 5,
            }
        ineligible = [
            s for s in (elig.get("steps") or [])
            if not s.get("eligible")
        ]
        if ineligible:
            payload = {
                "ok": False,
                "error": "reliability_gate_failed",
                "ineligible_steps": ineligible,
                "threshold": elig.get("threshold"),
                "min_sample": elig.get("min_sample"),
            }
            if as_json:
                print(json.dumps(
                    payload, indent=2, default=str,
                ))
            else:
                print(
                    "Reliability gate refused: "
                    f"{len(ineligible)} step(s) below "
                    "threshold."
                )
                for s in ineligible[:5]:
                    rate_pct = (
                        s.get("success_rate", 0.0) * 100
                    )
                    thr = elig.get("threshold", 0.9) * 100
                    print(
                        f"  - {s['capability']}: "
                        f"{rate_pct:.1f}% "
                        f"over {s.get('executed_count', 0)} "
                        "past run(s) "
                        f"(need {thr:.0f}% @ sample >= "
                        f"{elig.get('min_sample', 5)})"
                    )
                if len(ineligible) > 5:
                    print(
                        f"  ... +{len(ineligible) - 5} "
                        "more"
                    )
                print()
                print(
                    "Drop --require-reliable to force "
                    "execution, OR populate plan_history "
                    "by running these capabilities "
                    "manually first."
                )
            sys.exit(1)

    executor = CapabilityExecutor()
    steps_out: list[dict] = []
    overall_ok = True
    # Map capability_name -> last successful result.data for
    # composition piping.
    prior_results: dict = {}

    # Pre-execution stats snapshot for outcome correlation.
    # Captured here (not in record_plan_invocation) so the
    # invocation call stays decoupled from StoreManager.
    pre_stats: dict[str, Any] = {}
    if yes and store_id:
        try:
            sm = _get_store_manager()
            pre_stats = sm.get_stats(store_id) or {}
        except Exception as exc:  # noqa: BLE001
            logger.debug(
                "plan: pre_stats capture raised: %s", exc,
            )

    # Record this plan invocation BEFORE executing -- gives
    # us an event_id we can update post-execution with the
    # actual outcome (success / partial / fail / skipped).
    # No-op under pytest (Pattern J guard inside).
    history_event_id = ""
    try:
        from core.capability_planner import (
            record_plan_invocation,
        )
        history_event_id = record_plan_invocation(
            goal=plan.goal,
            plan=plan,
            store_id=str(store_id or ""),
            executed=yes,
            pre_stats=pre_stats,
        )
    except Exception as exc:  # noqa: BLE001
        logger.debug(
            "plan history: record_invocation raised: %s",
            exc,
        )

    with scope:
        for step in plan.steps:
            args_dict = dict(step.suggested_args or {})
            # Composition piping: replace the kwarg named in
            # step.pipe_as with the actual output of the
            # capability named in step.pipe_from -- when
            # that prior step succeeded and we're in --yes
            # mode (dry-run has no real prior data).
            if (
                yes
                and step.pipe_from
                and step.pipe_as
                and step.pipe_from in prior_results
            ):
                args_dict[step.pipe_as] = prior_results[
                    step.pipe_from
                ]
            if yes:
                result = executor.execute(
                    step.capability_name, args_dict,
                )
            else:
                result = executor.dry_run(
                    step.capability_name, args_dict,
                )
            steps_out.append(result.to_dict())
            # Track successful step outputs for downstream
            # piping.
            if result.ok and result.data is not None:
                prior_results[
                    step.capability_name
                ] = result.data
            # CLI handler refusals don't break the chain --
            # they're informational. Real failures (raise,
            # bad args) do stop the chain.
            if not result.ok and (
                result.invocation_kind != "cli_handler"
            ):
                overall_ok = False
                break

    # Record the outcome of this plan invocation. Outcome
    # semantics:
    #   skipped     -- dry-run only (no --yes)
    #   fail        -- execution failed
    #   executed_ok -- steps OK; audit closure not verified
    #   success     -- audit verified: pre-execution gaps
    #                  all closed
    #   partial     -- audit verified: some gaps closed,
    #                  others remain
    #   no_change   -- audit verified: no gaps closed
    #                  despite execution
    #
    # The success / partial / no_change outcomes only fire
    # when ``pre_audit_failing`` was supplied (i.e. the
    # operator used --close-audit-gaps mode). For free-form
    # goal plans we can't easily verify audit-based closure
    # so the outcome stays at executed_ok.
    outcome = ""
    outcome_notes = ""
    if history_event_id:
        if not yes:
            outcome = "skipped"
        elif not overall_ok:
            outcome = "fail"
        elif pre_audit_failing:
            # Post-execution audit verification.
            try:
                from engines.store_setup.launch_audit \
                    import audit_store
                post_audit = audit_store(
                    store_id=store_id,
                )
                still_failing = {
                    c.get("key", "")
                    for c in (
                        post_audit.get("checks") or []
                    )
                    if not c.get("ok")
                }
                closed = pre_audit_failing - still_failing
                remaining = (
                    pre_audit_failing & still_failing
                )
                outcome_notes = (
                    f"closed {len(closed)} of "
                    f"{len(pre_audit_failing)} gaps; "
                    f"completion_pct: "
                    f"{post_audit.get('completion_pct', 0)}"
                )
                if not closed:
                    outcome = "no_change"
                elif remaining:
                    outcome = "partial"
                else:
                    outcome = "success"
            except Exception as exc:  # noqa: BLE001
                logger.debug(
                    "plan history: post-audit raised: %s",
                    exc,
                )
                outcome = "executed_ok"
        else:
            outcome = "executed_ok"
        try:
            from core.capability_planner import (
                record_outcome,
            )
            record_outcome(
                history_event_id, outcome,
                notes=outcome_notes,
            )
        except Exception as exc:  # noqa: BLE001
            logger.debug(
                "plan history: record_outcome raised: %s",
                exc,
            )

    if as_json:
        print(json.dumps({
            "goal": plan.goal,
            "executed": yes,
            "ok": overall_ok,
            "history_event_id": history_event_id,
            "steps": steps_out,
        }, indent=2, default=str))
        if not overall_ok:
            sys.exit(1)
        return

    mode = "EXECUTED" if yes else "DRY-RUN"
    print(f"Plan {mode}: {plan.goal}")
    print()
    for i, step_res in enumerate(steps_out, start=1):
        mark = "OK  " if step_res["ok"] else "FAIL"
        if step_res.get("invocation_kind") == "cli_handler":
            mark = "SKIP"
        print(
            f"  {i}. [{mark}] {step_res['capability']}  "
            f"({step_res.get('invocation_kind', '-')})"
        )
        if step_res.get("error"):
            print(f"        error: {step_res['error']}")
        if (
            yes and step_res["ok"]
            and step_res.get("data") is not None
        ):
            # Render a one-line summary of the result
            d = step_res["data"]
            if isinstance(d, list):
                print(
                    f"        result: list of "
                    f"{len(d)} items"
                )
            elif isinstance(d, dict):
                keys = ", ".join(list(d.keys())[:5])
                print(
                    f"        result: dict with keys "
                    f"{{{keys}}}"
                )
            else:
                preview = str(d)[:80]
                print(f"        result: {preview}")
    print()
    if not yes:
        print(
            "Dry-run only. Pass --yes to actually invoke "
            "each step."
        )
    elif not overall_ok:
        sys.exit(1)


def _render_plan_as_context(plan) -> None:
    """Render a Plan as an LLM-ready markdown block.

    Operators feeding the plan to a downstream LLM (Claude
    API, ChatGPT, sub-agent prompt) get a structured but
    prose-style context. Each step includes the capability's
    full registry record (description / when_to_use /
    inputs / outputs / example_input / scopes_used) so the
    downstream LLM has everything it needs to reason about
    the plan without re-querying the registry.
    """
    from core.capability_registry import get_registry
    registry = get_registry()
    print(f"# Plan for: {plan.goal}")
    print()
    if plan.is_empty():
        print("> No matching capabilities in registry.")
        for n in plan.notes:
            print(f"- *{n}*")
        return
    if plan.audit_coverage:
        print(
            f"**Audit coverage:** "
            f"{', '.join(plan.audit_coverage)}"
        )
        print()
    print(f"## Steps ({len(plan.steps)})")
    print()
    for i, step in enumerate(plan.steps, start=1):
        cap = registry.get(step.capability_name)
        print(
            f"### {i}. `{step.capability_name}` "
            f"({step.role})"
        )
        print()
        print(step.description)
        if cap and cap.when_to_use:
            print()
            print(f"**When to use:** {cap.when_to_use}")
        if step.cli_command:
            print()
            print(f"**CLI:** `{step.cli_command}`")
        if step.closes_audits:
            print()
            print(
                f"**Closes audit checks:** "
                f"{', '.join(step.closes_audits)}"
            )
        if cap and cap.inputs:
            print()
            print("**Inputs:**")
            for k, v in cap.inputs.items():
                print(f"  - `{k}`: {v}")
        if cap and cap.outputs:
            print()
            print("**Outputs:**")
            for k, v in cap.outputs.items():
                print(f"  - `{k}`: {v}")
        if cap and cap.example_input:
            print()
            print("**Example input:**")
            print("```json")
            print(json.dumps(cap.example_input, indent=2))
            print("```")
        if cap and cap.scopes_used:
            print()
            print(
                f"**Shopify scopes:** "
                f"{', '.join(cap.scopes_used)}"
            )
        if cap and cap.side_effects:
            print()
            print("**Side effects:**")
            for se in cap.side_effects:
                print(f"  - {se}")
        print()
    if plan.cli_sequence:
        print("## Run")
        print()
        print("```bash")
        for c in plan.cli_sequence:
            print(c)
        print("```")
        print()
    if plan.notes:
        print("## Notes")
        print()
        for n in plan.notes:
            print(f"- {n}")


def _cmd_capabilities(args) -> None:
    """Query the substrate capability registry.

    Three sub-actions:
      - ``list``: enumerate every registered capability, with
        optional kind/tag/closes-audit filters.
      - ``show <name>``: full registration for one capability.
      - ``find <query>``: free-form substring search across
        name + description + when_to_use + tags.

    The capabilities catalog is what lets an LLM planner (and
    Claude during a task) discover "what fits this goal?"
    without grepping filenames.
    """
    try:
        from core.capability_registry.bootstrap import (
            ensure_registered,
        )
        from core.capability_registry import get_registry
    except Exception as exc:  # noqa: BLE001
        logger.debug("capability_registry import failed: %s", exc)
        print(f"capability registry unavailable: {exc}")
        return

    ensure_registered()
    registry = get_registry()
    action = getattr(args, "capability_action", None) or "list"
    as_json = bool(getattr(args, "json", False))

    if action == "list":
        results = registry.find(
            kind=getattr(args, "kind", None),
            tag=getattr(args, "tag", None),
            closes_audit=getattr(args, "closes_audit", None),
        )
        if as_json:
            print(json.dumps(
                [c.to_dict() for c in results],
                indent=2, default=str,
            ))
            return
        if not results:
            print("No capabilities matched the filters.")
            return
        print(
            f"Capabilities ({len(results)}/"
            f"{registry.count()} registered):"
        )
        print()
        for c in results:
            tags = (
                f"  [{', '.join(c.tags)}]" if c.tags else ""
            )
            print(f"  {c.name:<32} {c.kind:<14}{tags}")
            print(f"    -> {c.description}")
        return

    if action == "show":
        cap = registry.get(args.name)
        if cap is None:
            if as_json:
                print(json.dumps({
                    "ok": False,
                    "error": "not_found",
                    "name": args.name,
                }, indent=2))
            else:
                print(f"Unknown capability: {args.name}")
                similar = registry.find(query=args.name)
                if similar:
                    print()
                    print("Did you mean:")
                    for s in similar[:5]:
                        print(f"  {s.name}")
            sys.exit(1)

        # Operational state: reliability + revenue impact +
        # override status + bridge annotation. Cheap local-
        # file reads. Fail-open: each subsystem missing
        # degrades silently to its empty value.
        operational: dict[str, Any] = {
            "reliability": None,
            "revenue_impact": None,
            "override": None,
            "bridge_status": None,
        }
        try:
            from core.capability_planner import (
                capability_leaderboard,
                capability_revenue_impact,
                capability_degradations,
            )
            from core.capability_planner.\
capability_overrides import load_overrides
            from core.capability_planner import auto_demote
            # Reliability -- our cap might be below default
            # leaderboard min_sample_size, so query with =1
            # then filter.
            try:
                rel_rows = capability_leaderboard(
                    since_seconds=86400 * 30,
                    min_sample_size=1,
                    top_n=1000,
                )
                for r in rel_rows:
                    if r["capability"] == cap.name:
                        operational["reliability"] = r
                        break
            except Exception as exc:  # noqa: BLE001
                logger.debug(
                    "capability show reliability "
                    "raised: %s", exc,
                )
            # Revenue impact
            try:
                rev_rows = capability_revenue_impact(
                    since_seconds=86400 * 30,
                    min_sample_size=1,
                    top_n=1000,
                )
                for r in rev_rows:
                    if r["capability"] == cap.name:
                        operational["revenue_impact"] = r
                        break
            except Exception as exc:  # noqa: BLE001
                logger.debug(
                    "capability show revenue raised: %s",
                    exc,
                )
            # Override status
            try:
                overrides = load_overrides()
                entry = overrides.get(cap.name)
                if entry is not None:
                    operational["override"] = {
                        "kind": entry.kind,
                        "reason": entry.reason,
                        "recorded_at": entry.recorded_at,
                    }
            except Exception as exc:  # noqa: BLE001
                logger.debug(
                    "capability show override raised: %s",
                    exc,
                )
            # Bridge status -- if this cap appears in recent
            # degradations, surface its tier.
            try:
                degs = capability_degradations(
                    recent_window_seconds=86400 * 7,
                    baseline_window_seconds=86400 * 30,
                )
                degs = auto_demote.annotate_degradations(
                    degs,
                )
                for d in degs:
                    if d["capability"] == cap.name:
                        operational["bridge_status"] = {
                            "tier": d.get(
                                "bridge_status",
                            ),
                            "baseline_rate": d[
                                "baseline_rate"
                            ],
                            "recent_rate": d["recent_rate"],
                            "drop": d["drop"],
                        }
                        break
            except Exception as exc:  # noqa: BLE001
                logger.debug(
                    "capability show bridge raised: %s",
                    exc,
                )
        except ImportError as exc:
            logger.debug(
                "capability show operational import "
                "failed: %s", exc,
            )

        if as_json:
            envelope = cap.to_dict()
            envelope["operational"] = operational
            print(json.dumps(
                envelope, indent=2, default=str,
            ))
            return
        print(f"{cap.name}")
        print(f"  kind:        {cap.kind}")
        print(f"  module:      {cap.module_path}")
        print(f"  description: {cap.description}")
        print(f"  when to use: {cap.when_to_use}")
        if cap.tags:
            print(f"  tags:        {', '.join(cap.tags)}")
        if cap.scopes_used:
            print(
                f"  scopes:      {', '.join(cap.scopes_used)}"
            )
        if cap.audit_checks_closed:
            print(
                f"  closes:      "
                f"{', '.join(cap.audit_checks_closed)}"
            )
        if cap.composes_with:
            print(
                f"  composes:    "
                f"{', '.join(cap.composes_with)}"
            )
        if cap.cli_commands:
            print(
                f"  cli:         "
                f"{', '.join(cap.cli_commands)}"
            )
        if cap.side_effects:
            print("  side effects:")
            for se in cap.side_effects:
                print(f"    - {se}")
        if cap.example_input:
            print("  example input:")
            for k, v in cap.example_input.items():
                print(f"    {k}: {v}")
        # Operational state rendered only when at least one
        # signal exists. Silent on a brand-new capability
        # with no history.
        any_op = any(
            v is not None for v in operational.values()
        )
        if any_op:
            print()
            print("  Operational state (last 30 days):")
            rel = operational["reliability"]
            if rel:
                pct = rel["success_rate"] * 100
                print(
                    f"    Reliability: {pct:.1f}% "
                    f"({rel['success_count']}/"
                    f"{rel['executed_count']} runs)"
                )
            rev = operational["revenue_impact"]
            if rev:
                arrow = (
                    "+" if rev["total_revenue_delta"] >= 0
                    else ""
                )
                print(
                    f"    Revenue:     "
                    f"{arrow}${rev['total_revenue_delta']:,.2f} "
                    f"total (avg "
                    f"{arrow}${rev['avg_revenue_delta']:,.2f}, "
                    f"n={rev['sample_size']})"
                )
            ov = operational["override"]
            if ov:
                tag = (
                    "PROMOTE" if ov["kind"] == "promote"
                    else "DEMOTE"
                )
                if (
                    ov["kind"] == "demote"
                    and ov["reason"].startswith(
                        "auto_demote_degraded",
                    )
                ):
                    tag = "DEMOTE/AUTO"
                reason_tag = (
                    f"  ({ov['reason'][:60]})"
                    if ov["reason"] else ""
                )
                print(
                    f"    Override:    [{tag}]{reason_tag}"
                )
            bs = operational["bridge_status"]
            if bs:
                tier = bs["tier"] or ""
                drop_pp = bs["drop"] * 100
                print(
                    f"    Bridge:      [{tier.upper()}] "
                    f"recent {bs['recent_rate']*100:.0f}% "
                    f"vs baseline {bs['baseline_rate']*100:.0f}% "
                    f"(-{drop_pp:.0f}pp)"
                )
        # Drill-down hint: operator just inspected the
        # registration -- natural next move is `capabilities
        # run <name>` to actually invoke it (default dry-run).
        print()
        print(
            f"  Next: `shopai capabilities run {cap.name}` "
            "(dry-run; add --yes to invoke)."
        )
        return

    if action in ("promote", "demote"):
        try:
            from core.capability_planner.\
capability_overrides import (
                demote as _do_demote,
                promote as _do_promote,
            )
        except Exception as exc:  # noqa: BLE001
            logger.debug(
                "%s: import failed: %s", action, exc,
            )
            print(f"{action} unavailable: {exc}")
            return
        # Validate the capability exists in the registry
        # so operator typos surface immediately.
        cap = registry.get(args.name)
        if cap is None:
            if as_json:
                print(json.dumps({
                    "ok": False,
                    "error": "unknown_capability",
                    "name": args.name,
                }, indent=2))
            else:
                print(f"Unknown capability: {args.name}")
            sys.exit(1)
        reason = getattr(args, "reason", "") or ""
        fn = _do_promote if action == "promote" else _do_demote
        ok = fn(args.name, reason=reason)
        if as_json:
            print(json.dumps({
                "ok": ok,
                "action": action,
                "name": args.name,
                "reason": reason,
            }, indent=2))
            return
        if ok:
            print(
                f"Capability {action}d: {args.name}"
                + (f"  ({reason})" if reason else "")
            )
        else:
            print(
                f"Failed to {action} {args.name} "
                "(test environment or I/O error)."
            )
        return

    if action == "clear-override":
        try:
            from core.capability_planner.\
capability_overrides import clear as _do_clear
        except Exception as exc:  # noqa: BLE001
            logger.debug(
                "clear-override: import failed: %s", exc,
            )
            print(
                f"clear-override unavailable: {exc}"
            )
            return
        ok = _do_clear(args.name)
        if as_json:
            print(json.dumps({
                "ok": ok,
                "action": "clear-override",
                "name": args.name,
            }, indent=2))
            return
        if ok:
            print(f"Override cleared: {args.name}")
        else:
            print(
                f"No override found for {args.name} "
                "(or test environment)."
            )
        return

    if action == "overrides":
        try:
            from core.capability_planner.\
capability_overrides import load_overrides
        except Exception as exc:  # noqa: BLE001
            logger.debug(
                "overrides: import failed: %s", exc,
            )
            print(f"overrides unavailable: {exc}")
            return
        overrides = load_overrides()
        rows = [
            {
                "name": e.name,
                "kind": e.kind,
                "reason": e.reason,
                "recorded_at": e.recorded_at,
            }
            for e in overrides.entries
        ]
        if as_json:
            print(json.dumps(rows, indent=2, default=str))
            return
        if not rows:
            print(
                "No operator overrides set. Use "
                "``shopai capabilities promote <name>`` "
                "or ``demote <name>`` to add."
            )
            return
        print(f"Operator overrides ({len(rows)}):")
        for r in rows:
            kind_tag = (
                "[PROMOTE]" if r["kind"] == "promote"
                else "[DEMOTE]"
            )
            line = f"  {kind_tag} {r['name']}"
            if r["reason"]:
                line += f"  -- {r['reason']}"
            print(line)
        return

    if action == "reliability":
        try:
            from core.capability_planner import (
                capability_leaderboard,
            )
        except Exception as exc:  # noqa: BLE001
            logger.debug(
                "capability reliability: import "
                "failed: %s", exc,
            )
            print(f"reliability unavailable: {exc}")
            return
        window_days = max(
            1, int(
                getattr(args, "window_days", 30) or 30,
            ),
        )
        min_sample = max(
            1, int(
                getattr(args, "min_sample_size", 2) or 2,
            ),
        )
        top = max(1, int(getattr(args, "top", 20) or 20))
        rows = capability_leaderboard(
            since_seconds=window_days * 86400,
            min_sample_size=min_sample,
            top_n=top,
        )
        if as_json:
            print(json.dumps({
                "window_days": window_days,
                "min_sample_size": min_sample,
                "rows": rows,
            }, indent=2))
            return
        if not rows:
            print(
                f"No capability reliability data in the "
                f"last {window_days} day(s) (need >= "
                f"{min_sample} executed appearance(s) per "
                f"capability)."
            )
            return
        print(
            f"Capability reliability "
            f"(last {window_days} day(s), min sample "
            f"{min_sample}):"
        )
        print()
        for i, r in enumerate(rows, start=1):
            pct = r["success_rate"] * 100
            print(
                f"  {i:>3}. {pct:>5.1f}%  "
                f"({r['success_count']:>3}/"
                f"{r['executed_count']:<3})  "
                f"{r['capability']}"
            )
        return

    if action == "revenue-impact":
        try:
            from core.capability_planner import (
                capability_revenue_impact,
            )
        except Exception as exc:  # noqa: BLE001
            logger.debug(
                "revenue-impact: import failed: %s", exc,
            )
            print(f"revenue-impact unavailable: {exc}")
            return
        window_days = max(
            1, int(getattr(args, "window_days", 30) or 30),
        )
        min_sample = max(
            1, int(
                getattr(args, "min_sample_size", 1) or 1,
            ),
        )
        top = max(1, int(getattr(args, "top", 20) or 20))
        rows = capability_revenue_impact(
            since_seconds=window_days * 86400,
            min_sample_size=min_sample,
            top_n=top,
        )
        if as_json:
            print(json.dumps({
                "window_days": window_days,
                "min_sample_size": min_sample,
                "rows": rows,
            }, indent=2, default=str))
            return
        if not rows:
            print(
                f"No correlated revenue impact in the last "
                f"{window_days} day(s). Run "
                f"``shopai plan --auto-correlate`` after a "
                f"measurement window passes to populate."
            )
            return
        print(
            f"Capability revenue impact "
            f"(last {window_days} day(s); attribution = "
            f"full delta to each cap in plan):"
        )
        print()
        total_revenue_delta = sum(
            r["total_revenue_delta"] for r in rows
        )
        for i, r in enumerate(rows, start=1):
            arrow = "↑" if r["total_revenue_delta"] > 0 else (
                "↓" if r["total_revenue_delta"] < 0 else "·"
            )
            print(
                f"  {i:>3}. {arrow} "
                f"${r['total_revenue_delta']:>10,.2f}  "
                f"avg ${r['avg_revenue_delta']:>8,.2f}  "
                f"n={r['sample_size']:>3} "
                f"(+{r['positive_count']} / "
                f"-{r['negative_count']})  "
                f"{r['capability']}"
            )
        print()
        print(
            f"  Total attributed: "
            f"${total_revenue_delta:,.2f} across "
            f"{len(rows)} capabilit(ies)"
        )
        return

    if action == "auto-demote-history":
        try:
            from core.capability_planner import (
                auto_demote_history as _ah,
            )
        except Exception as exc:  # noqa: BLE001
            logger.debug(
                "auto-demote-history: import failed: %s",
                exc,
            )
            print(
                f"auto-demote-history unavailable: {exc}"
            )
            return
        window_days = max(
            1, int(getattr(args, "window_days", 7) or 7),
        )
        limit = max(1, int(getattr(args, "limit", 50) or 50))
        thrashing_only = bool(
            getattr(args, "thrashing", False),
        )

        if thrashing_only:
            rows = _ah.find_thrashing(
                window_seconds=window_days * 86400,
            )
            if as_json:
                print(json.dumps({
                    "window_days": window_days,
                    "thrashing": rows,
                }, indent=2, default=str))
                return
            print(
                f"Thrashing capabilities "
                f"(last {window_days} day(s), "
                f"min 2 demotes):"
            )
            print()
            if not rows:
                print(
                    "None. No capability has been "
                    "demoted multiple times in the "
                    "window."
                )
                return
            for r in rows:
                print(
                    f"  {r['capability']}: "
                    f"{r['demote_count']} demote(s), "
                    f"{r['release_count']} release(s)"
                )
            return

        events = _ah.recent_history(
            since_seconds=window_days * 86400,
        )
        events = events[:limit]
        if as_json:
            print(json.dumps({
                "window_days": window_days,
                "events": [
                    {
                        "kind": e.kind,
                        "capability": e.capability,
                        "reason": e.reason,
                        "recorded_at": e.recorded_at,
                    }
                    for e in events
                ],
            }, indent=2, default=str))
            return

        print(
            f"Auto-demote history "
            f"(last {window_days} day(s); newest first):"
        )
        print()
        if not events:
            print(
                "No bridge events recorded in the window."
            )
            return
        import datetime as _dt
        for e in events:
            stamp = _dt.datetime.fromtimestamp(
                e.recorded_at,
            ).strftime("%Y-%m-%d %H:%M")
            tag = (
                "[DEMOTE] " if e.kind == "demote"
                else "[RELEASE]"
            )
            reason_short = (
                f"  -- {e.reason[:60]}"
                if e.reason else ""
            )
            print(
                f"  {stamp}  {tag} {e.capability}"
                f"{reason_short}"
            )
        return

    if action == "orphans":
        try:
            from core.capability_planner.\
capability_overrides import (
                load_overrides,
                clear as _clear_override,
            )
        except Exception as exc:  # noqa: BLE001
            print(f"orphans unavailable: {exc}")
            return
        overrides = load_overrides()
        registered = {
            c.name for c in registry.all()
        }
        orphans = [
            e for e in overrides.entries
            if e.name not in registered
        ]
        yes = bool(getattr(args, "yes", False))
        if as_json:
            removed: list[str] = []
            if yes:
                for e in orphans:
                    if _clear_override(e.name):
                        removed.append(e.name)
            print(json.dumps({
                "orphans": [
                    {
                        "name": e.name,
                        "kind": e.kind,
                        "reason": e.reason,
                        "recorded_at": e.recorded_at,
                    }
                    for e in orphans
                ],
                "removed": removed,
                "applied": yes,
            }, indent=2, default=str))
            return
        if not orphans:
            print(
                "No orphan overrides -- every override "
                "references a registered capability."
            )
            return
        print(
            f"Orphan overrides ({len(orphans)}):"
        )
        for e in orphans:
            tag = (
                "PROMOTE" if e.kind == "promote"
                else "DEMOTE"
            )
            line = f"  [{tag}] {e.name}"
            if e.reason:
                line += f"  -- {e.reason[:60]}"
            print(line)
        if yes:
            print()
            removed_names = []
            for e in orphans:
                if _clear_override(e.name):
                    removed_names.append(e.name)
            print(
                f"Removed {len(removed_names)} orphan "
                f"override(s)."
            )
        else:
            print()
            print(
                "  Dry-run only. Re-run with --yes to "
                "remove these orphan overrides."
            )
        return

    if action == "promote-demote-cycles":
        window_days = max(
            1, int(
                getattr(args, "window_days", 14) or 14,
            ),
        )
        min_cycles = max(
            2, int(
                getattr(args, "min_cycles", 2) or 2,
            ),
        )
        try:
            from core.capability_planner import (
                auto_promote as _ap,
            )
            rows = _ap.find_promote_demote_cycles(
                window_seconds=window_days * 86400,
                min_cycles=min_cycles,
            )
        except Exception as exc:  # noqa: BLE001
            logger.debug(
                "promote-demote-cycles raised: %s", exc,
            )
            rows = []
        if as_json:
            print(json.dumps({
                "window_days": window_days,
                "min_cycles": min_cycles,
                "rows": rows,
            }, indent=2, default=str))
            return
        print(
            f"Promote/demote cycles "
            f"(last {window_days}d, min "
            f"{min_cycles} events):"
        )
        print()
        if not rows:
            print(
                "  No capabilities cycling between "
                "promote and demote."
            )
            return
        import datetime as _dt
        for r in rows:
            first = _dt.datetime.fromtimestamp(
                r["first_event_at"],
            ).strftime("%Y-%m-%d %H:%M")
            last = _dt.datetime.fromtimestamp(
                r["last_event_at"],
            ).strftime("%Y-%m-%d %H:%M")
            print(
                f"  {r['capability']}: "
                f"{r['promote_count']}p / "
                f"{r['demote_count']}d  "
                f"({r['total_events']} total)  "
                f"first {first} -> last {last}"
            )
        return

    if action == "lifecycle":
        name = getattr(args, "name", "") or ""
        if not name:
            print("Capability name required.")
            sys.exit(1)
            return
        window_days = max(
            1, int(
                getattr(args, "window_days", 30) or 30,
            ),
        )
        envelope: dict[str, Any] = {
            "capability": name,
            "window_days": window_days,
            "registered": False,
            "current_state": {
                "promoted": False,
                "demoted": False,
                "override_reason": "",
            },
            "reliability": None,
            "revenue_impact": None,
            "promote_events": [],
            "demote_events": [],
            "release_events": [],
            "bridge_status": None,
        }

        # Registry lookup
        try:
            cap_info = registry.get(name)
            if cap_info is not None:
                envelope["registered"] = True
                envelope["registry"] = cap_info.to_dict()
        except Exception as exc:  # noqa: BLE001
            logger.debug(
                "lifecycle: registry raised: %s", exc,
            )

        # Override state
        try:
            from core.capability_planner.\
capability_overrides import load_overrides
            overrides = load_overrides()
            entry = overrides.get(name)
            if entry is not None:
                envelope["current_state"] = {
                    "promoted": entry.kind == "promote",
                    "demoted": entry.kind == "demote",
                    "override_reason": entry.reason or "",
                    "recorded_at": entry.recorded_at,
                }
        except Exception as exc:  # noqa: BLE001
            logger.debug(
                "lifecycle: overrides raised: %s", exc,
            )

        # Reliability + revenue
        try:
            from core.capability_planner import (
                capability_leaderboard,
                capability_revenue_impact,
            )
            for r in capability_leaderboard(
                since_seconds=window_days * 86400,
                min_sample_size=1,
                top_n=1000,
            ):
                if r["capability"] == name:
                    envelope["reliability"] = r
                    break
            for r in capability_revenue_impact(
                since_seconds=window_days * 86400,
                min_sample_size=1,
                top_n=1000,
            ):
                if r["capability"] == name:
                    envelope["revenue_impact"] = r
                    break
        except Exception as exc:  # noqa: BLE001
            logger.debug(
                "lifecycle: leaderboard raised: %s", exc,
            )

        # Promote history
        try:
            from core.capability_planner import (
                auto_promote_history,
            )
            evs = auto_promote_history.recent_history(
                since_seconds=window_days * 86400,
                capability=name,
            )
            envelope["promote_events"] = [
                {
                    "recorded_at": e.recorded_at,
                    "reason": e.reason,
                    "metrics": e.metrics,
                }
                for e in evs
            ]
        except Exception as exc:  # noqa: BLE001
            logger.debug(
                "lifecycle: promote_history raised: %s",
                exc,
            )

        # Demote / release history (auto_demote_history
        # carries both kinds, filter by capability)
        try:
            from core.capability_planner import (
                auto_demote_history,
            )
            for e in auto_demote_history.recent_history(
                since_seconds=window_days * 86400,
            ):
                if e.capability != name:
                    continue
                row = {
                    "recorded_at": e.recorded_at,
                    "reason": e.reason,
                }
                if e.kind == "demote":
                    envelope["demote_events"].append(row)
                elif e.kind == "release":
                    envelope["release_events"].append(row)
        except Exception as exc:  # noqa: BLE001
            logger.debug(
                "lifecycle: demote_history raised: %s",
                exc,
            )

        # Bridge status from degradation annotation
        try:
            from core.capability_planner import (
                auto_demote as _ad,
                capability_degradations,
            )
            degs = capability_degradations(
                recent_window_seconds=86400 * 7,
                baseline_window_seconds=86400 * 30,
            )
            degs = _ad.annotate_degradations(degs)
            for d in degs:
                if d["capability"] == name:
                    envelope["bridge_status"] = {
                        "tier": d.get("bridge_status"),
                        "baseline_rate": d["baseline_rate"],
                        "recent_rate": d["recent_rate"],
                        "drop": d["drop"],
                    }
                    break
        except Exception as exc:  # noqa: BLE001
            logger.debug(
                "lifecycle: degradations raised: %s",
                exc,
            )

        if as_json:
            print(json.dumps(
                envelope, indent=2, default=str,
            ))
            return

        # Text view
        print(f"Lifecycle: {name}")
        print(f"  Window: last {window_days} day(s)")
        if not envelope["registered"]:
            print("  Registered: NO (not in registry)")
        else:
            print("  Registered: yes")

        cs = envelope["current_state"]
        if cs["promoted"]:
            tag = "[PROMOTE]"
            if cs.get("override_reason", "").startswith(
                "auto_promote_reliable",
            ):
                tag = "[PROMOTE/AUTO]"
            print(
                f"  Current:    {tag} "
                f"{cs.get('override_reason', '')[:80]}"
            )
        elif cs["demoted"]:
            tag = "[DEMOTE]"
            if cs.get("override_reason", "").startswith(
                "auto_demote_degraded",
            ):
                tag = "[DEMOTE/AUTO]"
            print(
                f"  Current:    {tag} "
                f"{cs.get('override_reason', '')[:80]}"
            )
        else:
            print("  Current:    (no override)")

        rel = envelope["reliability"]
        if rel:
            print(
                f"  Reliability: {rel['success_rate']*100:.1f}% "
                f"({rel['success_count']}/"
                f"{rel['executed_count']})"
            )
        rev = envelope["revenue_impact"]
        if rev:
            sign = (
                "+" if rev["total_revenue_delta"] >= 0
                else ""
            )
            print(
                f"  Revenue:     "
                f"{sign}${rev['total_revenue_delta']:,.2f} "
                f"(n={rev['sample_size']})"
            )
        bs = envelope["bridge_status"]
        if bs:
            tier = (bs["tier"] or "").upper()
            print(
                f"  Bridge:      [{tier}] "
                f"recent {bs['recent_rate']*100:.0f}% "
                f"vs baseline {bs['baseline_rate']*100:.0f}%"
            )

        # Timeline -- promote events
        prom = envelope["promote_events"]
        if prom:
            print()
            print(f"  Promote events ({len(prom)}):")
            import datetime as _dt
            for e in prom:
                stamp = _dt.datetime.fromtimestamp(
                    e["recorded_at"],
                ).strftime("%Y-%m-%d %H:%M")
                print(f"    {stamp}  {e['reason'][:70]}")

        # Demote events
        dem = envelope["demote_events"]
        if dem:
            print()
            print(f"  Demote events ({len(dem)}):")
            import datetime as _dt
            for e in dem:
                stamp = _dt.datetime.fromtimestamp(
                    e["recorded_at"],
                ).strftime("%Y-%m-%d %H:%M")
                print(f"    {stamp}  {e['reason'][:70]}")

        # Release events
        rel_evs = envelope["release_events"]
        if rel_evs:
            print()
            print(f"  Release events ({len(rel_evs)}):")
            import datetime as _dt
            for e in rel_evs:
                stamp = _dt.datetime.fromtimestamp(
                    e["recorded_at"],
                ).strftime("%Y-%m-%d %H:%M")
                print(f"    {stamp}  {e['reason'][:70]}")

        return

    if action == "winners":
        try:
            from core.capability_planner import (
                capability_revenue_impact,
            )
        except Exception as exc:  # noqa: BLE001
            print(f"winners unavailable: {exc}")
            return
        window_days = max(
            1, int(
                getattr(args, "window_days", 30) or 30,
            ),
        )
        top = max(1, int(getattr(args, "top", 10) or 10))
        min_sample = max(
            1, int(
                getattr(args, "min_sample", 2) or 2,
            ),
        )
        rows = capability_revenue_impact(
            since_seconds=window_days * 86400,
            min_sample_size=min_sample,
            top_n=top * 3,
        )
        # Filter to positive-revenue only
        winners = [
            r for r in rows
            if r["total_revenue_delta"] > 0
        ][:top]
        if as_json:
            print(json.dumps({
                "window_days": window_days,
                "min_sample": min_sample,
                "rows": winners,
            }, indent=2, default=str))
            return
        if not winners:
            print(
                f"No revenue-positive capabilities in "
                f"the last {window_days} day(s)."
            )
            return
        print(
            f"Top revenue winners (last "
            f"{window_days} day(s), min sample "
            f"{min_sample}):"
        )
        print()
        for i, r in enumerate(winners, 1):
            print(
                f"  {i:>3}. +${r['total_revenue_delta']:,.2f}"
                f"  avg +${r['avg_revenue_delta']:,.2f}  "
                f"n={r['sample_size']}  "
                f"({r['positive_count']}/"
                f"{r['sample_size']} positive)  "
                f"{r['capability']}"
            )
        print()
        print(
            "  Consider promoting these caps "
            "(``shopai capabilities promote <name>``) "
            "or transferring to peer stores."
        )
        return

    if action == "watchlist":
        try:
            from core.capability_planner import auto_demote
        except Exception as exc:  # noqa: BLE001
            logger.debug(
                "watchlist: import failed: %s", exc,
            )
            print(f"watchlist unavailable: {exc}")
            return
        recent_days = getattr(args, "recent_days", None)
        baseline_days = getattr(args, "baseline_days", None)
        min_recent = getattr(args, "min_recent", None)

        config = auto_demote.config_summary()
        rows = auto_demote.find_watchlist(
            recent_days=recent_days,
            baseline_days=baseline_days,
            min_recent=min_recent,
        )

        if as_json:
            print(json.dumps({
                "config": config,
                "watchlist": rows,
            }, indent=2, default=str))
            return

        print(
            f"Capability watchlist "
            f"(recent={config['recent_window_days']}d  "
            f"baseline={config['baseline_window_days']}d  "
            f"severe_threshold="
            f"{config['drop_threshold']:.2f}):"
        )
        print()
        if not rows:
            print(
                "No capabilities on the watchlist. The "
                "substrate is healthy at the regression "
                "level."
            )
            return
        print(f"Watching ({len(rows)} capabilit(ies)):")
        for r in rows:
            base_pct = r["baseline_rate"] * 100
            recent_pct = r["recent_rate"] * 100
            drop_pp = r["drop"] * 100
            print(
                f"  {r['capability']}: "
                f"{base_pct:.0f}% baseline -> "
                f"{recent_pct:.0f}% recent "
                f"(-{drop_pp:.0f}pp)  "
                f"({r['recent_samples']} sample(s))"
            )
        print()
        print(
            "Tip: ``shopai capabilities show <name>`` for "
            "details, or ``shopai capabilities reliability "
            "--top 50`` for the full leaderboard."
        )
        return

    if action == "auto-demote-release-candidates":
        try:
            from core.capability_planner import auto_demote
        except Exception as exc:  # noqa: BLE001
            logger.debug(
                "auto-demote-release-candidates: "
                "import failed: %s", exc,
            )
            print(
                f"auto-demote-release-candidates "
                f"unavailable: {exc}"
            )
            return
        yes = bool(getattr(args, "yes", False))
        recovery = getattr(args, "recovery", None)
        min_recent = getattr(args, "min_recent", None)
        recent_days = getattr(args, "recent_days", None)

        config = auto_demote.config_summary()
        candidates = auto_demote.find_release_candidates(
            recovery=recovery,
            min_recent=min_recent,
            recent_days=recent_days,
        )
        if yes:
            released = auto_demote.maybe_release_recovered(
                recovery=recovery,
                min_recent=min_recent,
                recent_days=recent_days,
            )
        else:
            released = []

        if as_json:
            print(json.dumps({
                "applied": yes,
                "config": config,
                "candidates": candidates,
                "released": released,
            }, indent=2, default=str))
            return

        mode = "APPLIED" if yes else "DRY-RUN"
        print(
            f"auto-demote-release-candidates ({mode})"
        )
        print(
            f"  recovery_threshold="
            f"{config['recovery_threshold']:.2f}  "
            f"min_recent={config['min_recent_sample']}  "
            f"recent={config['recent_window_days']}d"
        )
        print()
        if not candidates:
            print(
                "No bridge-demoted capabilities have "
                "recovered above the threshold."
            )
            return
        print(f"Recovered candidates ({len(candidates)}):")
        for c in candidates:
            print(
                f"  {c['recent_rate']*100:>5.1f}%  "
                f"({c['recent_samples']:>3} sample(s))  "
                f"{c['capability']}"
            )
        if yes:
            print()
            if not released:
                print(
                    "No demotes cleared (test environment "
                    "or I/O error)."
                )
            else:
                print(f"Released {len(released)} demote(s):")
                for r in released:
                    print(f"  - {r['capability']}")
        else:
            print()
            print(
                "Dry-run only. Re-run with --yes to clear "
                "the recovered demotes."
            )
        return

    if action == "auto-demote-degraded":
        try:
            from core.capability_planner import auto_demote
        except Exception as exc:  # noqa: BLE001
            logger.debug(
                "auto-demote-degraded: import failed: %s",
                exc,
            )
            print(
                f"auto-demote-degraded unavailable: {exc}"
            )
            return
        yes = bool(getattr(args, "yes", False))
        drop = getattr(args, "drop", None)
        min_recent = getattr(args, "min_recent", None)
        recent_days = getattr(args, "recent_days", None)
        baseline_days = getattr(args, "baseline_days", None)

        config = auto_demote.config_summary()
        candidates = auto_demote.find_demote_candidates(
            drop=drop,
            min_recent=min_recent,
            recent_days=recent_days,
            baseline_days=baseline_days,
        )

        if yes:
            applied = auto_demote.maybe_auto_demote_degraded(
                drop=drop,
                min_recent=min_recent,
                recent_days=recent_days,
                baseline_days=baseline_days,
            )
        else:
            applied = []

        if as_json:
            print(json.dumps({
                "applied": yes,
                "config": config,
                "candidates": candidates,
                "demoted": applied,
            }, indent=2, default=str))
            return

        # Text view
        mode = "APPLIED" if yes else "DRY-RUN"
        gate = "ON" if config["enabled"] else "OFF (env gate)"
        print(
            f"auto-demote-degraded ({mode}) — bridge gate: "
            f"{gate}"
        )
        print(
            f"  drop_threshold={config['drop_threshold']:.2f}  "
            f"min_recent={config['min_recent_sample']}  "
            f"recent={config['recent_window_days']}d  "
            f"baseline={config['baseline_window_days']}d"
        )
        print()
        if not candidates:
            print(
                "No degradation candidates above threshold."
            )
            return
        print(f"Candidates ({len(candidates)}):")
        for c in candidates:
            block = (
                f" [SKIP: {c['blocked_by']}]"
                if c["blocked_by"] else ""
            )
            print(
                f"  -{c['drop']*100:>5.1f}pp  "
                f"baseline={c['baseline_rate']:.2f}/"
                f"{c['baseline_samples']}  "
                f"recent={c['recent_rate']:.2f}/"
                f"{c['recent_samples']}  "
                f"{c['capability']}{block}"
            )
        if yes:
            print()
            if not applied:
                if not config["enabled"]:
                    print(
                        "No demotes applied: bridge gate is "
                        "OFF. Set "
                        "SHOPAI_AUTO_DEMOTE_DEGRADED=1 to "
                        "enable."
                    )
                else:
                    print("No demotes applied.")
            else:
                print(f"Demoted {len(applied)} capabilit(ies):")
                for a in applied:
                    print(f"  - {a['capability']}")
        else:
            print()
            print(
                "Dry-run only. Re-run with --yes to apply "
                "(also requires "
                "SHOPAI_AUTO_DEMOTE_DEGRADED=1)."
            )
        return

    if action == "run":
        try:
            from core.capability_executor import (
                CapabilityExecutor,
            )
        except Exception as exc:  # noqa: BLE001
            logger.debug(
                "capability_executor import failed: %s", exc,
            )
            print(f"executor unavailable: {exc}")
            return
        try:
            raw_args = getattr(args, "args", "{}") or "{}"
            args_dict = json.loads(raw_args)
            if not isinstance(args_dict, dict):
                raise ValueError(
                    "--args must be a JSON object"
                )
        except Exception as exc:  # noqa: BLE001
            print(f"invalid --args JSON: {exc}")
            sys.exit(1)

        execu = CapabilityExecutor()
        yes = bool(getattr(args, "yes", False))
        if yes:
            result = execu.execute(args.name, args_dict)
        else:
            result = execu.dry_run(args.name, args_dict)

        if as_json:
            print(json.dumps(
                result.to_dict(),
                indent=2, default=str,
            ))
            if not result.ok:
                sys.exit(1)
            return

        # ── Text view ──
        status = "OK" if result.ok else "FAIL"
        mode = "EXECUTED" if yes else "DRY-RUN"
        print(
            f"[{status}] {mode} -- {result.capability}"
        )
        if result.module_path:
            print(f"  module:      {result.module_path}")
        if result.invocation_kind:
            print(
                f"  invocation:  {result.invocation_kind}"
            )
        if result.args:
            print(f"  args:        {result.args}")
        if result.error:
            print(f"  error:       {result.error}")
        if yes and result.ok:
            print()
            print("Result:")
            try:
                print(json.dumps(
                    result.data,
                    indent=2, default=str,
                ))
            except Exception:  # noqa: BLE001
                # Non-JSON-serialisable result -- repr it
                print(repr(result.data))
        if not yes and result.ok:
            print()
            print(
                "Dry-run only. Pass --yes to actually "
                "invoke."
            )
        if not result.ok:
            sys.exit(1)
        return

    if action == "tree":
        root = registry.get(args.name)
        if root is None:
            if as_json:
                print(json.dumps({
                    "ok": False,
                    "error": "not_found",
                    "name": args.name,
                }, indent=2))
            else:
                print(f"Unknown capability: {args.name}")
            sys.exit(1)
        # Don't use `or 2` here -- 0 is a valid depth (root
        # only) and `0 or 2` would silently bump it to 2.
        depth_raw = getattr(args, "depth", 2)
        if depth_raw is None:
            depth_raw = 2
        max_depth = max(0, int(depth_raw))

        def _walk_tree(name: str, depth: int,
                       seen: set | None = None) -> dict:
            # Cycle protection: don't re-visit a node we're
            # already mid-rendering.
            seen = (seen or set()) | {name}
            cap = registry.get(name)
            if cap is None:
                return {
                    "name": name, "kind": "?",
                    "children": [],
                }
            children = []
            if depth > 0:
                for peer in cap.composes_with:
                    if peer in seen:
                        continue
                    children.append(
                        _walk_tree(peer, depth - 1, seen),
                    )
            return {
                "name": cap.name,
                "kind": cap.kind,
                "children": children,
            }

        tree = _walk_tree(args.name, max_depth)

        if as_json:
            print(json.dumps(tree, indent=2))
            return

        def _render_tree(node: dict, prefix: str = "",
                         is_last: bool = True) -> None:
            # ASCII connectors -- Windows cp1252 console
            # can't render Unicode box-drawing chars.
            connector = "`-- " if is_last else "|-- "
            print(
                f"{prefix}{connector}{node['name']} "
                f"[{node['kind']}]"
            )
            children = node["children"]
            for i, child in enumerate(children):
                child_prefix = prefix + (
                    "    " if is_last else "|   "
                )
                _render_tree(
                    child, child_prefix,
                    is_last=(i == len(children) - 1),
                )

        # Root: no connector, print + walk children.
        print(f"{tree['name']} [{tree['kind']}]")
        children = tree["children"]
        for i, child in enumerate(children):
            _render_tree(
                child, "",
                is_last=(i == len(children) - 1),
            )
        return

    if action == "stats":
        all_caps = registry.all()
        by_kind: dict[str, int] = {}
        by_tag: dict[str, int] = {}
        audit_coverage: dict[str, list[str]] = {}
        with_cli: list[str] = []
        for c in all_caps:
            by_kind[c.kind] = by_kind.get(c.kind, 0) + 1
            for t in c.tags:
                by_tag[t] = by_tag.get(t, 0) + 1
            for a in c.audit_checks_closed:
                audit_coverage.setdefault(a, []).append(
                    c.name,
                )
            if c.cli_commands:
                with_cli.append(c.name)
        stats = {
            "total": len(all_caps),
            "by_kind": dict(sorted(
                by_kind.items(),
                key=lambda kv: (-kv[1], kv[0]),
            )),
            "by_tag": dict(sorted(
                by_tag.items(),
                key=lambda kv: (-kv[1], kv[0]),
            )),
            "audit_coverage": {
                k: sorted(v)
                for k, v in audit_coverage.items()
            },
            "with_cli_count": len(with_cli),
        }
        if as_json:
            print(json.dumps(stats, indent=2))
            return
        print(f"Substrate registry: {stats['total']} capabilities")
        print()
        print("By kind:")
        for kind, n in stats["by_kind"].items():
            print(f"  {kind:<16} {n}")
        print()
        print("Top tags:")
        for tag, n in list(stats["by_tag"].items())[:10]:
            print(f"  {tag:<24} {n}")
        if stats["audit_coverage"]:
            print()
            print("Audit checks with at least one closer:")
            for k, closers in sorted(
                stats["audit_coverage"].items(),
            ):
                print(
                    f"  {k:<24} "
                    f"-> {', '.join(closers)}"
                )
        print()
        print(
            f"With CLI surface: {stats['with_cli_count']} "
            f"of {stats['total']}"
        )
        return

    if action == "find":
        results = registry.find(query=args.query)
        if as_json:
            print(json.dumps(
                [c.to_dict() for c in results],
                indent=2, default=str,
            ))
            return
        if not results:
            print(f"No capabilities match '{args.query}'.")
            return
        print(
            f"Capabilities matching '{args.query}' "
            f"({len(results)}):"
        )
        print()
        for c in results:
            print(f"  {c.name:<32} -- {c.when_to_use}")
        return

    # Unknown action -> usage hint
    print(
        "Usage: shopai capabilities {list|show|find} ..."
    )
    sys.exit(1)


def _cmd_onboard(args) -> None:
    """Wave 92: autonomous onboarding wizard.

    Single-command chain: register -> sync -> niche-detect
    -> launch -> go-live -> schedule. Each stage delegates
    to existing substrate (Wave 73 niche, Wave 83 detector,
    launch_orchestrator, Wave 55 go-live, Wave 54 cron).
    """
    from engines.store_setup.onboarding_wizard import (
        onboard_store,
    )

    as_json = bool(getattr(args, "json", False))
    dry_run = bool(getattr(args, "dry_run", False))
    api_key = getattr(args, "api_key", "") or ""
    client_id = getattr(args, "client_id", "") or ""
    client_secret = getattr(args, "client_secret", "") or ""
    niche = (getattr(args, "niche", "") or "").strip()

    result = onboard_store(
        store_id=args.store_id,
        shop_url=args.shop_url,
        api_key=api_key,
        client_id=client_id,
        client_secret=client_secret,
        name=getattr(args, "name", "") or "",
        niche=niche,
        store_type=getattr(args, "store_type", "dropshipping"),
        dry_run=dry_run,
    )

    if as_json:
        print(json.dumps({
            "store_id": result.store_id,
            "shop_url": result.shop_url,
            "final_verdict": result.final_verdict,
            "next_action": result.next_action,
            "stages": [
                {
                    "name": s.name,
                    "status": s.status,
                    "detail": s.detail,
                    "data": s.data,
                }
                for s in result.stages
            ],
        }, indent=2, default=str))
        return

    # Text render
    title = (
        "Onboarding DRY RUN" if dry_run
        else "Onboarding wizard"
    )
    print(
        f"{title}: {result.store_id} ({result.shop_url})"
    )
    print()
    marker = {
        "success": "[OK ]",
        "warn":    "[WRN]",
        "fail":    "[BAD]",
        "skipped": "[ - ]",
    }
    for stage in result.stages:
        mk = marker.get(stage.status, "[ ? ]")
        print(
            f"  {mk} {stage.name:<14} {stage.detail}"
        )
    print()
    verdict_marker = {
        "ready": "[OK ]",
        "ready_with_warnings": "[WRN]",
        "failed": "[BAD]",
        "dry_run": "[ - ]",
    }.get(result.final_verdict, "[ ? ]")
    print(
        f"  {verdict_marker} VERDICT: {result.final_verdict}"
    )
    if result.next_action:
        print()
        print(f"  Next: {result.next_action}")
    # When a cron line was emitted, show it inline so the
    # operator can copy-paste from the same surface.
    sched = next(
        (s for s in result.stages if s.name == "schedule"),
        None,
    )
    if (
        sched and sched.data.get("cron_line")
        and not dry_run
    ):
        print()
        print(f"  Cron: {sched.data['cron_line']}")


