def _cmd_autonomy_discover(args) -> None:
    """Wave 820: inspect + run payload discoverers.
    Wave 834: --all runs every discoverer + summary."""
    # Lazy-load every per-domain discoverer so they register.
    try:
        from core.automation import (  # noqa: F401
            discoverer_registry,
        )
    except ImportError:
        pass
    from core.automation.payload_discoverer import (
        discover, has_discoverer, registered_domains,
    )
    domain = (getattr(args, "domain", "") or "").strip()
    run_all = bool(getattr(args, "all", False))
    store = (getattr(args, "store", "") or "").strip()
    as_json = bool(getattr(args, "json", False))

    if run_all:
        regs = registered_domains()
        results = [
            (d, discover(d, store_id=store or None))
            for d in regs
        ]
        if as_json:
            print(json.dumps({
                "count": len(regs),
                "store_id": store,
                "domains": [
                    {
                        "domain": d,
                        "ok": r.ok,
                        "source": r.source,
                        "store_id": r.store_id,
                        "payload_size": r.payload_size,
                        "discovered_at": r.discovered_at,
                        "error": r.error,
                    }
                    for d, r in results
                ],
                "total_payload_rows": sum(
                    r.payload_size for _, r in results
                ),
                "failed_count": sum(
                    1 for _, r in results if not r.ok
                ),
            }, indent=2, default=str))
            return
        scope_label = f" (store={store})" if store else ""
        print(
            f"Autonomy discoverers ({len(regs)}){scope_label}:"
        )
        print()
        print(
            f"  {'domain':<22} {'status':<8} "
            f"{'rows':>5}  source"
        )
        for d, r in results:
            status = "OK" if r.ok else "ERR"
            print(
                f"  {d:<22} {status:<8} "
                f"{r.payload_size:>5}  {r.source or '(none)'}"
            )
        print()
        total = sum(r.payload_size for _, r in results)
        failed = sum(1 for _, r in results if not r.ok)
        print(
            f"  Total payload rows: {total}; "
            f"failed discoverers: {failed}"
        )
        for d, r in results:
            if not r.ok:
                print(f"    ! {d}: {r.error}")
        return

    if not domain:
        regs = registered_domains()
        if as_json:
            print(json.dumps({
                "registered_discoverers": regs,
                "count": len(regs),
            }, indent=2))
            return
        if not regs:
            print(
                "No discoverers registered yet. "
                "(Substrate W820 ships the registry; "
                "per-domain wiring starts W821.)"
            )
            return
        print(f"Registered discoverers ({len(regs)}):")
        for d in regs:
            print(f"  - {d}")
        return

    if not has_discoverer(domain):
        msg = f"no discoverer registered for {domain!r}"
        if as_json:
            print(json.dumps({"ok": False, "error": msg}))
        else:
            print(f"ERROR: {msg}")
        sys.exit(1)

    result = discover(domain, store_id=store or None)
    if as_json:
        print(json.dumps({
            "ok": result.ok,
            "domain": result.domain,
            "source": result.source,
            "store_id": result.store_id,
            "payload_size": result.payload_size,
            "discovered_at": result.discovered_at,
            "error": result.error,
            "payload_preview": result.payload[:5],
        }, indent=2, default=str))
        if not result.ok:
            sys.exit(1)
        return

    if not result.ok:
        print(f"discoverer FAILED for {domain}: {result.error}")
        sys.exit(1)
    scope_label = f"  store={store}" if store else ""
    print(
        f"discoverer OK for {domain}: "
        f"source={result.source}  "
        f"payload_size={result.payload_size}"
        f"{scope_label}"
    )
    for i, row in enumerate(result.payload[:5]):
        print(f"  [{i}] {str(row)[:140]}")
    if result.payload_size > 5:
        print(
            f"  ... and {result.payload_size - 5} more rows"
        )


def _cmd_autonomy_fire(args) -> None:
    """Wave 816: direct invocation of an autonomy applier."""
    from core.automation.autonomy_fire import fire, known_domains

    domain = (getattr(args, "domain", "") or "").strip()
    payload_json = getattr(args, "payload_json", "") or ""
    payload_file = getattr(args, "payload_file", "") or ""
    yes = bool(getattr(args, "yes", False))
    as_json = bool(getattr(args, "json", False))

    if domain not in known_domains():
        msg = (
            f"unknown domain {domain!r}. Known: "
            f"{', '.join(known_domains())}"
        )
        if as_json:
            print(json.dumps({"ok": False, "error": msg}))
        else:
            print(f"ERROR: {msg}")
        sys.exit(1)

    payload: list[dict] = []
    try:
        if payload_file:
            with open(payload_file, encoding="utf-8") as fh:
                payload = json.load(fh)
        elif payload_json:
            payload = json.loads(payload_json)
    except Exception as exc:  # noqa: BLE001
        msg = f"payload parse failed: {exc!s:.150}"
        if as_json:
            print(json.dumps({"ok": False, "error": msg}))
        else:
            print(f"ERROR: {msg}")
        sys.exit(1)
    if not isinstance(payload, list):
        msg = (
            f"payload must be a JSON list of dicts, got "
            f"{type(payload).__name__}"
        )
        if as_json:
            print(json.dumps({"ok": False, "error": msg}))
        else:
            print(f"ERROR: {msg}")
        sys.exit(1)

    # W962-6 bugfix: mirror cycle-run's env-gate so
    # `autonomy-fire --yes` can't carpet-bomb 10 domains
    # without explicit operator confirmation. Pre-fix only
    # --yes was required; this matches the SHOPAI_CYCLE_RUN_
    # CONFIRM safety pattern.
    if yes:
        import os as _os
        if not _os.environ.get(
            "SHOPAI_AUTONOMY_FIRE_CONFIRM", "",
        ) in ("1", "true", "yes"):
            msg = (
                "ERROR: live autonomy-fire requires "
                "SHOPAI_AUTONOMY_FIRE_CONFIRM=1 in addition "
                "to --yes. Mirror of cycle-run safety."
            )
            if as_json:
                print(json.dumps({"ok": False, "error": msg}))
            else:
                print(msg, file=sys.stderr)
            sys.exit(2)

    result = fire(domain, payload, dry_run=not yes)

    if as_json:
        print(json.dumps({
            "ok": result.ok,
            "domain": result.domain,
            "dry_run": result.dry_run,
            "invoked": result.invoked,
            "payload_size": result.payload_size,
            "event_count": len(result.events),
            "duration_ms": result.duration_ms,
            "error": result.error,
        }, indent=2, default=str))
        return

    mode = "DRY-RUN" if result.dry_run else "LIVE"
    print(
        f"autonomy-fire [{mode}] domain={result.domain} "
        f"payload_size={result.payload_size}"
    )
    if result.error:
        print(f"  ERROR: {result.error}")
        sys.exit(1)
    if result.dry_run:
        print(
            "  Pre-flight OK -- applier resolved + payload "
            "validated. Add --yes to invoke."
        )
        return
    print(
        f"  invoked: {result.invoked}  "
        f"events={len(result.events)}  "
        f"duration_ms={result.duration_ms:.1f}"
    )
    if result.events:
        print("  Events:")
        for i, ev in enumerate(result.events[:10]):
            ev_str = str(ev)[:120]
            print(f"    [{i}] {ev_str}")


