def _cmd_marketing_pause(args) -> None:
    """Wave 111: manually set the budget pause flag."""
    from engines.roas_guardrails.budget_state import pause
    import time as _t
    as_json = bool(getattr(args, "json", False))
    reason = (
        getattr(args, "reason", "manual operator pause")
        or "manual operator pause"
    )
    auto_h = float(
        getattr(args, "auto_resume_hours", 0.0) or 0.0,
    )
    auto_resume_at = (
        _t.time() + auto_h * 3600.0 if auto_h > 0 else 0.0
    )
    state = pause(
        reason=reason, auto_resume_after=auto_resume_at,
    )
    if as_json:
        print(json.dumps({
            "paused": state.paused, "reason": state.reason,
            "paused_at": state.paused_at,
            "auto_resume_after": state.auto_resume_after,
        }, indent=2, default=str))
        return
    print("Budget auto-pause flag SET")
    print(f"  Reason: {state.reason}")
    if state.auto_resume_after > 0:
        import datetime as _dt
        when = _dt.datetime.fromtimestamp(
            state.auto_resume_after,
        ).strftime("%Y-%m-%d %H:%M")
        print(f"  Auto-resume: {when}")


def _cmd_marketing_resume(args) -> None:
    """Wave 111: clear the budget pause flag."""
    from engines.roas_guardrails.budget_state import (
        get_state, resume,
    )
    as_json = bool(getattr(args, "json", False))
    if _gate_autonomy_resume(
        "marketing", get_state(), as_json=as_json,
    ):
        return
    state = resume()
    if as_json:
        print(json.dumps({
            "paused": state.paused, "reason": state.reason,
        }, indent=2))
        return
    print("Budget auto-pause flag CLEARED")


def _cmd_support_status(args) -> None:
    """Wave 105: empire-wide support status."""
    from engines.customer_support.support_status import (
        get_support_status,
    )

    as_json = bool(getattr(args, "json", False))
    window_h = float(
        getattr(args, "window_hours", 168.0) or 168.0,
    )
    store_id = (getattr(args, "store", "") or "").strip()

    report = get_support_status(
        window_hours=window_h,
        store_id=store_id or None,
    )

    if as_json:
        print(json.dumps({
            "window_hours": report.window_hours,
            "store_id": report.store_id,
            "refund_total_entries": (
                report.refund_total_entries
            ),
            "refund_applied_count": (
                report.refund_applied_count
            ),
            "refund_skipped_count": (
                report.refund_skipped_count
            ),
            "refund_total_amount": (
                report.refund_total_amount
            ),
            "refund_avg_amount": report.refund_avg_amount,
            "refund_verdict": report.refund_verdict,
            "refund_failure_ratio": (
                report.refund_failure_ratio
            ),
            "refund_paused": report.refund_paused,
            "refund_pause_reason": (
                report.refund_pause_reason
            ),
            "ticket_tag_total": report.ticket_tag_total,
            "ticket_tag_applied": report.ticket_tag_applied,
            "ticket_tag_failed": report.ticket_tag_failed,
            "verdict": report.verdict,
            "verdict_reasons": report.verdict_reasons,
            "next_action": report.next_action,
        }, indent=2, default=str))
        return

    # Text render
    marker = {
        "healthy": "[OK ]",
        "quiet": "[ - ]",
        "degraded": "[WRN]",
        "paused": "[BAD]",
    }.get(report.verdict, "[ ? ]")
    scope = (
        f"store={report.store_id}" if report.store_id
        else "fleet"
    )
    print(
        f"Support status ({scope}, last "
        f"{report.window_hours:.0f}h)"
    )
    print()
    # Refund stack
    print("  Refund stack:")
    print(
        f"    Applied:       "
        f"{report.refund_applied_count}  "
        f"(${report.refund_total_amount:,.2f}, "
        f"avg ${report.refund_avg_amount:,.2f})"
    )
    print(
        f"    Skipped:       "
        f"{report.refund_skipped_count}"
    )
    print(
        f"    Health:        {report.refund_verdict}  "
        f"(failure ratio "
        f"{report.refund_failure_ratio:.0%})"
    )
    if report.refund_paused:
        print(
            f"    *** PAUSED ***  reason: "
            f"{report.refund_pause_reason}"
        )
    print()
    # Ticket-tag stack
    print("  Ticket-tag stack:")
    print(
        f"    Applied:       "
        f"{report.ticket_tag_applied}"
    )
    print(
        f"    Failed:        "
        f"{report.ticket_tag_failed}"
    )
    print()
    print(f"  {marker} VERDICT: {report.verdict}")
    for reason in report.verdict_reasons:
        print(f"    - {reason}")
    if report.next_action:
        print()
        print(f"  Next: {report.next_action}")


def _cmd_refund_health(args) -> None:
    """Wave 103: refund health verdict + optional bridge."""
    from engines.returns_management.refund_health import (
        analyze_refund_health,
        maybe_auto_pause_refunds,
    )

    as_json = bool(getattr(args, "json", False))
    window_h = float(
        getattr(args, "window_hours", 24.0) or 24.0,
    )
    apply_bridge = bool(getattr(args, "apply_bridge", False))

    report = (
        maybe_auto_pause_refunds(window_hours=window_h)
        if apply_bridge
        else analyze_refund_health(window_hours=window_h)
    )

    if as_json:
        print(json.dumps({
            "window_hours": report.window_hours,
            "sample_size": report.sample_size,
            "applied_count": report.applied_count,
            "adapter_failed_count": (
                report.adapter_failed_count
            ),
            "failure_ratio": report.failure_ratio,
            "verdict": report.verdict,
            "reasons": report.reasons,
            "already_paused": report.already_paused,
            "bridge_fired": report.bridge_fired,
            "bridge_reason": report.bridge_reason,
        }, indent=2, default=str))
        return

    marker = {
        "healthy": "[OK ]",
        "degraded": "[WRN]",
        "critical": "[BAD]",
    }.get(report.verdict, "[ ? ]")
    print(
        f"Refund health (last {report.window_hours:.0f}h)"
    )
    print()
    print(f"  Sample size:        {report.sample_size}")
    print(f"  Applied:            {report.applied_count}")
    print(
        f"  Adapter failed:     "
        f"{report.adapter_failed_count}"
    )
    print(
        f"  Failure ratio:      "
        f"{report.failure_ratio:.0%}"
    )
    print()
    print(f"  {marker} VERDICT: {report.verdict}")
    for reason in report.reasons:
        print(f"    - {reason}")
    if report.already_paused:
        print()
        print("  *** REFUNDS ARE CURRENTLY PAUSED ***")
        print(
            "  Resume: `shopai refund-resume`"
        )
    if apply_bridge:
        print()
        if report.bridge_fired:
            print(
                f"  [AUTO-PAUSED] {report.bridge_reason}"
            )
        else:
            print(f"  Bridge: {report.bridge_reason}")


def _cmd_refund_pause(args) -> None:
    """Wave 103: manually set the refund pause flag."""
    from engines.returns_management.refund_state import pause
    import time as _t

    as_json = bool(getattr(args, "json", False))
    reason = (
        getattr(args, "reason", "manual operator pause")
        or "manual operator pause"
    )
    auto_hours = float(
        getattr(args, "auto_resume_hours", 0.0) or 0.0,
    )
    auto_resume_at = (
        _t.time() + auto_hours * 3600.0
        if auto_hours > 0 else 0.0
    )
    state = pause(
        reason=reason,
        auto_resume_after=auto_resume_at,
    )
    if as_json:
        print(json.dumps({
            "paused": state.paused,
            "reason": state.reason,
            "paused_at": state.paused_at,
            "auto_resume_after": state.auto_resume_after,
        }, indent=2, default=str))
        return
    print("Refund auto-pause flag SET")
    print(f"  Reason: {state.reason}")
    if state.auto_resume_after > 0:
        import datetime as _dt
        when = _dt.datetime.fromtimestamp(
            state.auto_resume_after,
        ).strftime("%Y-%m-%d %H:%M")
        print(f"  Auto-resume: {when}")
    else:
        print(
            "  Auto-resume: never (operator must clear "
            "via `shopai refund-resume`)"
        )


